def _early_hide_owned_windows_console() -> bool:
    """Hide only the transient console created for a normal GUI file launch."""
    if os.name != "nt" or __name__ != "__main__":
        return False
    if any(
        str(argument).casefold() in _EARLY_CONSOLE_CLI_ARGUMENTS
        for argument in sys.argv[1:]
    ):
        return False
    if str(os.environ.get("PC_REHD_CODE_X_KEEP_CONSOLE", "") or "").strip().casefold() in {
        "1",
        "true",
        "yes",
        "on",
    }:
        return False
    try:
        import ctypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        user32 = ctypes.WinDLL("user32", use_last_error=True)
        kernel32.GetConsoleWindow.restype = ctypes.c_void_p
        kernel32.GetConsoleProcessList.argtypes = [
            ctypes.POINTER(ctypes.c_uint32),
            ctypes.c_uint32,
        ]
        kernel32.GetConsoleProcessList.restype = ctypes.c_uint32
        user32.ShowWindow.argtypes = [ctypes.c_void_p, ctypes.c_int]
        user32.ShowWindow.restype = ctypes.c_bool
        console_window = kernel32.GetConsoleWindow()
        if not console_window:
            return False
        process_ids = (ctypes.c_uint32 * 8)()
        process_count = int(
            kernel32.GetConsoleProcessList(process_ids, len(process_ids))
        )
        if process_count != 1 or int(process_ids[0]) != os.getpid():
            return False
        user32.ShowWindow(console_window, 0)
        return True
    except (AttributeError, OSError, TypeError, ValueError):
        return False


_EARLY_WINDOWS_CONSOLE_HIDDEN = _early_hide_owned_windows_console()

