IPC_PROTOCOL_NAME = "pc-rehd-code-x-operation"
IPC_PROTOCOL_VERSION = 2
AGENT_API_REVISION = 1
MAX_IPC_MESSAGE_BYTES = 256 * 1024 * 1024
IPC_MESSAGE_HEADER = struct.Struct("!I")
OPERATION_STATUS_COMMAND = "__operation_status__"


class ProtocolError(RuntimeError):
    pass


class MaxPythonLinkError(RuntimeError):
    """A Max/Python transport or availability event; never a modal UI error."""


class MaxSessionPausedError(MaxPythonLinkError):
    """The Max process is alive, but scene work is temporarily unavailable."""


class MaxIpcTransportError(MaxPythonLinkError):
    """The exact-PID IPC channel failed before a valid command receipt arrived."""


class BlenderAgentRestartRequiredError(ConnectionError):
    """The BPY startup bridge is installed, but this process predates it."""


class MaxSessionState(str, Enum):
    READY = "ready"
    PAUSED_MINIMIZED = "paused_minimized"
    PAUSED_BACKGROUND = "paused_background"
    BUSY = "busy"
    DISCONNECTED = "disconnected"


class AgentCommandError(RuntimeError):
    def __init__(
        self,
        message: str,
        *,
        operation_id: str = "",
        state: str = "failed",
        status_code: str = "AGENT_COMMAND_FAILED",
        retryable: bool = False,
    ) -> None:
        super().__init__(str(message))
        self.operation_id = str(operation_id)
        self.state = str(state)
        self.status_code = str(status_code)
        self.retryable = bool(retryable)


class OperationState(str, Enum):
    CREATED = "created"
    ADMITTED = "admitted"
    QUEUED = "queued"
    PREPARING = "preparing"
    DISPATCHED = "dispatched"
    RUNNING_MAX = "running_max"
    VALIDATING = "validating"
    COMPLETED = "completed"
    FAILED = "failed"
    CANCELLED_BEFORE_START = "cancelled_before_start"
    EXPIRED_NOT_STARTED = "expired_not_started"
    TIMED_OUT_UNKNOWN = "timed_out_unknown"


TERMINAL_OPERATION_STATES = frozenset(
    {
        OperationState.COMPLETED.value,
        OperationState.FAILED.value,
        OperationState.CANCELLED_BEFORE_START.value,
        OperationState.EXPIRED_NOT_STARTED.value,
        OperationState.TIMED_OUT_UNKNOWN.value,
    }
)


@dataclass(frozen=True, slots=True)
class AgentIdentity:
    protocol_version: int
    api_revision: int
    component_revision: str
    command_spec_digest: str
    capabilities: tuple[str, ...]


def normalize_operation_id(value: object = "") -> str:
    normalized = str(value or "").strip().lower()
    if not normalized:
        return uuid.uuid4().hex
    if len(normalized) != 32 or any(
        character not in "0123456789abcdef" for character in normalized
    ):
        raise ProtocolError(
            "operation_id must be 32 lowercase hexadecimal characters"
        )
    return normalized


def payload_digest(payload: Mapping[str, Any] | None) -> str:
    encoded = json.dumps(
        dict(payload or {}),
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest().upper()


def deadline_epoch_ms(timeout_seconds: float) -> int:
    timeout = max(0.05, float(timeout_seconds))
    return int(time.time() * 1000.0 + timeout * 1000.0)


def deadline_expired(deadline_ms: object, *, now_ms: int | None = None) -> bool:
    try:
        value = int(deadline_ms)
    except (TypeError, ValueError, OverflowError):
        return True
    current = int(time.time() * 1000.0) if now_ms is None else int(now_ms)
    return value <= current


def remaining_deadline_seconds(
    deadline_ms: object, *, floor: float = 0.05
) -> float:
    try:
        remaining = (
            int(deadline_ms) - int(time.time() * 1000.0)
        ) / 1000.0
    except (TypeError, ValueError, OverflowError):
        remaining = 0.0
    return max(float(floor), remaining)


def make_request(
    token: str,
    target_pid: int,
    command: str,
    payload: Mapping[str, Any] | None = None,
    *,
    operation_id: str = "",
    deadline_ms: int,
    command_spec_digest: str,
    client_component_revision: str,
) -> dict[str, Any]:
    pid = int(target_pid)
    if pid <= 0:
        raise ProtocolError("Target Max PID must be greater than zero")
    command_text = str(command or "").strip()
    if not command_text:
        raise ProtocolError("IPC command cannot be empty")
    if int(deadline_ms) <= 0:
        raise ProtocolError("IPC request deadline must be positive")
    return {
        "protocol": IPC_PROTOCOL_NAME,
        "version": IPC_PROTOCOL_VERSION,
        "api_revision": AGENT_API_REVISION,
        "token": str(token),
        "operation_id": normalize_operation_id(operation_id),
        "target_pid": pid,
        "command": command_text,
        "payload": dict(payload or {}),
        "payload_digest": payload_digest(payload),
        "deadline_epoch_ms": int(deadline_ms),
        "command_spec_digest": str(command_spec_digest or "").strip().upper(),
        "client_component_revision": str(client_component_revision or "").strip(),
        "submitted_epoch_ms": int(time.time() * 1000.0),
    }


def validate_agent_request(
    request: Mapping[str, Any],
    expected_token: str,
    agent_pid: int,
) -> dict[str, Any]:
    if request.get("protocol") != IPC_PROTOCOL_NAME:
        raise ProtocolError("IPC protocol mismatch")
    if int(request.get("version", 0) or 0) != IPC_PROTOCOL_VERSION:
        raise ProtocolError("IPC protocol version mismatch")
    if int(request.get("api_revision", 0) or 0) != AGENT_API_REVISION:
        raise ProtocolError("Agent API revision mismatch")
    import secrets

    if not secrets.compare_digest(
        str(request.get("token", "")), str(expected_token)
    ):
        raise ProtocolError("IPC authentication failed")
    operation_id = normalize_operation_id(request.get("operation_id", ""))
    target_pid = int(request.get("target_pid", 0) or 0)
    if target_pid <= 0 or target_pid != int(agent_pid):
        raise ProtocolError(
            f"Target Max PID mismatch: request={target_pid}, agent={int(agent_pid)}"
        )
    command = str(request.get("command", "") or "").strip()
    if not command:
        raise ProtocolError("IPC command is missing")
    payload = request.get("payload", {})
    if not isinstance(payload, dict):
        raise ProtocolError("IPC command payload must be an object")
    if str(request.get("payload_digest", "") or "").upper() != payload_digest(
        payload
    ):
        raise ProtocolError("IPC payload digest mismatch")
    deadline_ms = int(request.get("deadline_epoch_ms", 0) or 0)
    if deadline_ms <= 0:
        raise ProtocolError("IPC request deadline is missing")
    normalized = dict(request)
    normalized["operation_id"] = operation_id
    normalized["target_pid"] = target_pid
    normalized["command"] = command
    normalized["payload"] = dict(payload)
    normalized["deadline_epoch_ms"] = deadline_ms
    return normalized


def make_response(
    request: Mapping[str, Any],
    agent_pid: int,
    *,
    state: str,
    status_code: str,
    result: Mapping[str, Any] | None = None,
    error: str = "",
    retryable: bool = False,
    started_epoch_ms: int = 0,
    finished_epoch_ms: int | None = None,
) -> dict[str, Any]:
    normalized_state = str(state or "").strip().lower()
    if normalized_state not in TERMINAL_OPERATION_STATES:
        raise ProtocolError(
            f"Response state is not terminal: {normalized_state!r}"
        )
    finished = (
        int(time.time() * 1000.0)
        if finished_epoch_ms is None
        else int(finished_epoch_ms)
    )
    return {
        "protocol": IPC_PROTOCOL_NAME,
        "version": IPC_PROTOCOL_VERSION,
        "api_revision": AGENT_API_REVISION,
        "operation_id": normalize_operation_id(request.get("operation_id", "")),
        "target_pid": int(request.get("target_pid", 0) or 0),
        "agent_pid": int(agent_pid),
        "command": str(request.get("command", "") or ""),
        "state": normalized_state,
        "terminal": True,
        "ok": normalized_state == OperationState.COMPLETED.value,
        "status_code": str(status_code or ""),
        "retryable": bool(retryable),
        "result": dict(result or {}),
        "error": str(error or ""),
        "started_epoch_ms": int(started_epoch_ms or 0),
        "finished_epoch_ms": finished,
    }


def validate_response(
    response: Mapping[str, Any],
    *,
    operation_id: str,
    target_pid: int,
) -> dict[str, Any]:
    if response.get("protocol") != IPC_PROTOCOL_NAME:
        raise ProtocolError("IPC response protocol mismatch")
    if int(response.get("version", 0) or 0) != IPC_PROTOCOL_VERSION:
        raise ProtocolError("IPC response version mismatch")
    if int(response.get("api_revision", 0) or 0) != AGENT_API_REVISION:
        raise ProtocolError("IPC response API revision mismatch")
    expected_id = normalize_operation_id(operation_id)
    if normalize_operation_id(response.get("operation_id", "")) != expected_id:
        raise ProtocolError("IPC response operation ID mismatch")
    pid = int(target_pid)
    if int(response.get("agent_pid", 0) or 0) != pid:
        raise ProtocolError("IPC response came from the wrong Max PID")
    if int(response.get("target_pid", 0) or 0) != pid:
        raise ProtocolError("IPC response target PID mismatch")
    state = str(response.get("state", "") or "").strip().lower()
    if response.get("terminal") is not True or state not in TERMINAL_OPERATION_STATES:
        raise ProtocolError("IPC response is not a valid terminal receipt")
    result = response.get("result", {})
    if not isinstance(result, dict):
        raise ProtocolError("IPC response result must be an object")
    normalized = dict(response)
    normalized["state"] = state
    normalized["result"] = dict(result)
    return normalized


def receive_ipc_bytes(connection: socket.socket, size: int) -> bytes:
    remaining = int(size)
    parts: list[bytes] = []
    while remaining:
        chunk = connection.recv(remaining)
        if not chunk:
            raise ProtocolError(
                "IPC connection closed before the message was complete"
            )
        parts.append(chunk)
        remaining -= len(chunk)
    return b"".join(parts)


def send_ipc_message(
    connection: socket.socket, payload: Mapping[str, Any]
) -> None:
    body = json.dumps(
        dict(payload), ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    if len(body) > MAX_IPC_MESSAGE_BYTES:
        raise ProtocolError(
            f"Structured IPC message is too large: {len(body)} bytes"
        )
    connection.sendall(IPC_MESSAGE_HEADER.pack(len(body)) + body)


def receive_ipc_message(connection: socket.socket) -> dict[str, Any]:
    header = receive_ipc_bytes(connection, IPC_MESSAGE_HEADER.size)
    (size,) = IPC_MESSAGE_HEADER.unpack(header)
    if size < 2 or size > MAX_IPC_MESSAGE_BYTES:
        raise ProtocolError(f"Invalid structured IPC message size: {size}")
    try:
        payload = json.loads(receive_ipc_bytes(connection, size).decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ProtocolError(f"Invalid structured IPC message: {exc}") from exc
    if not isinstance(payload, dict):
        raise ProtocolError("Structured IPC message root must be a mapping")
    return payload


