class CommandAccess(str, Enum):
    CONTROL = "control"
    SCENE_READ = "scene_read"
    SCENE_WRITE = "scene_write"


class QueuePolicy(str, Enum):
    FIFO = "fifo"
    LATEST_WINS = "latest_wins"
    SINGLE_FLIGHT = "single_flight"


@dataclass(frozen=True, slots=True)
class CommandSpec:
    name: str
    operation: str
    access: CommandAccess
    queue_policy: QueuePolicy
    timeout_seconds: float
    priority: int
    foreground_required: bool = True
    coalesce_exact: bool = True

    def as_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "operation": self.operation,
            "access": self.access.value,
            "queue_policy": self.queue_policy.value,
            "timeout_seconds": float(self.timeout_seconds),
            "priority": int(self.priority),
            "foreground_required": bool(self.foreground_required),
            "coalesce_exact": bool(self.coalesce_exact),
        }


def _spec(
    name: str,
    operation: str,
    access: CommandAccess,
    queue_policy: QueuePolicy,
    timeout_seconds: float,
    priority: int,
    *,
    foreground_required: bool = True,
    coalesce_exact: bool = True,
) -> CommandSpec:
    return CommandSpec(
        name=name,
        operation=operation,
        access=access,
        queue_policy=queue_policy,
        timeout_seconds=timeout_seconds,
        priority=priority,
        foreground_required=foreground_required,
        coalesce_exact=coalesce_exact,
    )


