# Connection admission deliberately stays small. Feature-specific commands are
# checked at their own call sites so a missing optional feature never makes an
# otherwise healthy Max Agent unusable.
MAX_WORKER_REQUIRED_CAPABILITIES = frozenset(
    {"health", "compatibility_probe"}
)
MAX_RESCUE_REQUIRED_ACTIONS = frozenset({"health", "ensure_worker"})


def command_spec_digest() -> str:
    encoded = json.dumps(
        {
            "revision": COMMAND_SPEC_REVISION,
            "commands": [COMMAND_SPECS[name].as_dict() for name in sorted(COMMAND_SPECS)],
        },
        ensure_ascii=True,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("ascii")
    return hashlib.sha256(encoded).hexdigest().upper()


COMMAND_SPEC_DIGEST = command_spec_digest()


def get_command_spec(command: object) -> CommandSpec:
    normalized = str(command or "").strip()
    try:
        return COMMAND_SPECS[normalized]
    except KeyError as exc:
        raise ProtocolError(f"Unsupported Max Agent command: {normalized!r}") from exc


def _max_background_execution_requested(payload: Mapping[str, Any] | None) -> bool:
    value = dict(payload or {}).get(_MAX_BACKGROUND_EXECUTION_CONTROL_KEY, False)
    if value not in {False, True}:
        raise ProtocolError("Max background-execution control must be boolean")
    return bool(value)


def _max_queue_retention_requested(payload: Mapping[str, Any] | None) -> bool:
    value = dict(payload or {}).get(
        _MAX_QUEUE_RETAIN_UNTIL_IDLE_CONTROL_KEY, False
    )
    if value not in {False, True}:
        raise ProtocolError("Max queue-retention control must be boolean")
    return bool(value)


class CoordinatorError(RuntimeError):
    def __init__(
        self,
        message: str,
        *,
        operation_id: str,
        state: OperationState,
        status_code: str,
    ) -> None:
        super().__init__(str(message))
        self.operation_id = str(operation_id)
        self.state = state.value
        self.status_code = str(status_code)
        self.retryable = False


class OperationCancelledBeforeStart(CoordinatorError):
    pass


class OperationExpiredNotStarted(TimeoutError, CoordinatorError):
    def __init__(self, message: str, **kwargs: Any) -> None:
        TimeoutError.__init__(self, str(message))
        CoordinatorError.__init__(self, str(message), **kwargs)


class OperationTimedOutUnknown(TimeoutError, CoordinatorError):
    def __init__(self, message: str, **kwargs: Any) -> None:
        TimeoutError.__init__(self, str(message))
        CoordinatorError.__init__(self, str(message), **kwargs)


class OperationTransport(Protocol):
    def execute_operation(self, record: "OperationRecord") -> dict[str, Any]: ...

    def cancel_inflight(self, operation_id: str, reason: str) -> None: ...


@dataclass(slots=True)
class OperationRecord:
    operation_id: str
    pid: int
    command: str
    payload: dict[str, Any]
    spec: CommandSpec
    deadline_epoch_ms: int
    sequence: int
    state: OperationState = OperationState.CREATED
    created_monotonic: float = field(default_factory=time.monotonic)
    updated_monotonic: float = field(default_factory=time.monotonic)
    started_epoch_ms: int = 0
    finished_epoch_ms: int = 0
    transport_epoch: int = 0
    result: dict[str, Any] | None = None
    error: BaseException | None = None
    status_code: str = "OPERATION_CREATED"
    waiters: int = 1
    event: threading.Event = field(default_factory=threading.Event, repr=False)

    @property
    def fingerprint(self) -> str:
        return f"{self.command}:{payload_digest(self.payload)}"

    @property
    def terminal(self) -> bool:
        return self.state in {
            OperationState.COMPLETED,
            OperationState.FAILED,
            OperationState.CANCELLED_BEFORE_START,
            OperationState.EXPIRED_NOT_STARTED,
            OperationState.TIMED_OUT_UNKNOWN,
        }


@dataclass(slots=True)
class _PidLane:
    pid: int
    transport: OperationTransport
    online: bool = True
    epoch: int = 1
    sequence: int = 0
    queue: list[tuple[int, int, str]] = field(default_factory=list)
    records: dict[str, OperationRecord] = field(default_factory=dict)
    workflows: dict[str, str] = field(default_factory=dict)
    active_operation_id: str = ""
    worker: threading.Thread | None = None
    stopped: bool = False


class OperationCoordinator:
    """The only owner of Launcher -> Max operation ordering.

    Each PID has one deterministic priority queue and one worker. Feature code
    may submit commands, but it cannot create its own Max ordering, retries, or
    replay policy.
    """

    def __init__(self, *, history_limit: int = 256, queue_limit: int = 128) -> None:
        self._condition = threading.Condition(threading.RLock())
        self._lanes: dict[int, _PidLane] = {}
        self._history_limit = max(32, int(history_limit))
        self._queue_limit = max(8, int(queue_limit))

    def register_pid(self, pid: int, transport: OperationTransport) -> None:
        exact_pid = int(pid)
        if exact_pid <= 0:
            raise ValueError("Coordinator PID must be greater than zero")
        with self._condition:
            lane = self._lanes.get(exact_pid)
            if lane is None:
                lane = _PidLane(pid=exact_pid, transport=transport)
                self._lanes[exact_pid] = lane
            else:
                lane.transport = transport
                lane.online = True
                lane.stopped = False
                lane.epoch += 1
            if lane.worker is None or not lane.worker.is_alive():
                lane.worker = threading.Thread(
                    target=self._worker,
                    args=(exact_pid,),
                    name=f"PC-REHD-MaxCoordinator-{exact_pid}",
                    daemon=True,
                )
                lane.worker.start()
            self._condition.notify_all()

    def disconnect_pid(self, pid: int, reason: str) -> None:
        exact_pid = int(pid)
        cancel_transport: tuple[OperationTransport, str] | None = None
        with self._condition:
            lane = self._lanes.get(exact_pid)
            if lane is None:
                return
            lane.online = False
            lane.epoch += 1
            lane.workflows.clear()
            while lane.queue:
                _priority, _sequence, operation_id = heapq.heappop(lane.queue)
                record = lane.records.get(operation_id)
                if record is not None and not record.terminal:
                    self._finish_cancelled_locked(record, reason)
            active = lane.records.get(lane.active_operation_id)
            if active is not None and not active.terminal:
                self._finish_unknown_locked(active, reason)
                cancel_transport = (lane.transport, active.operation_id)
            self._condition.notify_all()
        if cancel_transport is not None:
            transport, operation_id = cancel_transport
            try:
                transport.cancel_inflight(operation_id, reason)
            except Exception:
                pass

    def stop_pid(self, pid: int, reason: str = "Coordinator stopped") -> None:
        exact_pid = int(pid)
        self.disconnect_pid(exact_pid, reason)
        with self._condition:
            lane = self._lanes.get(exact_pid)
            if lane is not None:
                lane.stopped = True
                self._condition.notify_all()

    def begin_workflow(self, pid: int, token: str, phase: str) -> None:
        exact_pid = int(pid)
        normalized_token = str(token or "").strip()
        if exact_pid <= 0 or not normalized_token:
            raise ValueError("Workflow requires a positive PID and non-empty token")
        with self._condition:
            lane = self._lanes.get(exact_pid)
            if lane is None or not lane.online or lane.stopped:
                raise ConnectionError(f"Max PID {exact_pid} has no admitted workflow session")
            lane.workflows[normalized_token] = str(phase or "accepted")
            self._condition.notify_all()

    def update_workflow(self, pid: int, token: str, phase: str) -> None:
        with self._condition:
            lane = self._lanes.get(int(pid))
            normalized_token = str(token or "").strip()
            if lane is None or normalized_token not in lane.workflows:
                return
            lane.workflows[normalized_token] = str(phase or "working")

    def end_workflow(self, pid: int, token: str) -> None:
        with self._condition:
            lane = self._lanes.get(int(pid))
            if lane is not None:
                lane.workflows.pop(str(token or "").strip(), None)
                self._condition.notify_all()

    def pid_busy(self, pid: int) -> bool:
        with self._condition:
            lane = self._lanes.get(int(pid))
            if lane is None:
                return False
            active = lane.records.get(lane.active_operation_id)
            if active is not None and not active.terminal:
                return True
            if lane.workflows:
                return True
            return any(
                (record := lane.records.get(operation_id)) is not None
                and not record.terminal
                for _priority, _sequence, operation_id in lane.queue
            )

    def submit(
        self,
        pid: int,
        command: str,
        payload: Mapping[str, Any] | None = None,
        *,
        timeout_seconds: float | None = None,
        operation_id: str = "",
    ) -> tuple[str, dict[str, Any]]:
        exact_pid = int(pid)
        spec = get_command_spec(command)
        payload_copy = dict(payload or {})
        timeout = (
            spec.timeout_seconds
            if timeout_seconds is None
            else min(spec.timeout_seconds, max(0.05, float(timeout_seconds)))
        )
        if _max_queue_retention_requested(payload_copy):
            timeout = max(timeout, float(MAX_OPERATION_QUEUE_RETAIN_SECONDS))
        deadline_ms = deadline_epoch_ms(timeout)
        fingerprint = f"{spec.name}:{payload_digest(payload_copy)}"
        with self._condition:
            lane = self._lanes.get(exact_pid)
            if lane is None or not lane.online or lane.stopped:
                raise ConnectionError(f"Max PID {exact_pid} has no admitted operation session")
            if spec.coalesce_exact:
                existing = self._find_fingerprint_locked(lane, fingerprint)
                if existing is not None:
                    existing.waiters += 1
                    record = existing
                else:
                    record = self._enqueue_locked(
                        lane,
                        spec,
                        payload_copy,
                        deadline_ms,
                        operation_id,
                    )
            else:
                record = self._enqueue_locked(
                    lane,
                    spec,
                    payload_copy,
                    deadline_ms,
                    operation_id,
                )
            self._condition.notify_all()

        remaining = max(0.05, (record.deadline_epoch_ms - int(time.time() * 1000.0)) / 1000.0)
        if not record.event.wait(remaining + 0.25):
            cancel_transport: OperationTransport | None = None
            with self._condition:
                if not record.terminal:
                    if record.state in {
                        OperationState.CREATED,
                        OperationState.ADMITTED,
                        OperationState.QUEUED,
                        OperationState.PREPARING,
                    }:
                        self._finish_expired_locked(record)
                    else:
                        self._finish_unknown_locked(
                            record,
                            "Operation deadline elapsed after dispatch; Max result is unknown",
                        )
                        lane = self._lanes.get(exact_pid)
                        cancel_transport = lane.transport if lane is not None else None
            if cancel_transport is not None:
                try:
                    cancel_transport.cancel_inflight(
                        record.operation_id,
                        "Operation deadline elapsed after dispatch",
                    )
                except Exception:
                    pass
        if record.error is not None:
            raise record.error
        if record.state is not OperationState.COMPLETED or record.result is None:
            raise ProtocolError(
                f"Operation {record.operation_id} reached {record.state.value} without a result"
            )
        return record.operation_id, dict(record.result)

    def request_in_flight(self, pid: int) -> bool:
        # The session must remain BUSY while a command is merely queued too.
        # Callers use this as their connection-retention gate, not only as an
        # "currently executing" probe.
        return self.pid_busy(pid)

    def queue_depth(self, pid: int) -> int:
        with self._condition:
            lane = self._lanes.get(int(pid))
            if lane is None:
                return 0
            return sum(
                1
                for _priority, _sequence, operation_id in lane.queue
                if (record := lane.records.get(operation_id)) is not None and not record.terminal
            )

    def snapshot(self, pid: int) -> list[dict[str, Any]]:
        with self._condition:
            lane = self._lanes.get(int(pid))
            if lane is None:
                return []
            return [
                {
                    "operation_id": record.operation_id,
                    "command": record.command,
                    "state": record.state.value,
                    "status_code": record.status_code,
                    "waiters": record.waiters,
                    "deadline_epoch_ms": record.deadline_epoch_ms,
                }
                for record in sorted(lane.records.values(), key=lambda item: item.sequence)
            ] + [
                {
                    "operation_id": token,
                    "command": "workflow",
                    "state": phase,
                    "status_code": "WORKFLOW_ACTIVE",
                    "waiters": 1,
                    "deadline_epoch_ms": 0,
                }
                for token, phase in sorted(lane.workflows.items())
            ]

    def _enqueue_locked(
        self,
        lane: _PidLane,
        spec: CommandSpec,
        payload: dict[str, Any],
        deadline_ms: int,
        operation_id: str,
    ) -> OperationRecord:
        queued_count = sum(
            1
            for _priority, _sequence, queued_id in lane.queue
            if (queued := lane.records.get(queued_id)) is not None and not queued.terminal
        )
        if queued_count >= self._queue_limit:
            raise RuntimeError(f"Max PID {lane.pid} operation queue is full")
        if spec.queue_policy is QueuePolicy.LATEST_WINS:
            for _priority, _sequence, queued_id in list(lane.queue):
                queued = lane.records.get(queued_id)
                if (
                    queued is not None
                    and not queued.terminal
                    and queued.command == spec.name
                    and queued.state in {OperationState.ADMITTED, OperationState.QUEUED}
                ):
                    self._finish_cancelled_locked(
                        queued,
                        f"A newer {spec.name} request replaced this queued probe",
                    )
        lane.sequence += 1
        record = OperationRecord(
            operation_id=normalize_operation_id(operation_id),
            pid=lane.pid,
            command=spec.name,
            payload=payload,
            spec=spec,
            deadline_epoch_ms=int(deadline_ms),
            sequence=lane.sequence,
            state=OperationState.ADMITTED,
            status_code="OPERATION_ADMITTED",
            transport_epoch=lane.epoch,
        )
        if record.operation_id in lane.records:
            raise ProtocolError(f"Duplicate operation_id {record.operation_id}")
        lane.records[record.operation_id] = record
        record.state = OperationState.QUEUED
        record.status_code = "OPERATION_QUEUED"
        record.updated_monotonic = time.monotonic()
        heapq.heappush(lane.queue, (spec.priority, record.sequence, record.operation_id))
        self._trim_history_locked(lane)
        return record

    @staticmethod
    def _find_fingerprint_locked(lane: _PidLane, fingerprint: str) -> OperationRecord | None:
        for record in lane.records.values():
            if not record.terminal and record.fingerprint == fingerprint:
                return record
        return None

    def _worker(self, pid: int) -> None:
        exact_pid = int(pid)
        while True:
            with self._condition:
                lane = self._lanes.get(exact_pid)
                while lane is not None and not lane.stopped:
                    record = self._next_record_locked(lane)
                    if record is not None:
                        break
                    self._condition.wait(timeout=0.5)
                    lane = self._lanes.get(exact_pid)
                if lane is None or lane.stopped:
                    return
                if not lane.online:
                    continue
                if int(time.time() * 1000.0) >= record.deadline_epoch_ms:
                    self._finish_expired_locked(record)
                    continue
                record.state = OperationState.PREPARING
                record.status_code = "OPERATION_PREPARING"
                record.updated_monotonic = time.monotonic()
                lane.active_operation_id = record.operation_id
                transport = lane.transport
                epoch = lane.epoch
                record.transport_epoch = epoch
                record.state = OperationState.DISPATCHED
                record.status_code = "OPERATION_DISPATCHED"
                record.started_epoch_ms = int(time.time() * 1000.0)
                record.updated_monotonic = time.monotonic()

            try:
                response = transport.execute_operation(record)
                self._complete_from_response(exact_pid, record, epoch, response)
            except BaseException as exc:
                self._complete_from_exception(exact_pid, record, epoch, exc)
            finally:
                with self._condition:
                    current_lane = self._lanes.get(exact_pid)
                    if (
                        current_lane is not None
                        and current_lane.active_operation_id == record.operation_id
                    ):
                        current_lane.active_operation_id = ""
                    self._condition.notify_all()

    @staticmethod
    def _next_record_locked(lane: _PidLane) -> OperationRecord | None:
        while lane.queue:
            _priority, _sequence, operation_id = heapq.heappop(lane.queue)
            record = lane.records.get(operation_id)
            if record is not None and not record.terminal:
                return record
        return None

    def _complete_from_response(
        self,
        pid: int,
        record: OperationRecord,
        epoch: int,
        response: Mapping[str, Any],
    ) -> None:
        with self._condition:
            lane = self._lanes.get(int(pid))
            if record.terminal:
                return
            if lane is None or not lane.online or lane.epoch != epoch:
                self._finish_unknown_locked(record, "Session changed while Max was executing")
                return
            state = str(response.get("state", "") or "").strip().lower()
            status_code = str(response.get("status_code", "") or "AGENT_RESPONSE")
            if state == OperationState.COMPLETED.value:
                result = response.get("result", {})
                if not isinstance(result, dict):
                    self._finish_failed_locked(
                        record,
                        ProtocolError("Agent completed without a mapping result"),
                        "INVALID_AGENT_RESULT",
                    )
                    return
                record.state = OperationState.VALIDATING
                record.status_code = "OPERATION_VALIDATING"
                record.result = dict(result)
                record.state = OperationState.COMPLETED
                record.status_code = status_code or "OPERATION_COMPLETED"
                self._signal_terminal_locked(record)
                return
            message = str(response.get("error", "") or status_code or "Max Agent command failed")
            if state == OperationState.CANCELLED_BEFORE_START.value:
                self._finish_cancelled_locked(record, message)
            elif state == OperationState.EXPIRED_NOT_STARTED.value:
                self._finish_expired_locked(record, message)
            elif state == OperationState.TIMED_OUT_UNKNOWN.value:
                self._finish_unknown_locked(record, message)
            else:
                self._finish_failed_locked(
                    record,
                    AgentCommandError(
                        message,
                        operation_id=record.operation_id,
                        state=state or OperationState.FAILED.value,
                        status_code=status_code,
                        retryable=False,
                    ),
                    status_code,
                )

    def _complete_from_exception(
        self,
        pid: int,
        record: OperationRecord,
        epoch: int,
        exc: BaseException,
    ) -> None:
        with self._condition:
            lane = self._lanes.get(int(pid))
            if record.terminal:
                return
            if lane is None or not lane.online or lane.epoch != epoch:
                self._finish_unknown_locked(record, f"{type(exc).__name__}: {exc}")
                return
            if record.state in {OperationState.DISPATCHED, OperationState.RUNNING_MAX}:
                self._finish_unknown_locked(
                    record,
                    f"Transport failed after dispatch; Max result is unknown: {type(exc).__name__}: {exc}",
                )
            else:
                self._finish_failed_locked(record, exc, "OPERATION_TRANSPORT_FAILED")

    def _finish_cancelled_locked(self, record: OperationRecord, reason: str) -> None:
        record.state = OperationState.CANCELLED_BEFORE_START
        record.status_code = "CANCELLED_BEFORE_START"
        record.error = OperationCancelledBeforeStart(
            reason,
            operation_id=record.operation_id,
            state=record.state,
            status_code=record.status_code,
        )
        self._signal_terminal_locked(record)

    def _finish_expired_locked(
        self,
        record: OperationRecord,
        reason: str = "Operation deadline elapsed before Max started it",
    ) -> None:
        record.state = OperationState.EXPIRED_NOT_STARTED
        record.status_code = "EXPIRED_NOT_STARTED"
        record.error = OperationExpiredNotStarted(
            reason,
            operation_id=record.operation_id,
            state=record.state,
            status_code=record.status_code,
        )
        self._signal_terminal_locked(record)

    def _finish_unknown_locked(self, record: OperationRecord, reason: str) -> None:
        record.state = OperationState.TIMED_OUT_UNKNOWN
        record.status_code = "TIMED_OUT_UNKNOWN_NO_AUTORETRY"
        record.error = OperationTimedOutUnknown(
            reason,
            operation_id=record.operation_id,
            state=record.state,
            status_code=record.status_code,
        )
        self._signal_terminal_locked(record)

    def _finish_failed_locked(
        self,
        record: OperationRecord,
        error: BaseException,
        status_code: str,
    ) -> None:
        record.state = OperationState.FAILED
        record.status_code = str(status_code or "OPERATION_FAILED")
        record.error = error
        self._signal_terminal_locked(record)

    @staticmethod
    def _signal_terminal_locked(record: OperationRecord) -> None:
        record.finished_epoch_ms = int(time.time() * 1000.0)
        record.updated_monotonic = time.monotonic()
        record.event.set()

    def _trim_history_locked(self, lane: _PidLane) -> None:
        if len(lane.records) <= self._history_limit:
            return
        removable = sorted(
            (record for record in lane.records.values() if record.terminal),
            key=lambda item: item.sequence,
        )
        for record in removable[: max(0, len(lane.records) - self._history_limit)]:
            lane.records.pop(record.operation_id, None)


