def _load_blender_fbx_texture_tool_payload() -> dict[str, str]:
    """Read the user-provided Blender tool as one hash-checked Agent payload."""
    path = BLENDER_FBX_TEXTURE_TOOL_PATH.resolve(strict=False)
    if not path.is_file():
        raise FileNotFoundError(f"Blender texture tool is missing: {path}")
    source_bytes = path.read_bytes()
    if not source_bytes or len(source_bytes) > BLENDER_FBX_TEXTURE_TOOL_MAX_BYTES:
        raise ValueError("Blender texture tool source size is invalid")
    try:
        source_text = source_bytes.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise ValueError("Blender texture tool must be UTF-8") from exc
    compile(source_text, str(path), "exec")
    if BLENDER_FBX_TEXTURE_TOOL_ENTRYPOINT not in source_text:
        raise ValueError("Blender texture tool entry point is missing")
    return {
        "schema": BLENDER_FBX_TEXTURE_TOOL_SCHEMA,
        "tool_id": BLENDER_FBX_TEXTURE_TOOL_ID,
        "source_name": path.name,
        "source_sha256": hashlib.sha256(source_bytes).hexdigest().upper(),
        "source_b64": base64.b64encode(source_bytes).decode("ascii"),
    }
