def _environment_flag_enabled(name: str) -> bool:
    return str(os.environ.get(name, "") or "").strip().casefold() in {
        "1",
        "true",
        "yes",
        "on",
    }


def _canonical_operation_name(operation: object) -> str:
    normalized = str(operation or "").strip().casefold().replace("-", "_")
    aliases = {
        "import": "import_mod",
        "export": "export_mod",
        "inspect": "inspect_scene",
        "max_agent": "health",
        "sbc": "auxiliary",
        "adr": "auxiliary",
        "ems": "auxiliary",
    }
    normalized = aliases.get(normalized, normalized)
    if normalized.startswith(("sbc_", "adr_", "ems_", "auxiliary_")):
        normalized = "auxiliary"
    elif normalized in {"mrl", "mrl_bind", "manual_texture"}:
        normalized = "texture"
    if normalized not in OPERATION_REQUIRED_DOMAINS:
        raise ValueError(f"Unsupported Launcher operation: {operation!r}")
    return normalized


def _operation_required_domains(operation: object) -> tuple[str, ...]:
    return tuple(OPERATION_REQUIRED_DOMAINS[_canonical_operation_name(operation)])


def _operation_timeout_seconds(operation: object) -> float:
    canonical = _canonical_operation_name(operation)
    return float(OPERATION_TIMEOUT_SECONDS[canonical])


def _agent_command_operation(command: object) -> str:
    normalized = str(command or "").strip().casefold()
    return AGENT_COMMAND_OPERATIONS.get(normalized, "inspect_scene")


def _agent_command_timeout_seconds(command: object, fallback: float) -> float:
    configured = _operation_timeout_seconds(_agent_command_operation(command))
    fallback_value = max(0.2, float(fallback))
    if abs(fallback_value - float(AGENT_REQUEST_TIMEOUT)) < 1e-9:
        return configured
    return min(configured, fallback_value)


def _operation_failure_domain(operation: object) -> str:
    canonical = _canonical_operation_name(operation)
    return str(OPERATION_FAILURE_DOMAINS[canonical])


def _operation_dispatch_receipt(
    operation: object,
    *,
    correlation_id: str,
    started: float,
    error: Exception | None = None,
) -> dict[str, Any]:
    canonical = _canonical_operation_name(operation)
    if error is None:
        status = "PASS"
        status_code = "OPERATION_DISPATCH_ACCEPTED"
        retryable = False
        recovery_action = "none"
        detail = "Operation was dispatched to its declared failure domain."
    elif isinstance(error, (TimeoutError, socket.timeout)):
        status = "FAIL"
        status_code = "OPERATION_DOMAIN_TIMEOUT"
        retryable = True
        recovery_action = "retry_current_operation"
        detail = str(error)
    elif isinstance(error, (ConnectionError, OSError, ProtocolError, AgentCommandError)):
        status = "FAIL"
        status_code = "OPERATION_DOMAIN_UNAVAILABLE"
        retryable = True
        recovery_action = "reconnect_required_domain"
        detail = str(error)
    elif isinstance(error, (ImportError, ModuleNotFoundError)):
        status = "FAIL"
        status_code = "OPERATION_DEPENDENCY_UNAVAILABLE"
        retryable = True
        recovery_action = "run_explicit_runtime_health"
        detail = str(error)
    elif isinstance(error, (TypeError, ValueError)):
        status = "FAIL"
        status_code = "OPERATION_INVALID_REQUEST"
        retryable = False
        recovery_action = "fix_current_operation_request"
        detail = str(error)
    else:
        status = "FAIL"
        status_code = "OPERATION_DOMAIN_FAILED"
        retryable = False
        recovery_action = "inspect_current_operation_receipt"
        detail = str(error)
    return {
        "schema": OPERATION_RECEIPT_SCHEMA,
        "module": "PC-REHD Code X Launcher",
        "operation": canonical,
        "failure_domain": _operation_failure_domain(canonical),
        "isolation_scope": "current_operation_only",
        "status": status,
        "status_code": status_code,
        "retryable": retryable,
        "degraded": error is not None,
        "recovery_action": recovery_action,
        "contract_revision": 1,
        "correlation_id": str(correlation_id),
        "duration_ms": max(0.0, round((time.perf_counter() - started) * 1000.0, 3)),
        "error_type": type(error).__name__ if error is not None else "",
        "detail": detail,
        "required_domains": list(_operation_required_domains(canonical)),
        "timeout_seconds": _operation_timeout_seconds(canonical),
    }


def _isolated_python_child_environment(
    base_environment: dict[str, str] | None = None,
) -> dict[str, str]:
    environment = dict(os.environ if base_environment is None else base_environment)
    for variable_name in tuple(environment):
        if str(variable_name).upper().startswith("PYTHON"):
            environment.pop(variable_name, None)
    environment.update(ISOLATED_PYTHON_ENVIRONMENT)
    return environment


def _require_supported_launcher_python(
    version_info: tuple[int, ...] | None = None,
) -> dict[str, Any]:
    if version_info is None:
        try:
            from codex_python_runtime_bootstrap import ensure_required_python_runtime

            runtime_report = ensure_required_python_runtime(
                context_label="PC-REHD Code X Launcher"
            )
            current = (
                sys.version_info.major,
                sys.version_info.minor,
                sys.version_info.micro,
            )
            return {
                "current": f"{current[0]}.{current[1]}.{current[2]}",
                "supported": runtime_report.get("exact_required") is True,
                "supported_versions": list(runtime_report.get("supported_python_versions", [])),
                "bootstrap_approved": runtime_report.get("ab_approved") is True,
                "candidate_session": runtime_report.get("candidate_session") is True,
                "required_python": ".".join(str(part) for part in LAUNCHER_REQUIRED_PYTHON),
            }
        except SystemExit:
            raise
        except Exception:
            # A failed exact-runtime install is a real startup failure. Never
            # continue under the old interpreter after Bootstrap reports it.
            raise
    current = (
        (
            sys.version_info.major,
            sys.version_info.minor,
            sys.version_info.micro,
        )
        if version_info is None
        else tuple(int(value) for value in version_info)
    )
    supported = current == LAUNCHER_REQUIRED_PYTHON
    report = {
        "current": ".".join(str(part) for part in current),
        "supported": supported,
        "supported_versions": [f"{major}.{minor}" for major, minor in LAUNCHER_SUPPORTED_PYTHON_MINORS],
        "required_python": ".".join(str(part) for part in LAUNCHER_REQUIRED_PYTHON),
    }
    if supported is not True:
        raise RuntimeError(
            "Unsupported Launcher Python "
            + report["current"]
            + ". The Launcher requires the validated x64 Python 3.14.7 runtime; it will not fall back to another Python release."
        )
    return report


def _call_with_windows_thread_priority(
    operation: Callable[[], Any],
    *,
    performance_critical: bool,
    background_maintenance: bool = False,
) -> Any:
    if os.name != "nt" or not (performance_critical or background_maintenance):
        return operation()
    try:
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.GetCurrentThread.restype = wintypes.HANDLE
        kernel32.GetThreadPriority.argtypes = [wintypes.HANDLE]
        kernel32.GetThreadPriority.restype = ctypes.c_int
        kernel32.SetThreadPriority.argtypes = [wintypes.HANDLE, ctypes.c_int]
        kernel32.SetThreadPriority.restype = wintypes.BOOL
        thread_handle = kernel32.GetCurrentThread()
        previous = int(kernel32.GetThreadPriority(thread_handle))
        changed = bool(
            kernel32.SetThreadPriority(
                thread_handle,
                WINDOWS_THREAD_PRIORITY_HIGHEST
                if performance_critical
                else WINDOWS_THREAD_PRIORITY_BELOW_NORMAL,
            )
        )
    except Exception:
        return operation()
    try:
        return operation()
    finally:
        if changed and previous != 0x7FFFFFFF:
            try:
                kernel32.SetThreadPriority(thread_handle, previous)
            except Exception:
                pass


def _call_with_windows_process_priority(
    operation: Callable[[], Any],
    *,
    performance_critical: bool,
) -> Any:
    if os.name != "nt" or not performance_critical:
        return operation()
    try:
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.GetCurrentProcess.restype = wintypes.HANDLE
        kernel32.GetPriorityClass.argtypes = [wintypes.HANDLE]
        kernel32.GetPriorityClass.restype = wintypes.DWORD
        kernel32.SetPriorityClass.argtypes = [wintypes.HANDLE, wintypes.DWORD]
        kernel32.SetPriorityClass.restype = wintypes.BOOL
        process_handle = kernel32.GetCurrentProcess()
        previous = int(kernel32.GetPriorityClass(process_handle))
        changed = bool(
            kernel32.SetPriorityClass(
                process_handle,
                WINDOWS_ABOVE_NORMAL_PRIORITY_CLASS,
            )
        )
    except Exception:
        return operation()
    try:
        return operation()
    finally:
        if changed and previous:
            try:
                kernel32.SetPriorityClass(process_handle, previous)
            except Exception:
                pass


def _set_current_windows_process_priority(priority_class: int) -> bool:
    if os.name != "nt":
        return False
    try:
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.GetCurrentProcess.restype = wintypes.HANDLE
        kernel32.SetPriorityClass.argtypes = [wintypes.HANDLE, wintypes.DWORD]
        kernel32.SetPriorityClass.restype = wintypes.BOOL
        return bool(
            kernel32.SetPriorityClass(
                kernel32.GetCurrentProcess(),
                int(priority_class),
            )
        )
    except Exception:
        return False


def _low_priority_subprocess_creation_flags() -> int:
    if os.name != "nt":
        return 0
    return int(getattr(subprocess, "CREATE_NO_WINDOW", 0)) | int(
        getattr(
            subprocess,
            "BELOW_NORMAL_PRIORITY_CLASS",
            WINDOWS_BELOW_NORMAL_PRIORITY_CLASS,
        )
    )


def _windows_console_is_attached() -> bool:
    if os.name != "nt":
        return False
    try:
        import ctypes

        return bool(ctypes.windll.kernel32.GetConsoleWindow())
    except (AttributeError, OSError):
        return False


def _windowed_python_executable() -> Path | None:
    candidates = (
        str(sys.executable or ""),
        str(getattr(sys, "_base_executable", "") or ""),
    )
    seen: set[str] = set()
    for raw_path in candidates:
        if not raw_path:
            continue
        candidate = Path(raw_path).resolve().with_name("pythonw.exe")
        key = str(candidate).casefold()
        if key in seen:
            continue
        seen.add(key)
        if candidate.is_file():
            return candidate
    return None


def _configure_windowless_multiprocessing() -> bool:
    """Keep spawned Writer and policy-smoke workers off the Windows taskbar."""
    if os.name != "nt":
        return False
    executable = _windowed_python_executable()
    if executable is None:
        return False
    try:
        import multiprocessing

        multiprocessing.set_executable(str(executable))
        return True
    except (ImportError, OSError, RuntimeError, TypeError):
        return False


def _start_runtime_guardian() -> bool:
    """Run the PowerShell runtime guardian beside the normal GUI process."""
    if os.name != "nt":
        return False
    detector = next(MODULE_DIR.glob("*Click Bat First.ps1"), None)
    if detector is None:
        return False
    system_root = Path(os.environ.get("SystemRoot", r"C:\Windows"))
    powershell = system_root / "System32" / "WindowsPowerShell" / "v1.0" / "powershell.exe"
    if not powershell.is_file():
        return False
    command = [
        str(powershell),
        "-NoLogo",
        "-NoProfile",
        "-ExecutionPolicy",
        "Bypass",
        "-WindowStyle",
        "Hidden",
        "-File",
        str(detector),
        "-Guardian",
        "-ParentPid",
        str(os.getpid()),
        "-PythonPath",
        str(Path(sys.executable).resolve()),
    ]
    popen_kwargs: dict[str, object] = {
        "cwd": str(MODULE_DIR),
        "stdin": subprocess.DEVNULL,
        "stdout": subprocess.DEVNULL,
        "stderr": subprocess.DEVNULL,
        "close_fds": True,
        "creationflags": int(getattr(subprocess, "CREATE_NO_WINDOW", 0)),
    }
    try:
        subprocess.Popen(command, **popen_kwargs)
        return True
    except OSError:
        return False


def _set_windows_launcher_app_id() -> None:
    if os.name != "nt":
        return
    try:
        import ctypes

        setter = ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID
        setter.argtypes = [ctypes.c_wchar_p]
        setter.restype = ctypes.c_long
        setter("PC-REHD.CodeX.Launcher")
    except (AttributeError, OSError):
        pass


def _capture_launcher_original_window_icon(root: Any) -> bool:
    """Retain Tk's original feather icon before iconphoto replaces it."""
    if hasattr(root, "_pc_rehd_original_native_class_icons"):
        return True
    if os.name != "nt":
        return False
    try:
        import ctypes
        from ctypes import wintypes

        root.update_idletasks()
        user32 = ctypes.windll.user32
        getter = getattr(user32, "GetClassLongPtrW", user32.GetClassLongW)
        getter.argtypes = [wintypes.HWND, ctypes.c_int]
        getter.restype = ctypes.c_void_p
        for hwnd_value in _native_toplevel_hwnds(root):
            hwnd = wintypes.HWND(hwnd_value)
            big_icon = int(getter(hwnd, -14) or 0)  # GCLP_HICON
            small_icon = int(getter(hwnd, -34) or 0)  # GCLP_HICONSM
            if big_icon or small_icon:
                root._pc_rehd_original_native_class_icons = (big_icon, small_icon)
                return True
    except (AttributeError, OSError, TypeError):
        pass
    return False


def _set_launcher_native_icon_handles(
    root: Any,
    *,
    class_icons: tuple[int, int] | None = None,
) -> bool:
    if os.name != "nt":
        return False
    try:
        import ctypes
        from ctypes import wintypes

        user32 = ctypes.windll.user32
        getter = getattr(user32, "GetClassLongPtrW", user32.GetClassLongW)
        setter = getattr(user32, "SetClassLongPtrW", user32.SetClassLongW)
        getter.argtypes = [wintypes.HWND, ctypes.c_int]
        getter.restype = ctypes.c_void_p
        setter.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_void_p]
        setter.restype = ctypes.c_void_p
        user32.SendMessageW.argtypes = [
            wintypes.HWND,
            wintypes.UINT,
            wintypes.WPARAM,
            wintypes.LPARAM,
        ]
        user32.SendMessageW.restype = wintypes.LPARAM
        updated = False
        for hwnd_value in _native_toplevel_hwnds(root):
            hwnd = wintypes.HWND(hwnd_value)
            current_big = int(getter(hwnd, -14) or 0)
            current_small = int(getter(hwnd, -34) or 0)
            if not (current_big or current_small):
                continue
            if class_icons is not None:
                current_big, current_small = class_icons
                setter(hwnd, -14, ctypes.c_void_p(current_big))
                setter(hwnd, -34, ctypes.c_void_p(current_small))
            user32.SendMessageW(hwnd, 0x0080, 1, current_big)  # WM_SETICON / ICON_BIG
            user32.SendMessageW(hwnd, 0x0080, 0, current_small)  # ICON_SMALL
            user32.SendMessageW(hwnd, 0x0080, 2, current_small)  # ICON_SMALL2
            user32.RedrawWindow(hwnd, None, None, 0x0401)
            updated = True
        return updated
    except (AttributeError, OSError, TypeError):
        return False


def _launcher_umbrella_icon_images(root: Any) -> tuple[Any, ...]:
    cached = getattr(root, "_pc_rehd_launcher_icon_images", ())
    if cached:
        return tuple(cached)
    import tkinter as tk

    images = tuple(
        tk.PhotoImage(
            master=root,
            data=LAUNCHER_ICON_PNG_BASE64[size],
            format="png",
        )
        for size in sorted(LAUNCHER_ICON_PNG_BASE64)
    )
    root._pc_rehd_launcher_icon_images = images
    return images


def _apply_launcher_window_icon(root: Any) -> bool:
    """Install the embedded Umbrella icon for the root and future Toplevels."""
    import tkinter as tk

    _capture_launcher_original_window_icon(root)
    try:
        images = _launcher_umbrella_icon_images(root)
        root.iconphoto(True, *images)
    except tk.TclError:
        return False
    _set_launcher_native_icon_handles(root)
    root._pc_rehd_launcher_icon_style = LAUNCHER_ICON_STYLE_UMBRELLA
    return True


def _restore_launcher_original_window_icon(root: Any) -> bool:
    if not _capture_launcher_original_window_icon(root):
        return False
    original_icons = getattr(root, "_pc_rehd_original_native_class_icons", None)
    if not isinstance(original_icons, tuple) or len(original_icons) != 2:
        return False
    if not _set_launcher_native_icon_handles(root, class_icons=original_icons):
        return False
    root._pc_rehd_launcher_icon_style = LAUNCHER_ICON_STYLE_ORIGINAL
    return True


def _set_launcher_window_icon_style(root: Any, style: str) -> bool:
    normalized = str(style or "").strip().casefold()
    if normalized == LAUNCHER_ICON_STYLE_ORIGINAL:
        return _restore_launcher_original_window_icon(root)
    return _apply_launcher_window_icon(root)


def _relaunch_gui_without_console() -> bool:
    """Move the normal Tk Launcher off python.exe while preserving CLI tools."""
    if os.name != "nt":
        return False
    if str(os.environ.get(MODE_ENV, "") or "").strip().casefold() == AGENT_MODE:
        return False
    if _environment_flag_enabled(KEEP_CONSOLE_ENV):
        return False
    if _environment_flag_enabled(WINDOWED_RELAUNCH_ENV):
        return False
    if any(str(argument).casefold() in CONSOLE_CLI_ARGUMENTS for argument in sys.argv[1:]):
        return False
    if not _windows_console_is_attached():
        return False

    executable = _windowed_python_executable() or Path(sys.executable).resolve()
    environment = _isolated_python_child_environment()
    environment[WINDOWED_RELAUNCH_ENV] = "1"
    try:
        subprocess.Popen(
            [str(executable), str(Path(__file__).resolve()), *sys.argv[1:]],
            cwd=str(MODULE_DIR),
            env=environment,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            close_fds=True,
            creationflags=int(getattr(subprocess, "CREATE_NO_WINDOW", 0)),
        )
    except OSError:
        return False
    return True


_MESSAGE_EDITOR_DEFAULT_TITLE = "01 - 导入 FBX 显式法线 / Import FBX Explicit Normals"
_MESSAGE_EDITOR_DEFAULT_BODY = (
    "中文：\n"
    "导入时，保留 FBX 自带的显式法线应当：\n"
    "Smoothing Groups：关\n"
    "Import Normals：开\n"
    "这样 Mesh 的棱角便会光滑许多。\n\n"
    "English:\n"
    "To preserve explicit normals from an FBX during import:\n"
    "Smoothing Groups: Off\n"
    "Import Normals: On\n"
    "This keeps the FBX explicit normals and gives the Mesh much smoother normal transitions."
)
_MESSAGE_EDITOR_DEFAULT_ID = "explicit-fbx-normals"
# CODEX_MESSAGE_EDITOR_EMBEDDED_BEGIN
# The payload is one UTF-8 JSON object encoded as Base64. Message Editor updates
# only this line, so the Launcher file itself remains the portable authority.
CODEX_MESSAGE_EDITOR_EMBEDDED_B64 = ""
# CODEX_MESSAGE_EDITOR_EMBEDDED_END
_MESSAGE_EDITOR_EMBEDDED_PATTERN = re.compile(
    rb'(?m)^(CODEX_MESSAGE_EDITOR_EMBEDDED_B64\s*=\s*")[^"\r\n]*(")[ \t]*(\r?)$'
)


def _launcher_identity_bytes(source_bytes: bytes) -> bytes:
    """Ignore the portable message payload when identifying executable code."""
    matches = list(_MESSAGE_EDITOR_EMBEDDED_PATTERN.finditer(source_bytes))
    if len(matches) != 1:
        return source_bytes
    return _MESSAGE_EDITOR_EMBEDDED_PATTERN.sub(
        rb'\1<MESSAGE_EDITOR_PAYLOAD>\2\3', source_bytes, count=1
    )


def _launcher_source_sha256(source_bytes: bytes) -> str:
    return hashlib.sha256(_launcher_identity_bytes(source_bytes)).hexdigest().upper()


def _launcher_state_path(log_directory: str | Path | None = None) -> Path:
    root = Path(log_directory).expanduser() if str(log_directory or "").strip() else DEFAULT_LOG_DIR
    return root.resolve(strict=False) / LAUNCHER_STATE_FILE_NAME


def _normalize_long_term_cache_directory(value: str | Path | None) -> Path:
    raw = os.path.expandvars(str(value or "").strip())
    root = Path(raw).expanduser() if raw else DEFAULT_LOG_DIR
    try:
        return root.resolve(strict=False)
    except OSError:
        return Path(os.path.abspath(os.fspath(root)))


def _long_term_cache_locator_path() -> Path:
    return DEFAULT_LOG_DIR.resolve(strict=False) / LONG_TERM_CACHE_LOCATOR_FILE_NAME


def _load_long_term_cache_directory(
    fallback_state: Mapping[str, Any] | None = None,
) -> Path:
    locator_path = _long_term_cache_locator_path()
    try:
        payload = (
            json.loads(locator_path.read_text(encoding="utf-8"))
            if locator_path.is_file()
            else {}
        )
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
        payload = {}
    selected = ""
    if (
        isinstance(payload, dict)
        and str(payload.get("schema", "") or "") == LONG_TERM_CACHE_LOCATOR_SCHEMA
    ):
        selected = str(payload.get("directory", "") or "").strip()
    if not selected and isinstance(fallback_state, Mapping):
        selected = str(fallback_state.get("log_directory", "") or "").strip()
    return _normalize_long_term_cache_directory(selected)


def _write_long_term_cache_directory_locator(directory: str | Path) -> Path:
    selected = _normalize_long_term_cache_directory(directory)
    path = _long_term_cache_locator_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(
        f".{path.name}.{os.getpid()}.{threading.get_ident()}.tmp"
    )
    payload = {
        "schema": LONG_TERM_CACHE_LOCATOR_SCHEMA,
        "directory": str(selected),
        "updated_at": time.strftime("%Y-%m-%dT%H:%M:%S%z", time.localtime()),
    }
    try:
        temporary.write_text(
            json.dumps(payload, ensure_ascii=False, sort_keys=True) + "\n",
            encoding="utf-8",
            newline="\n",
        )
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)
    return selected


def _migrate_long_term_cache_files(
    source_directory: str | Path,
    target_directory: str | Path,
) -> list[str]:
    source = _normalize_long_term_cache_directory(source_directory)
    target = _normalize_long_term_cache_directory(target_directory)
    if source == target:
        return []
    migrated: list[str] = []
    for filename in (
        LAUNCHER_STATE_FILE_NAME,
        EXPORT_SETS_WINDOW_SIZE_FILE_NAME,
        MESSAGE_EDITOR_HISTORY_FILE_NAME,
        EXPORT_PATH_HISTORY_FILE.name,
    ):
        source_path = source / filename
        target_path = target / filename
        if not source_path.is_file() or target_path.exists():
            continue
        target_path.parent.mkdir(parents=True, exist_ok=True)
        temporary = target_path.with_name(
            f".{target_path.name}.{os.getpid()}.{threading.get_ident()}.tmp"
        )
        try:
            shutil.copy2(source_path, temporary)
            os.replace(temporary, target_path)
            migrated.append(filename)
        finally:
            temporary.unlink(missing_ok=True)
    return migrated


def _export_path_history_path(
    log_directory: str | Path | None = None,
) -> Path:
    root = _normalize_long_term_cache_directory(log_directory)
    return root / EXPORT_PATH_HISTORY_FILE.name


def _normalize_manual_texture_path(
    raw: Any,
    *,
    expected_format: str | None = None,
) -> str:
    text = os.path.expandvars(str(raw or "").strip())
    if not text:
        return ""
    try:
        path = Path(text).expanduser().resolve(strict=False)
    except (OSError, RuntimeError, ValueError):
        return ""
    suffix = path.suffix.casefold().lstrip(".")
    if suffix not in {"dds", "tex"}:
        return ""
    normalized_format = str(expected_format or "").strip().casefold()
    if normalized_format and suffix != normalized_format:
        return ""
    return str(path)


def _normalize_manual_texture_path_history(raw: Any) -> list[str]:
    rows = raw if isinstance(raw, (list, tuple)) else ()
    normalized: list[str] = []
    seen: set[str] = set()
    for row in rows:
        path = _normalize_manual_texture_path(row)
        key = os.path.normcase(path).casefold() if path else ""
        if not key or key in seen:
            continue
        seen.add(key)
        normalized.append(path)
        if len(normalized) >= MANUAL_TEXTURE_PATH_HISTORY_LIMIT:
            break
    return normalized


def _normalize_mrl_path(raw: Any) -> str:
    text = os.path.expandvars(str(raw or "").strip().strip('"'))
    if not text:
        return ""
    try:
        path = Path(text).expanduser().resolve(strict=False)
    except (OSError, RuntimeError, ValueError):
        return ""
    if path.suffix.casefold() != ".mrl":
        return ""
    return str(path)


def _normalize_mrl_path_history(raw: Any) -> list[str]:
    rows = raw if isinstance(raw, (list, tuple)) else ()
    normalized: list[str] = []
    seen: set[str] = set()
    for row in rows:
        path = _normalize_mrl_path(row)
        key = os.path.normcase(path).casefold() if path else ""
        if not key or key in seen:
            continue
        seen.add(key)
        normalized.append(path)
    return normalized


def _export_sets_window_size_path(log_directory: str | Path | None = None) -> Path:
    root = Path(log_directory).expanduser() if str(log_directory or "").strip() else DEFAULT_LOG_DIR
    return root.resolve(strict=False) / EXPORT_SETS_WINDOW_SIZE_FILE_NAME


def _normalize_export_sets_window_size(raw: Any) -> list[int]:
    values = raw.get("size", []) if isinstance(raw, dict) else raw
    try:
        width, height = int(values[0]), int(values[1])
    except (IndexError, TypeError, ValueError):
        return []
    return [width, height] if width > 0 and height > 0 else []


def _load_export_sets_window_size(log_directory: str | Path | None = None) -> list[int]:
    path = _export_sets_window_size_path(log_directory)
    try:
        raw = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
        raw = {}
    return _normalize_export_sets_window_size(raw)


def _write_export_sets_window_size(
    width: int, height: int, log_directory: str | Path | None = None
) -> list[int]:
    size = _normalize_export_sets_window_size([width, height])
    if not size:
        return []
    path = _export_sets_window_size_path(log_directory)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(
        f".{path.name}.{os.getpid()}.{threading.get_ident()}.tmp"
    )
    try:
        temporary.write_text(
            json.dumps({"size": size}, ensure_ascii=False, sort_keys=True) + "\n",
            encoding="utf-8",
            newline="\n",
        )
        os.replace(temporary, path)
    finally:
        try:
            if temporary.exists():
                temporary.unlink()
        except OSError:
            pass
    return size


def _normalize_rename_value_tokens(raw: Any) -> list[str]:
    candidates = raw if isinstance(raw, (list, tuple)) else []
    normalized_values: list[str] = []
    seen: set[str] = set()
    for candidate in candidates:
        if isinstance(candidate, bool):
            continue
        try:
            normalized = str(int(str(candidate).strip(), 10))
        except (TypeError, ValueError):
            continue
        if normalized in seen:
            continue
        seen.add(normalized)
        normalized_values.append(normalized)
    return normalized_values


def _normalize_mesh_rename_field(value: Any) -> str:
    field = str(value or "").strip().casefold()
    return field if field in MESH_RENAME_FIELDS else "lod"


def _normalize_rename_value_pins(raw: Any, history: Any) -> list[str]:
    history_values = _normalize_rename_value_tokens(history)
    history_set = set(history_values).difference(RENAME_VALUE_HISTORY_DEFAULTS)
    pinned_set = set(_normalize_rename_value_tokens(raw)).intersection(history_set)
    return [value for value in history_values if value in pinned_set]


def _normalize_rename_value_history(
    raw: Any, pinned_values: Any = (),
) -> list[str]:
    user_values = [
        value
        for value in _normalize_rename_value_tokens(raw)
        if value not in RENAME_VALUE_HISTORY_DEFAULTS
    ]
    pinned_set = set(_normalize_rename_value_tokens(pinned_values))
    pinned = [value for value in user_values if value in pinned_set]
    temporary = [value for value in user_values if value not in pinned_set]
    user_limit = max(
        0, RENAME_VALUE_HISTORY_LIMIT - len(RENAME_VALUE_HISTORY_DEFAULTS)
    )
    pinned = pinned[:user_limit]
    temporary = temporary[: max(0, user_limit - len(pinned))]
    return [*RENAME_VALUE_HISTORY_DEFAULTS, *pinned, *temporary]


def _normalize_launcher_state(raw: Any) -> dict[str, Any]:
    source = raw if isinstance(raw, dict) else {}
    ui_language_preference = str(
        source.get("ui_language_preference", "") or ""
    ).strip().upper()
    if ui_language_preference not in {"CN", "EN"}:
        ui_language_preference = ""
    launcher_icon_style = str(
        source.get("launcher_icon_style", LAUNCHER_ICON_STYLE_UMBRELLA) or ""
    ).strip().casefold()
    if launcher_icon_style not in LAUNCHER_ICON_STYLES:
        launcher_icon_style = LAUNCHER_ICON_STYLE_UMBRELLA
    scene_auto_colors_mode = str(
        source.get("scene_auto_colors_mode", DEFAULT_SCENE_AUTO_COLOR_MODE) or ""
    ).strip().casefold()
    if scene_auto_colors_mode not in SCENE_AUTO_COLOR_MODES:
        scene_auto_colors_mode = DEFAULT_SCENE_AUTO_COLOR_MODE
    try:
        scene_auto_colors_seed = max(
            1, int(source.get("scene_auto_colors_seed", 1) or 1)
        )
    except (TypeError, ValueError):
        scene_auto_colors_seed = 1
    raw_window_sizes = source.get("main_window_sizes", {})
    if not isinstance(raw_window_sizes, dict):
        raw_window_sizes = {}
    main_window_sizes: dict[str, list[int]] = {}
    for page in ("max", "blender"):
        for language in ("CN", "EN"):
            for mode in ("expanded", "collapsed"):
                for scaling in (False, True):
                    surface = f"main-{page}"
                    if scaling:
                        surface += "-scaling"
                    cache_key = _ui_layout_cache_key(language, surface, mode)
                    legacy_key = _ui_layout_cache_key(language, "main", mode)
                    raw_size = (
                        raw_window_sizes.get(cache_key, [])
                        if scaling
                        else raw_window_sizes.get(
                            cache_key,
                            raw_window_sizes.get(
                                legacy_key, raw_window_sizes.get(mode, [])
                            ),
                        )
                    )
                    try:
                        width, height = int(raw_size[0]), int(raw_size[1])
                    except (IndexError, TypeError, ValueError):
                        main_window_sizes[cache_key] = []
                    else:
                        main_window_sizes[cache_key] = (
                            [width, height] if width > 0 and height > 0 else []
                        )
    raw_window_signatures = source.get("main_window_layout_signatures", {})
    if not isinstance(raw_window_signatures, dict):
        raw_window_signatures = {}
    main_window_layout_signatures = {}
    for page in ("max", "blender"):
        for language in ("CN", "EN"):
            for mode in ("expanded", "collapsed"):
                for scaling in (False, True):
                    surface = f"main-{page}"
                    if scaling:
                        surface += "-scaling"
                    cache_key = _ui_layout_cache_key(language, surface, mode)
                    legacy_key = _ui_layout_cache_key(language, "main", mode)
                    main_window_layout_signatures[cache_key] = str(
                        (
                            raw_window_signatures.get(cache_key, "")
                            if scaling
                            else raw_window_signatures.get(
                                cache_key,
                                raw_window_signatures.get(
                                    legacy_key, raw_window_signatures.get(mode, "")
                                ),
                            )
                        )
                        or ""
                    )

    raw_scaling_layout_cache = source.get("main_ui_scaling_layout_cache", {})
    if not isinstance(raw_scaling_layout_cache, dict):
        raw_scaling_layout_cache = {}
    main_ui_scaling_layout_cache: dict[str, dict[str, Any]] = {}
    for page in ("max", "blender"):
        for language in ("CN", "EN"):
            for mode in ("expanded", "collapsed"):
                cache_key = _ui_layout_cache_key(
                    language, f"main-{page}-scaling", mode
                )
                raw_entry = raw_scaling_layout_cache.get(cache_key, {})
                if not isinstance(raw_entry, dict):
                    continue
                try:
                    cached_width = int(raw_entry.get("width", 0) or 0)
                    cached_height = int(raw_entry.get("height", 0) or 0)
                    spacing_scale = float(
                        raw_entry.get("spacing_scale", 1.0) or 1.0
                    )
                    widget_scale = float(
                        raw_entry.get("widget_scale", 1.0) or 1.0
                    )
                except (TypeError, ValueError):
                    continue
                if (
                    cached_width <= 0
                    or cached_height <= 0
                    or not math.isfinite(spacing_scale)
                    or not math.isfinite(widget_scale)
                    or not (
                        MAIN_WINDOW_SCALING_MIN_SCALE
                        <= spacing_scale
                        <= MAIN_WINDOW_SCALING_MAX_SCALE
                    )
                    or not (
                        MAIN_WINDOW_SCALING_MIN_WIDGET_SCALE
                        <= widget_scale
                        <= MAIN_WINDOW_SCALING_MAX_SCALE
                    )
                ):
                    continue
                main_ui_scaling_layout_cache[cache_key] = {
                    "width": cached_width,
                    "height": cached_height,
                    "spacing_scale": spacing_scale,
                    "widget_scale": widget_scale,
                    "signature": str(raw_entry.get("signature", "") or ""),
                }
    raw_window_default_modes = source.get("main_window_default_modes", {})
    if not isinstance(raw_window_default_modes, dict):
        raw_window_default_modes = {}
    main_window_default_modes = {}
    for page in ("max", "blender"):
        for language in ("CN", "EN"):
            for mode in ("expanded", "collapsed"):
                for scaling in (False, True):
                    surface = f"main-{page}"
                    if scaling:
                        surface += "-scaling"
                    cache_key = _ui_layout_cache_key(language, surface, mode)
                    legacy_key = _ui_layout_cache_key(language, "main", mode)
                    main_window_default_modes[cache_key] = bool(
                        (
                            raw_window_default_modes.get(cache_key, False)
                            if scaling
                            else raw_window_default_modes.get(
                                cache_key,
                                raw_window_default_modes.get(
                                    legacy_key, raw_window_default_modes.get(mode, False)
                                ),
                            )
                        )
                    )
    try:
        export_sets_scroll_position = float(
            source.get("export_sets_scroll_position", 0.0) or 0.0
        )
    except (TypeError, ValueError):
        export_sets_scroll_position = 0.0
    if not math.isfinite(export_sets_scroll_position):
        export_sets_scroll_position = 0.0
    export_sets_scroll_position = min(1.0, max(0.0, export_sets_scroll_position))
    def normalize_collapsed_sections(value: Any) -> dict[str, bool]:
        raw_sections = value if isinstance(value, dict) else {}
        return {
            key: bool(raw_sections.get(key, False))
            for key in ("model", "rename", "filter")
        }

    collapsed_sections = normalize_collapsed_sections(
        source.get("collapsed_sections", {})
    )
    # One development build incorrectly used the mode-panel Collapse button
    # to persist all three content sections as collapsed. Repair that exact
    # legacy state once; the new button owns only its own panel.
    if (
        "compact_mode_panel_collapsed" not in source
        and all(collapsed_sections.values())
    ):
        collapsed_sections = {key: False for key in collapsed_sections}
    compact_mode_panel_collapsed = bool(
        source.get("compact_mode_panel_collapsed", False)
    )
    max_collapsed_sections = normalize_collapsed_sections(
        source.get("max_collapsed_sections", collapsed_sections)
    )
    blender_collapsed_sections = normalize_collapsed_sections(
        source.get("blender_collapsed_sections", collapsed_sections)
    )
    max_compact_mode_panel_collapsed = bool(
        source.get("max_compact_mode_panel_collapsed", compact_mode_panel_collapsed)
    )
    blender_compact_mode_panel_collapsed = bool(
        source.get(
            "blender_compact_mode_panel_collapsed", compact_mode_panel_collapsed
        )
    )
    max_advanced_rename_enabled = bool(
        source.get("max_advanced_rename_enabled", False)
    )
    # Blender rebuilds the LOD hierarchy immediately after a Mesh rename, so
    # its rename history controls must always remain available.
    blender_advanced_rename_enabled = True
    legacy_toolbox_geometry = str(
        source.get("toolbox_geometry", "") or ""
    ).strip()
    if TK_WINDOW_GEOMETRY_RE.fullmatch(legacy_toolbox_geometry) is None:
        legacy_toolbox_geometry = ""

    def normalize_toolbox_geometry(value: Any) -> str:
        geometry = str(value or "").strip()
        return (
            geometry
            if TK_WINDOW_GEOMETRY_RE.fullmatch(geometry) is not None
            else ""
        )

    # The old Launcher used one toolbox record for both backends. Migrate that
    # legacy value only to MAX; Blender starts with its own blank page record.
    max_toolbox_geometry = normalize_toolbox_geometry(
        source.get("max_toolbox_geometry", legacy_toolbox_geometry)
    )
    blender_toolbox_geometry = normalize_toolbox_geometry(
        source.get("blender_toolbox_geometry", "")
    )
    # Older builds could save Tk's hidden staging coordinate (+0+0) as the
    # Blender Toolbox position. Only a geometry captured from a visible
    # Toolbox is trusted when that ambiguous coordinate is restored.
    blender_toolbox_geometry_verified = bool(
        source.get("blender_toolbox_geometry_verified", False)
    )
    max_toolbox_visible = bool(
        source.get("max_toolbox_visible", source.get("toolbox_visible", False))
    )
    blender_toolbox_visible = bool(source.get("blender_toolbox_visible", False))
    scene_normals_geometry = str(
        source.get("scene_normals_geometry", "") or ""
    ).strip()
    if TK_WINDOW_GEOMETRY_RE.fullmatch(scene_normals_geometry) is None:
        scene_normals_geometry = ""
    scene_normals_dock_side = str(
        source.get("scene_normals_dock_side", "") or ""
    ).strip().casefold()
    if scene_normals_dock_side not in {"top", "bottom", "left", "right"}:
        scene_normals_dock_side = ""
    try:
        scene_normals_dock_offset = int(
            source.get("scene_normals_dock_offset", 0) or 0
        )
    except (TypeError, ValueError):
        scene_normals_dock_offset = 0
    raw_log_directory = os.path.expandvars(
        str(source.get("log_directory", DEFAULT_LOG_DIR) or DEFAULT_LOG_DIR).strip()
    )
    log_directory = str(
        (Path(raw_log_directory).expanduser() if raw_log_directory else DEFAULT_LOG_DIR).resolve(
            strict=False
        )
    )
    raw_manual_texture_last_paths = source.get("manual_texture_last_paths", {})
    if not isinstance(raw_manual_texture_last_paths, dict):
        raw_manual_texture_last_paths = {}
    manual_texture_last_paths = {
        texture_format: _normalize_manual_texture_path(
            raw_manual_texture_last_paths.get(texture_format, ""),
            expected_format=texture_format,
        )
        for texture_format in ("dds", "tex")
    }
    manual_texture_path_history = _normalize_manual_texture_path_history(
        source.get("manual_texture_path_history", [])
    )
    history_keys = {
        os.path.normcase(path).casefold() for path in manual_texture_path_history
    }
    for texture_format in reversed(("dds", "tex")):
        path = manual_texture_last_paths[texture_format]
        key = os.path.normcase(path).casefold() if path else ""
        if key and key not in history_keys:
            manual_texture_path_history.insert(0, path)
            history_keys.add(key)
    manual_texture_path_history = manual_texture_path_history[
        :MANUAL_TEXTURE_PATH_HISTORY_LIMIT
    ]
    mrl_last_path = _normalize_mrl_path(source.get("mrl_last_path", ""))
    mrl_path_history = _normalize_mrl_path_history(
        source.get("mrl_path_history", [])
    )
    if mrl_last_path:
        mrl_key = os.path.normcase(mrl_last_path).casefold()
        mrl_path_history = [
            mrl_last_path,
            *[
                path
                for path in mrl_path_history
                if os.path.normcase(path).casefold() != mrl_key
            ],
        ]
    mrl_save_decoded_textures = bool(
        source.get(
            "mrl_save_decoded_textures",
            source.get("save_decoded_textures", False),
        )
    )
    mrl_open_decoded_texture_directory = bool(
        source.get("mrl_open_decoded_texture_directory", True)
    )
    import_texture_folder_cleanup_disabled = bool(
        source.get("import_texture_folder_cleanup_disabled", False)
    )
    raw_model_option_preferences = source.get("model_option_preferences", {})
    if not isinstance(raw_model_option_preferences, dict):
        raw_model_option_preferences = {}
    model_option_preferences = {
        "import_normals": bool(
            raw_model_option_preferences.get("import_normals", True)
        ),
        "import_textures": bool(
            raw_model_option_preferences.get("import_textures", False)
        ),
        "reset_scene_on_import": bool(
            raw_model_option_preferences.get("reset_scene_on_import", False)
        ),
        "check_source": bool(
            raw_model_option_preferences.get("check_source", True)
        ),
        "export_map2": bool(
            raw_model_option_preferences.get("export_map2", False)
        ),
        "uv_half_safe": bool(
            raw_model_option_preferences.get("uv_half_safe", True)
        ),
        "log_mode": bool(
            raw_model_option_preferences.get("log_mode", True)
        ),
    }
    raw_export_option_preferences = source.get("export_option_preferences", {})
    if not isinstance(raw_export_option_preferences, dict):
        raw_export_option_preferences = {}
    export_option_preferences = {
        "append_newmod_suffix": bool(
            raw_export_option_preferences.get("append_newmod_suffix", True)
        ),
        "auto_rename_source_mod": bool(
            raw_export_option_preferences.get("auto_rename_source_mod", False)
        ),
        "overwrite_source_mod": bool(
            raw_export_option_preferences.get("overwrite_source_mod", False)
        ),
        "legacy_export": bool(
            raw_export_option_preferences.get("legacy_export", False)
        ),
        "quick_select_to_modify": bool(
            raw_export_option_preferences.get("quick_select_to_modify", False)
        ),
    }
    if export_option_preferences["overwrite_source_mod"]:
        export_option_preferences["append_newmod_suffix"] = False
    rename_value = str(source.get("rename_value", "255") or "255").strip()
    rename_field = _normalize_mesh_rename_field(
        source.get("rename_field", "lod")
    )
    raw_rename_value_history = source.get("rename_value_history")
    if not isinstance(raw_rename_value_history, (list, tuple)):
        raw_rename_value_history = [rename_value]
    raw_rename_value_pins = source.get("rename_value_pinned_values", [])
    rename_value_history = _normalize_rename_value_history(
        raw_rename_value_history, raw_rename_value_pins
    )
    rename_value_pinned_values = _normalize_rename_value_pins(
        raw_rename_value_pins, rename_value_history
    )
    blender_mode_enabled = bool(source.get("blender_mode_enabled", False))
    advanced_options_visible = bool(source.get("advanced_options_visible", True))
    blender_advanced_options_visible = bool(
        source.get("blender_advanced_options_visible", False)
    )
    blender_mode_restore_advanced_visible = bool(
        source.get(
            "blender_mode_restore_advanced_visible", advanced_options_visible
        )
    )
    max_scaling_mode_enabled = bool(
        source.get(
            "max_scaling_mode_enabled",
            source.get("scaling_mode_enabled", False),
        )
    )
    blender_scaling_mode_enabled = bool(
        source.get("blender_scaling_mode_enabled", False)
    )
    raw_scaling_mode_enabled_by_surface = source.get(
        "scaling_mode_enabled_by_surface", {}
    )
    if not isinstance(raw_scaling_mode_enabled_by_surface, dict):
        raw_scaling_mode_enabled_by_surface = {}
    scaling_mode_enabled_by_surface = {}
    for page, fallback in (
        ("max", max_scaling_mode_enabled),
        ("blender", blender_scaling_mode_enabled),
    ):
        for language in ("CN", "EN"):
            surface = f"{page}:{language}"
            scaling_mode_enabled_by_surface[surface] = bool(
                raw_scaling_mode_enabled_by_surface.get(surface, fallback)
            )
    # This is a per-Launcher safety switch. A new Launcher run always restores
    # automatic repair; a one-time stop is stored beside Blender's startup bridge.
    blender_fbx_hierarchy_auto_repair_enabled = True
    raw_blender_executable = os.path.expandvars(
        str(source.get("blender_executable", "") or "").strip()
    )
    blender_executable = (
        str(Path(raw_blender_executable).expanduser().resolve(strict=False))
        if raw_blender_executable
        else ""
    )
    return {
        "schema": LAUNCHER_STATE_SCHEMA,
        "ui_language_preference": ui_language_preference,
        "launcher_icon_style": launcher_icon_style,
        "always_on_top_enabled": bool(
            source.get("always_on_top_enabled", True)
        ),
        "dark_mode_enabled": bool(
            source.get("dark_mode_enabled", _windows_prefers_dark_mode())
        ),
        "scene_auto_colors_enabled": bool(source.get("scene_auto_colors_enabled", False)),
        "scene_auto_colors_mode": scene_auto_colors_mode,
        "scene_auto_colors_seed": scene_auto_colors_seed,
        "rename_value": rename_value,
        "rename_field": rename_field,
        "rename_value_history": rename_value_history,
        "rename_value_pinned_values": rename_value_pinned_values,
        "advanced_options_visible": advanced_options_visible,
        "blender_mode_enabled": blender_mode_enabled,
        "blender_advanced_options_visible": blender_advanced_options_visible,
        "blender_mode_restore_advanced_visible": (
            blender_mode_restore_advanced_visible
        ),
        "scaling_mode_enabled": max_scaling_mode_enabled,
        "max_scaling_mode_enabled": max_scaling_mode_enabled,
        "blender_scaling_mode_enabled": blender_scaling_mode_enabled,
        "scaling_mode_enabled_by_surface": scaling_mode_enabled_by_surface,
        "blender_fbx_hierarchy_auto_repair_enabled": (
            blender_fbx_hierarchy_auto_repair_enabled
        ),
        "blender_executable": blender_executable,
        # Legacy keys mirror MAX. New keys keep MAX and Blender windows apart.
        "toolbox_visible": max_toolbox_visible,
        "toolbox_geometry": max_toolbox_geometry,
        "max_toolbox_visible": max_toolbox_visible,
        "blender_toolbox_visible": blender_toolbox_visible,
        "max_toolbox_geometry": max_toolbox_geometry,
        "blender_toolbox_geometry": blender_toolbox_geometry,
        "blender_toolbox_geometry_verified": blender_toolbox_geometry_verified,
        "scene_normals_visible": bool(source.get("scene_normals_visible", False)),
        "scene_normals_geometry": scene_normals_geometry,
        "scene_normals_dock_side": scene_normals_dock_side,
        "scene_normals_dock_offset": scene_normals_dock_offset,
        "main_window_sizes": main_window_sizes,
        "main_window_layout_signatures": main_window_layout_signatures,
        "main_window_default_modes": main_window_default_modes,
        "main_ui_scaling_layout_cache": main_ui_scaling_layout_cache,
        "export_sets_scroll_position": export_sets_scroll_position,
        # Legacy keys mirror MAX so an older Launcher build can still open the
        # saved state. New builds keep each backend's page state independent.
        "collapsed_sections": max_collapsed_sections,
        "max_collapsed_sections": max_collapsed_sections,
        "blender_collapsed_sections": blender_collapsed_sections,
        "compact_mode_panel_collapsed": max_compact_mode_panel_collapsed,
        "max_compact_mode_panel_collapsed": max_compact_mode_panel_collapsed,
        "blender_compact_mode_panel_collapsed": (
            blender_compact_mode_panel_collapsed
        ),
        "max_advanced_rename_enabled": max_advanced_rename_enabled,
        "blender_advanced_rename_enabled": blender_advanced_rename_enabled,
        "manual_texture_last_paths": manual_texture_last_paths,
        "manual_texture_path_history": manual_texture_path_history,
        "mrl_last_path": mrl_last_path,
        "mrl_path_history": mrl_path_history,
        "mrl_save_decoded_textures": mrl_save_decoded_textures,
        "mrl_open_decoded_texture_directory": mrl_open_decoded_texture_directory,
        "import_texture_folder_cleanup_disabled": (
            import_texture_folder_cleanup_disabled
        ),
        "model_option_preferences": model_option_preferences,
        "export_option_preferences": export_option_preferences,
        "log_directory": log_directory,
    }


def _load_launcher_state(log_directory: str | Path | None = None) -> dict[str, Any]:
    path = _launcher_state_path(log_directory)
    try:
        raw = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
        raw = {}
    return _normalize_launcher_state(raw)


def _write_launcher_state(
    state: dict[str, Any], log_directory: str | Path | None = None
) -> dict[str, Any]:
    normalized = _normalize_launcher_state(state)
    path = _launcher_state_path(log_directory)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(
        f".{path.name}.{os.getpid()}.{threading.get_ident()}.tmp"
    )
    try:
        temporary.write_text(
            json.dumps(normalized, ensure_ascii=False, sort_keys=True) + "\n",
            encoding="utf-8",
            newline="\n",
        )
        os.replace(temporary, path)
    finally:
        try:
            if temporary.exists():
                temporary.unlink()
        except OSError:
            pass
    return normalized


def _embedded_message_editor_document() -> dict[str, Any]:
    try:
        payload = base64.b64decode(CODEX_MESSAGE_EDITOR_EMBEDDED_B64, validate=True)
        raw = json.loads(payload.decode("utf-8"))
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError):
        raw = None
    return _normalize_message_editor_snapshot(raw)


def _message_editor_history_path(log_directory: str | Path | None = None) -> Path:
    root = Path(log_directory).expanduser() if str(log_directory or "").strip() else DEFAULT_LOG_DIR
    return root.resolve(strict=False) / MESSAGE_EDITOR_HISTORY_FILE_NAME


def _normalize_message_editor_snapshot(raw: Any, fallback: dict[str, Any] | None = None) -> dict[str, Any]:
    default_entry = {
        "id": _MESSAGE_EDITOR_DEFAULT_ID,
        "title": _MESSAGE_EDITOR_DEFAULT_TITLE,
        "body": _MESSAGE_EDITOR_DEFAULT_BODY,
    }
    default_second_entry = {
        "id": "message-7d8acaf4d8244275bc37c81ba9a88bf0",
        "title": "02 - 新消息",
        "body": "",
    }
    base = {
        "entries": [default_entry, default_second_entry],
        "selected_id": _MESSAGE_EDITOR_DEFAULT_ID,
        "expanded": True,
        "continuous_list": True,
    }
    if isinstance(fallback, dict):
        base = _normalize_message_editor_snapshot(fallback)
    if not isinstance(raw, dict):
        return copy.deepcopy(base)

    # V1 stored one title/body pair. Promote it to the V2 multi-message notebook.
    if "entries" not in raw:
        title = str(raw.get("title", base["entries"][0]["title"]) or "")
        body = str(raw.get("body", base["entries"][0]["body"]) or "")
        entry_id = str(raw.get("id", "") or "").strip()
        if not entry_id:
            if title == _MESSAGE_EDITOR_DEFAULT_TITLE and body == _MESSAGE_EDITOR_DEFAULT_BODY:
                entry_id = _MESSAGE_EDITOR_DEFAULT_ID
            else:
                digest = hashlib.sha256(f"{title}\0{body}".encode("utf-8")).hexdigest()[:16]
                entry_id = f"message-{digest}"
        entries = [{"id": entry_id, "title": title, "body": body}]
        if entry_id == _MESSAGE_EDITOR_DEFAULT_ID:
            entries.append(copy.deepcopy(default_second_entry))
        return {
            "entries": entries,
            "selected_id": entry_id,
            "expanded": bool(raw.get("expanded", base["expanded"])),
            "continuous_list": True,
        }

    entries: list[dict[str, str]] = []
    used_ids: set[str] = set()
    raw_entries = raw.get("entries", [])
    if isinstance(raw_entries, list):
        for index, item in enumerate(raw_entries):
            if not isinstance(item, dict):
                continue
            title = str(item.get("title", "") or "")
            body = str(item.get("body", "") or "")
            entry_id = str(item.get("id", "") or "").strip()
            if not entry_id or entry_id in used_ids:
                digest = hashlib.sha256(
                    f"{index}\0{title}\0{body}".encode("utf-8")
                ).hexdigest()[:16]
                entry_id = f"message-{digest}"
                suffix = 2
                while entry_id in used_ids:
                    entry_id = f"message-{digest}-{suffix}"
                    suffix += 1
            used_ids.add(entry_id)
            entries.append({"id": entry_id, "title": title, "body": body})
    if (
        not bool(raw.get("continuous_list", False))
        and len(entries) == 1
        and entries[0] == default_entry
    ):
        entries.append(copy.deepcopy(default_second_entry))
        used_ids.add(default_second_entry["id"])
    selected_id = str(raw.get("selected_id", "") or "")
    if selected_id not in used_ids:
        selected_id = entries[0]["id"] if entries else ""
    return {
        "entries": entries,
        "selected_id": selected_id,
        "expanded": bool(raw.get("expanded", base["expanded"])),
        "continuous_list": True,
    }


def _load_message_editor_state(log_directory: str | Path | None = None) -> dict[str, Any]:
    embedded_document = _embedded_message_editor_document()
    default = {
        "schema": MESSAGE_EDITOR_STATE_SCHEMA,
        "document": embedded_document,
        "history": [],
        "redo": [],
        "window": {
            "geometry": "",
            "dock_side": "",
            "dock_offset": 0,
            "expanded_height": 360,
            "visible": False,
        },
    }
    path = _message_editor_history_path(log_directory)
    try:
        raw_text = path.read_text(encoding="utf-8") if path.is_file() else ""
        first_line = raw_text.splitlines()[0] if raw_text else ""
        raw = json.loads(first_line) if first_line else {}
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
        raw = {}
    if not isinstance(raw, dict):
        return default
    raw_document = raw.get("document")
    saved_document = (
        _normalize_message_editor_snapshot(raw_document, fallback=embedded_document)
        if isinstance(raw_document, dict)
        else embedded_document
    )
    history: list[dict[str, Any]] = []
    raw_history = raw.get("history", [])
    if isinstance(raw_history, list):
        for item in raw_history[-MESSAGE_EDITOR_MAX_HISTORY:]:
            normalized = _normalize_message_editor_snapshot(item)
            if normalized != saved_document and normalized not in history:
                history.append(normalized)
    redo: list[dict[str, Any]] = []
    raw_redo = raw.get("redo", [])
    if isinstance(raw_redo, list):
        for item in raw_redo[-MESSAGE_EDITOR_MAX_HISTORY:]:
            normalized = _normalize_message_editor_snapshot(item)
            if normalized != saved_document and normalized not in redo:
                redo.append(normalized)
    raw_window = raw.get("window", {})
    window = raw_window if isinstance(raw_window, dict) else {}
    try:
        dock_offset = int(window.get("dock_offset", 0) or 0)
    except (TypeError, ValueError):
        dock_offset = 0
    try:
        expanded_height = max(260, int(window.get("expanded_height", 360) or 360))
    except (TypeError, ValueError):
        expanded_height = 360
    return {
        "schema": MESSAGE_EDITOR_STATE_SCHEMA,
        "document": saved_document,
        "history": history[-MESSAGE_EDITOR_MAX_HISTORY:],
        "redo": redo[-MESSAGE_EDITOR_MAX_HISTORY:],
        "window": {
            "geometry": str(window.get("geometry", "") or ""),
            "dock_side": str(window.get("dock_side", "") or ""),
            "dock_offset": dock_offset,
            "expanded_height": expanded_height,
            "visible": bool(window.get("visible", False)),
        },
    }


def _write_embedded_message_editor_document(document: dict[str, Any]) -> bool:
    normalized = _normalize_message_editor_snapshot(document)
    encoded = base64.b64encode(
        json.dumps(normalized, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    )
    path = Path(__file__).resolve()
    temporary: Path | None = None
    try:
        source_bytes = path.read_bytes()
        matches = list(_MESSAGE_EDITOR_EMBEDDED_PATTERN.finditer(source_bytes))
        if len(matches) != 1:
            return False
        replacement = (
            matches[0].group(1) + encoded + matches[0].group(2) + matches[0].group(3)
        )
        if matches[0].group(0) == replacement:
            return True
        updated = source_bytes[:matches[0].start()] + replacement + source_bytes[matches[0].end():]
        compile(updated, str(path), "exec")
        temporary = path.with_name(f".{path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp")
        temporary.write_bytes(updated)
        os.replace(temporary, path)
        return True
    except (OSError, TypeError, ValueError, SyntaxError):
        return False
    finally:
        if temporary is not None:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                pass


def _write_message_editor_history(
    document: dict[str, Any],
    history: list[dict[str, Any]],
    redo: list[dict[str, Any]],
    *,
    log_directory: str | Path | None = None,
    geometry: str = "",
    dock_side: str = "",
    dock_offset: int = 0,
    expanded_height: int = 360,
    visible: bool = False,
) -> bool:
    path = _message_editor_history_path(log_directory)
    temporary: Path | None = None
    payload = {
        "schema": MESSAGE_EDITOR_STATE_SCHEMA,
        "document": _normalize_message_editor_snapshot(document),
        "history": [
            _normalize_message_editor_snapshot(item)
            for item in history[-MESSAGE_EDITOR_MAX_HISTORY:]
        ],
        "redo": [
            _normalize_message_editor_snapshot(item)
            for item in redo[-MESSAGE_EDITOR_MAX_HISTORY:]
        ],
        "window": {
            "geometry": str(geometry or ""),
            "dock_side": str(dock_side or ""),
            "dock_offset": int(dock_offset or 0),
            "expanded_height": max(260, int(expanded_height or 360)),
            "visible": bool(visible),
        },
        "updated_at": time.strftime("%Y-%m-%dT%H:%M:%S%z", time.localtime()),
    }
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(f".{path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp")
        header = json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
        lines = [
            "PC-REHD Code X Message Editor - latest 3 undo and redo versions",
            "The live document is stored here and is embedded in PC-REHD Code X Launcher.py when the editor closes.",
        ]
        for index, item in enumerate(reversed(payload["history"]), start=1):
            lines.extend(("", f"===== HISTORY {index} / {len(payload['history'])} ====="))
            entries = item.get("entries", [])
            if not entries:
                lines.append("[No messages]")
            for entry_index, entry in enumerate(entries, start=1):
                marker = " *" if entry.get("id") == item.get("selected_id") else ""
                lines.extend((
                    f"----- MESSAGE {entry_index}{marker} -----",
                    str(entry.get("title", "")),
                    str(entry.get("body", "")),
                ))
        for index, item in enumerate(reversed(payload["redo"]), start=1):
            lines.extend(("", f"===== REDO {index} / {len(payload['redo'])} ====="))
            entries = item.get("entries", [])
            if not entries:
                lines.append("[No messages]")
            for entry_index, entry in enumerate(entries, start=1):
                marker = " *" if entry.get("id") == item.get("selected_id") else ""
                lines.extend((
                    f"----- MESSAGE {entry_index}{marker} -----",
                    str(entry.get("title", "")),
                    str(entry.get("body", "")),
                ))
        temporary.write_text(header + "\n" + "\n".join(lines) + "\n", encoding="utf-8")
        os.replace(temporary, path)
        return True
    except (OSError, TypeError, ValueError):
        return False
    finally:
        if temporary is not None:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                pass


def _emergency_health_log_roots(preferred: str | Path | None = None) -> list[Path]:
    """Return independent fallbacks for failures that cannot load Bootstrap."""
    candidates: list[Path] = []

    def add(path_value: str | Path | None) -> None:
        if path_value in {None, ""}:
            return
        candidate = Path(os.path.expandvars(str(path_value))).expanduser()
        key = os.path.normcase(os.path.abspath(os.fspath(candidate)))
        if all(os.path.normcase(os.path.abspath(os.fspath(existing))) != key for existing in candidates):
            candidates.append(candidate)

    add(preferred)
    add(DEFAULT_LOG_DIR)
    add(Path(os.environ["LOCALAPPDATA"]) / "PC_REHD_Code_X" if os.environ.get("LOCALAPPDATA") else None)
    add(Path.home() / "PC_REHD_Code_X")
    return candidates


def _write_emergency_health_issue(
    *,
    preferred_log_dir: str | Path | None,
    action: str,
    detail: str,
    error: BaseException,
    max_process_id: int = 0,
    request_id: str = "",
) -> str:
    """Write one classified issue without importing Bootstrap or other project modules."""
    last_error = ""
    for root in _emergency_health_log_roots(preferred_log_dir):
        log_path = root / BOOTSTRAP_HEALTH_LOG_FILE_NAME
        temporary: Path | None = None
        try:
            root.mkdir(parents=True, exist_ok=True)
            try:
                state = json.loads(log_path.read_text(encoding="utf-8")) if log_path.is_file() else {}
            except Exception:
                state = {}
            if not isinstance(state, dict):
                state = {}
            active = state.setdefault("active_issues", {})
            if not isinstance(active, dict):
                active = {}
                state["active_issues"] = active
            state.setdefault("schema", "pc-rehd-code-x-health-log-v2")
            state.setdefault("description", "Only current error incidents and permanent major-bug alarms are retained.")
            state.setdefault("major_bug_alarms", {})
            error_type = type(error).__name__.upper()
            action_key = re.sub(r"[^A-Z0-9_]+", "_", str(action).upper()).strip("_") or "UNKNOWN"
            category = f"LAUNCHER_EMERGENCY:{action_key}:{error_type}"
            now = time.time()
            timestamp = time.strftime("%Y-%m-%dT%H:%M:%S%z", time.localtime(now))
            record = active.get(category)
            if not isinstance(record, dict):
                record = {
                    "category": category,
                    "severity": "ERROR",
                    "first_seen_epoch": now,
                    "first_seen": timestamp,
                    "occurrences": 0,
                }
                active[category] = record
            record.update(
                {
                    "summary": f"Launcher could not complete {action} and the normal Bootstrap reporter was unavailable.",
                    "details": {
                        "action": str(action),
                        "max_process_id": max(0, int(max_process_id or 0)),
                        "request_id": str(request_id),
                        "operation_error": str(detail),
                        "reporter_error": f"{type(error).__name__}: {error}",
                        "traceback": traceback.format_exc()[-4000:],
                    },
                    "last_seen_epoch": now,
                    "last_seen": timestamp,
                    "occurrences": int(record.get("occurrences", 0) or 0) + 1,
                }
            )
            state["updated"] = timestamp
            temporary = log_path.with_name(f".{log_path.name}.{os.getpid()}.{uuid.uuid4().hex}.tmp")
            temporary.write_text(
                json.dumps(state, ensure_ascii=False, indent=2, sort_keys=True, default=str),
                encoding="utf-8",
            )
            os.replace(temporary, log_path)
            return str(log_path)
        except Exception as fallback_error:
            last_error = f"{type(fallback_error).__name__}: {fallback_error}"
        finally:
            if temporary is not None:
                try:
                    temporary.unlink(missing_ok=True)
                except OSError:
                    pass
    try:
        print(
            f"[{APP_NAME}] emergency health log failed | action={action} | "
            f"error={type(error).__name__}: {error} | fallback={last_error}",
            file=sys.stderr,
        )
    except Exception:
        pass
    return ""

MESH_SLOT_RE = re.compile(r"(?i)(?:^|[^A-Z0-9])MESH[_\s-]*0*(\d+)(?:$|[^0-9])")
STANDARD_RE6_EXPORT_MESH_NAME_RE = re.compile(r"(?i)^Mesh_(\d{3,})(?=$|[^0-9])")
COMPACT_BLENDER_RE6_MESH_NAME_RE = re.compile(
    r"(?i)^(?P<mesh_slot>0*[1-9]\d*)_X(?P<header_fvf>[0-9A-F]{8})_"
    r"(?P<lod_level>-?\d+)_(?P<material_id>-?\d+)_(?P<group_id>-?\d+)_"
    r"(?P<display_mode>-?\d+)_(?P<mesh_type>-?\d+)"
    r"(?P<import_suffix>_Import(?:[2-9]|[1-9]\d+)(?:_[1-9]\d*)?)?$"
)
# Pre-short-name Launcher builds appended a long Header token after an
# otherwise complete Blender compact name.  Read it as a compatibility form;
# current renames always write the canonical compact form instead.
LEGACY_COMPACT_BLENDER_RE6_MESH_NAME_RE = re.compile(
    r"(?i)^(?P<mesh_slot>0*[1-9]\d*)_X(?P<header_fvf>[0-9A-F]{8})_"
    r"(?P<lod_level>-?\d+)_(?P<material_id>-?\d+)_(?P<group_id>-?\d+)_"
    r"(?P<display_mode>-?\d+)_(?P<mesh_type>-?\d+)"
    r"(?P<legacy_suffix>(?:_(?:Import(?:[2-9]|[1-9]\d+)(?:_[1-9]\d*)?|"
    r"LODx-?\d+|MatID:-?\d+|Group:-?\d+|DisplayMode:-?\d+|Type:-?\d+))*)$"
)
LEGACY_COMPACT_BLENDER_RE6_MESH_SUFFIX_TOKEN_RE = re.compile(
    r"(?i)_(?:"
    r"(?P<import_suffix>Import(?:[2-9]|[1-9]\d+)(?:_[1-9]\d*)?)|"
    r"LODx(?P<lod_level>-?\d+)|"
    r"MatID:(?P<material_id>-?\d+)|"
    r"Group:(?P<group_id>-?\d+)|"
    r"DisplayMode:(?P<display_mode>-?\d+)|"
    r"Type:(?P<mesh_type>-?\d+)"
    r")"
)


def _parse_compact_blender_re6_mesh_name(value: Any) -> dict[str, Any] | None:
    """Retired compact names are deliberately never accepted as RE6 Headers."""
    _ = value
    return None


def _parse_full_blender_re6_mesh_name(value: Any) -> dict[str, Any] | None:
    """Return the Header facts encoded by the canonical full RE6 Mesh name."""
    text = str(value or "").strip()
    match = _MAX_BLENDER_FBX_FULL_MESH_NAME_RE.fullmatch(text)
    if match is None:
        return None
    return {
        "scene_name_mesh_slot": int(match.group("mesh_slot")),
        "header_fvf": "0x" + str(match.group("header_fvf")).upper(),
        "lod_level": int(match.group("lod_level")),
        "material_id": int(match.group("material_id")),
        "group_id": int(match.group("group_id")),
        "display_mode": int(match.group("display_mode")),
        "mesh_type": int(match.group("mesh_type")),
        "import_suffix": _normalize_blender_re6_import_suffix(text),
    }


# 3ds Max can truncate a long RE6 FBX Mesh name after DisplayMode before
# Blender sees it.  Do not classify generic Mesh_### names as this condition:
# every Header token through DisplayMode must be present first.
_BLENDER_TRUNCATED_MAX_FBX_MESH_NAME_RE = re.compile(
    r"(?i)^Mesh_(?P<mesh_slot>0*\d+)_"
    r"(?:X|0X)?(?P<header_fvf>[0-9A-F]{8})_"
    r"LODx(?P<lod_level>-?\d+)_MatID:(?P<material_id>-?\d+)_"
    r"Group:(?P<group_id>-?\d+)_DisplayMode:(?P<display_mode>-?\d+)"
    r"(?P<truncated_tail>.*)$"
)
_BLENDER_RE6_MESH_NAME_PREFIX_RE = re.compile(r"(?i)^Mesh_0*\d+(?:_|$)")


def _normalize_blender_re6_import_suffix(value: Any) -> str:
    """Return Blender's canonical repeated-import suffix from either spelling."""
    match = _MAX_BLENDER_FBX_IMPORT_SUFFIX_RE.search(str(value or "").strip())
    if match is None:
        return ""
    ordinal = int(match.group("ordinal"))
    duplicate = int(match.group("duplicate") or 0)
    return f"_Import{ordinal}" + (f"_{duplicate}" if duplicate else "")


def _blender_re6_header_key(facts: Mapping[str, Any]) -> tuple[int, str, int, int, int, int, int]:
    """Build the complete MOD Header identity encoded by a Blender Mesh name."""
    fvf = str(facts.get("header_fvf", "") or "").strip().upper()
    if fvf.startswith("0X"):
        fvf = fvf[2:]
    if re.fullmatch(r"[0-9A-F]{8}", fvf) is None:
        raise ValueError("RE6 Mesh Header has no valid eight-digit FVF")
    try:
        return (
            int(facts["scene_name_mesh_slot"]),
            fvf,
            int(facts["lod_level"]),
            int(facts["material_id"]),
            int(facts["group_id"]),
            int(facts["display_mode"]),
            int(facts["mesh_type"]),
        )
    except (KeyError, TypeError, ValueError, OverflowError) as exc:
        raise ValueError("RE6 Mesh Header is incomplete") from exc


def _blender_re6_header_prefix_key(facts: Mapping[str, Any]) -> tuple[int, str, int, int, int, int]:
    """Return the Header portion left intact by the Max FBX truncation."""
    key = _blender_re6_header_key(
        {
            **dict(facts),
            "mesh_type": int(facts.get("mesh_type", 0) or 0),
        }
    )
    return key[:6]


def _parse_blender_truncated_max_fbx_mesh_name(value: Any) -> dict[str, Any] | None:
    """Read a Max long Mesh name that lost its Type field after DisplayMode."""
    text = str(value or "").strip()
    if not text:
        return None
    if (
        _parse_compact_blender_re6_mesh_name(text) is not None
        or _MAX_BLENDER_FBX_FULL_MESH_NAME_RE.fullmatch(text) is not None
    ):
        return None
    match = _BLENDER_TRUNCATED_MAX_FBX_MESH_NAME_RE.fullmatch(text)
    if match is None:
        return None
    return {
        "scene_name_mesh_slot": int(match.group("mesh_slot")),
        "header_fvf": "0x" + str(match.group("header_fvf")).upper(),
        "lod_level": int(match.group("lod_level")),
        "material_id": int(match.group("material_id")),
        "group_id": int(match.group("group_id")),
        "display_mode": int(match.group("display_mode")),
        "import_suffix": _normalize_blender_re6_import_suffix(
            match.group("truncated_tail")
        ),
    }


def _blender_scene_mesh_name_rows(
    scene_contract: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Return every physical Blender Mesh needed for a name-only repair check."""
    raw_nodes = scene_contract.get("nodes", [])
    if not isinstance(raw_nodes, list):
        raw_nodes = scene_contract.get("meshes", [])
    if not isinstance(raw_nodes, list):
        return []
    rows: list[dict[str, Any]] = []
    seen_handles: set[int] = set()
    for raw_node in raw_nodes:
        if not isinstance(raw_node, Mapping):
            continue
        if not bool(raw_node.get("is_mesh", True)):
            continue
        try:
            handle = int(raw_node.get("scene_node_handle", 0) or 0)
        except (TypeError, ValueError, OverflowError):
            continue
        if handle <= 0 or handle in seen_handles:
            continue
        name = str(raw_node.get("scene_node", "") or "").strip()
        if not name or _is_mod_auxiliary_scene_node_name(name):
            continue
        seen_handles.add(handle)
        rows.append({"handle": handle, "name": name})
    return rows


def _blender_max_fbx_name_repair_candidates(
    scene_contract: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Find only Max-style long names truncated after DisplayMode."""
    candidates: list[dict[str, Any]] = []
    for row in _blender_scene_mesh_name_rows(scene_contract):
        facts = _parse_blender_truncated_max_fbx_mesh_name(row["name"])
        if facts is not None:
            candidates.append({**row, "facts": facts})
    return candidates


def _blender_max_fbx_name_repair_signature(
    candidates: Iterable[Mapping[str, Any]],
) -> str:
    rows = sorted(
        (
            int(row.get("handle", 0) or 0),
            str(row.get("name", "") or ""),
        )
        for row in candidates
    )
    return hashlib.sha256(
        json.dumps(rows, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def _blender_full_mesh_name_from_header_key(
    key: tuple[int, str, int, int, int, int, int],
    *,
    import_suffix: str = "",
) -> str:
    mesh_slot, fvf, lod_level, material_id, group_id, display_mode, mesh_type = key
    return (
        f"Mesh_{mesh_slot:03d}_{fvf}_LODx{lod_level}_MatID:{material_id}_"
        f"Group:{group_id}_DisplayMode:{display_mode}_Type:{mesh_type}{import_suffix}"
    )


def _build_blender_max_fbx_name_repair_plan(
    scene_contract: Mapping[str, Any],
    import_scene: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Validate one selected MOD against Blender, then plan only safe name repairs."""
    raw_meshes = import_scene.get("meshes", [])
    if not isinstance(raw_meshes, list) or not raw_meshes:
        raise ValueError("Selected MOD did not contain any Mesh Header records")
    source_keys: list[tuple[int, str, int, int, int, int, int]] = []
    source_by_prefix: dict[tuple[int, str, int, int, int, int], set[tuple[int, str, int, int, int, int, int]]] = {}
    for raw_mesh in raw_meshes:
        if not isinstance(raw_mesh, Mapping):
            raise ValueError("Selected MOD returned an invalid Mesh Header record")
        facts = _parse_full_blender_re6_mesh_name(raw_mesh.get("node_name", ""))
        if facts is None:
            raise ValueError("Selected MOD did not produce complete RE6 Mesh Header names")
        key = _blender_re6_header_key(facts)
        source_keys.append(key)
        source_by_prefix.setdefault(key[:6], set()).add(key)
    source_counter = Counter(source_keys)

    scene_rows = _blender_scene_mesh_name_rows(scene_contract)
    if not scene_rows:
        raise ValueError("Current Blender scene does not contain any Mesh nodes")
    normalized_rows: list[dict[str, Any]] = []
    malformed_mesh_names: list[str] = []
    truncated_count = 0
    for row in scene_rows:
        name = str(row["name"])
        full_facts = _parse_full_blender_re6_mesh_name(name)
        truncated_facts = _parse_blender_truncated_max_fbx_mesh_name(name)
        facts: dict[str, Any] | None = None
        kind = ""
        if full_facts is not None:
            facts = dict(full_facts)
            kind = "complete"
        elif truncated_facts is not None:
            facts = dict(truncated_facts)
            candidates = source_by_prefix.get(
                _blender_re6_header_prefix_key(facts), set()
            )
            if len(candidates) != 1:
                raise ValueError(
                    "A truncated 3ds Max FBX Mesh Header is ambiguous in the selected MOD: "
                    + name
                )
            recovered_key = next(iter(candidates))
            facts["mesh_type"] = int(recovered_key[6])
            kind = "truncated"
            truncated_count += 1
        elif _BLENDER_RE6_MESH_NAME_PREFIX_RE.match(name) is not None:
            malformed_mesh_names.append(name)
            continue
        else:
            # User-created names such as 123456 are deliberately unrelated to
            # this repair tool and must not block or receive a rename.
            continue
        header_key = _blender_re6_header_key(facts)
        normalized_rows.append(
            {
                **row,
                "facts": facts,
                "kind": kind,
                "header_key": header_key,
                "import_suffix": _normalize_blender_re6_import_suffix(
                    facts.get("import_suffix", "") or name
                ),
            }
        )
    if malformed_mesh_names:
        raise ValueError(
            "Current Blender scene contains incomplete Mesh_*** names that are not a recoverable 3ds Max DisplayMode truncation: "
            + ", ".join(malformed_mesh_names[:8])
        )
    if truncated_count < 1:
        raise ValueError("No recoverable 3ds Max FBX Mesh naming error was found")

    grouped_rows: dict[str, list[dict[str, Any]]] = {}
    for row in normalized_rows:
        grouped_rows.setdefault(str(row["import_suffix"]), []).append(row)
    if not grouped_rows:
        raise ValueError("Current Blender scene has no RE6 Mesh Headers to match")
    mismatch_details: list[str] = []
    for import_suffix, rows in sorted(grouped_rows.items()):
        actual_counter = Counter(
            row["header_key"] for row in rows
        )
        if actual_counter != source_counter:
            missing = sum((source_counter - actual_counter).values())
            unexpected = sum((actual_counter - source_counter).values())
            label = import_suffix or "base import"
            mismatch_details.append(
                f"{label}: MOD={sum(source_counter.values())}, scene={sum(actual_counter.values())}, missing={missing}, unexpected={unexpected}"
            )
    if mismatch_details:
        raise ValueError(
            "The selected MOD must match every Blender RE6 Mesh Header before any rename. "
            + " | ".join(mismatch_details)
        )

    repair_rows = [row for row in normalized_rows if row["kind"] == "truncated"]
    repair_handles = {int(row["handle"]) for row in repair_rows}
    occupied_names = {
        str(row["name"]).casefold()
        for row in scene_rows
        if int(row["handle"]) not in repair_handles
    }
    commands: list[dict[str, Any]] = []
    final_names: set[str] = set()
    for row in repair_rows:
        new_name = _blender_full_mesh_name_from_header_key(
            row["header_key"], import_suffix=str(row["import_suffix"])
        )
        folded_name = new_name.casefold()
        if folded_name in occupied_names or folded_name in final_names:
            raise ValueError(
                "Repair would conflict with an existing Blender object name: " + new_name
            )
        final_names.add(folded_name)
        commands.append(
            {
                "scene_node_handle": int(row["handle"]),
                "old_name": str(row["name"]),
                "new_name": new_name,
            }
        )
    verification = {
        "source_mesh_count": sum(source_counter.values()),
        "scene_re6_mesh_count": sum(len(rows) for rows in grouped_rows.values()),
        "import_group_count": len(grouped_rows),
        "repair_mesh_count": len(commands),
    }
    return {"commands": commands}, verification
