ProtocolError = OperationProtocolError
AgentCommandError = OperationAgentCommandError


class SceneChangedError(RuntimeError):
    pass


class OperationDomainError(RuntimeError):
    def __init__(self, message: str, receipt: dict[str, Any] | None = None) -> None:
        super().__init__(message)
        self.receipt = dict(receipt) if isinstance(receipt, dict) else {}


def _normalized_output_path_identity(path: str | Path) -> tuple[str, str]:
    raw_path = str(path).strip()
    if not raw_path:
        raise ValueError("Export output MOD path is empty")
    candidate = Path(raw_path).expanduser()
    try:
        resolved = candidate.resolve(strict=False)
    except (OSError, RuntimeError):
        resolved = Path(os.path.abspath(os.fspath(candidate)))
    display_path = os.path.normpath(str(resolved))
    return os.path.normcase(display_path), display_path


def _try_acquire_export_named_mutex(scope: str, identity: str) -> tuple[dict[str, Any] | None, str]:
    """Acquire a crash-released Windows mutex without creating lock files."""
    if os.name != "nt":
        return {"handle": 0, "name": "", "abandoned": False}, ""
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.CreateMutexW.argtypes = [ctypes.c_void_p, wintypes.BOOL, wintypes.LPCWSTR]
    kernel32.CreateMutexW.restype = wintypes.HANDLE
    kernel32.WaitForSingleObject.argtypes = [wintypes.HANDLE, wintypes.DWORD]
    kernel32.WaitForSingleObject.restype = wintypes.DWORD
    kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
    kernel32.CloseHandle.restype = wintypes.BOOL
    digest = hashlib.sha256(str(identity).encode("utf-8", errors="surrogatepass")).hexdigest().upper()
    name = f"Local\\PC_REHD_Code_X_Launcher_{scope}_{digest}"
    handle = kernel32.CreateMutexW(None, False, name)
    if not handle:
        raise OSError(ctypes.get_last_error(), f"CreateMutexW failed for {name}")
    wait_result = int(kernel32.WaitForSingleObject(handle, 0))
    if wait_result in {0x00000000, 0x00000080}:  # WAIT_OBJECT_0 / WAIT_ABANDONED
        return {
            "handle": handle,
            "name": name,
            "abandoned": wait_result == 0x00000080,
        }, ""
    kernel32.CloseHandle(handle)
    if wait_result == 0x00000102:  # WAIT_TIMEOUT
        return None, name
    raise OSError(ctypes.get_last_error(), f"WaitForSingleObject failed for {name}: {wait_result}")


def _release_export_named_mutex(lease: dict[str, Any] | None) -> None:
    if not lease or os.name != "nt" or not lease.get("handle"):
        return
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.ReleaseMutex.argtypes = [wintypes.HANDLE]
    kernel32.ReleaseMutex.restype = wintypes.BOOL
    kernel32.CloseHandle.argtypes = [wintypes.HANDLE]
    kernel32.CloseHandle.restype = wintypes.BOOL
    handle = lease["handle"]
    try:
        if not kernel32.ReleaseMutex(handle):
            raise OSError(ctypes.get_last_error(), f"ReleaseMutex failed for {lease.get('name', '')}")
    finally:
        kernel32.CloseHandle(handle)


class _ExportTransactionRegistry:
    """Own one live export per Max PID and per normalized output path."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._by_pid: dict[int, dict[str, Any]] = {}
        self._by_output: dict[str, dict[str, Any]] = {}

    def snapshot_for_pid(self, max_process_id: int) -> dict[str, Any] | None:
        with self._lock:
            owner = self._by_pid.get(int(max_process_id))
            return dict(owner) if owner is not None else None

    def try_acquire_pid_preflight(
        self,
        max_process_id: int,
    ) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
        """Reserve one Max PID before a legacy export reads the Max scene."""
        pid = int(max_process_id)
        if pid <= 0:
            raise ValueError("Export preflight requires Max PID > 0")
        with self._lock:
            existing = self._by_pid.get(pid)
            if existing is not None:
                conflict = dict(existing)
                conflict["conflict_scope"] = "max_pid"
                return None, conflict
            pid_mutex, _pid_mutex_name = _try_acquire_export_named_mutex(
                "MaxPid",
                str(pid),
            )
            if pid_mutex is None:
                return None, {
                    "max_process_id": pid,
                    "request_id": "",
                    "output_mod": "",
                    "conflict_scope": "max_pid",
                    "cross_process": True,
                }
            pid_mutex["max_process_id"] = pid
            pid_mutex["owner_thread_id"] = threading.get_ident()
            return pid_mutex, None

    @staticmethod
    def release_pid_preflight(lease: dict[str, Any] | None) -> None:
        _release_export_named_mutex(lease)

    def try_acquire(
        self,
        max_process_id: int,
        output_mod: str | Path,
        token: str,
    ) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
        pid = int(max_process_id)
        normalized_token = str(token).strip()
        if pid <= 0:
            raise ValueError("Export transaction requires Max PID > 0")
        if not normalized_token:
            raise ValueError("Export transaction token is empty")
        output_key, display_path = _normalized_output_path_identity(output_mod)
        with self._lock:
            existing = self._by_pid.get(pid)
            if existing is not None:
                conflict = dict(existing)
                conflict["conflict_scope"] = "max_pid"
                return None, conflict
            existing = self._by_output.get(output_key)
            if existing is not None:
                conflict = dict(existing)
                conflict["conflict_scope"] = "output_path"
                return None, conflict
            pid_mutex, _pid_mutex_name = _try_acquire_export_named_mutex("MaxPid", str(pid))
            if pid_mutex is None:
                return None, {
                    "max_process_id": pid,
                    "request_id": "",
                    "output_mod": display_path,
                    "conflict_scope": "max_pid",
                    "cross_process": True,
                }
            try:
                output_mutex, _output_mutex_name = _try_acquire_export_named_mutex(
                    "Output", output_key
                )
            except Exception:
                _release_export_named_mutex(pid_mutex)
                raise
            if output_mutex is None:
                _release_export_named_mutex(pid_mutex)
                return None, {
                    "max_process_id": 0,
                    "request_id": "",
                    "output_mod": display_path,
                    "conflict_scope": "output_path",
                    "cross_process": True,
                }
            owner = {
                "max_process_id": pid,
                "token": normalized_token,
                "request_id": "",
                "output_key": output_key,
                "output_mod": display_path,
                "started_at": time.time(),
                "_pid_mutex": pid_mutex,
                "_output_mutex": output_mutex,
            }
            self._by_pid[pid] = owner
            self._by_output[output_key] = owner
            return dict(owner), None

    def bind_request_id(self, max_process_id: int, token: str, request_id: str) -> bool:
        with self._lock:
            owner = self._by_pid.get(int(max_process_id))
            if owner is None or str(owner.get("token", "")) != str(token):
                return False
            owner["request_id"] = str(request_id).strip()
            return True

    def release(self, max_process_id: int, token: str) -> bool:
        with self._lock:
            owner = self._by_pid.get(int(max_process_id))
            if owner is None or str(owner.get("token", "")) != str(token):
                return False
            self._by_pid.pop(int(max_process_id), None)
            output_key = str(owner.get("output_key", ""))
            if self._by_output.get(output_key) is owner:
                self._by_output.pop(output_key, None)
            _release_export_named_mutex(owner.get("_output_mutex"))
            _release_export_named_mutex(owner.get("_pid_mutex"))
            return True


def _run_export_transaction_registry_guard() -> dict[str, Any]:
    registry = _ExportTransactionRegistry()
    guard_pid = max(1, (os.getpid() << 64) ^ time.monotonic_ns())
    other_pid = guard_pid + 1
    base = Path(tempfile.gettempdir()) / "PC_REHD_Code_X" / (
        f"mutex_guard_{guard_pid}_{time.monotonic_ns()}.NewMOD"
    )
    first, conflict = registry.try_acquire(guard_pid, base, "first")
    if first is None or conflict is not None:
        raise RuntimeError("Launcher export registry could not acquire its first transaction")
    external_registry = _ExportTransactionRegistry()
    preflight_result: dict[str, Any] = {}

    def contend_pid_preflight() -> None:
        lease, preflight_conflict = external_registry.try_acquire_pid_preflight(
            guard_pid
        )
        preflight_result["lease"] = lease
        preflight_result["conflict"] = preflight_conflict
        if lease is not None:
            external_registry.release_pid_preflight(lease)

    preflight_thread = threading.Thread(target=contend_pid_preflight, daemon=True)
    preflight_thread.start()
    preflight_thread.join(timeout=2.0)
    if (
        preflight_thread.is_alive()
        or preflight_result.get("lease") is not None
        or not bool((preflight_result.get("conflict") or {}).get("cross_process"))
    ):
        raise RuntimeError(
            "Launcher legacy-export preflight no longer rejects an external Max PID owner"
        )
    duplicate_pid, pid_conflict = registry.try_acquire(
        guard_pid, base.with_name(base.stem + "_other.NewMOD"), "second"
    )
    if duplicate_pid is not None or (pid_conflict or {}).get("conflict_scope") != "max_pid":
        raise RuntimeError("Launcher export registry no longer rejects duplicate Max PID exports")
    duplicate_path, path_conflict = registry.try_acquire(other_pid, base, "third")
    if duplicate_path is not None or (path_conflict or {}).get("conflict_scope") != "output_path":
        raise RuntimeError("Launcher export registry no longer rejects duplicate output paths")
    if registry.release(guard_pid, "wrong-token"):
        raise RuntimeError("A stale Launcher export token released the active transaction")
    if not registry.release(guard_pid, "first"):
        raise RuntimeError("Launcher export registry could not release its owner")
    handoff_pid = other_pid + 1
    preflight_lease, preflight_conflict = registry.try_acquire_pid_preflight(
        handoff_pid
    )
    if preflight_lease is None or preflight_conflict is not None:
        raise RuntimeError("Launcher legacy-export preflight could not reserve a free Max PID")
    handoff_owner, handoff_conflict = registry.try_acquire(
        handoff_pid,
        base.with_name(base.stem + "_handoff.NewMOD"),
        "preflight-handoff",
    )
    if handoff_owner is None or handoff_conflict is not None:
        registry.release_pid_preflight(preflight_lease)
        raise RuntimeError(
            "Launcher legacy-export preflight could not hand ownership to the export transaction"
        )
    registry.release_pid_preflight(preflight_lease)
    if not registry.release(handoff_pid, "preflight-handoff"):
        raise RuntimeError("Launcher preflight handoff transaction could not be released")
    reacquired, conflict = registry.try_acquire(other_pid, base, "fourth")
    if reacquired is None or conflict is not None or not registry.release(other_pid, "fourth"):
        raise RuntimeError("Launcher export registry did not recover after release")
    if os.name == "nt":
        kernel_identity = f"guard:{os.getpid()}:{time.monotonic_ns()}"
        kernel_owner, _kernel_name = _try_acquire_export_named_mutex(
            "Regression", kernel_identity
        )
        if kernel_owner is None:
            raise RuntimeError("Launcher cross-process mutex guard could not acquire its owner")
        contender_result: dict[str, Any] = {}

        def contend_kernel_mutex() -> None:
            contender, _name = _try_acquire_export_named_mutex("Regression", kernel_identity)
            contender_result["lease"] = contender
            if contender is not None:
                _release_export_named_mutex(contender)

        thread = threading.Thread(target=contend_kernel_mutex, daemon=True)
        thread.start()
        thread.join(timeout=2.0)
        _release_export_named_mutex(kernel_owner)
        if thread.is_alive() or contender_result.get("lease") is not None:
            raise RuntimeError("Launcher cross-process mutex no longer rejects a concurrent owner")
        recovered_kernel, _name = _try_acquire_export_named_mutex("Regression", kernel_identity)
        if recovered_kernel is None:
            raise RuntimeError("Launcher cross-process mutex did not recover after release")
        _release_export_named_mutex(recovered_kernel)
    source_path = Path(__file__).resolve()
    tree = ast.parse(source_path.read_text(encoding="utf-8"), filename=str(source_path))
    registry_class = next(
        (
            node for node in tree.body
            if isinstance(node, ast.ClassDef)
            and node.name == "_ExportTransactionRegistry"
        ),
        None,
    )
    registry_methods = {
        node.name: node
        for node in (registry_class.body if registry_class is not None else [])
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name in {
            "try_acquire_pid_preflight",
            "release_pid_preflight",
            "try_acquire",
            "release",
        }
    }
    for method_name, required_call in {
        "try_acquire_pid_preflight": "_try_acquire_export_named_mutex",
        "release_pid_preflight": "_release_export_named_mutex",
        "try_acquire": "_try_acquire_export_named_mutex",
        "release": "_release_export_named_mutex",
    }.items():
        method = registry_methods.get(method_name)
        calls = {
            call.func.id
            for call in ast.walk(method) if method is not None
            if isinstance(call, ast.Call) and isinstance(call.func, ast.Name)
        }
        if required_call not in calls:
            raise RuntimeError(
                f"Launcher cross-process export mutex is not wired into {method_name}"
            )
    export_defs = [
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name == "_export_mod_active"
    ]
    if len(export_defs) != 1:
        raise RuntimeError("Launcher export transaction gate cannot find _export_mod_active")
    called_attributes = {
        node.func.attr
        for node in ast.walk(export_defs[0])
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
    }
    missing_calls = {"snapshot_for_pid", "try_acquire", "bind_request_id", "release"} - called_attributes
    if missing_calls:
        raise RuntimeError(
            "Launcher export transaction gate is not wired into the live export path: "
            + ", ".join(sorted(missing_calls))
        )
    legacy_export_defs = [
        node
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name == "_request_mod_export"
    ]
    if len(legacy_export_defs) != 1:
        raise RuntimeError("Launcher export transaction gate cannot find _request_mod_export")
    legacy_attribute_calls = [
        node
        for node in ast.walk(legacy_export_defs[0])
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
    ]
    legacy_called_attributes = {
        node.func.attr for node in legacy_attribute_calls
    }
    missing_legacy_calls = {
        "try_acquire_pid_preflight",
        "release_pid_preflight",
    } - legacy_called_attributes
    if missing_legacy_calls:
        raise RuntimeError(
            "Legacy export can contact Max before cross-process preflight ownership: "
            + ", ".join(sorted(missing_legacy_calls))
        )
    preflight_lines = [
        node.lineno
        for node in legacy_attribute_calls
        if node.func.attr == "try_acquire_pid_preflight"
    ]
    max_request_lines = [
        node.lineno
        for node in legacy_attribute_calls
        if node.func.attr == "_request_max_scene_interface"
    ]
    if (
        not preflight_lines
        or not max_request_lines
        or min(preflight_lines) >= min(max_request_lines)
    ):
        raise RuntimeError(
            "Legacy export must reserve its Max PID before the first Agent scene request"
        )
    return {
        "status": "PASS",
        "per_max_pid": 1,
        "per_output_path": 1,
        "cross_process": os.name == "nt",
        "legacy_preflight_before_agent": True,
        "queueing": False,
    }


