def _schedule_dangerous_export_feature(
    feature: str,
    *,
    requested: bool,
    bone_export_mode: str,
) -> dict[str, Any]:
    """Single authority for risky export features; UI state alone is never permission."""
    policy = DANGEROUS_EXPORT_FEATURE_POLICIES.get(str(feature))
    if not isinstance(policy, dict):
        raise ValueError(f"Unknown dangerous export feature: {feature}")
    normalized_bone_mode = str(bone_export_mode or "disabled").strip().lower()
    supported_mode = normalized_bone_mode in {"disabled", "bones_only", "bones_plus_mesh"}
    enabled = bool(requested) and normalized_bone_mode in {
        "disabled",
        "bones_plus_mesh",
    }
    return {
        "feature": str(feature),
        "requested": bool(requested),
        "enabled": enabled,
        "reason": (
            "enabled_for_ordinary_export"
            if enabled and normalized_bone_mode == "disabled"
            else "enabled_for_bones_plus_mesh"
            if enabled and normalized_bone_mode == "bones_plus_mesh"
            else "bones_only_has_no_mesh"
            if requested and normalized_bone_mode == "bones_only"
            else "unsupported_export_mode"
            if requested and not supported_mode
            else "not_requested"
        ),
        "bone_export_mode": normalized_bone_mode,
        "policy": dict(policy),
    }

