def _runtime_attribute_path(node: ast.AST) -> str:
    parts: list[str] = []
    current = node
    while isinstance(current, ast.Attribute):
        parts.append(current.attr)
        current = current.value
    if isinstance(current, ast.Name):
        parts.append(current.id)
    return ".".join(reversed(parts))


def _run_pymxs_runtime_api_policy_guard() -> dict[str, Any]:
    source_path = Path(__file__).resolve()
    try:
        tree = ast.parse(source_path.read_text(encoding="utf-8"), filename=str(source_path))
    except (OSError, SyntaxError) as exc:
        raise RuntimeError(f"Cannot validate the PYMXS runtime API policy: {exc}") from exc

    calls = {
        path
        for node in ast.walk(tree)
        if isinstance(node, ast.Call)
        for path in [_runtime_attribute_path(node.func)]
        if path.startswith("rt.")
    }
    parents: dict[ast.AST, ast.AST] = {}
    for parent in ast.walk(tree):
        for child in ast.iter_child_nodes(parent):
            parents[child] = parent

    def enclosing_function(node: ast.AST) -> str:
        current: ast.AST | None = node
        while current is not None:
            if isinstance(current, (ast.FunctionDef, ast.AsyncFunctionDef)):
                return current.name
            current = parents.get(current)
        return "<module>"

    reviewed_calls = _PYMXS_APPROVED_RUNTIME_CALLS | _PYMXS_OPTIONAL_RUNTIME_CALLS
    dynamic_runtime_paths: set[str] = set()
    dynamic_runtime_getattrs: list[int] = []
    reviewed_dynamic_getattrs = 0
    for node in ast.walk(tree):
        if not (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == "getattr"
            and node.args
            and isinstance(node.args[0], ast.Name)
            and node.args[0].id == "rt"
        ):
            continue
        allowed_paths = _PYMXS_DYNAMIC_RUNTIME_ACCESS_BY_FUNCTION.get(enclosing_function(node))
        if allowed_paths is None:
            dynamic_runtime_getattrs.append(node.lineno)
            continue
        dynamic_runtime_paths.update(allowed_paths)
        reviewed_dynamic_getattrs += 1
    effective_paths = calls | dynamic_runtime_paths
    reviewed_paths = reviewed_calls | _PYMXS_REQUIRED_RUNTIME_VALUES
    unreviewed = sorted(effective_paths - reviewed_paths)
    stale = sorted(_PYMXS_APPROVED_RUNTIME_CALLS - effective_paths)
    stale_optional = sorted(_PYMXS_OPTIONAL_RUNTIME_CALLS - effective_paths)
    lifetime_violations: list[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        runtime_path = _runtime_attribute_path(node.func)
        if runtime_path == "rt.gc":
            lifetime_violations.append(f"forced-MaxScript-GC@{node.lineno}")
        if runtime_path != "rt.importFile":
            continue
        current: ast.AST | None = node
        while current is not None:
            if isinstance(current, ast.With):
                for item in current.items:
                    context_expr = item.context_expr
                    context_path = _runtime_attribute_path(
                        context_expr.func
                    ) if isinstance(context_expr, ast.Call) else ""
                    if context_path == "pymxs.undo":
                        lifetime_violations.append(
                            f"FBX-import-inside-pymxs.undo@{node.lineno}"
                        )
            current = parents.get(current)
    if unreviewed or stale or stale_optional or dynamic_runtime_getattrs or lifetime_violations:
        detail: list[str] = []
        if unreviewed:
            detail.append("unreviewed=" + ",".join(unreviewed))
        if stale:
            detail.append("stale=" + ",".join(stale))
        if stale_optional:
            detail.append("stale_optional=" + ",".join(stale_optional))
        if dynamic_runtime_getattrs:
            detail.append(
                "dynamic_getattr=" + ",".join(str(line) for line in dynamic_runtime_getattrs)
            )
        if lifetime_violations:
            detail.append(
                "wrapper_lifetime=" + ",".join(sorted(set(lifetime_violations)))
            )
        raise RuntimeError(
            "PYMXS runtime API policy violation; review every direct runtime call: "
            + " | ".join(detail)
        )
    return {
        "status": "PASS",
        "version": PYMXS_RUNTIME_API_POLICY_VERSION,
        "reviewed_direct_calls": len(calls),
        "reviewed_optional_calls": len(_PYMXS_OPTIONAL_RUNTIME_CALLS),
        "reviewed_dynamic_runtime_getattrs": reviewed_dynamic_getattrs,
        "dynamic_runtime_getattrs": len(dynamic_runtime_getattrs),
    }


def _run_pymxs_geometry_policy_guard() -> dict[str, Any]:
    """Audit only the Max-side main .MOD export call graph."""

    def function_definitions(candidate_tree: ast.Module) -> tuple[
        dict[str, ast.FunctionDef | ast.AsyncFunctionDef],
        dict[str, int],
    ]:
        definitions: dict[str, ast.FunctionDef | ast.AsyncFunctionDef] = {}
        counts: dict[str, int] = {}
        for node in candidate_tree.body:
            if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            definitions[node.name] = node
            counts[node.name] = counts.get(node.name, 0) + 1
        return definitions, counts

    def export_call_graph(
        candidate_tree: ast.Module,
    ) -> tuple[
        dict[str, ast.FunctionDef | ast.AsyncFunctionDef],
        set[str],
        dict[str, list[str]],
    ]:
        definitions, counts = function_definitions(candidate_tree)
        entrypoint = PYMXS_EXPORT_GEOMETRY_ENTRYPOINT
        if counts.get(entrypoint, 0) != 1:
            raise RuntimeError(f"Main .MOD export entrypoint is not unique: {entrypoint}")
        reachable: set[str] = set()
        edges: dict[str, list[str]] = {}
        pending = [entrypoint]
        while pending:
            function_name = pending.pop()
            if function_name in reachable:
                continue
            function_node = definitions.get(function_name)
            if function_node is None:
                raise RuntimeError(f"Main .MOD export call graph lost {function_name}")
            reachable.add(function_name)
            direct_calls = {
                node.func.id
                for node in ast.walk(function_node)
                if isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id in definitions
            }
            edges[function_name] = sorted(direct_calls)
            pending.extend(sorted(direct_calls - reachable))
        duplicates = sorted(name for name in reachable if counts.get(name, 0) != 1)
        if duplicates:
            raise RuntimeError(
                "Main .MOD export call graph contains duplicate function definitions: "
                + ", ".join(duplicates)
            )
        return definitions, reachable, edges

    def graph_fingerprint(
        source_text: str,
        definitions: dict[str, ast.FunctionDef | ast.AsyncFunctionDef],
        reachable: set[str],
    ) -> str:
        canonical_source = "\n".join(
            ast.get_source_segment(source_text, definitions[name])
            or ast.dump(definitions[name], annotate_fields=True, include_attributes=False)
            for name in sorted(reachable)
        )
        return hashlib.sha256(canonical_source.encode("utf-8")).hexdigest().upper()

    def audit_source(source_text: str, *, approved_fingerprint: str) -> dict[str, Any]:
        try:
            candidate_tree = ast.parse(source_text)
        except SyntaxError as exc:
            raise RuntimeError(f"Cannot parse the Launcher export policy: {exc}") from exc
        definitions, reachable, edges = export_call_graph(candidate_tree)
        parents: dict[ast.AST, ast.AST] = {}
        for parent in ast.walk(candidate_tree):
            for child in ast.iter_child_nodes(parent):
                parents[child] = parent

        violations: list[str] = []
        missing_required = sorted(set(PYMXS_EXPORT_REQUIRED_FUNCTIONS) - reachable)
        violations.extend(f"missing_required_function={name}" for name in missing_required)
        forbidden_reachable = sorted(set(PYMXS_EXPORT_FORBIDDEN_FUNCTIONS) & reachable)
        violations.extend(f"forbidden_reachable_function={name}" for name in forbidden_reachable)

        allowed_runtime_calls = set(PYMXS_EXPORT_ALLOWED_RUNTIME_CALLS)
        allowed_runtime_values = set(PYMXS_EXPORT_ALLOWED_RUNTIME_VALUES)
        forbidden_methods = set(PYMXS_EXPORT_FORBIDDEN_ARRAY_METHODS)
        forbidden_attributes = set(PYMXS_EXPORT_FORBIDDEN_GEOMETRY_ATTRIBUTES)
        forbidden_request_keys = set(PYMXS_EXPORT_FORBIDDEN_REQUEST_KEYS)
        runtime_calls: set[str] = set()
        runtime_values: set[str] = set()

        for function_name in sorted(reachable):
            function_node = definitions[function_name]
            for node in ast.walk(function_node):
                if function_name == PYMXS_EXPORT_GEOMETRY_ENTRYPOINT:
                    request_key = ""
                    if (
                        isinstance(node, ast.Call)
                        and isinstance(node.func, ast.Attribute)
                        and node.func.attr == "get"
                        and isinstance(node.func.value, ast.Name)
                        and node.func.value.id == "payload"
                        and node.args
                        and isinstance(node.args[0], ast.Constant)
                        and isinstance(node.args[0].value, str)
                    ):
                        request_key = node.args[0].value
                    elif (
                        isinstance(node, ast.Subscript)
                        and isinstance(node.value, ast.Name)
                        and node.value.id == "payload"
                        and isinstance(node.slice, ast.Constant)
                        and isinstance(node.slice.value, str)
                    ):
                        request_key = node.slice.value
                    if request_key in forbidden_request_keys:
                        violations.append(
                            f"cached_export_request_key={function_name}:{request_key}@{node.lineno}"
                        )
                if isinstance(node, ast.Attribute):
                    runtime_path = _runtime_attribute_path(node)
                    if node.attr in forbidden_methods:
                        violations.append(f"forbidden_array_api={function_name}:{node.attr}@{node.lineno}")
                    if node.attr in forbidden_attributes:
                        violations.append(
                            f"forbidden_geometry_attribute={function_name}:{node.attr}@{node.lineno}"
                        )
                    if (
                        runtime_path == "rt.objects"
                        and function_name not in PYMXS_EXPORT_NAME_ONLY_SCENE_FUNCTIONS
                    ):
                        violations.append(
                            f"unapproved_full_scene_identity_snapshot="
                            f"{function_name}:rt.objects@{node.lineno}"
                        )
                    parent = parents.get(node)
                    is_inner_attribute = isinstance(parent, ast.Attribute) and parent.value is node
                    is_call_target = isinstance(parent, ast.Call) and parent.func is node
                    if runtime_path.startswith("rt.") and not is_inner_attribute and not is_call_target:
                        runtime_values.add(runtime_path)
                        if runtime_path not in allowed_runtime_values:
                            violations.append(
                                f"unapproved_runtime_value={function_name}:{runtime_path}@{node.lineno}"
                            )
                if not isinstance(node, ast.Call):
                    continue
                runtime_call = _runtime_attribute_path(node.func)
                if runtime_call.startswith("rt."):
                    runtime_calls.add(runtime_call)
                    if runtime_call not in allowed_runtime_calls:
                        violations.append(
                            f"unapproved_runtime_call={function_name}:{runtime_call}@{node.lineno}"
                        )
                if isinstance(node.func, ast.Name):
                    if node.func.id in forbidden_methods:
                        violations.append(
                            f"forbidden_array_call={function_name}:{node.func.id}@{node.lineno}"
                        )
                    if node.func.id in PYMXS_EXPORT_FORBIDDEN_FUNCTIONS:
                        violations.append(
                            f"forbidden_function_call={function_name}:{node.func.id}@{node.lineno}"
                        )
                    if node.func.id == "getattr":
                        dynamic_names = {
                            argument.value
                            for argument in node.args[1:]
                            if isinstance(argument, ast.Constant)
                            and isinstance(argument.value, str)
                        }
                        forbidden_dynamic = sorted(
                            dynamic_names & (forbidden_methods | forbidden_attributes)
                        )
                        violations.extend(
                            f"forbidden_dynamic_geometry={function_name}:{name}@{node.lineno}"
                            for name in forbidden_dynamic
                        )
                        if (
                            node.args
                            and isinstance(node.args[0], ast.Name)
                            and node.args[0].id == "rt"
                        ):
                            violations.append(
                                f"dynamic_runtime_access={function_name}:getattr(rt)@{node.lineno}"
                            )
                for keyword in node.keywords:
                    if (
                        keyword.arg == "include_arrays"
                        and isinstance(keyword.value, ast.Constant)
                        and keyword.value.value is True
                    ):
                        violations.append(f"include_arrays=True={function_name}@{node.lineno}")

        exporter_parameter_contract = {
            "_max_set_and_verify_fbx_export_param": {
                "runtime_calls": {
                    "rt.FBXExporterSetParam",
                    "rt.FBXExporterGetParam",
                },
                "function_calls": set(),
            },
            "_max_restore_fbx_export": {
                "runtime_calls": set(),
                "function_calls": {"_max_set_and_verify_fbx_export_param"},
            },
            "_max_configure_fbx_export": {
                "runtime_calls": {
                    "rt.pluginManager.loadClass",
                    "rt.FBXExporterGetParam",
                },
                "function_calls": {
                    "_max_set_and_verify_fbx_export_param",
                    "_max_restore_fbx_export",
                },
            },
            "_max_export_fbx": {
                "runtime_calls": set(),
                "function_calls": {
                    "_max_configure_fbx_export",
                    "_max_restore_fbx_export",
                },
            },
        }
        for function_name, requirements in exporter_parameter_contract.items():
            function_node = definitions.get(function_name)
            if function_node is None or function_name not in reachable:
                continue
            function_runtime_calls = {
                _runtime_attribute_path(node.func)
                for node in ast.walk(function_node)
                if isinstance(node, ast.Call)
                and _runtime_attribute_path(node.func).startswith("rt.")
            }
            function_calls = {
                node.func.id
                for node in ast.walk(function_node)
                if isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
            }
            for missing_call in sorted(requirements["runtime_calls"] - function_runtime_calls):
                violations.append(
                    f"fbx_export_contract_missing_runtime_call={function_name}:{missing_call}"
                )
            for missing_call in sorted(requirements["function_calls"] - function_calls):
                violations.append(
                    f"fbx_export_contract_missing_function_call={function_name}:{missing_call}"
                )

        for function_name in (
            "_max_set_and_verify_fbx_export_param",
            "_max_restore_fbx_export",
            "_max_configure_fbx_export",
        ):
            function_node = definitions.get(function_name)
            if function_node is None or function_name not in reachable:
                continue
            if not any(isinstance(node, ast.Raise) for node in ast.walk(function_node)):
                violations.append(f"fbx_export_contract_missing_failure_raise={function_name}")
            for handler in (
                node for node in ast.walk(function_node) if isinstance(node, ast.ExceptHandler)
            ):
                handler_nodes = list(ast.walk(handler))
                has_forbidden_exit = any(
                    isinstance(node, (ast.Pass, ast.Return, ast.Break, ast.Continue))
                    for node in handler_nodes
                )
                records_or_raises = any(isinstance(node, ast.Raise) for node in handler_nodes) or any(
                    isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Attribute)
                    and node.func.attr == "append"
                    for node in handler_nodes
                )
                if has_forbidden_exit or not records_or_raises:
                    violations.append(
                        f"fbx_export_contract_silent_exception_handler={function_name}@{handler.lineno}"
                    )

        export_ui_defs = [
            node
            for node in ast.walk(candidate_tree)
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name == "_export_mod_active"
        ]
        if len(export_ui_defs) != 1:
            violations.append("launcher_export_ui_entry_not_unique")
        else:
            export_commands: set[str] = set()
            dynamic_export_requests: list[int] = []
            for node in ast.walk(export_ui_defs[0]):
                if not (
                    isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Attribute)
                    and node.func.attr == "request"
                ):
                    continue
                if node.args and isinstance(node.args[0], ast.Constant) and isinstance(node.args[0].value, str):
                    export_commands.add(node.args[0].value)
                else:
                    dynamic_export_requests.append(node.lineno)
            unknown_commands = sorted(
                export_commands - set(PYMXS_EXPORT_ALLOWED_UI_AGENT_COMMANDS)
            )
            violations.extend(f"unapproved_export_agent_command={name}" for name in unknown_commands)
            violations.extend(
                f"dynamic_export_agent_command@{line}" for line in dynamic_export_requests
            )

            required_export_interfaces = {"export.mod", "export.bone_edit"}
            routed_export_interfaces: set[str] = set()
            dynamic_interface_routes: list[int] = []
            selector_names: set[str] = set()
            for node in ast.walk(export_ui_defs[0]):
                if not (
                    isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Attribute)
                    and node.func.attr == "_request_max_scene_interface"
                    and len(node.args) >= 2
                ):
                    continue
                interface_arg = node.args[1]
                if isinstance(interface_arg, ast.Constant) and isinstance(interface_arg.value, str):
                    routed_export_interfaces.add(interface_arg.value)
                elif isinstance(interface_arg, ast.Name):
                    selector_names.add(interface_arg.id)
                else:
                    dynamic_interface_routes.append(node.lineno)
            for node in ast.walk(export_ui_defs[0]):
                assigned_names: set[str] = set()
                assigned_value: ast.AST | None = None
                if isinstance(node, ast.Assign):
                    assigned_names = {
                        target.id for target in node.targets if isinstance(target, ast.Name)
                    }
                    assigned_value = node.value
                elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
                    assigned_names = {node.target.id}
                    assigned_value = node.value
                if not (assigned_names & selector_names) or assigned_value is None:
                    continue
                routed_export_interfaces.update(
                    constant.value
                    for constant in ast.walk(assigned_value)
                    if isinstance(constant, ast.Constant)
                    and isinstance(constant.value, str)
                    and constant.value in required_export_interfaces
                )
            violations.extend(
                f"dynamic_export_scene_interface@{line}" for line in dynamic_interface_routes
            )
            missing_interfaces = sorted(required_export_interfaces - routed_export_interfaces)
            violations.extend(
                f"launcher_export_ui_missing_scene_interface={name}"
                for name in missing_interfaces
            )

            registry_defs: list[ast.AST] = []
            for node in candidate_tree.body:
                if (
                    isinstance(node, ast.Assign)
                    and any(
                        isinstance(target, ast.Name)
                        and target.id == "MAX_SCENE_ACCESS_INTERFACES"
                        for target in node.targets
                    )
                ) or (
                    isinstance(node, ast.AnnAssign)
                    and isinstance(node.target, ast.Name)
                    and node.target.id == "MAX_SCENE_ACCESS_INTERFACES"
                ):
                    registry_defs.append(node)
            if len(registry_defs) != 1:
                violations.append("max_scene_access_interface_registry_not_unique")
            else:
                registry_node = registry_defs[0]
                registry_value = registry_node.value
                try:
                    interface_registry = ast.literal_eval(registry_value)
                except (ValueError, TypeError):
                    interface_registry = None
                if not isinstance(interface_registry, dict):
                    violations.append("max_scene_access_interface_registry_not_static")
                else:
                    expected_route = {
                        "command": "export_mod",
                        "contract": "passthrough",
                        "operation": "export_mod",
                    }
                    for interface_name in sorted(required_export_interfaces):
                        route = interface_registry.get(interface_name)
                        if route != expected_route:
                            violations.append(
                                f"max_scene_export_interface_invalid={interface_name}"
                            )

        dispatcher = definitions.get("_execute_max_command")
        if dispatcher is None:
            violations.append("max_agent_dispatcher_missing")
        else:
            export_dispatch_calls = [
                node
                for node in ast.walk(dispatcher)
                if isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == PYMXS_EXPORT_GEOMETRY_ENTRYPOINT
            ]
            dispatcher_constants = {
                node.value
                for node in ast.walk(dispatcher)
                if isinstance(node, ast.Constant) and isinstance(node.value, str)
            }
            if len(export_dispatch_calls) != 1 or "export_mod" not in dispatcher_constants:
                violations.append("max_agent_export_mod_must_dispatch_directly_to_entrypoint")

        if violations:
            raise RuntimeError(
                "Main .MOD export PYMXS boundary violation. This is a maintainer/AI code error, "
                "not a user MOD-data error: "
                + ", ".join(sorted(set(violations))[:32])
                + " | "
                + PYMXS_EXPORT_AI_REVIEW_QUESTION
            )

        fingerprint = graph_fingerprint(source_text, definitions, reachable)
        review_required = bool(
            approved_fingerprint and fingerprint != approved_fingerprint
        )
        return {
            "status": "PASS",
            "scope": PYMXS_EXPORT_GEOMETRY_POLICY_SCOPE,
            "entrypoint": PYMXS_EXPORT_GEOMETRY_ENTRYPOINT,
            "call_graph_functions": sorted(reachable),
            "call_graph_edges": {name: edges[name] for name in sorted(edges)},
            "call_graph_function_count": len(reachable),
            "call_graph_fingerprint": fingerprint,
            "approved_call_graph_fingerprint": approved_fingerprint,
            "ai_review": {
                "status": "AI_REVIEW_REQUIRED" if review_required else "APPROVED",
                "blocking_user_export": False,
                "question": PYMXS_EXPORT_AI_REVIEW_QUESTION if review_required else "",
            },
            "runtime_calls": sorted(runtime_calls),
            "runtime_values": sorted(runtime_values),
        }

    source_path = Path(__file__).resolve()
    try:
        source = source_path.read_text(encoding="utf-8")
    except OSError as exc:
        raise RuntimeError(f"Cannot read the Launcher export policy: {exc}") from exc
    report = audit_source(
        source,
        approved_fingerprint=PYMXS_EXPORT_APPROVED_CALL_GRAPH_FINGERPRINT,
    )

    fixture = """
def _max_runtime():
    return object()

def _max_bucket_identity_receipt(rows):
    return rows

def _max_export_scene_nodes_by_handle(rt):
    return {node.handle: node for node in list(rt.objects)}

def _max_export_nodes_from_handles(rt):
    _max_export_scene_nodes_by_handle(rt)
    return []

def _max_export_selection_handles(rt):
    return [node.handle for node in list(rt.selection)]

def _max_restore_export_selection(rt):
    rt.clearSelection()

def _max_export_bone_fbx_scope(rt):
    return _max_export_nodes_from_handles(rt)

def _max_prepare_export_map2_unwrap(rt, nodes):
    return {"requested": True, "nodes": []}

def _max_set_and_verify_fbx_export_param(rt, key, expected):
    rt.FBXExporterSetParam(key, expected)
    actual = rt.FBXExporterGetParam(key)
    if actual != expected:
        raise RuntimeError("FBX exporter rejected parameter")

def _max_restore_fbx_export(rt, previous):
    failures = []
    for key, value in previous.items():
        try:
            _max_set_and_verify_fbx_export_param(rt, key, value)
        except Exception as exc:
            failures.append(str(exc))
    if failures:
        raise RuntimeError("FBX exporter restore failed")

def _max_configure_fbx_export(rt):
    rt.pluginManager.loadClass(rt.FBXEXP)
    previous = {"Animation": rt.FBXExporterGetParam("Animation")}
    try:
        _max_set_and_verify_fbx_export_param(rt, "Animation", False)
    except Exception:
        _max_restore_fbx_export(rt, previous)
        raise
    return previous

def _max_export_fbx(rt):
    _max_export_nodes_from_handles(rt)
    _max_export_selection_handles(rt)
    previous = _max_configure_fbx_export(rt)
    try:
        return rt.exportFile("selected.fbx")
    finally:
        _max_restore_export_selection(rt)
        _max_restore_fbx_export(rt, previous)

def _max_export_mod(payload):
    _max_bucket_identity_receipt([])
    _max_export_bone_fbx_scope(_max_runtime())
    _max_prepare_export_map2_unwrap(_max_runtime(), [])
    return _max_export_fbx(_max_runtime())

MAX_SCENE_ACCESS_INTERFACES = {
    "export.mod": {
        "command": "export_mod", "contract": "passthrough", "operation": "export_mod",
    },
    "export.bone_edit": {
        "command": "export_mod", "contract": "passthrough", "operation": "export_mod",
    },
}

def _export_mod_active(self):
    export_interface_id = "export.bone_edit" if self.bone_edit else "export.mod"
    self.session.request("health")
    return self._request_max_scene_interface(self.session, export_interface_id)

def _execute_max_command(command, payload):
    if command == "export_mod":
        return _max_export_mod(payload)
    return {}

def _unrelated_normal_tool(rt):
    return rt.getNormal(None, 1)

def _max_export_auxiliary(rt):
    return rt.getVert(None, 1)
"""
    fixture_report = audit_source(fixture, approved_fingerprint="")
    unrelated_fixture_report = audit_source(
        fixture.replace(
            "return rt.getNormal(None, 1)",
            "return rt.getFace(None, 1)",
        ),
        approved_fingerprint="",
    )
    if (
        unrelated_fixture_report["call_graph_fingerprint"]
        != fixture_report["call_graph_fingerprint"]
    ):
        raise RuntimeError("An unrelated tool changed the main .MOD export fingerprint")
    benign_export_edit = fixture.replace(
        "    _max_bucket_identity_receipt([])\n",
        "    payload = dict(payload)\n"
        "    _max_bucket_identity_receipt([])\n",
    )
    benign_review = audit_source(
        benign_export_edit,
        approved_fingerprint=fixture_report["call_graph_fingerprint"],
    )
    if (
        benign_review.get("status") != "PASS"
        or benign_review.get("ai_review", {}).get("status") != "AI_REVIEW_REQUIRED"
        or benign_review.get("ai_review", {}).get("blocking_user_export") is not False
        or not benign_review.get("ai_review", {}).get("question")
    ):
        raise RuntimeError("Benign export-code drift did not ask AI without blocking the user")

    def expect_blocked(mutated_source: str, expected_token: str) -> None:
        try:
            audit_source(mutated_source, approved_fingerprint="")
        except RuntimeError as exc:
            if expected_token not in str(exc):
                raise RuntimeError(
                    f"PYMXS export mutation gate failed for {expected_token}: {exc}"
                ) from exc
            return
        raise RuntimeError(f"PYMXS export mutation gate accepted {expected_token}")

    expect_blocked(
        fixture.replace(
            "    rt.pluginManager.loadClass(rt.FBXEXP)\n",
            "    str(rt.FBXEXP)\n",
        ),
        "fbx_export_contract_missing_runtime_call=_max_configure_fbx_export:rt.pluginManager.loadClass",
    )
    expect_blocked(
        fixture.replace(
            "    actual = rt.FBXExporterGetParam(key)\n",
            "    actual = expected\n",
        ),
        "fbx_export_contract_missing_runtime_call=_max_set_and_verify_fbx_export_param:rt.FBXExporterGetParam",
    )
    expect_blocked(
        fixture.replace(
            "            failures.append(str(exc))\n",
            "            pass\n",
        ),
        "fbx_export_contract_silent_exception_handler=_max_restore_fbx_export",
    )
    expect_blocked(
        fixture.replace(
            "def _max_export_mod(payload):\n",
            "def _max_export_mod(payload):\n"
            "    rt = _max_runtime()\n"
            "    rt.getNormal(None, 1)\n",
        ),
        "getNormal",
    )
    expect_blocked(
        fixture.replace(
            "def _max_export_mod(payload):\n",
            "def _max_export_mod(payload):\n"
            "    rt = _max_runtime()\n"
            "    rt.isValidNode(None)\n",
        ),
        "rt.isValidNode",
    )
    expect_blocked(
        fixture.replace(
            "def _max_export_mod(payload):\n",
            "def _max_is_live_scene_node(rt, node):\n"
            "    return rt.isValidNode(node)\n\n"
            "def _max_export_mod(payload):\n"
            "    _max_is_live_scene_node(_max_runtime(), None)\n",
        ),
        "forbidden_reachable_function=_max_is_live_scene_node",
    )
    expect_blocked(
        fixture.replace(
            "def _max_export_mod(payload):\n",
            "def _max_export_mod(payload):\n"
            "    rt = _max_runtime()\n"
            "    list(rt.objects)\n",
        ),
        "rt.objects",
    )
    expect_blocked(
        fixture.replace(
            "    _max_bucket_identity_receipt([])\n",
            "    payload.get(\"include_skin_bones\", False)\n"
            "    _max_bucket_identity_receipt([])\n",
        ),
        "cached_export_request_key=_max_export_mod:include_skin_bones",
    )
    expect_blocked(
        fixture.replace(
            '"export.bone_edit": {\n'
            '        "command": "export_mod", "contract": "passthrough", "operation": "export_mod",\n',
            '"export.bone_edit": {\n'
            '        "command": "inspect_scene", "contract": "passthrough", "operation": "export_mod",\n',
        ),
        "max_scene_export_interface_invalid=export.bone_edit",
    )
    expect_blocked(
        fixture.replace(
            "    _max_bucket_identity_receipt([])\n",
            "    payload[\"include_skin_bones\"]\n"
            "    _max_bucket_identity_receipt([])\n",
        ),
        "cached_export_request_key=_max_export_mod:include_skin_bones",
    )
    report.update(
        {
            "version": PYMXS_GEOMETRY_POLICY_VERSION,
            "pymxs_geometry_arrays": False,
            "geometry_carrier": "max_selected_fbx",
            "interactive_tools_outside_export_graph": True,
            "auxiliary_geometry_outside_export_graph": True,
            "mutation_tests": {
                "unrelated_getNormal": "PASS",
                "unrelated_tool_fingerprint": "UNCHANGED",
                "benign_export_edit": "AI_REVIEW_REQUIRED_NONBLOCKING",
                "fbx_exporter_plugin_load_removed": "BLOCKED",
                "fbx_exporter_readback_removed": "BLOCKED",
                "fbx_exporter_exception_swallowed": "BLOCKED",
                "reachable_getNormal": "BLOCKED",
            "unapproved_reachable_rt_objects": "BLOCKED",
                "cached_include_skin_bones_get": "BLOCKED",
                "cached_include_skin_bones_subscript": "BLOCKED",
                "export_scene_interface_route_drift": "BLOCKED",
                "auxiliary_geometry_api": "PASS",
            },
        }
    )
    return report


def _run_popup_foreground_policy_guard() -> dict[str, Any]:
    """Enforce the single managed-window scheduler contract for every GUI surface."""
    source_path = Path(__file__).resolve()
    try:
        source = source_path.read_text(encoding="utf-8")
        tree = ast.parse(source, filename=str(source_path))
    except (OSError, SyntaxError) as exc:
        raise RuntimeError(f"Cannot validate the managed-window policy: {exc}") from exc

    parents: dict[ast.AST, ast.AST] = {}
    for parent in ast.walk(tree):
        for child in ast.iter_child_nodes(parent):
            parents[child] = parent

    def qualified_function(node: ast.AST) -> str:
        current: ast.AST | None = node
        function_names: list[str] = []
        class_name = ""
        while current is not None:
            if isinstance(current, (ast.FunctionDef, ast.AsyncFunctionDef)):
                function_names.append(current.name)
            elif isinstance(current, ast.ClassDef):
                class_name = current.name
                break
            current = parents.get(current)
        if not function_names:
            return "<module>"
        qualified = ".".join(reversed(function_names))
        return f"{class_name}.{qualified}" if class_name else qualified

    def leaf_call_names(node: ast.AST) -> set[str]:
        names: set[str] = set()
        for call in ast.walk(node):
            if not isinstance(call, ast.Call):
                continue
            if isinstance(call.func, ast.Name):
                names.add(call.func.id)
            elif isinstance(call.func, ast.Attribute):
                names.add(call.func.attr)
        return names

    def method_source(node: ast.AST | None) -> str:
        return ast.get_source_segment(source, node) or "" if node is not None else ""

    violations: list[str] = []
    class_defs = [
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == "_ManagedWindowScheduler"
    ]
    if len(class_defs) != 1:
        violations.append(f"managed_scheduler_class_count={len(class_defs)}")
        scheduler_methods: dict[str, ast.AST] = {}
    else:
        scheduler_methods = {
            node.name: node
            for node in class_defs[0].body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        }
    required_scheduler_methods = {
        "register",
        "unregister",
        "dispose",
        "mark_recent",
        "_window_priority",
        "acquire_temporary_layer",
        "release_temporary_layer",
        "_native_stack_is_current",
        "window_activated",
        "observe_geometry",
        "forget_geometry",
        "window_configured",
        "_flush_geometry",
        "begin_settling",
        "finish_settling",
        "is_settling",
        "floating_ball_active",
        "is_floating_ball",
        "window_deferred_for_floating",
        "wait_until_floating_restored",
        "run_after_floating_restore",
        "enforce_floating_ball",
        "enter_floating_ball",
        "restore_from_floating_ball",
        "request_restack",
        "flush_restack",
        "set_geometry",
        "sync_topmost",
        "request_activation",
        "allows_background_max_execution",
        "show",
        "hide",
        "show_exclusive",
        "raise_all",
        "hide_for_launcher",
        "restore_after_launcher",
        "register_scroll_surface",
        "unregister_scroll_surface",
        "scroll_is_blocked",
        "latch_scrollbar",
        "layout_cache_key",
        "adaptive_window_geometry",
        "queue_scroll",
        "flush_scroll",
        "cancel_scroll",
    }
    missing_scheduler_methods = required_scheduler_methods - set(scheduler_methods)
    if missing_scheduler_methods:
        violations.append(
            "managed_scheduler_methods_missing="
            + ",".join(sorted(missing_scheduler_methods))
        )

    scheduler_contract = {
        "__init__": {"bind"},
        "dispose": {"unregister", "destroy", "request_restack"},
        "publish_root": {
            "_show_themed_window",
            "update_idletasks",
            "request_activation",
        },
        "request_activation": {
            "_foreground_window_pid",
            "_bring_tk_window_to_front",
            "_focus_tk_window_if_safe",
            "request_restack",
        },
        "wait_until_floating_restored": {"wait_variable"},
        "run_after_floating_restore": {
            "floating_ball_active",
            "window_deferred_for_floating",
        },
        "enforce_floating_ball": {
            "_show_themed_window",
            "_native_toplevel_hwnds",
            "lift",
            "_schedule_floating_guard",
        },
        "enter_floating_ball": {
            "show",
            "withdraw",
            "enforce_floating_ball",
        },
        "restore_from_floating_ball": {
            "_show_themed_window",
            "show",
            "hide",
            "request_activation",
        },
        "finish_settling": {"after"},
        "request_restack": {"after"},
        "flush_restack": {"sync_topmost"},
        "window_activated": {"request_restack"},
        "window_configured": {"after"},
        "_flush_geometry": {"after"},
        "show": {
            "_show_themed_window",
            "sync_topmost",
            "request_activation",
            "_flush_native_window_paints",
            "_reveal_themed_window",
            "finish_settling",
        },
        "hide": {
            "_mask_window_until_themed",
            "_suspend_tk_grab_for_unmap",
            "withdraw",
            "request_restack",
        },
        "show_exclusive": {"iconify", "show"},
        "raise_all": {"request_activation"},
        "unregister_scroll_surface": {"cancel_scroll"},
        "adaptive_window_geometry": {"minsize", "maxsize"},
        "queue_scroll": {"scroll_is_blocked", "after"},
        "flush_scroll": {"scroll_is_blocked", "after"},
        "hide_for_launcher": {
            "_mask_window_until_themed",
            "_suspend_tk_grab_for_unmap",
            "withdraw",
        },
        "restore_after_launcher": {
            "show",
            "_flush_native_window_paints",
            "_reveal_themed_window",
            "_restore_tk_grab_after_map",
            "finish_settling",
        },
        "queue_scroll": {"after"},
        "flush_scroll": {"_atomic_native_viewport_paint"},
    }
    for method_name, required_calls in scheduler_contract.items():
        node = scheduler_methods.get(method_name)
        calls = leaf_call_names(node) if node is not None else set()
        missing = required_calls - calls
        if missing:
            violations.append(
                f"managed_scheduler_{method_name}_calls_missing="
                + ",".join(sorted(missing))
            )

    show_source = method_source(scheduler_methods.get("show"))
    hide_source = method_source(scheduler_methods.get("hide_for_launcher"))
    restore_source = method_source(scheduler_methods.get("restore_after_launcher"))
    init_source = method_source(scheduler_methods.get("__init__"))
    sync_topmost_source = method_source(scheduler_methods.get("sync_topmost"))
    activation_source = method_source(scheduler_methods.get("request_activation"))
    floating_active_source = method_source(
        scheduler_methods.get("floating_ball_active")
    )
    floating_enforce_source = method_source(
        scheduler_methods.get("enforce_floating_ball")
    )
    floating_enter_source = method_source(
        scheduler_methods.get("enter_floating_ball")
    )
    floating_restore_source = method_source(
        scheduler_methods.get("restore_from_floating_ball")
    )
    floating_hide_source = method_source(scheduler_methods.get("hide"))
    floating_deferred_callback_source = method_source(
        scheduler_methods.get("run_after_floating_restore")
    )
    background_max_source = method_source(
        scheduler_methods.get("allows_background_max_execution")
    )
    queue_scroll_source = method_source(scheduler_methods.get("queue_scroll"))
    flush_scroll_source = method_source(scheduler_methods.get("flush_scroll"))
    if "MANAGED_WINDOW_STAGING" not in show_source or "if activate:" not in show_source:
        violations.append("managed_scheduler_show_state_or_explicit_activation_missing")
    if "activate=False" not in restore_source:
        violations.append("managed_restore_can_steal_focus")
    if hide_source.find("_mask_window_until_themed") > hide_source.find(".withdraw("):
        violations.append("managed_hide_masks_after_withdraw")
    if any(
        "time.sleep(" in candidate
        for candidate in (show_source, restore_source, activation_source)
    ):
        violations.append("managed_scheduler_contains_activation_sleep")
    if ".after(" in activation_source or "after_idle" in activation_source:
        violations.append("managed_activation_contains_retry_loop")
    if "return not bool(topmost_enabled)" not in background_max_source:
        violations.append("managed_background_max_condition_is_not_topmost_inverse")
    if "_pc_rehd_floating_ball_active" not in floating_active_source:
        violations.append("managed_floating_ball_state_not_scheduler_owned")
    if (
        "MANAGED_WINDOW_FLOATING_BALL_LAYER" not in floating_enter_source
        or "MANAGED_WINDOW_FLOATING_HIDDEN" not in floating_restore_source
        or "SetWindowPos" not in floating_enforce_source
        or "-topmost" not in floating_enforce_source
        or "FLOATING_BALL_GUARD_INTERVAL_MS" not in method_source(
            scheduler_methods.get("_schedule_floating_guard")
        )
    ):
        violations.append("managed_floating_ball_exclusive_topmost_contract_missing")
    if (
        "_pc_rehd_floating_restore_callbacks" not in floating_deferred_callback_source
        or "_pc_rehd_floating_restore_callbacks" not in floating_restore_source
        or "callback()" not in floating_restore_source
        or "_pc_rehd_floating_restore_callbacks" not in floating_hide_source
    ):
        violations.append("managed_floating_deferred_ui_commit_missing")
    for sequence in ("<Configure>", "<Activate>", "<ButtonRelease>"):
        if sequence not in init_source:
            violations.append(f"managed_root_restack_binding_missing={sequence}")
    if "<ButtonPress>" in init_source:
        violations.append("managed_root_restack_can_discard_button_command")
    if "after_idle" in queue_scroll_source or ".after(0," not in queue_scroll_source:
        violations.append("managed_scroll_can_starve_behind_continuous_input")
    if "update_idletasks" in flush_scroll_source:
        violations.append("managed_scroll_forces_global_idle_flush")
    if (
        "_flush_native_window_paints(restored)" not in restore_source
        or restore_source.find("_flush_native_window_paints(restored)")
        > restore_source.find("_reveal_themed_window")
    ):
        violations.append("managed_restore_not_single_batch_paint")
    if "update_idletasks" in restore_source:
        violations.append("managed_restore_contains_per_window_idle_flush")
    if "visible.sort(key=self._window_priority)" not in sync_topmost_source:
        violations.append("managed_window_layers_not_stable")
    if (
        "MANAGED_WINDOW_DIALOG_LAYER" not in sync_topmost_source
        or "_native_stack_is_current" not in sync_topmost_source
    ):
        violations.append("managed_modal_layer_or_native_order_probe_missing")
    if (
        "if not root_topmost:" not in sync_topmost_source
        or "self.root.lift()" not in sync_topmost_source
    ):
        violations.append("managed_non_topmost_group_restack_missing")
    if show_source.find("self.request_activation") > show_source.find("self.sync_topmost"):
        violations.append("managed_activation_can_override_final_layer_order")
    if show_source.find("self.sync_topmost") > show_source.find(
        "_reveal_themed_window"
    ):
        violations.append("managed_window_revealed_before_final_layer_order")

    painter_defs = [
        node
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name == "_show_themed_window"
    ]
    if len(painter_defs) != 1:
        violations.append("managed_hidden_painter_missing")
    else:
        painter_calls = leaf_call_names(painter_defs[0])
        required_painter_calls = {
            "_mask_window_until_themed",
            "_prepare_native_window_theme_restore",
            "_refresh_tk_window_theme",
            "_apply_native_window_theme",
            "_drain_tk_window_paint_events",
            "deiconify",
            "_flush_native_window_paints",
            "_restore_native_window_theme_mask",
            "_reveal_themed_window",
        }
        missing = required_painter_calls - painter_calls
        if missing:
            violations.append(
                "managed_hidden_painter_calls_missing=" + ",".join(sorted(missing))
            )
        painter_source = method_source(painter_defs[0])
        if (
            painter_source.find("_mask_window_until_themed") > painter_source.find(".deiconify(")
            or painter_source.find(".deiconify(") > painter_source.find("_reveal_themed_window")
            or "+20000+20000" not in painter_source
        ):
            violations.append("managed_hidden_painter_order_or_offscreen_stage_invalid")

    toplevel_calls = 0
    lifecycle_bindings: list[tuple[str, str, str, int]] = []
    visibility_allowlist = {
        "withdraw": {
            "_ManagedWindowScheduler._defer_window_for_floating",
            "_ManagedWindowScheduler.enter_floating_ball",
            "_ManagedWindowScheduler.restore_from_floating_ball",
            "_ManagedWindowScheduler.hide",
            "_ManagedWindowScheduler.hide_for_launcher",
            "_create_managed_toplevel",
            "LauncherApp._on_close",
            "run_ui",
            "run_ui_smoke_test",
        },
        "deiconify": {"_show_themed_window", "run_ui_smoke_test"},
        "iconify": {"_ManagedWindowScheduler.show_exclusive"},
    }
    geometry_write_allowlist = {
        "_ManagedWindowScheduler.set_geometry",
        "_ManagedWindowScheduler.show",
        "_set_themed_window_geometry",
        "_show_themed_window",
        "run_ui_smoke_test",
    }
    activation_allowlist = {"_ManagedWindowScheduler.request_activation"}
    topmost_allowlist = {
        "_ManagedWindowScheduler.enforce_floating_ball",
        "_ManagedWindowScheduler.sync_topmost",
        "_run_managed_native_dialog",
        "LauncherApp._apply_topmost.apply_window",
        "run_ui_smoke_test",
    }

    for node in ast.walk(tree):
        scope = qualified_function(node)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            is_toplevel_constructor = node.func.attr == "Toplevel" or (
                node.func.attr == "__new__"
                and isinstance(node.func.value, ast.Attribute)
                and node.func.value.attr == "Toplevel"
            )
            if is_toplevel_constructor:
                toplevel_calls += 1
                if scope != _MANAGED_TOPLEVEL_FACTORY:
                    violations.append(f"direct_Toplevel@{node.lineno}")
            elif node.func.attr in _POPUP_API_NAMES and scope not in {
                _MANAGED_FILE_DIALOG_HELPER,
                _MANAGED_MESSAGEBOX_HELPER,
            }:
                violations.append(f"direct_popup_api_{node.func.attr}@{node.lineno}")

            if node.func.attr == "bind" and node.args:
                sequence = (
                    str(node.args[0].value)
                    if isinstance(node.args[0], ast.Constant)
                    and isinstance(node.args[0].value, str)
                    else ""
                )
                if sequence in {"<Map>", "<Unmap>", "<Visibility>"}:
                    receiver = ast.unparse(node.func.value)
                    lifecycle_bindings.append(
                        (scope, receiver, sequence, node.lineno)
                    )

            if node.func.attr in visibility_allowlist:
                if scope not in visibility_allowlist[node.func.attr]:
                    violations.append(
                        f"decentralized_{node.func.attr}@{scope}:{node.lineno}"
                    )

            if node.func.attr == "geometry" and node.args:
                if scope not in geometry_write_allowlist:
                    violations.append(f"managed_geometry_bypass@{scope}:{node.lineno}")

            if node.func.attr == "attributes" and node.args:
                first_argument = node.args[0]
                if (
                    isinstance(first_argument, ast.Constant)
                    and first_argument.value == "-topmost"
                    and scope not in topmost_allowlist
                ):
                    violations.append(f"managed_topmost_bypass@{scope}:{node.lineno}")

        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            if (
                node.func.id in {"_bring_tk_window_to_front", "_focus_tk_window_if_safe"}
                and scope not in activation_allowlist
            ):
                violations.append(
                    f"managed_activation_bypass_{node.func.id}@{scope}:{node.lineno}"
                )

        if isinstance(node, ast.ImportFrom) and node.module == "tkinter":
            for alias in node.names:
                if alias.name in {
                    "filedialog",
                    "messagebox",
                    "simpledialog",
                    "colorchooser",
                } and scope not in {
                    _MANAGED_FILE_DIALOG_HELPER,
                    _MANAGED_MESSAGEBOX_HELPER,
                }:
                    violations.append(
                        f"direct_popup_import_{alias.name}@{node.lineno}"
                    )

    if toplevel_calls != 1:
        violations.append(f"managed_Toplevel_call_count={toplevel_calls}")
    expected_lifecycle_bindings = {
        ("LauncherApp.__init__", "self.root", "<Map>"),
        ("LauncherApp.__init__", "self.root", "<Unmap>"),
        ("LauncherApp.__init__", "self.root", "<Visibility>"),
    }
    actual_lifecycle_bindings = {
        (scope, receiver, sequence)
        for scope, receiver, sequence, _line in lifecycle_bindings
    }
    if actual_lifecycle_bindings != expected_lifecycle_bindings:
        violations.append(
            "managed_lifecycle_bindings_invalid="
            + repr(sorted(actual_lifecycle_bindings))
        )

    deprecated_identifiers = {
        "_repair_native_managed_window_owner",
        "_detach_native_managed_window_owner",
        "_install_native_minimize_interceptor",
        "_queue_managed_window_foreground_restore",
        "_prepare_themed_window_for_unmap",
        "_queue_toolbox_geometry_after_map",
        "_queue_themed_window_reveal",
        "_launcher_minimize_is_locked",
        "_pc_rehd_activation_generation",
        "_pc_rehd_logical_owner",
        "_pc_rehd_popup_focus_guard",
        "_pc_rehd_themed_reveal_after",
        "_pc_rehd_layout_pending",
        "_pc_rehd_pin_above_owner",
        "_message_editor_snap_after",
        "_scene_normals_monitor_snap_after",
        "_schedule_message_editor_snap",
        "_schedule_scene_normals_monitor_snap",
    }
    referenced_identifiers = {
        node.id for node in ast.walk(tree) if isinstance(node, ast.Name)
    } | {
        node.attr for node in ast.walk(tree) if isinstance(node, ast.Attribute)
    } | {
        node.name
        for node in ast.walk(tree)
        if isinstance(
            node,
            (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef),
        )
    }
    for token in sorted(deprecated_identifiers & referenced_identifiers):
        violations.append(f"deprecated_window_patch_present={token}")
    for node in ast.walk(tree):
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and node.func.attr == "DwmFlush"
            and qualified_function(node) != "_flush_native_compositor_once"
        ):
            violations.append(
                f"per_window_compositor_block_present@{qualified_function(node)}:{node.lineno}"
            )
    if any(
        isinstance(node, ast.Call)
        and isinstance(node.func, ast.Attribute)
        and node.func.attr == "transient"
        for node in ast.walk(tree)
    ):
        violations.append("tk_transient_present")
    if any(
        isinstance(node, ast.Call)
        and any(
            isinstance(argument, ast.Constant) and argument.value == "transient"
            for argument in node.args
        )
        and any(
            isinstance(argument, ast.Constant) and argument.value == "wm"
            for argument in node.args
        )
        for node in ast.walk(tree)
    ):
        violations.append("native_tk_transient_present")

    function_defs = {
        node.name: node
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }
    qualified_function_defs = {
        qualified_function(node): node
        for node in ast.walk(tree)
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }
    deferred_interaction_contracts = {
        "MrlTextureBindDialog._show_history": (
            "run_after_floating_restore(",
            "commit_history_interaction",
            "winfo_viewable()",
            "window.grab_set()",
        ),
        "LauncherApp._show_manual_texture_path_history": (
            "run_after_floating_restore(",
            "commit_history_interaction",
            "winfo_viewable()",
            "window.grab_set()",
        ),
        "LauncherApp._show_fvf_weight_capacity_notice": (
            "run_after_floating_restore(",
            "commit_notice_interaction",
            "winfo_viewable()",
            "window.grab_set()",
            "update_countdown()",
        ),
    }
    for qualified_name, required_tokens in deferred_interaction_contracts.items():
        candidate_source = method_source(qualified_function_defs.get(qualified_name))
        for token in required_tokens:
            if token not in candidate_source:
                violations.append(
                    "managed_floating_deferred_interaction_missing="
                    + qualified_name
                    + ":"
                    + token
                )
    paint_drain_source = method_source(function_defs.get("_drain_tk_window_paint_events"))
    viewport_paint_source = method_source(function_defs.get("_atomic_native_viewport_paint"))
    if "IDLE_EVENTS" in paint_drain_source or "update_idletasks" in paint_drain_source:
        violations.append("managed_paint_drain_executes_unrelated_idle_callbacks")
    if "0x0100" in viewport_paint_source:
        violations.append("managed_viewport_scroll_forces_synchronous_native_paint")
    factory = function_defs.get(_MANAGED_TOPLEVEL_FACTORY)
    if factory is None:
        violations.append("managed_Toplevel_factory_missing")
    else:
        factory_calls = leaf_call_names(factory)
        for required_call in {
            "_install_window_foreground_guard",
            "_install_tk_pointer_interaction_guard",
            "_mask_window_until_themed",
            "withdraw",
        }:
            if required_call not in factory_calls:
                violations.append(
                    f"managed_factory_call_missing={required_call}"
                )
        factory_source = method_source(factory)
        if factory_source.find(".withdraw(") > factory_source.find(
            "_mask_window_until_themed"
        ):
            violations.append("managed_factory_does_not_withdraw_before_native_mask")
        if "<ButtonPress>" in factory_source or any(
            sequence not in factory_source
            for sequence in ("<Configure>", "<Activate>", "<ButtonRelease>")
        ):
            violations.append("managed_factory_activation_binding_invalid")

    for helper_name in (
        "_managed_window_scheduler",
        "_show_managed_toplevel",
        "_restore_managed_window_foreground",
        "_managed_scroll_command",
        "_managed_file_dialog",
        "_managed_messagebox",
    ):
        if helper_name not in function_defs:
            violations.append(f"managed_helper_missing={helper_name}")

    for method_name in (
        "_show_toolbox",
        "_show_blender_toolbox",
        "_show_scene_normals_monitor",
        "_show_rename_selection_notice",
    ):
        method = function_defs.get(method_name)
        calls = leaf_call_names(method) if method is not None else set()
        if "_show_managed_toplevel" not in calls:
            violations.append(f"managed_surface_show_bypass={method_name}")

    tooltip_classes = [
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == "HoverTooltip"
    ]
    if len(tooltip_classes) != 1:
        violations.append(f"managed_tooltip_class_count={len(tooltip_classes)}")
    else:
        tooltip_methods = {
            node.name: node
            for node in tooltip_classes[0].body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        }
        tooltip_show_source = method_source(tooltip_methods.get("_show"))
        tooltip_hide_source = method_source(tooltip_methods.get("_hide"))
        if (
            "MANAGED_WINDOW_TOOLTIP_LAYER" not in tooltip_show_source
            or "acquire_temporary_layer" not in tooltip_show_source
            or "force_front=True" not in tooltip_show_source
        ):
            violations.append("managed_tooltip_temporary_layer_missing")
        if "_release_temporary_layer" not in tooltip_hide_source:
            violations.append("managed_tooltip_layer_release_missing")

    layer_contracts = {
        "_show_toolbox": "MANAGED_WINDOW_TOOLBOX_LAYER",
        "_show_blender_toolbox": "MANAGED_WINDOW_TOOLBOX_LAYER",
        "_show_message_editor": "MANAGED_WINDOW_PERSISTENT_LAYER",
        "_show_scene_normals_monitor": "MANAGED_WINDOW_PERSISTENT_LAYER",
        "_show_rename_selection_notice": "MANAGED_WINDOW_TOOLTIP_LAYER",
    }
    for method_name, layer_token in layer_contracts.items():
        method = function_defs.get(method_name)
        if layer_token not in method_source(method):
            violations.append(f"managed_surface_layer_missing={method_name}")
    for method_name in ("_show_message_editor", "_show_scene_normals_monitor"):
        method = function_defs.get(method_name)
        if method is None or "observe_geometry" not in leaf_call_names(method):
            violations.append(f"managed_surface_geometry_observer_missing={method_name}")
    rename_notice_hide_source = method_source(
        function_defs.get("_hide_rename_selection_notice")
    )
    for token in ("release_temporary_layer", "dispose"):
        if token not in rename_notice_hide_source:
            violations.append(
                f"managed_rename_notice_hide_contract_missing={token}"
            )

    for method_name in (
        "_present_exclusive_export_sets_window",
        "_present_exclusive_instance_copy_window",
        "_present_exclusive_seam_window",
    ):
        method = function_defs.get(method_name)
        if method is None or "show_exclusive" not in leaf_call_names(method):
            violations.append(f"exclusive_surface_scheduler_bypass={method_name}")

    choice_dialog_classes = [
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == "ChoiceDialog"
    ]
    if len(choice_dialog_classes) != 1:
        violations.append(
            f"managed_choice_dialog_class_count={len(choice_dialog_classes)}"
        )
    else:
        choice_dialog_methods = {
            node.name: node
            for node in choice_dialog_classes[0].body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        }
        choice_init_source = method_source(choice_dialog_methods.get("__init__"))
        choice_show_source = method_source(choice_dialog_methods.get("show"))
        for token in (
            "_pc_rehd_keep_owner_minimized",
            "owner_hidden",
            "center_on_screen or owner_hidden",
        ):
            if token not in choice_init_source:
                violations.append(
                    f"managed_choice_dialog_hidden_owner_missing={token}"
                )
        for token in (
            "_show_managed_toplevel",
            "wait_until_floating_restored",
            "winfo_viewable",
            "if not visible:",
            "self._cancel()",
            "self.window.grab_set()",
        ):
            if token not in choice_show_source:
                violations.append(
                    f"managed_choice_dialog_visibility_gate_missing={token}"
                )
        if choice_show_source.find("winfo_viewable") > choice_show_source.find(
            "self.window.grab_set()"
        ):
            violations.append("managed_choice_dialog_grabs_before_visible")

    for wrapper_name in (_MANAGED_FILE_DIALOG_HELPER, _MANAGED_MESSAGEBOX_HELPER):
        wrapper = function_defs.get(wrapper_name)
        if (
            wrapper is None
            or "_run_managed_native_dialog" not in leaf_call_names(wrapper)
        ):
            violations.append(f"managed_native_dialog_wrapper_bypass={wrapper_name}")

    native_dialog_runner = function_defs.get("_run_managed_native_dialog")
    native_dialog_source = method_source(native_dialog_runner)
    for token in (
        "MANAGED_WINDOW_NATIVE_DIALOG_LAYER",
        "_pc_rehd_native_dialog_active",
        "_pc_rehd_native_dialog_lease",
        "wait_until_floating_restored",
    ):
        if token not in native_dialog_source:
            violations.append(f"managed_native_dialog_lease_missing={token}")
    if native_dialog_runner is None or not any(
        isinstance(node, ast.Try) and bool(node.finalbody)
        for node in ast.walk(native_dialog_runner)
    ):
        violations.append("managed_native_dialog_lease_has_no_finally")

    notice = function_defs.get("_show_mesh_slot_limit_notice")
    if notice is None:
        violations.append("mesh_slot_limit_notice_missing")
    else:
        notice_calls = leaf_call_names(notice)
        blocking = {"grab_set", "grab_set_global", "wait_window"} & notice_calls
        if blocking:
            violations.append(
                "mesh_slot_limit_notice_blocks_export=" + ",".join(sorted(blocking))
            )
        if "after" not in notice_calls or not any(
            isinstance(node, ast.Constant) and node.value == 8
            for node in ast.walk(notice)
        ):
            violations.append("mesh_slot_limit_notice_async_countdown_invalid")

    export_queue = function_defs.get("_queue_export_sets_foreground_restore")
    if export_queue is None:
        violations.append("export_sets_foreground_coalescer_missing")
    else:
        queue_calls = leaf_call_names(export_queue)
        if "after_idle" not in queue_calls or "after" in queue_calls:
            violations.append("export_sets_foreground_not_single_idle_commit")

    launcher_unmap = function_defs.get("_on_launcher_unmapped")
    launcher_restore = function_defs.get("_queue_launcher_restore")
    if (
        launcher_unmap is None
        or "_hide_managed_windows_for_launcher_minimize"
        not in leaf_call_names(launcher_unmap)
    ):
        violations.append("launcher_minimize_scheduler_delegate_missing")
    if (
        launcher_restore is None
        or "_restore_managed_windows_after_launcher"
        not in leaf_call_names(launcher_restore)
    ):
        violations.append("launcher_restore_scheduler_delegate_missing")
    launcher_unmap_source = method_source(launcher_unmap)
    if (
        "floating_ball_active" not in launcher_unmap_source
        or "enforce_floating_ball" not in launcher_unmap_source
    ):
        violations.append("launcher_unmap_can_escape_floating_ball_state")
    for method_name in (
        "_enter_floating_ball",
        "_restore_from_floating_ball",
        "_toggle_floating_ball",
    ):
        method = function_defs.get(method_name)
        if method is None:
            violations.append(f"launcher_floating_ball_method_missing={method_name}")
    floating_enter = function_defs.get("_enter_floating_ball")
    floating_restore = function_defs.get("_restore_from_floating_ball")
    if floating_enter is not None and "enter_floating_ball" not in leaf_call_names(
        floating_enter
    ):
        violations.append("launcher_floating_ball_enter_bypasses_scheduler")
    if floating_restore is not None and "restore_from_floating_ball" not in leaf_call_names(
        floating_restore
    ):
        violations.append("launcher_floating_ball_restore_bypasses_scheduler")

    if violations:
        raise RuntimeError(
            "Managed-window scheduler policy violation: "
            + ", ".join(sorted(set(violations))[:40])
        )
    return {
        "status": "PASS",
        "version": POPUP_FOREGROUND_POLICY_VERSION,
        "rule": POPUP_FOREGROUND_POLICY_RULE,
        "scheduler": "_ManagedWindowScheduler",
        "scheduler_methods": sorted(required_scheduler_methods),
        "direct_toplevel_calls": toplevel_calls,
        "lifecycle_bindings": ["Launcher.<Map>", "Launcher.<Unmap>", "Launcher.<Visibility>"],
        "managed_restore_states": [
            MANAGED_WINDOW_LAYOUT,
            MANAGED_WINDOW_STAGING,
            MANAGED_WINDOW_VISIBLE,
            MANAGED_WINDOW_LAUNCHER_HIDDEN,
            MANAGED_WINDOW_FLOATING_HIDDEN,
            MANAGED_WINDOW_DESTROYED,
        ],
        "hidden_paint": "transparent_offscreen_single_reveal",
        "passive_restore_activation": False,
        "per_window_restore_handlers": False,
        "native_owner_mutation": False,
        "activation_retries": False,
        "persisted_position_owner": "feature",
        "live_restore_position_owner": "_ManagedWindowScheduler",
        "viewport_commit_owner": "_ManagedWindowScheduler",
        "window_layers": {
            "persistent": MANAGED_WINDOW_PERSISTENT_LAYER,
            "toolbox": MANAGED_WINDOW_TOOLBOX_LAYER,
            "dialog": MANAGED_WINDOW_DIALOG_LAYER,
            "tooltip": MANAGED_WINDOW_TOOLTIP_LAYER,
            "native_dialog": MANAGED_WINDOW_NATIVE_DIALOG_LAYER,
            "floating_ball": MANAGED_WINDOW_FLOATING_BALL_LAYER,
        },
        "native_z_order_probe": True,
        "blocking_modal_visible_before_grab": True,
        "mesh_slot_limit_notice_nonblocking": True,
        "floating_ball_exclusive_visibility": True,
        "floating_ball_native_topmost_guard_ms": FLOATING_BALL_GUARD_INTERVAL_MS,
        "floating_deferred_interactions": "restore_then_grab_focus_or_countdown",
    }
def _normalize_mesh_filter_choice(value: object) -> str:
    text = str(value or "").strip()
    if not text or text == "显示全部" or text.casefold() in {"all", "show all"}:
        return "All"
    for prefix in ("仅展示 ", "Show only "):
        if text.startswith(prefix):
            text = text[len(prefix):].strip()
            break
    return text or "All"


# PC-REHD 1.2.8/V4 tests this MeshHeader field as decimal ``4128``.
RE6_DEGENERATE_LINE_MESH_TYPE = 4128
BLENDER_MESH_TYPE_RECOVERY_SCHEMA = "pc-rehd-blender-mesh-type-recovery-v1"
BLENDER_NODE_MAP_SCHEMA = "pc-rehd-blender-node-map-v1"
BLENDER_NODE_MAP_DIRECTORY_NAME = "BlenderNodeMaps"
BLENDER_NODE_MAP_TRUSTED = "TRUSTED"
BLENDER_NODE_MAP_UNTRUSTED = "UNTRUSTED"
BLENDER_NODE_MAP_MONITOR_INTERVAL_SECONDS = 1.5
BLENDER_MAX_FBX_NAME_REPAIR_DETECTION_INTERVAL_SECONDS = 2.0
BLENDER_NODE_MAP_HEADER_FIELDS = (
    "meshtype",
    "vert_count",
    "unk01",
    "mat_id",
    "lod_level",
    "unk04",
    "vert_flag",
    "vert_stride",
    "unk05",
    "vert_start",
    "vert_base",
    "fvf_info",
    "face_start",
    "face_count",
    "face_base",
    "bonemapindex",
    "weightmaps",
    "unk07",
    "unk08",
    "min_index",
    "max_index",
    "unk09",
)
BLENDER_NODE_MAP_HEADER_CONTRACT_FIELDS = {
    "fvf_info": "header_fvf",
    "lod_level": "lod_level",
    "mat_id": "material_id",
    "unk01": "group_id",
    "unk05": "display_mode",
    "meshtype": "mesh_type",
}


def _valid_sha256_text(value: object) -> str:
    text = str(value or "").strip().upper()
    return text if re.fullmatch(r"[0-9A-F]{64}", text) else ""


def _blender_node_map_cache_directory(log_directory: str | Path) -> Path:
    root = _normalize_long_term_cache_directory(log_directory)
    return root / BLENDER_NODE_MAP_DIRECTORY_NAME


def _blender_node_map_cache_path(log_directory: str | Path, node_map_id: object) -> Path:
    normalized_id = str(node_map_id or "").strip().lower()
    if not re.fullmatch(r"[0-9a-f]{32}", normalized_id):
        raise ValueError("Blender node map ID is invalid")
    return _blender_node_map_cache_directory(log_directory) / f"{normalized_id}.json"


def _atomic_write_json_document(path: Path, value: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(
        f".{path.name}.{os.getpid()}.{threading.get_ident()}.{uuid.uuid4().hex}.tmp"
    )
    try:
        temporary.write_text(
            json.dumps(
                dict(value), ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
            )
            + "\n",
            encoding="utf-8",
            newline="\n",
        )
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def _canonical_blender_mesh_name(display_slot: object) -> str:
    slot = _positive_mesh_slot(display_slot)
    if slot <= 0:
        raise ValueError("Blender node map has no positive display Mesh slot")
    return f"Mesh_{slot:03d}"


def _normalize_blender_node_map_header(value: object) -> dict[str, int]:
    if not isinstance(value, Mapping):
        raise ValueError("Blender node map Mesh Header is not an object")
    header: dict[str, int] = {}
    for field_name in BLENDER_NODE_MAP_HEADER_FIELDS:
        if field_name not in value:
            raise ValueError(f"Blender node map Mesh Header is missing {field_name}")
        try:
            header[field_name] = int(value[field_name])
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError(
                f"Blender node map Mesh Header has an invalid {field_name}"
            ) from exc
    if not 0 <= header["fvf_info"] <= 0xFFFFFFFF:
        raise ValueError("Blender node map Mesh Header FVF is out of range")
    if not 0 <= header["meshtype"] <= 0xFFFF:
        raise ValueError("Blender node map Mesh Header Type is out of range")
    return header


def _blender_node_map_header_digest(header: Mapping[str, Any]) -> str:
    normalized = _normalize_blender_node_map_header(header)
    return hashlib.sha256(
        json.dumps(normalized, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest().upper()


def _blender_node_map_summary(node_map: Mapping[str, Any] | None) -> dict[str, Any]:
    value = node_map if isinstance(node_map, Mapping) else {}
    entries = value.get("entries", [])
    return {
        "schema": BLENDER_NODE_MAP_SCHEMA,
        "node_map_id": str(value.get("node_map_id", "") or ""),
        "status": str(value.get("status", BLENDER_NODE_MAP_UNTRUSTED) or BLENDER_NODE_MAP_UNTRUSTED),
        "entry_count": len(entries) if isinstance(entries, list) else 0,
        "source_sha256": _valid_sha256_text(
            (value.get("source") or {}).get("sha256") if isinstance(value.get("source"), Mapping) else ""
        ),
        "reason": str(value.get("status_reason", "") or ""),
    }


def _write_blender_node_map(log_directory: str | Path, node_map: Mapping[str, Any]) -> Path:
    value = copy.deepcopy(dict(node_map))
    if str(value.get("schema", "") or "") != BLENDER_NODE_MAP_SCHEMA:
        raise ValueError("Blender node map schema is invalid")
    path = _blender_node_map_cache_path(log_directory, value.get("node_map_id"))
    value["updated_at"] = time.strftime("%Y-%m-%dT%H:%M:%S%z", time.localtime())
    _atomic_write_json_document(path, value)
    return path


def _load_blender_node_map(log_directory: str | Path, node_map_id: object) -> dict[str, Any] | None:
    try:
        path = _blender_node_map_cache_path(log_directory, node_map_id)
        if not path.is_file():
            return None
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError):
        return None
    if not isinstance(value, dict):
        return None
    if str(value.get("schema", "") or "") != BLENDER_NODE_MAP_SCHEMA:
        return None
    if str(value.get("node_map_id", "") or "").strip().lower() != str(node_map_id or "").strip().lower():
        return None
    return value


def _read_mod_mesh_header_source(source_mod: str | Path) -> dict[str, Any]:
    """Read one immutable MOD Header table for Blender node-map construction."""
    source = Path(source_mod).expanduser().resolve(strict=True)
    if not _is_export_source_mod(source, require_file=True):
        raise ValueError(f"Blender node-map source is not a readable .MOD: {source}")
    source_bytes = b""
    source_snapshot: dict[str, Any] | None = None
    for _attempt in range(2):
        before = _file_snapshot(source)
        candidate = source.read_bytes()
        after = _file_snapshot(source)
        if _same_file_snapshot(before, after):
            source_bytes = candidate
            source_snapshot = after
            break
    if source_snapshot is None:
        raise RuntimeError(f"MOD changed while reading Blender node-map source: {source}")
    importer = _load_operation_dependency("import_mod", "importer")
    parse_header = getattr(importer, "_parse_header", None)
    parse_mesh_headers = getattr(importer, "_parse_mesh_headers", None)
    find_display_map = getattr(importer, "_find_cdxm_display_map", None)
    display_slot_from_map = getattr(importer, "_display_slot_from_map", None)
    if not all(callable(value) for value in (parse_header, parse_mesh_headers, find_display_map, display_slot_from_map)):
        raise RuntimeError("Importer has no complete MOD Header parser for Blender node maps")
    mod_header = parse_header(source_bytes)
    raw_headers = list(parse_mesh_headers(source_bytes, mod_header))
    raw_display_map = list(find_display_map(source_bytes, mod_header) or [])
    if not raw_headers:
        raise RuntimeError("Blender node-map source MOD has no Mesh Headers")
    headers_by_physical: dict[int, dict[str, int]] = {}
    display_to_physical: dict[int, int] = {}
    physical_to_display: dict[int, int] = {}
    for physical_slot, raw_header in enumerate(raw_headers, start=1):
        header = _normalize_blender_node_map_header(
            {field_name: getattr(raw_header, field_name) for field_name in BLENDER_NODE_MAP_HEADER_FIELDS}
        )
        display_slot = _positive_mesh_slot(display_slot_from_map(raw_display_map, physical_slot))
        if display_slot <= 0:
            display_slot = physical_slot
        if display_slot in display_to_physical:
            raise ProtocolError(
                f"Source MOD maps display Mesh_{display_slot:03d} to more than one physical Header"
            )
        headers_by_physical[physical_slot] = header
        physical_to_display[physical_slot] = display_slot
        display_to_physical[display_slot] = physical_slot
    _require_unchanged_file_snapshot(source, source_snapshot, label="Blender node-map source MOD")
    return {
        "path": str(source),
        "name": source.name,
        "sha256": hashlib.sha256(source_bytes).hexdigest().upper(),
        "headers_by_physical": headers_by_physical,
        "physical_to_display": physical_to_display,
        "display_to_physical": display_to_physical,
    }


def _build_blender_node_map(
    scene_contract: Mapping[str, Any],
    worker_snapshot: Mapping[str, Any],
    source: Mapping[str, Any],
    *,
    blender_process_id: int,
    reason: str,
) -> dict[str, Any]:
    """Join every live Blender Mesh to one source MOD Header exactly once."""
    if not isinstance(scene_contract, Mapping) or not isinstance(worker_snapshot, Mapping):
        raise TypeError("Blender node-map construction requires scene and Worker snapshots")
    headers_by_physical = source.get("headers_by_physical", {})
    physical_to_display = source.get("physical_to_display", {})
    display_to_physical = source.get("display_to_physical", {})
    source_sha = _valid_sha256_text(source.get("sha256"))
    if not isinstance(headers_by_physical, Mapping) or not source_sha:
        raise ValueError("Blender node-map source Headers are incomplete")
    scene_by_handle = {
        int(row.get("scene_node_handle", 0) or 0): dict(row)
        for row in scene_contract.get("meshes", [])
        if isinstance(row, Mapping) and int(row.get("scene_node_handle", 0) or 0) > 0
    }
    snapshot_rows = worker_snapshot.get("meshes", [])
    if not isinstance(snapshot_rows, list) or not snapshot_rows:
        raise ProtocolError("Blender node-map snapshot has no Mesh rows")
    entries: list[dict[str, Any]] = []
    seen_handles: set[int] = set()
    seen_physical: set[int] = set()
    seen_display: set[int] = set()
    failures: list[str] = []
    for raw_snapshot in snapshot_rows:
        if not isinstance(raw_snapshot, Mapping):
            failures.append("invalid Worker Mesh row")
            continue
        handle = int(raw_snapshot.get("scene_node_handle", 0) or 0)
        if handle <= 0 or handle in seen_handles:
            failures.append(f"duplicate or invalid Blender Mesh handle {handle}")
            continue
        seen_handles.add(handle)
        scene_row = scene_by_handle.get(handle, {})
        raw_source_sha = _valid_sha256_text(
            scene_row.get("import_source_sha256", raw_snapshot.get("import_source_sha256", ""))
        )
        if raw_source_sha and raw_source_sha != source_sha:
            failures.append(f"Mesh handle {handle} belongs to another source MOD")
            continue
        physical_slot = _positive_mesh_slot(
            scene_row.get("physical_mesh_slot", raw_snapshot.get("physical_mesh_slot", 0))
        )
        if physical_slot <= 0:
            physical_slot = _positive_mesh_slot(
                scene_row.get("mesh_slot", raw_snapshot.get("mesh_slot", 0))
            )
        display_slot = _positive_mesh_slot(
            scene_row.get("display_mesh_slot", raw_snapshot.get("display_mesh_slot", 0))
        )
        if display_slot <= 0:
            display_slot = _positive_mesh_slot(
                scene_row.get("scene_name_mesh_slot", raw_snapshot.get("scene_name_mesh_slot", 0))
            )
        if physical_slot <= 0 and display_slot > 0:
            physical_slot = _positive_mesh_slot(display_to_physical.get(display_slot, 0))
        if physical_slot <= 0 or physical_slot not in headers_by_physical:
            failures.append(f"Mesh handle {handle} cannot be matched to the selected MOD Header")
            continue
        expected_display = _positive_mesh_slot(physical_to_display.get(physical_slot, 0))
        if expected_display <= 0:
            failures.append(f"Source MOD has no display slot for physical Mesh {physical_slot}")
            continue
        if display_slot > 0 and display_slot != expected_display:
            failures.append(
                f"Mesh handle {handle} display slot {display_slot} disagrees with source physical slot {physical_slot}"
            )
            continue
        if physical_slot in seen_physical or expected_display in seen_display:
            failures.append(
                f"Selected MOD produces an ambiguous Blender mapping for physical Mesh {physical_slot}"
            )
            continue
        seen_physical.add(physical_slot)
        seen_display.add(expected_display)
        header = _normalize_blender_node_map_header(headers_by_physical[physical_slot])
        entries.append(
            {
                "node_mapping_id": uuid.uuid4().hex,
                "canonical_name": _canonical_blender_mesh_name(expected_display),
                "physical_mesh_slot": physical_slot,
                "display_mesh_slot": expected_display,
                "node_handle": handle,
                "source_scene_name": str(
                    scene_row.get("scene_node", raw_snapshot.get("scene_node", "")) or ""
                ),
                "full_mesh_header": header,
                "full_mesh_header_sha256": _blender_node_map_header_digest(header),
            }
        )
    if failures:
        raise ProtocolError("Blender node-map build refused: " + "; ".join(failures[:12]))
    if len(entries) != len(snapshot_rows):
        raise ProtocolError("Blender node-map build did not cover every live Blender Mesh")
    entries.sort(key=lambda row: (int(row["display_mesh_slot"]), int(row["physical_mesh_slot"])))
    return {
        "schema": BLENDER_NODE_MAP_SCHEMA,
        "node_map_id": uuid.uuid4().hex,
        "status": BLENDER_NODE_MAP_TRUSTED,
        "status_reason": str(reason or "built"),
        "blender_process_id": int(blender_process_id),
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%S%z", time.localtime()),
        "source": {
            "path": str(source.get("path", "") or ""),
            "name": str(source.get("name", "") or ""),
            "sha256": source_sha,
        },
        "entries": entries,
        "last_snapshot": {},
    }


def _verify_blender_node_map_snapshot(
    node_map: Mapping[str, Any], worker_snapshot: Mapping[str, Any]
) -> dict[str, Any]:
    expected_map_id = str(node_map.get("node_map_id", "") or "").strip().lower()
    expected_entries = node_map.get("entries", [])
    snapshot_entries = worker_snapshot.get("meshes", [])
    errors: list[str] = []
    if not re.fullmatch(r"[0-9a-f]{32}", expected_map_id):
        errors.append("node map ID is invalid")
    if not isinstance(expected_entries, list) or not isinstance(snapshot_entries, list):
        errors.append("node-map entries are malformed")
        expected_entries = []
        snapshot_entries = []
    expected_by_id: dict[str, dict[str, Any]] = {}
    for raw_entry in expected_entries:
        if not isinstance(raw_entry, Mapping):
            errors.append("stored mapping contains an invalid entry")
            continue
        entry_id = str(raw_entry.get("node_mapping_id", "") or "").strip().lower()
        if not re.fullmatch(r"[0-9a-f]{32}", entry_id) or entry_id in expected_by_id:
            errors.append("stored mapping contains a duplicate or invalid entry ID")
            continue
        expected_by_id[entry_id] = dict(raw_entry)
    observed_by_id: dict[str, dict[str, Any]] = {}
    for raw_entry in snapshot_entries:
        if not isinstance(raw_entry, Mapping):
            errors.append("Worker snapshot contains an invalid Mesh entry")
            continue
        entry_id = str(raw_entry.get("node_mapping_id", "") or "").strip().lower()
        if not re.fullmatch(r"[0-9a-f]{32}", entry_id) or entry_id in observed_by_id:
            errors.append("Blender scene has a missing or duplicate mapping ID")
            continue
        observed_by_id[entry_id] = dict(raw_entry)
    if len(expected_by_id) != len(observed_by_id):
        errors.append(
            f"Mesh count differs: map={len(expected_by_id)}, scene={len(observed_by_id)}"
        )
    expected_source_sha = _valid_sha256_text(
        (node_map.get("source") or {}).get("sha256") if isinstance(node_map.get("source"), Mapping) else ""
    )
    for entry_id, expected in expected_by_id.items():
        observed = observed_by_id.get(entry_id)
        if observed is None:
            errors.append(f"Mapped Mesh {expected.get('canonical_name', entry_id)} was deleted")
            continue
        if str(observed.get("node_map_id", "") or "").strip().lower() != expected_map_id:
            errors.append(f"Mapped Mesh {expected.get('canonical_name', entry_id)} has another map ID")
        if str(observed.get("scene_node", "") or "") != str(expected.get("canonical_name", "") or ""):
            errors.append(f"Mapped Mesh {expected.get('canonical_name', entry_id)} was renamed in Blender")
        if str(observed.get("canonical_name", "") or "") != str(expected.get("canonical_name", "") or ""):
            errors.append(f"Mapped Mesh {expected.get('canonical_name', entry_id)} lost its canonical name marker")
        if _positive_mesh_slot(observed.get("physical_mesh_slot")) != _positive_mesh_slot(
            expected.get("physical_mesh_slot")
        ):
            errors.append(f"Mapped Mesh {expected.get('canonical_name', entry_id)} physical slot changed")
        if _positive_mesh_slot(observed.get("display_mesh_slot")) != _positive_mesh_slot(
            expected.get("display_mesh_slot")
        ):
            errors.append(f"Mapped Mesh {expected.get('canonical_name', entry_id)} display slot changed")
        if str(observed.get("full_mesh_header_sha256", "") or "").upper() != str(
            expected.get("full_mesh_header_sha256", "") or ""
        ).upper():
            errors.append(f"Mapped Mesh {expected.get('canonical_name', entry_id)} Header changed outside Launcher")
        if expected_source_sha and _valid_sha256_text(observed.get("source_sha256")) != expected_source_sha:
            errors.append(f"Mapped Mesh {expected.get('canonical_name', entry_id)} source SHA changed")
    for entry_id, observed in observed_by_id.items():
        if entry_id not in expected_by_id:
            errors.append(f"Blender scene has an unmapped Mesh {observed.get('scene_node', entry_id)}")
    return {
        "schema": "pc-rehd-blender-node-map-verify-v1",
        "trusted": not errors,
        "expected_mesh_count": len(expected_by_id),
        "scene_mesh_count": len(observed_by_id),
        "errors": errors[:64],
        "checked_at": time.strftime("%Y-%m-%dT%H:%M:%S%z", time.localtime()),
    }


def _overlay_blender_node_map_contract(
    raw_contract: Mapping[str, Any], node_map: Mapping[str, Any]
) -> dict[str, Any]:
    contract = copy.deepcopy(dict(raw_contract))
    entries = node_map.get("entries", []) if isinstance(node_map, Mapping) else []
    by_id = {
        str(entry.get("node_mapping_id", "") or "").strip().lower(): dict(entry)
        for entry in entries
        if isinstance(entry, Mapping)
        and re.fullmatch(r"[0-9a-f]{32}", str(entry.get("node_mapping_id", "") or "").strip().lower())
    }
    source = node_map.get("source", {}) if isinstance(node_map.get("source"), Mapping) else {}
    source_sha = _valid_sha256_text(source.get("sha256"))
    map_id = str(node_map.get("node_map_id", "") or "").strip().lower()
    for collection_name in ("meshes", "nodes"):
        collection = contract.get(collection_name, [])
        if not isinstance(collection, list):
            continue
        for row in collection:
            if not isinstance(row, dict) or not bool(row.get("is_mesh", collection_name == "meshes")):
                continue
            entry_id = str(row.get("node_mapping_id", "") or "").strip().lower()
            entry = by_id.get(entry_id)
            if entry is None:
                continue
            header = _normalize_blender_node_map_header(entry.get("full_mesh_header", {}))
            row["blender_node_map_id"] = map_id
            row["node_mapping_id"] = entry_id
            row["canonical_name"] = str(entry.get("canonical_name", "") or "")
            row["re6_full_mesh_header"] = header
            row["re6_full_mesh_header_sha256"] = str(
                entry.get("full_mesh_header_sha256", "") or _blender_node_map_header_digest(header)
            ).upper()
            row["mesh_slot"] = int(entry["physical_mesh_slot"])
            row["physical_mesh_slot"] = int(entry["physical_mesh_slot"])
            row["display_mesh_slot"] = int(entry["display_mesh_slot"])
            row["scene_name_mesh_slot"] = int(entry["display_mesh_slot"])
            row["mesh_slot_basis"] = "blender_node_map"
            row["header_fvf"] = f"0x{header['fvf_info']:08X}"
            row["source_fvf"] = f"0x{header['fvf_info']:08X}"
            for header_field, contract_field in BLENDER_NODE_MAP_HEADER_CONTRACT_FIELDS.items():
                row[contract_field] = int(header[header_field])
            row["import_source_sha256"] = source_sha
            row["import_source_name"] = str(source.get("name", "") or "")
    contract["blender_node_map"] = _blender_node_map_summary(node_map)
    return contract


def _positive_mesh_slot(value: object) -> int:
    try:
        slot = int(value or 0)
    except (TypeError, ValueError, OverflowError):
        return 0
    return slot if slot > 0 else 0


def _contract_mesh_type(value: object) -> int | None:
    if value is None or str(value).strip() == "":
        return None
    try:
        mesh_type = int(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return mesh_type if 0 <= mesh_type <= 0xFFFF else None


def _blender_mesh_type_recovery_requirements(
    contract: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Return legacy Blender Meshes whose source Header Type is absent.

    A mesh becomes eligible only when its physical slot or ``Mesh_###`` name
    supplies a stable MOD slot.  Ordinary Blender Meshes never enter this
    recovery route.
    """
    requirements: list[dict[str, Any]] = []
    meshes = contract.get("meshes", [])
    if not isinstance(meshes, list):
        return requirements
    for row in meshes:
        if not isinstance(row, Mapping):
            continue
        slot = _positive_mesh_slot(row.get("physical_mesh_slot"))
        if slot <= 0:
            slot = _positive_mesh_slot(row.get("scene_name_mesh_slot"))
        if slot <= 0:
            slot = _positive_mesh_slot(row.get("mesh_slot"))
        if slot <= 0 or _contract_mesh_type(row.get("mesh_type")) is not None:
            continue
        requirements.append(
            {
                "physical_slot": slot,
                "scene_node": str(row.get("scene_node", "") or ""),
                "scene_node_handle": int(row.get("scene_node_handle", 0) or 0),
                "import_source_sha256": _valid_sha256_text(
                    row.get("import_source_sha256")
                ),
            }
        )
    return requirements


def _read_mod_mesh_type_map(source_mod: str | Path) -> dict[str, Any]:
    """Parse only immutable MOD MeshHeader Type fields for Blender recovery."""
    source = Path(source_mod).expanduser().resolve(strict=True)
    if not _is_export_source_mod(source, require_file=True):
        raise ValueError(f"Mesh Type recovery source is not a readable .MOD: {source}")

    source_bytes = b""
    source_snapshot: dict[str, Any] | None = None
    for _attempt in range(2):
        before = _file_snapshot(source)
        candidate_bytes = source.read_bytes()
        after = _file_snapshot(source)
        if _same_file_snapshot(before, after):
            source_bytes = candidate_bytes
            source_snapshot = after
            break
    if source_snapshot is None:
        raise RuntimeError(f"MOD changed while reading Header Types: {source}")

    importer = _load_operation_dependency("import_mod", "importer")
    parse_header = getattr(importer, "_parse_header", None)
    parse_mesh_headers = getattr(importer, "_parse_mesh_headers", None)
    if not callable(parse_header) or not callable(parse_mesh_headers):
        raise RuntimeError("Importer has no MOD MeshHeader parser for Blender recovery")
    header = parse_header(source_bytes)
    headers = parse_mesh_headers(source_bytes, header)
    mesh_types: dict[int, int] = {}
    for slot, mesh_header in enumerate(headers, start=1):
        try:
            mesh_type = int(getattr(mesh_header, "meshtype"))
        except (TypeError, ValueError, OverflowError, AttributeError) as exc:
            raise RuntimeError(
                f"Source MOD Mesh {slot} has no valid Header Type"
            ) from exc
        if not 0 <= mesh_type <= 0xFFFF:
            raise RuntimeError(f"Source MOD Mesh {slot} Header Type is out of range")
        mesh_types[slot] = mesh_type
    if not mesh_types:
        raise RuntimeError("Source MOD has no Mesh Headers to recover")
    _require_unchanged_file_snapshot(
        source, source_snapshot, label="Mesh Type recovery source MOD"
    )
    return {
        "source_path": source,
        "source_name": source.name,
        "source_sha256": hashlib.sha256(source_bytes).hexdigest().upper(),
        "mesh_types": mesh_types,
    }


def _build_blender_mesh_type_recovery(
    contract: Mapping[str, Any],
    source: Mapping[str, Any],
) -> dict[str, Any]:
    """Build an explicit, source-checked Type restore map for a legacy scene."""
    requirements = _blender_mesh_type_recovery_requirements(contract)
    if not requirements:
        return {"mesh_types": {}, "recovery_slots": []}
    source_sha256 = _valid_sha256_text(source.get("source_sha256"))
    if not source_sha256:
        raise RuntimeError("Mesh Type recovery source has no SHA-256 identity")
    source_types = source.get("mesh_types", {})
    if not isinstance(source_types, Mapping):
        raise RuntimeError("Mesh Type recovery source omitted its Header Type map")

    foreign_rows = [
        row
        for row in requirements
        if row["import_source_sha256"]
        and row["import_source_sha256"] != source_sha256
    ]
    if foreign_rows:
        raise ProtocolError(
            "Selected MOD does not match the Blender scene source SHA-256: "
            + ", ".join(
                f"Mesh_{int(row['physical_slot']):03d}" for row in foreign_rows[:12]
            )
        )

    duplicate_slots = {
        slot
        for slot in (_positive_mesh_slot(row["physical_slot"]) for row in requirements)
        if sum(
            1
            for candidate in requirements
            if _positive_mesh_slot(candidate["physical_slot"]) == slot
        ) > 1
    }
    if duplicate_slots:
        raise ProtocolError(
            "Blender scene has ambiguous legacy Mesh slots: "
            + ", ".join(f"Mesh_{slot:03d}" for slot in sorted(duplicate_slots)[:12])
        )

    recovered_types: dict[int, int] = {}
    unavailable_slots: list[int] = []
    for row in requirements:
        slot = _positive_mesh_slot(row["physical_slot"])
        mesh_type = _contract_mesh_type(source_types.get(slot, source_types.get(str(slot))))
        if mesh_type is None:
            unavailable_slots.append(slot)
            continue
        recovered_types[slot] = mesh_type
    if unavailable_slots:
        raise ProtocolError(
            "Selected MOD has no matching Mesh Header Type for: "
            + ", ".join(f"Mesh_{slot:03d}" for slot in sorted(unavailable_slots)[:12])
        )
    return {
        "schema": BLENDER_MESH_TYPE_RECOVERY_SCHEMA,
        "source_path": str(source.get("source_path", "") or ""),
        "source_name": str(source.get("source_name", "") or ""),
        "source_sha256": source_sha256,
        "mesh_types": recovered_types,
        "recovery_slots": sorted(recovered_types),
    }


def _overlay_blender_mesh_type_recovery(
    contract: Mapping[str, Any], recovery: Mapping[str, Any]
) -> dict[str, Any]:
    """Use pending source Header Type values for this filter plan only."""
    restored = copy.deepcopy(dict(contract))
    raw_types = recovery.get("mesh_types", {})
    mesh_types = {
        _positive_mesh_slot(slot): _contract_mesh_type(value)
        for slot, value in dict(raw_types).items()
    }
    mesh_types = {
        slot: mesh_type
        for slot, mesh_type in mesh_types.items()
        if slot > 0 and mesh_type is not None
    }
    for row in restored.get("meshes", []):
        if not isinstance(row, dict) or _contract_mesh_type(row.get("mesh_type")) is not None:
            continue
        slot = _positive_mesh_slot(row.get("physical_mesh_slot"))
        if slot <= 0:
            slot = _positive_mesh_slot(row.get("scene_name_mesh_slot"))
        if slot <= 0:
            slot = _positive_mesh_slot(row.get("mesh_slot"))
        if slot in mesh_types:
            row["mesh_type"] = mesh_types[slot]
    return restored


def _mesh_is_degenerate_for_filter_contract(mesh: Mapping[str, Any]) -> bool:
    """Match the PC-REHD 1.2.8/V4 ``Hide degen`` checkbox exactly."""
    try:
        return int(mesh.get("mesh_type", -1)) == RE6_DEGENERATE_LINE_MESH_TYPE
    except (TypeError, ValueError, OverflowError):
        return False


def _mesh_hidden_by_filter_contract(
    mesh: dict[str, Any],
    *,
    lod: object,
    material_group: object,
    fvf: object,
    hide_lod0: bool,
    hide_degenerate: bool,
) -> bool:
    normalized_lod = _normalize_mesh_filter_choice(lod)
    normalized_material = _normalize_mesh_filter_choice(material_group)
    normalized_fvf = _normalize_mesh_filter_choice(fvf).removeprefix("0x").upper()
    if normalized_lod.casefold() == "all":
        normalized_lod = ""
    if normalized_material.casefold() == "all":
        normalized_material = ""
    if normalized_fvf.casefold() == "all":
        normalized_fvf = ""
    mesh_lod = mesh.get("lod_level")
    mesh_material_group = (
        None
        if mesh.get("material_id") is None
        else int(mesh["material_id"]) // 16
    )
    mesh_fvf = str(mesh.get("header_fvf", "") or "").removeprefix("0x").upper()
    return bool(
        (normalized_lod and str(mesh_lod) != normalized_lod)
        or (normalized_material and str(mesh_material_group) != normalized_material)
        or (normalized_fvf and mesh_fvf != normalized_fvf)
        or (hide_lod0 and mesh_lod == 0)
        or (hide_degenerate and _mesh_is_degenerate_for_filter_contract(mesh))
    )


def _run_ui_quality_policy_guard() -> dict[str, Any]:
    """Keep future UI edits themed, language-separated, and off blocking backends."""
    source_path = Path(__file__).resolve()
    try:
        source = source_path.read_text(encoding="utf-8")
        tree = ast.parse(source, filename=str(source_path))
    except (OSError, SyntaxError) as exc:
        raise RuntimeError(f"Cannot validate the UI quality policy: {exc}") from exc

    launcher_classes = [
        node
        for node in tree.body
        if isinstance(node, ast.ClassDef) and node.name == "LauncherApp"
    ]
    if len(launcher_classes) != 1:
        raise RuntimeError("UI quality policy cannot find exactly one LauncherApp class")
    launcher_class = launcher_classes[0]
    methods = {
        node.name: node
        for node in launcher_class.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    def method_source(node: ast.AST | None) -> str:
        return ast.get_source_segment(source, node) or "" if node is not None else ""

    parents: dict[ast.AST, ast.AST] = {}
    for parent in ast.walk(launcher_class):
        for child in ast.iter_child_nodes(parent):
            parents[child] = parent

    def dotted_name(node: ast.AST) -> str:
        parts: list[str] = []
        current: ast.AST | None = node
        while isinstance(current, ast.Attribute):
            parts.append(current.attr)
            current = current.value
        if isinstance(current, ast.Name):
            parts.append(current.id)
        return ".".join(reversed(parts))

    def enclosing_callable(node: ast.AST) -> ast.AST | None:
        current: ast.AST | None = node
        while current is not None:
            if isinstance(current, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
                return current
            current = parents.get(current)
        return None

    def enclosing_method(node: ast.AST) -> ast.FunctionDef | ast.AsyncFunctionDef | None:
        current: ast.AST | None = node
        while current is not None:
            if isinstance(current, (ast.FunctionDef, ast.AsyncFunctionDef)) and parents.get(current) is launcher_class:
                return current
            current = parents.get(current)
        return None

    def direct_nodes(scope: ast.AST) -> list[ast.AST]:
        found: list[ast.AST] = []

        class DirectVisitor(ast.NodeVisitor):
            def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
                if node is scope:
                    self.generic_visit(node)

            def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
                if node is scope:
                    self.generic_visit(node)

            def visit_Lambda(self, node: ast.Lambda) -> None:
                if node is scope:
                    self.generic_visit(node)

            def generic_visit(self, node: ast.AST) -> None:
                found.append(node)
                super().generic_visit(node)

        DirectVisitor().visit(scope)
        return found

    local_definitions: dict[tuple[str, str], list[ast.AST]] = {}
    for node in ast.walk(launcher_class):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
            continue
        method = enclosing_method(node)
        if method is None or node is method or isinstance(node, ast.Lambda):
            continue
        local_definitions.setdefault((method.name, node.name), []).append(node)

    background_scopes: set[ast.AST] = set()

    def register_background_target(expression: ast.AST | None, owner: ast.AST) -> None:
        if expression is None:
            return
        method = enclosing_method(owner)
        if isinstance(expression, ast.Name) and method is not None:
            background_scopes.update(
                local_definitions.get((method.name, expression.id), [])
            )
        elif isinstance(expression, ast.Attribute):
            name = dotted_name(expression)
            if name.startswith("self.") and expression.attr in methods:
                background_scopes.add(methods[expression.attr])
        elif isinstance(expression, ast.Lambda):
            background_scopes.add(expression)

    for call in [node for node in ast.walk(launcher_class) if isinstance(node, ast.Call)]:
        called = dotted_name(call.func)
        if called.endswith(("._run_background", "._start_deferred_maintenance")):
            operation = call.args[0] if call.args else next(
                (keyword.value for keyword in call.keywords if keyword.arg == "operation"),
                None,
            )
            register_background_target(operation, call)
        elif called == "_call_with_windows_thread_priority":
            operation = call.args[0] if call.args else None
            register_background_target(operation, call)
        elif called in {"threading.Thread", "multiprocessing.Process"} or called.endswith(".Process"):
            target = next(
                (keyword.value for keyword in call.keywords if keyword.arg == "target"),
                None,
            )
            register_background_target(target, call)

    # A background operation may delegate to a sibling local helper, as the
    # export operation does for Writer receipt hashing. Keep that local chain
    # asynchronous without treating unrelated same-named helpers as workers.
    changed = True
    while changed:
        changed = False
        for scope in list(background_scopes):
            method = enclosing_method(scope)
            if method is None:
                continue
            for node in direct_nodes(scope):
                if not isinstance(node, ast.Call):
                    continue
                targets: list[ast.AST] = []
                if isinstance(node.func, ast.Name):
                    targets.extend(local_definitions.get((method.name, node.func.id), []))
                elif (
                    isinstance(node.func, ast.Attribute)
                    and isinstance(node.func.value, ast.Name)
                    and node.func.value.id == "self"
                    and node.func.attr in methods
                ):
                    targets.append(methods[node.func.attr])
                for target in targets:
                    if target not in background_scopes:
                        background_scopes.add(target)
                        changed = True

    violations: list[str] = []
