    def _build_ui(self) -> None:
        ttk = self.ttk
        root = self.root
        self._compact_model_control_anchor: dict[int, tuple[int, int, int, int]] = {}
        layout = self._main_layout()
        self._main_viewport_content_size = (1, 1)
        self._main_viewport_layout_signature = None
        self._main_viewport_content_configure_size = None
        self._main_viewport_canvas_configure_size = None
        viewport = self.tk.Canvas(
            root,
            background=self.colors["bg"],
            borderwidth=0,
            highlightthickness=0,
            relief="flat",
            xscrollincrement=16,
            yscrollincrement=16,
        )
        content = ttk.Frame(viewport, style="Panel.TFrame")
        content_window_id = viewport.create_window(
            (0, 0), window=content, anchor="nw"
        )
        horizontal_scroll = ttk.Scrollbar(
            root,
            orient="horizontal",
            command=lambda *arguments: self._scroll_main_viewport(
                "x", *arguments
            ),
            style="App.Horizontal.TScrollbar",
        )
        vertical_scroll = ttk.Scrollbar(
            root,
            orient="vertical",
            command=lambda *arguments: self._scroll_main_viewport(
                "y", *arguments
            ),
            style="App.Vertical.TScrollbar",
        )
        horizontal_scroll.bind(
            "<ButtonRelease-1>", self._flush_main_viewport_scroll, add="+"
        )
        vertical_scroll.bind(
            "<ButtonRelease-1>", self._flush_main_viewport_scroll, add="+"
        )
        viewport.configure(
            xscrollcommand=horizontal_scroll.set,
            yscrollcommand=vertical_scroll.set,
        )
        content.bind(
            "<Configure>", self._sync_main_viewport_scrollregion, add="+"
        )
        viewport.bind(
            "<Configure>", self._on_main_viewport_canvas_configure, add="+"
        )
        viewport.place(x=0, y=0, width=1, height=1)
        self.main_viewport_canvas = viewport
        self.main_viewport_content = content
        self.main_viewport_window_id = int(content_window_id)
        self.main_viewport_hscroll = horizontal_scroll
        self.main_viewport_vscroll = vertical_scroll
        _managed_window_scheduler(self.root).register_scroll_surface(
            viewport,
            self._main_viewport_dropdown_is_open,
            atomic_paint=False,
        )
        self.main_resize_grip = self.tk.Frame(
            root,
            width=MAIN_RESIZE_GRIP_SIZE,
            height=MAIN_RESIZE_GRIP_SIZE,
            background=self.colors["bg"],
            borderwidth=0,
            highlightthickness=0,
            cursor="size_nw_se",
        )
        self.main_resize_grip.bind(
            "<ButtonPress-1>", self._begin_main_resize_grip, add="+"
        )
        self.main_resize_grip.bind(
            "<B1-Motion>", self._drag_main_resize_grip, add="+"
        )
        self.main_resize_grip.bind(
            "<ButtonRelease-1>", self._end_main_resize_grip, add="+"
        )
        self.main_resize_grip.bind(
            "<Enter>", self._expand_main_resize_grip_hit_area, add="+"
        )
        self.main_resize_grip.bind(
            "<Leave>", self._schedule_main_resize_grip_hit_area_collapse, add="+"
        )
        self._position_main_resize_grip()
        self.option_controls = []
        self.max_scene_controls: list[tuple[Any, str]] = []
        self.aux_export_buttons: dict[str, Any] = {}
        self.aux_export_tooltips: dict[str, HoverTooltip] = {}
        self.log_cache_directory_tooltips: list[HoverTooltip] = []
        self.advanced_widgets: list[Any] = []
        self.bucket_lists = {}
        self.bucket_empty_labels = {}
        self.scene_tree = None
        self.header_combo = None
        self.inspect_button = None
        self.source_entry = None
        self.source_browse_button = None
        self.toolbox_window = None
        self.blender_toolbox_window = None
        self.blender_texture_tool_button = None
        self.blender_texture_tooltip = None
