    def _compact_process_toolbar_width(
        self, layout: dict[str, int] | None = None
    ) -> int:
        """Match the compact PID selector to the rendered Model File column."""
        current_layout = layout or self._main_layout()
        width = max(1, int(current_layout["left_w"]))
        flow = getattr(self, "_section_flow", {})
        if isinstance(flow, dict):
            width = max(width, int(flow.get("left_width", 0) or 0))
        model_group = getattr(self, "model_group", None)
        if model_group is not None:
            try:
                model_info = model_group.place_info()
                width = max(
                    width,
                    int(float(model_info.get("width", 0) or 0)),
                    int(model_group.winfo_width()),
                )
            except (self.tk.TclError, TypeError, ValueError):
                pass
        return width

    def _sync_toolbar_region_geometry(self) -> None:
        """Keep backend controls and the action stack in independent regions."""
        toolbar = getattr(self, "toolbar", None)
        process_area = getattr(self, "toolbar_process_area", None)
        action_area = getattr(self, "toolbar_action_area", None)
        if toolbar is None or process_area is None or action_area is None:
            return
        try:
            process_area.update_idletasks()
            current_width = max(
                1,
                int(process_area.winfo_reqwidth()),
            )
            process_height = max(
                1,
                int(process_area.winfo_reqheight()),
                int(process_area.grid_bbox(0, 0, 6, 1)[3]),
            )
        except (self.tk.TclError, TypeError, ValueError):
            return

        layout = self._main_layout()
        blender_mode = bool(getattr(self, "blender_mode_enabled", False))
        current_label = self._tr(
            "Blender 进程:" if blender_mode else "MAX 进程:",
            "Blender Process:" if blender_mode else "MAX Process:",
        )
        alternate_label = self._tr(
            "MAX 进程:" if blender_mode else "Blender 进程:",
            "MAX Process:" if blender_mode else "Blender Process:",
        )
        current_launch = self._tr(
            "启动 Blender" if blender_mode else "启动 Max",
            "Launch Blender" if blender_mode else "Launch Max",
        )
        alternate_launch = self._tr(
            "启动 Max" if blender_mode else "启动 Blender",
            "Launch Max" if blender_mode else "Launch Blender",
        )
        reserved_width = current_width
        reserved_width += max(
            0,
            self._measure_ui_text(alternate_label)
            - self._measure_ui_text(current_label),
        )
        reserved_width += max(
            0,
            self._measure_ui_text(alternate_launch)
            - self._measure_ui_text(current_launch),
        )
        reserved_width += 8
        advanced_visible = bool(
            getattr(self, "advanced_visible_var", None)
            and self.advanced_visible_var.get()
        )
        if advanced_visible:
            # Never retain an earlier process-row width. The final width is
            # anchored below to the action icon, so MAX/Blender switches do
            # not leave this strip stretched across the UI.
            stable_width = reserved_width
        else:
            # Compact MAX/Blender pages use the same narrow process column as
            # the Model File panel.  Do not inherit a previous Advanced page's
            # long PID selector width.
            stable_width = self._compact_process_toolbar_width(layout)
            try:
                process_area.configure(width=stable_width)
            except self.tk.TclError:
                pass
        try:
            toolbar.columnconfigure(0, minsize=stable_width)
        except self.tk.TclError:
            return

        if not advanced_visible:
            # Compact mode has dedicated left-side controls.  Do not let the
            # hidden Advanced action stack reserve or redraw a right column.
            self._set_widget_place_visible(action_area, False)
            toolbar_x = int(layout["left_x"])
            toolbar_y = int(layout["toolbar_y"])
            self._toolbar_region_size = (stable_width, process_height)
            self._set_widget_place_geometry(
                toolbar,
                x=toolbar_x,
                y=toolbar_y,
                width=stable_width,
                height=process_height,
            )
            self._raise_placed_widget(toolbar)
            self._raise_placed_widget(process_area)
            try:
                self.model_process_label.configure(
                    text=str(self.model_process_label.cget("text"))
                )
            except self.tk.TclError:
                pass
            self._raise_toolbar_process_label()
            self._position_blender_hierarchy_message_frame()
            return

        try:
            action_area.update_idletasks()
            action_width = max(
                1,
                int(action_area.winfo_reqwidth()),
            )
            action_height = max(
                1,
                int(action_area.winfo_reqheight()),
            )
        except (self.tk.TclError, TypeError, ValueError):
            return

        # The action stack belongs beside the advanced columns, not after the
        # active backend's label. Its coordinate is therefore shared by MAX,
        # Blender, Chinese, and English layouts.
        action_x = (
            int(layout["right_x"])
            + int(layout["side_w"])
            + max(18, int(layout["left_x"]))
        )
        right_area = getattr(self, "right_area", None)
        try:
            advanced_visible = bool(
                getattr(self, "advanced_visible_var", None)
                and self.advanced_visible_var.get()
            )
            if right_area is not None and advanced_visible:
                right_info = right_area.place_info()
                panel_x = int(
                    float(
                        right_info.get(
                            "x",
                            getattr(self, "_right_x", layout["middle_x"]),
                        )
                        or 0
                    )
                )
                panel_width = max(
                    1,
                    int(right_area.winfo_reqwidth()),
                )
                action_x = max(
                    action_x,
                    panel_x + panel_width + max(18, int(layout["left_x"])),
                )
        except (self.tk.TclError, TypeError, ValueError):
            pass
        scaling_advanced = bool(
            getattr(self, "_scaling_mode_enabled", False)
            and advanced_visible
            and not self._scaling_mode_preserves_advanced_topology()
        )
        if scaling_advanced:
            # Scaling Mode keeps the action stack below the wrapped process
            # rows, so the advanced page never grows a hidden horizontal strip.
            action_x = int(layout["left_x"])
        action_y = int(layout["toolbar_y"]) + process_height + 10
        if scaling_advanced:
            action_y += self._scale_main_ui_spacing_metric(2, minimum=1)
        toolbar_x = int(layout["left_x"])
        toolbar_y = int(layout["toolbar_y"])
        action_relative_x = max(0, action_x - toolbar_x)
        action_relative_y = max(0, action_y - toolbar_y)
        if advanced_visible:
            # The process strip ends level with the right edge of the action
            # cluster (whose top-right control is the launcher icon). Keep the
            # standard input widths; their posted popup independently reveals
            # the complete path and PID text.
            stable_width = max(stable_width, action_relative_x + action_width)
            self._toolbar_process_area_width = stable_width
            self._max_advanced_process_toolbar_width = stable_width
            try:
                toolbar.columnconfigure(0, minsize=stable_width)
            except self.tk.TclError:
                return
        toolbar_width = max(stable_width, action_relative_x + action_width)
        toolbar_height = max(process_height, action_relative_y + action_height)
        self._toolbar_region_size = (toolbar_width, toolbar_height)
        self._set_widget_place_geometry(
            action_area,
            x=action_relative_x,
            y=action_relative_y,
            width=action_width,
            height=action_height,
        )
        self._set_widget_place_geometry(
            toolbar,
            x=toolbar_x,
            y=toolbar_y,
            width=toolbar_width,
            height=toolbar_height,
        )
        self._raise_placed_widget(toolbar)
        self._raise_placed_widget(process_area)
        right_area = getattr(self, "right_area", None)
        if right_area is not None and advanced_visible:
            self._raise_placed_widget(right_area)
        # The toolbar frame spans the action column's bounding box.  Its
        # background must never cover the left content panels that begin below
        # the process row, so the main panels are raised in the same commit.
        for content_widget in (
            getattr(self, "model_group", None),
            getattr(self, "rename_group", None),
            getattr(self, "filter_group", None),
            getattr(self, "footer_frame", None),
        ):
            try:
                if (
                    content_widget is not None
                    and bool(content_widget.winfo_exists())
                    and str(content_widget.winfo_manager()) == "place"
                ):
                    self._raise_placed_widget(content_widget)
            except self.tk.TclError:
                continue
        try:
            self.model_process_label.configure(
                text=str(self.model_process_label.cget("text"))
            )
        except self.tk.TclError:
            pass
        self._raise_toolbar_process_label()
        if not advanced_visible:
            # Compact content can be re-anchored after a scaled width pass.
            # Keep the process strip above any panel that briefly shares its
            # edge so the MAX/Blender title cannot appear clipped until hover.
            self._raise_placed_widget(toolbar)
            self._raise_placed_widget(process_area)
        self._position_blender_hierarchy_message_frame()

    def _build_rehd_groups(self, root: Any) -> None:
        ttk = self.ttk
        layout = self._main_layout()
        # This is only a layout container. The nested groups retain their own
        # borders, so an outer LabelFrame would add an unrelated extra box.
        area = ttk.Frame(
            root,
            style="Panel.TFrame",
            padding=(7, 6, 7, 7),
        )
        self.right_area = area
        area.place(x=layout["middle_x"], y=layout["top_y"])
        area.columnconfigure(0, weight=1, uniform="right_columns")
        area.columnconfigure(1, weight=1, uniform="right_columns")
        left_stack = ttk.Frame(area, style="Panel.TFrame")
        right_stack = ttk.Frame(area, style="Panel.TFrame")
        left_stack.grid(row=0, column=0, sticky="new", padx=(0, 7))
        right_stack.grid(row=0, column=1, sticky="new", padx=(7, 0))
        left_stack.columnconfigure(0, weight=1)
        right_stack.columnconfigure(0, weight=1)
        self.right_left_stack = left_stack
        self.right_right_stack = right_stack
        self.blender_max_only_advanced_widgets: list[Any] = []
        self.blender_only_advanced_widgets: list[Any] = []

        def build_aux_group(parent: Any, row: int, cn: str, en: str, kind: str) -> Any:
            group = ttk.LabelFrame(parent, text=self._tr(cn, en), style="V4.TLabelframe")
            group.grid(row=row, column=0, sticky="ew", pady=(0, 8))
            self.blender_max_only_advanced_widgets.append(group)
            group.columnconfigure((0, 1), weight=1, uniform=f"{kind}_buttons")
            import_button = ttk.Button(
                group,
                text=self._tr("导入", "Import"),
                command=lambda aux_kind=kind: self._import_auxiliary(aux_kind),
            )
            import_button.grid(row=0, column=0, sticky="ew", padx=(6, 3), pady=(5, 6))
            export_button = ttk.Button(
                group,
                text=self._tr("导出", "Export"),
                command=lambda aux_kind=kind: self._export_auxiliary(aux_kind),
                state="disabled",
            )
            export_button.grid(
                row=0, column=1, sticky="ew", padx=(3, 6), pady=(5, 4)
            )
            self.aux_export_tooltips[kind] = HoverTooltip(
                export_button,
                lambda: self._tr(
                    "旧版 PC-REHD 1.2.8 脚本根本不支持导出；新版 Python 化从未进行任何验证、样本测试，也不可信。",
                    "The original PC-REHD 1.2.8 script did not support export at all. The new Pythonized route has never been validated or sample-tested and is not trustworthy.",
                ),
                delay_ms=250,
            )
            python_toggle = ttk.Checkbutton(
                group,
                text=self._tr("Python化 - 未验证", "Pythonized - Unverified"),
                variable=self.aux_python_vars[kind],
                command=lambda aux_kind=kind: self._on_aux_python_changed(aux_kind),
            )
            python_toggle.grid(row=1, column=0, columnspan=2, sticky="w", padx=6, pady=(0, 6))
            self.option_controls.append(python_toggle)
            self.aux_export_buttons[kind] = export_button
            return import_button, export_button

        sbc_import, sbc_export = build_aux_group(left_stack, 0, "REHD SBC 文件", "REHD SBC File", "sbc")
        ems_import, ems_export = build_aux_group(left_stack, 1, "REHD EMS 文件", "REHD EMS file", "ems")
        adr_import, adr_export = build_aux_group(right_stack, 0, "REHD ADR 文件", "REHD ADR file", "adr")

        fixes = ttk.Frame(left_stack, style="Panel.TFrame")
        fixes.grid(row=2, column=0, sticky="ew", pady=(0, 8))
        self.compatibility_fix_frame = fixes
        fixes.columnconfigure(0, weight=1)
        dmc = ttk.Checkbutton(fixes, text=self._tr("DMC4SE 修正", "DMC4SE FIX"), variable=self.fix_dmc_var, command=lambda: self._show_fix_notice("dmc"))
        dmc.grid(row=0, column=0, sticky="ew", pady=(0, 3))
        lp2 = ttk.Checkbutton(fixes, text=self._tr("Lost Planet 2 修正", "Lost Planet 2 FIX"), variable=self.fix_lp2_var, command=lambda: self._show_fix_notice("lp2"))
        lp2.grid(row=1, column=0, sticky="ew", pady=(3, 0))
