    def _seam_record_label(self, record: dict[str, Any]) -> str:
        if not isinstance(record, dict) or not str(record.get("name", "") or "").strip():
            return self._tr("尚未记录", "Not recorded")
        name = str(record.get("name", "") or "")
        try:
            count = int(record.get("selected_count", len(record.get("indices", []))) or 0)
        except (TypeError, ValueError):
            count = 0
        return self._tr(
            f"{name}\n已记录 {count} 个顶点",
            f"{name}\n{count} vertices recorded",
        )

    def _refresh_seam_tool_view(self) -> None:
        workspace = self._active_workspace()
        if workspace is None:
            left = {}
            right = {}
            seam_range = 0.75
            seam_strength = 0.5
            status = self._tr("请选择两个 Skin Mesh", "Select two skinned Meshes")
        else:
            left = workspace.seam_left
            right = workspace.seam_right
            seam_range = max(0.0001, min(1000.0, float(workspace.seam_range)))
            seam_strength = max(0.0, min(1.0, float(workspace.seam_strength)))
            status = self._tr("已连接 Max，可记录两个接缝选区", "Max connected; record two seam selections")
        try:
            self.seam_left_var.set(self._seam_record_label(left))
            self.seam_right_var.set(self._seam_record_label(right))
            self.seam_range_var.set(seam_range)
            self.seam_strength_var.set(seam_strength)
            self.seam_range_value_var.set(f"{seam_range:.2f}")
            self.seam_strength_value_var.set(f"{round(seam_strength * 100):d}%")
            self.seam_status_var.set(status)
        except Exception:
            return

    def _on_seam_range_changed(self, value: Any) -> None:
        try:
            current = max(0.0001, min(1000.0, float(value)))
        except (TypeError, ValueError):
            return
        workspace = self._active_workspace()
        if workspace is not None:
            workspace.seam_range = current
        try:
            self.seam_range_value_var.set(f"{current:.2f}")
        except Exception:
            pass

    def _on_seam_strength_changed(self, value: Any) -> None:
        try:
            current = max(0.0, min(1.0, float(value)))
        except (TypeError, ValueError):
            return
        workspace = self._active_workspace()
        if workspace is not None:
            workspace.seam_strength = current
        try:
            self.seam_strength_value_var.set(f"{round(current * 100):d}%")
        except Exception:
            pass

    def _show_seam_error(self, exc: Exception) -> None:
        detail = self._localized_error_detail(exc)
        message = self._tr(f"未完成：{detail}", f"Not completed: {detail}")
        self.seam_status_var.set(message)
        self._set_status(message, progress=0)
        window = getattr(self, "seam_window", None)
        if window is None:
            return
        try:
            if bool(window.winfo_exists()):
                _managed_window_scheduler(self.root).show(window, activate=True)
        except self.tk.TclError:
            pass

    def _run_seam_operation(
        self,
        operation: str,
        payload: dict[str, Any],
        on_success: Callable[[ManagedMaxSession, dict[str, Any], str], None],
    ) -> None:
        session = self._active_session()
        if session is None:
            self._show_seam_error(RuntimeError(self._tr("当前没有活动的 Max。", "No active Max session.")))
            return
        action = f"seam_{operation}"
        generation = self._begin_session_operation(session, action)
        request_payload = dict(payload)
        request_payload["operation"] = operation

        def request() -> tuple[str, dict[str, Any]]:
            if operation in {"capture", "auto"}:
                interface_id = f"seam.{operation}"
                _plan_request_id, scene_data = self._request_max_scene_interface(
                    session,
                    interface_id,
                )
                target_rows = [
                    dict(row)
                    for row in scene_data.get("target_meshes", [])
                    if isinstance(row, dict)
                ]
                request_payload.update(
                    {
                        "scene_interface_id": interface_id,
                        "scene_snapshot_digest": str(scene_data.get("digest", "") or ""),
                        "node_handles": [int(row["handle"]) for row in target_rows],
                        "node_names": {
                            str(int(row["handle"])): str(row.get("name", "") or "")
                            for row in target_rows
                        },
                    }
                )
            return self._request_max_scene_interface(
                session,
                "seam.apply",
                request_payload,
            )

        def success(value: tuple[str, dict[str, Any]]) -> None:
            if not self._owns_session_operation(session, action, generation):
                return
            request_id, result = value
            returned_pid = int(result.get("max_process_id", 0) or 0)
            if returned_pid != session.pid:
                self._show_seam_error(
                    ProtocolError(f"Seam response PID mismatch: expected={session.pid}, returned={returned_pid}")
                )
                return
            on_success(session, result, request_id)

        def error(exc: Exception) -> None:
            if not self._owns_session_operation(session, action, generation):
                return
            session.workspace.last_status = self._tr(f"失败：{exc}", f"Failed: {exc}")
            if self._session_is_visible(session):
                self._show_seam_error(exc)

        self._run_background(
            request,
            success,
            label=self._tr("接缝权重处理中", "Blending seam weights"),
            on_error=error,
        )

    def _record_seam_selection(self, side: str) -> None:
        normalized = "left" if str(side).casefold() == "left" else "right"

        def success(session: ManagedMaxSession, result: dict[str, Any], request_id: str) -> None:
            record = result.get("record")
            if not isinstance(record, dict):
                raise ProtocolError("Seam capture returned no selection record")
            if normalized == "left":
                session.workspace.seam_left = copy.deepcopy(record)
            else:
                session.workspace.seam_right = copy.deepcopy(record)
            if self._session_is_visible(session):
                self._refresh_seam_tool_view()
                self._set_status(
                    self._tr(
                        f"已记录 Mesh {1 if normalized == 'left' else 2} 接缝选区 | Request {request_id[:12]}",
                        f"Mesh {1 if normalized == 'left' else 2} seam selection recorded | Request {request_id[:12]}",
                    ),
                    progress=100,
                )

        self._run_seam_operation("capture", {"side": normalized}, success)

    def _clear_seam_selection(self, side: str | None = None) -> None:
        workspace = self._active_workspace()
        if workspace is None:
            return
        normalized = str(side or "").casefold()
        if normalized in {"left", "1"}:
            workspace.seam_left = {}
        elif normalized in {"right", "2"}:
            workspace.seam_right = {}
        else:
            workspace.seam_left = {}
            workspace.seam_right = {}
        self._refresh_seam_tool_view()

    def _seam_blend_result_status(
        self, result: dict[str, Any], request_id: str, *, automatic: bool
    ) -> str:
        pairs = int(result.get("pair_count", 0) or 0)
        changed = int(result.get("changed_vertex_count", 0) or 0)
        failed = int(result.get("failed_vertex_count", 0) or 0)
        mode_cn = "自动混合" if automatic else "接缝权重混合"
        mode_en = "Automatic blend" if automatic else "Seam weight blend"
        suffix_cn = f"，{failed} 个顶点写入失败" if failed else ""
        suffix_en = f", {failed} vertex writes failed" if failed else ""
        return self._tr(
            f"{mode_cn}完成：匹配 {pairs} 对，写入 {changed} 个顶点{suffix_cn} | {request_id[:12]}",
            f"{mode_en} complete: {pairs} pairs, {changed} vertices written{suffix_en} | {request_id[:12]}",
        )

    def _blend_recorded_seams(self) -> None:
        workspace = self._active_workspace()
        if workspace is None:
            self._show_seam_error(RuntimeError(self._tr("当前没有活动的 Max。", "No active Max session.")))
            return
        if not workspace.seam_left or not workspace.seam_right:
            self._show_seam_error(
                ValueError(
                    self._tr(
                        "请先分别记录 Mesh 1 和 Mesh 2 的 Skin 选区。",
                        "Record the Skin selection for Mesh 1 and Mesh 2 first.",
                    )
                )
            )
            return
        payload = {
            "left": copy.deepcopy(workspace.seam_left),
            "right": copy.deepcopy(workspace.seam_right),
            "range": float(workspace.seam_range),
            "strength": float(workspace.seam_strength),
        }

        def success(session: ManagedMaxSession, result: dict[str, Any], request_id: str) -> None:
            session.workspace.seam_left = copy.deepcopy(result.get("left") or session.workspace.seam_left)
            session.workspace.seam_right = copy.deepcopy(result.get("right") or session.workspace.seam_right)
            if self._session_is_visible(session):
                self._refresh_seam_tool_view()
                self._set_status(self._seam_blend_result_status(result, request_id, automatic=False), progress=100)

        self._run_seam_operation("blend", payload, success)

    def _auto_blend_seams(self) -> None:
        workspace = self._active_workspace()
        if workspace is None:
            self._show_seam_error(RuntimeError(self._tr("当前没有活动的 Max。", "No active Max session.")))
            return
        payload = {
            "range": float(workspace.seam_range),
            "strength": float(workspace.seam_strength),
        }

        def success(session: ManagedMaxSession, result: dict[str, Any], request_id: str) -> None:
            if isinstance(result.get("left"), dict):
                session.workspace.seam_left = copy.deepcopy(result["left"])
            if isinstance(result.get("right"), dict):
                session.workspace.seam_right = copy.deepcopy(result["right"])
            if self._session_is_visible(session):
                self._refresh_seam_tool_view()
                self._set_status(self._seam_blend_result_status(result, request_id, automatic=True), progress=100)

        self._run_seam_operation("auto", payload, success)

    def _close_seam_weight_tool(self, *, restore_toolbox: bool = True) -> None:
        window = getattr(self, "seam_window", None)
        reopen_toolbox = bool(
            restore_toolbox
            and getattr(self, "_seam_reopen_toolbox_on_close", False)
        )
        self._seam_reopen_toolbox_on_close = False
        self.seam_window = None
        if window is not None:
            try:
                setattr(window, "_pc_rehd_keep_owner_minimized", False)
                if bool(window.winfo_exists()):
                    window.destroy()
            except self.tk.TclError:
                pass
        try:
            _show_themed_window(
                self.root, dark=bool(getattr(self, "_theme_dark", False))
            )
            self.root.after_idle(
                lambda reopen=reopen_toolbox: self._restore_launcher_after_exclusive_tool(
                    reopen
                )
            )
        except self.tk.TclError:
            pass

    def _present_exclusive_seam_window(self, window: Any) -> None:
        """Keep the seam tool above Max while its Launcher owner stays minimized."""
        try:
            if not bool(window.winfo_exists()):
                return
            _managed_window_scheduler(self.root).show_exclusive(
                window, activate=True
            )
        except self.tk.TclError:
            return

    def _show_seam_weight_tool(self) -> None:
        toolbox_was_open = self._toolbox_is_open()
        existing = getattr(self, "seam_window", None)
        if existing is not None:
            try:
                if bool(existing.winfo_exists()):
                    toolbox = getattr(self, "toolbox_window", None)
                    if toolbox is not None and toolbox is not existing:
                        self._seam_reopen_toolbox_on_close = True
                        self._close_toolbox(toolbox)
                    self._present_exclusive_seam_window(existing)
                    self._refresh_seam_tool_view()
                    return
            except self.tk.TclError:
                pass
        toolbox = getattr(self, "toolbox_window", None)
        self._seam_reopen_toolbox_on_close = toolbox_was_open
        if toolbox is not None:
            try:
                if bool(toolbox.winfo_exists()):
                    self._close_toolbox(toolbox)
            except self.tk.TclError:
                pass
        window = _create_managed_toplevel(self.root, activate=True)
        self.seam_window = window
        window.title(self._tr("接缝处权重统一", "Seam Weight Unify"))
        window.configure(background=self.colors["bg"])
        window.resizable(True, True)
        window.protocol("WM_DELETE_WINDOW", self._close_seam_weight_tool)
        window.bind("<Escape>", lambda _event: self._close_seam_weight_tool())
        window.columnconfigure(0, weight=1)
        window.rowconfigure(0, weight=1)
        body = self.ttk.Frame(window, style="Panel.TFrame", padding=(18, 16, 18, 16))
        body.grid(row=0, column=0, sticky="nsew")
        body.columnconfigure(0, weight=1)
        self.ttk.Label(body, text=self._tr("接缝处权重统一", "Seam Weight Unify"), style="DialogTitle.TLabel").grid(
            row=0, column=0, sticky="w", pady=(0, 6)
        )
        hint = self.ttk.Label(
            body,
            text=self._tr(
                "手动：在 Skin 顶点或面选择模式中选 Mesh 1，记录左侧；再选 Mesh 2，记录右侧。\n"
                "自动：只选择两个完整的 Skin Mesh，工具会按接近位置寻找接缝并高亮结果。",
                "Manual: select Mesh 1 in Skin vertex or face mode and record it on the left; then record Mesh 2 on the right.\n"
                "Automatic: select exactly two complete skinned Meshes; nearby seam vertices are detected and highlighted.",
            ),
            style="Muted.TLabel",
            justify="left",
            anchor="w",
        )
        hint.grid(row=1, column=0, sticky="ew", pady=(0, 12))
        cards = self.ttk.Frame(body, style="Panel.TFrame")
        cards.grid(row=2, column=0, sticky="ew")
        cards.columnconfigure(0, weight=1)
        cards.columnconfigure(1, weight=1)
        for column, title, variable, side in (
            (0, self._tr("Mesh 1：记录左侧选区", "Mesh 1: Record Left Selection"), self.seam_left_var, "left"),
            (1, self._tr("Mesh 2：记录右侧选区", "Mesh 2: Record Right Selection"), self.seam_right_var, "right"),
        ):
            card = self.ttk.LabelFrame(cards, text=title, style="V4.TLabelframe", padding=(10, 8))
            card.grid(row=0, column=column, sticky="nsew", padx=(0, 6) if column == 0 else (6, 0))
            card.columnconfigure(0, weight=1)
            self.ttk.Label(card, textvariable=variable, style="Dialog.TLabel", justify="left", anchor="w").grid(
                row=0, column=0, sticky="ew", pady=(0, 8)
            )
            button = self.ttk.Button(
                card,
                text=self._tr("记录当前选区", "Record Current Selection"),
                command=lambda target=side: self._record_seam_selection(target),
                style="Accent.TButton",
            )
            button.grid(row=1, column=0, sticky="ew")
            self.ttk.Button(
                card,
                text=self._tr("清除", "Clear"),
                command=lambda target=side: self._clear_seam_selection(target),
            ).grid(row=2, column=0, sticky="ew", pady=(6, 0))
            if side == "left":
                self.seam_left_record_button = button
            else:
                self.seam_right_record_button = button

        controls = self.ttk.LabelFrame(
            body, text=self._tr("融合设置", "Blend Settings"), style="V4.TLabelframe", padding=(10, 8)
        )
        controls.grid(row=3, column=0, sticky="ew", pady=(12, 0))
        controls.columnconfigure(1, weight=1)
        self.ttk.Label(controls, text=self._tr("融合范围", "Blend Range"), style="Dialog.TLabel").grid(
            row=0, column=0, sticky="w", padx=(0, 10)
        )
        self.ttk.Scale(
            controls,
            from_=0.05,
            to=10.0,
            variable=self.seam_range_var,
            command=self._on_seam_range_changed,
        ).grid(row=0, column=1, sticky="ew")
        self.ttk.Label(controls, textvariable=self.seam_range_value_var, width=7, anchor="e", style="Dialog.TLabel").grid(
            row=0, column=2, sticky="e", padx=(10, 0)
        )
        self.ttk.Label(controls, text=self._tr("融合强度", "Blend Strength"), style="Dialog.TLabel").grid(
            row=1, column=0, sticky="w", padx=(0, 10), pady=(8, 0)
        )
        self.ttk.Scale(
            controls,
            from_=0.0,
            to=1.0,
            variable=self.seam_strength_var,
            command=self._on_seam_strength_changed,
        ).grid(row=1, column=1, sticky="ew", pady=(8, 0))
        self.ttk.Label(controls, textvariable=self.seam_strength_value_var, width=7, anchor="e", style="Dialog.TLabel").grid(
            row=1, column=2, sticky="e", padx=(10, 0), pady=(8, 0)
        )
        self.ttk.Label(
            controls,
            text=self._tr("范围越大找得更远，强度越大改得更明显。", "A larger range searches farther; a larger strength changes weights more."),
            style="Muted.TLabel",
        ).grid(row=2, column=0, columnspan=3, sticky="w", pady=(8, 0))

        self.tk.Label(
            body,
            text=self._tr(
                "重大操作之前请记得备份MAX场景，测试发现MAX自带的撤销、重做按钮可能引起程序崩溃退出，虽然MAX提供最终紧急备份，但中间操作将被丢弃。\nMAX会自动为本工具的改动生成可撤销、可重做的历史恢复节点",
                "Remember to back up the Max scene before major operations. Testing found that Max's built-in Undo and Redo buttons may cause the program to crash and exit; although Max provides a final emergency backup, intermediate work will be lost.\nMax automatically creates undoable and redoable history recovery points for changes made by this tool.",
            ),
            background=self.colors["panel"],
            foreground=self.colors["warn"],
            font=("Microsoft YaHei UI", 11, "bold"),
            justify="left",
            anchor="w",
            wraplength=560,
        ).grid(row=4, column=0, sticky="ew", pady=(12, 0))

        actions = self.ttk.Frame(body, style="Panel.TFrame")
        actions.grid(row=5, column=0, sticky="ew", pady=(14, 0))
        actions.columnconfigure(0, weight=1)
        actions.columnconfigure(1, weight=1)
        self.seam_blend_button = self.ttk.Button(
            actions,
            text=self._tr("Mesh 接缝权重混合", "Blend Recorded Seams"),
            command=self._blend_recorded_seams,
            style="Accent.TButton",
        )
        self.seam_blend_button.grid(row=0, column=0, sticky="ew", padx=(0, 5))
        self.seam_auto_button = self.ttk.Button(
            actions,
            text=self._tr("自动混合", "Automatic Blend"),
            command=self._auto_blend_seams,
            style="Accent.TButton",
        )
        self.seam_auto_button.grid(row=0, column=1, sticky="ew", padx=(5, 0))
        self.ttk.Button(
            actions,
            text=self._tr("清除两侧记录", "Clear Both Records"),
            command=lambda: self._clear_seam_selection(None),
        ).grid(row=1, column=0, columnspan=2, sticky="ew", pady=(7, 0))
        self.ttk.Label(body, textvariable=self.seam_status_var, style="Muted.TLabel", anchor="w").grid(
            row=6, column=0, sticky="ew", pady=(10, 0)
        )
        self._refresh_seam_tool_view()
        window.update_idletasks()
        screen_width = max(640, int(window.winfo_screenwidth()))
        screen_height = max(480, int(window.winfo_screenheight()))
        width = min(screen_width - 60, max(620, int(window.winfo_reqwidth())))
        height = min(screen_height - 80, max(390, int(window.winfo_reqheight())))
        x, y = _centered_window_position(
            width, height, screen_width, screen_height
        )
        window.minsize(min(width, 620), min(height, 360))
        window.maxsize(screen_width - 20, screen_height - 20)
        _set_themed_window_geometry(
            window,
            f"{width}x{height}+{x}+{y}",
            dark=bool(self._theme_dark),
        )
        setattr(window, "_pc_rehd_keep_owner_minimized", True)
        setattr(window, "_pc_rehd_force_front", True)
        self._present_exclusive_seam_window(window)

    def _message_editor_is_open(self) -> bool:
        window = getattr(self, "message_editor_window", None)
        if window is None:
            return False
        try:
            return bool(window.winfo_exists())
        except self.tk.TclError:
            return False

    def _message_editor_current_document(self) -> dict[str, Any]:
        fallback = _normalize_message_editor_snapshot(
            self.message_editor_state.get("document", {})
        )
        if not self._message_editor_is_open():
            return fallback
        current = copy.deepcopy(fallback)
        entry_ids = {entry["id"] for entry in current["entries"]}
        selected_id = self._message_editor_selected_id
        if selected_id not in entry_ids:
            selected_id = current.get("selected_id", "")
        if selected_id not in entry_ids:
            selected_id = current["entries"][0]["id"] if current["entries"] else ""
        current["selected_id"] = selected_id
        try:
            for entry in current["entries"]:
                if entry["id"] != selected_id:
                    continue
                if self.message_editor_title_var is not None:
                    entry["title"] = str(self.message_editor_title_var.get())
                if self.message_editor_text is not None:
                    entry["body"] = str(self.message_editor_text.get("1.0", "end-1c"))
                break
        except self.tk.TclError:
            pass
        current["expanded"] = bool(self._message_editor_expanded)
        return _normalize_message_editor_snapshot(current, fallback=fallback)

    @staticmethod
    def _message_editor_content_changed(
        previous: dict[str, Any], current: dict[str, Any]
    ) -> bool:
        if isinstance(previous.get("entries"), list) and isinstance(
            current.get("entries"), list
        ):
            return previous["entries"] != current["entries"]
        before = _normalize_message_editor_snapshot(previous)
        after = _normalize_message_editor_snapshot(current)
        return before.get("entries", []) != after.get("entries", [])

    def _message_editor_selected_entry(
        self, document: dict[str, Any]
    ) -> dict[str, Any] | None:
        normalized = _normalize_message_editor_snapshot(document)
        selected_id = str(normalized.get("selected_id", "") or "")
        return next(
            (entry for entry in normalized["entries"] if entry["id"] == selected_id),
            None,
        )

    @staticmethod
    def _message_editor_display_line_count(text_widget: Any) -> int:
        counted = text_widget.count("1.0", "end", "displaylines")
        if isinstance(counted, (tuple, list)):
            counted = counted[0] if counted else 0
        return max(1, int(counted or 0))

    def _fit_message_editor_text_widget(self, text_widget: Any) -> int:
        target_height = max(
            2, self._message_editor_display_line_count(text_widget)
        )
        for _attempt in range(6):
            if int(text_widget.cget("height")) != target_height:
                text_widget.configure(height=target_height)
            text_widget.update_idletasks()
            text_widget.yview_moveto(0.0)
            first, last = (float(value) for value in text_widget.yview())
            if first <= 0.001 and last >= 0.999:
                return target_height
            visible_fraction = max(0.001, last - first)
            target_height = max(
                target_height + 1,
                int(math.ceil(target_height / visible_fraction)),
            )
        text_widget.configure(height=target_height)
        return target_height

    def _fit_message_editor_text_widgets(self) -> None:
        self._message_editor_text_fit_after = None
        window = getattr(self, "message_editor_window", None)
        host = getattr(self, "message_editor_entries_frame", None)
        canvas = getattr(self, "message_editor_entries_canvas", None)
        if window is None or host is None or canvas is None:
            return
        try:
            fit_all = bool(self._message_editor_text_fit_all)
            self._message_editor_text_fit_all = False
            if fit_all:
                visible_widgets = [
                    widgets
                    for entry_id, widgets in self.message_editor_entry_widgets.items()
                    if entry_id not in self._message_editor_collapsed_ids
                ]
            else:
                selected = self.message_editor_entry_widgets.get(
                    self._message_editor_selected_id
                )
                visible_widgets = (
                    [selected]
                    if selected is not None
                    and self._message_editor_selected_id
                    not in self._message_editor_collapsed_ids
                    else []
                )
            if not visible_widgets:
                return
            if any(int(widgets["text"].winfo_width()) <= 2 for widgets in visible_widgets):
                self._message_editor_text_fit_all = fit_all
                self._message_editor_text_fit_after = window.after(
                    40, self._fit_message_editor_text_widgets
                )
                return
            changed = False
            for widgets in visible_widgets:
                text_widget = widgets["text"]
                previous_height = int(text_widget.cget("height"))
                target_height = self._fit_message_editor_text_widget(text_widget)
                if previous_height != target_height:
                    changed = True
            if changed:
                host.update_idletasks()
                self._refresh_message_editor_scrollregion()
        except (self.tk.TclError, TypeError, ValueError):
            self._message_editor_text_fit_after = None

    def _schedule_message_editor_text_fit(
        self, *, all_widgets: bool = False, delay_ms: int = 70
    ) -> None:
        window = getattr(self, "message_editor_window", None)
        if window is None:
            return
        self._message_editor_text_fit_all = bool(
            self._message_editor_text_fit_all or all_widgets
        )
        callback_id = self._message_editor_text_fit_after
        if callback_id is not None:
            try:
                window.after_cancel(callback_id)
            except self.tk.TclError:
                pass
        try:
            self._message_editor_text_fit_after = window.after(
                max(1, int(delay_ms)), self._fit_message_editor_text_widgets
            )
        except self.tk.TclError:
            self._message_editor_text_fit_after = None

    def _fit_message_editor_text_widgets_now(
        self, *, all_widgets: bool = False
    ) -> None:
        window = getattr(self, "message_editor_window", None)
        if window is None:
            return
        callback_id = self._message_editor_text_fit_after
        if callback_id is not None:
            try:
                window.after_cancel(callback_id)
            except self.tk.TclError:
                pass
        self._message_editor_text_fit_after = None
        self._message_editor_text_fit_all = bool(
            self._message_editor_text_fit_all or all_widgets
        )
        self._fit_message_editor_text_widgets()

    def _scroll_message_editor_entries(self, event: Any) -> str:
        canvas = getattr(self, "message_editor_entries_canvas", None)
        if canvas is not None:
            try:
                delta = int(getattr(event, "delta", 0) or 0)
                if delta:
                    _managed_window_scheduler(self.root).queue_scroll(
                        canvas,
                        "y",
                        "scroll",
                        -1 if delta > 0 else 1,
                        "units",
                    )
            except self.tk.TclError:
                pass
        return "break"

    def _refresh_message_editor_scrollregion(self) -> None:
        canvas = getattr(self, "message_editor_entries_canvas", None)
        if canvas is None:
            return
        self._sync_canvas_scrollregion_from_bbox(
            canvas, "_message_editor_scrollregion_signature"
        )

    def _apply_message_editor_selection(self, selected_id: str) -> None:
        current = _normalize_message_editor_snapshot(
            self._message_editor_last_saved_document
        )
        entry_ids = {str(entry["id"]) for entry in current["entries"]}
        if selected_id not in entry_ids:
            return
        previous_id = self._message_editor_selected_id
        current["selected_id"] = selected_id
        current["expanded"] = bool(self._message_editor_expanded)
        self._message_editor_applying_document = True
        try:
            previous_widgets = self.message_editor_entry_widgets.get(previous_id)
            if previous_widgets is not None:
                self._configure_widget_if_changed(
                    previous_widgets["border"], background=self.colors["border"]
                )
            selected_widgets = self.message_editor_entry_widgets.get(selected_id)
            if selected_widgets is None:
                return
            self._configure_widget_if_changed(
                selected_widgets["border"], background=self.colors["accent"]
            )
            self._message_editor_selected_id = selected_id
            self.message_editor_title_var = selected_widgets["title_var"]
            self.message_editor_title_entry = selected_widgets["title_entry"]
            self.message_editor_text = selected_widgets["text"]
            self.message_editor_state["document"] = copy.deepcopy(current)
            self._refresh_message_editor_selector(current)
            self._apply_message_editor_edit_state()
        finally:
            self._message_editor_applying_document = False
        if self._persist_message_editor_state(document=current, visible=True):
            self._message_editor_last_saved_document = copy.deepcopy(current)

    def _select_message_editor_entry_id(self, selected_id: str) -> None:
        if (
            self._message_editor_applying_document
            or selected_id == self._message_editor_selected_id
        ):
            return
        self._flush_message_editor_autosave(commit_history=True)
        current = _normalize_message_editor_snapshot(
            self._message_editor_last_saved_document
        )
        if not any(entry["id"] == selected_id for entry in current["entries"]):
            return
        self._message_editor_editing = False
        self._apply_message_editor_selection(selected_id)

    def _toggle_message_editor_entry_collapsed(self, entry_id: str) -> None:
        widgets = self.message_editor_entry_widgets.get(entry_id)
        if widgets is None:
            return
        if entry_id in self._message_editor_collapsed_ids:
            self._message_editor_collapsed_ids.discard(entry_id)
            widgets["collapse_button"].configure(text="▼")
            widgets["text"].grid()
        else:
            self._message_editor_collapsed_ids.add(entry_id)
            widgets["collapse_button"].configure(text="▶")
            widgets["text"].grid_remove()
        try:
            self.message_editor_window.after_idle(
                self._refresh_message_editor_scrollregion
            )
        except self.tk.TclError:
            pass
        self._schedule_message_editor_text_fit(all_widgets=True)

    def _render_message_editor_entries(self, document: dict[str, Any]) -> None:
        host = getattr(self, "message_editor_entries_frame", None)
        canvas = getattr(self, "message_editor_entries_canvas", None)
        if host is None or canvas is None:
            return
        normalized = _normalize_message_editor_snapshot(document)
        selected_id = str(normalized.get("selected_id", "") or "")
        for child in host.winfo_children():
            child.destroy()
        self.message_editor_entry_widgets = {}
        self.message_editor_title_var = None
        self.message_editor_title_entry = None
        self.message_editor_text = None

        for row, entry in enumerate(normalized["entries"]):
            entry_id = str(entry["id"])
            selected = entry_id == selected_id
            border = self.tk.Frame(
                host,
                background=self.colors["accent"] if selected else self.colors["border"],
                borderwidth=0,
                padx=1,
                pady=1,
            )
            border.grid(row=row, column=0, sticky="ew", pady=(0, 8))
            border.columnconfigure(0, weight=1)
            item = self.ttk.Frame(border, style="Panel.TFrame", padding=(0, 0, 0, 0))
            item.grid(row=0, column=0, sticky="ew")
            item.columnconfigure(1, weight=1)

            title_var = self.tk.StringVar(master=host, value=str(entry["title"]))
            collapsed = entry_id in self._message_editor_collapsed_ids
            collapse_button = self.ttk.Button(
                item,
                text="▶" if collapsed else "▼",
                width=3,
                command=lambda target=entry_id: self._toggle_message_editor_entry_collapsed(
                    target
                ),
            )
            collapse_button.grid(row=0, column=0, sticky="w", padx=(0, 5), pady=(0, 5))
            title_entry = self.ttk.Entry(item, textvariable=title_var, state="readonly")
            title_entry.grid(row=0, column=1, sticky="ew", pady=(0, 5))
            text_widget = self.tk.Text(
                item,
                height=2,
                wrap="word",
                undo=True,
                maxundo=100,
                background=self.colors["field"],
                foreground=self.colors["text"],
                insertbackground=self.colors["text"],
                selectbackground=self.colors["select"],
                selectforeground=self.colors["accent_text"],
                relief="flat",
                borderwidth=0,
                highlightthickness=0,
                padx=10,
                pady=8,
                font=("Microsoft YaHei UI", 9),
            )
            text_widget.grid(row=1, column=0, columnspan=2, sticky="ew")
            text_widget.insert("1.0", str(entry["body"]))
            text_widget.edit_modified(False)
            text_widget.configure(state="disabled")
            if collapsed:
                text_widget.grid_remove()

            for widget in (border, item, title_entry, text_widget):
                widget.bind(
                    "<Button-1>",
                    lambda _event, target=entry_id: self._select_message_editor_entry_id(
                        target
                    ),
                    add="+",
                )
                widget.bind("<MouseWheel>", self._scroll_message_editor_entries, add="+")

            self.message_editor_entry_widgets[entry_id] = {
                "border": border,
                "collapse_button": collapse_button,
                "title_var": title_var,
                "title_entry": title_entry,
                "text": text_widget,
            }
            title_var.trace_add("write", self._on_message_editor_changed)
            text_widget.bind(
                "<<Modified>>", self._on_message_editor_text_modified, add="+"
            )
            if selected:
                self.message_editor_title_var = title_var
                self.message_editor_title_entry = title_entry
                self.message_editor_text = text_widget

        host.columnconfigure(0, weight=1)
        self._schedule_message_editor_text_fit(all_widgets=True)

    def _refresh_message_editor_selector(self, document: dict[str, Any]) -> None:
        selector = getattr(self, "message_editor_selector", None)
        if selector is None:
            return
        normalized = _normalize_message_editor_snapshot(document)
        entries = normalized["entries"]
        self._message_editor_selector_ids = [entry["id"] for entry in entries]
        labels = [
            entry["title"].strip() or self._tr("（无标题）", "(Untitled)")
            for entry in entries
        ]
        selected_id = str(normalized.get("selected_id", "") or "")
        try:
            target_state = "readonly" if entries else "disabled"
            render_signature = (id(selector), tuple(labels), target_state)
            if render_signature != self._message_editor_selector_signature:
                selector.configure(values=labels, state=target_state)
                self._message_editor_selector_signature = render_signature
            if selected_id in self._message_editor_selector_ids:
                target_index = self._message_editor_selector_ids.index(selected_id)
                if int(selector.current()) != target_index:
                    selector.current(target_index)
            elif str(selector.get()):
                selector.set("")
        except self.tk.TclError:
            pass

    def _apply_message_editor_edit_state(self) -> None:
        has_entry = bool(self._message_editor_selected_id)
        editing = bool(self._message_editor_editing and has_entry)
        try:
            for entry_id, widgets in self.message_editor_entry_widgets.items():
                entry_editing = bool(editing and entry_id == self._message_editor_selected_id)
                self._configure_widget_if_changed(
                    widgets["title_entry"],
                    state="normal" if entry_editing else "readonly"
                )
                self._configure_widget_if_changed(
                    widgets["text"],
                    state="normal" if entry_editing else "disabled"
                )
            if self.message_editor_edit_button is not None:
                self._configure_widget_if_changed(
                    self.message_editor_edit_button,
                    text=self._tr("完成", "Done") if editing else self._tr("编辑", "Edit"),
                    state="normal" if has_entry else "disabled",
                )
            if self.message_editor_delete_button is not None:
                self._configure_widget_if_changed(
                    self.message_editor_delete_button,
                    state="normal" if has_entry else "disabled"
                )
        except self.tk.TclError:
            pass

    def _persist_message_editor_state(
        self,
        *,
        document: dict[str, Any] | None = None,
        visible: bool | None = None,
        embed_document: bool = False,
    ) -> bool:
        current = _normalize_message_editor_snapshot(
            document if document is not None else self._message_editor_current_document()
        )
        window_state = dict(self.message_editor_state.get("window", {}))
        geometry = str(window_state.get("geometry", "") or "")
        is_open = self._message_editor_is_open()
        window = self.message_editor_window if is_open else None
        if window is not None:
            try:
                geometry = str(window.geometry())
                if self._message_editor_expanded:
                    self._message_editor_expanded_height = max(
                        260, int(window.winfo_height() or self._message_editor_expanded_height)
                    )
            except self.tk.TclError:
                pass
        effective_visible = is_open if visible is None else bool(visible)
        if not self._persist_message_editor_enabled:
            self.message_editor_state = {
                "schema": MESSAGE_EDITOR_STATE_SCHEMA,
                "document": current,
                "history": copy.deepcopy(self._message_editor_history),
                "redo": copy.deepcopy(self._message_editor_redo),
                "window": {
                    "geometry": geometry,
                    "dock_side": str(self._message_editor_dock_side or ""),
                    "dock_offset": int(self._message_editor_dock_offset),
                    "expanded_height": int(self._message_editor_expanded_height),
                    "visible": effective_visible,
                },
            }
            return True
        try:
            log_directory = _resolve_log_directory(self.log_dir_var.get())
        except Exception:
            log_directory = Path(self._long_term_cache_directory)
        queued = self._queue_message_editor_history_write(
            {
                "document": copy.deepcopy(current),
                "history": copy.deepcopy(self._message_editor_history),
                "redo": copy.deepcopy(self._message_editor_redo),
                "log_directory": log_directory,
                "geometry": geometry,
                "dock_side": str(self._message_editor_dock_side or ""),
                "dock_offset": int(self._message_editor_dock_offset),
                "expanded_height": int(self._message_editor_expanded_height),
                "visible": effective_visible,
                "embed_document": bool(embed_document),
            }
        )
        self.message_editor_state = {
            "schema": MESSAGE_EDITOR_STATE_SCHEMA,
            "document": current,
            "history": copy.deepcopy(self._message_editor_history),
            "redo": copy.deepcopy(self._message_editor_redo),
            "window": {
                "geometry": geometry,
                "dock_side": str(self._message_editor_dock_side or ""),
                "dock_offset": int(self._message_editor_dock_offset),
                "expanded_height": int(self._message_editor_expanded_height),
                "visible": effective_visible,
            },
        }
        return bool(queued)

    def _queue_message_editor_history_write(self, payload: dict[str, Any]) -> bool:
        payload = dict(payload)
        with self._message_editor_write_lock:
            previous = self._message_editor_pending_write
            if isinstance(previous, dict) and bool(previous.get("embed_document", False)):
                payload["embed_document"] = True
            self._message_editor_pending_write = payload
            if self._message_editor_writer_active:
                return True
            self._message_editor_writer_active = True

        def persist_latest() -> None:
            while True:
                with self._message_editor_write_lock:
                    pending = self._message_editor_pending_write
                    self._message_editor_pending_write = None
                    if pending is None:
                        self._message_editor_writer_active = False
                        return
                try:
                    self._wait_for_import_export_priority()

                    def write_pending() -> None:
                        _write_message_editor_history(
                            pending["document"],
                            pending["history"],
                            pending["redo"],
                            log_directory=pending["log_directory"],
                            geometry=str(pending["geometry"]),
                            dock_side=str(pending["dock_side"]),
                            dock_offset=int(pending["dock_offset"]),
                            expanded_height=int(pending["expanded_height"]),
                            visible=bool(pending["visible"]),
                        )
                        if bool(pending.get("embed_document", False)):
                            _write_embedded_message_editor_document(pending["document"])

                    _call_with_windows_thread_priority(
                        write_pending,
                        performance_critical=False,
                        background_maintenance=True,
                    )
                except Exception:
                    pass

        try:
            threading.Thread(
                target=persist_latest,
                name=f"{APP_NAME}-MessageState",
                daemon=False,
            ).start()
            return True
        except Exception:
            with self._message_editor_write_lock:
                self._message_editor_writer_active = False
            return False

    def _update_message_editor_history_buttons(self) -> None:
        undo_button = getattr(self, "message_editor_undo_button", None)
        redo_button = getattr(self, "message_editor_redo_button", None)
        undo_count = min(MESSAGE_EDITOR_MAX_HISTORY, len(self._message_editor_history))
        redo_count = min(MESSAGE_EDITOR_MAX_HISTORY, len(self._message_editor_redo))
        try:
            if undo_button is not None:
                undo_button.configure(
                    text=self._tr(
                        f"撤销改动 ({undo_count}/3)", f"Undo Changes ({undo_count}/3)"
                    ),
                    state="normal" if undo_count > 0 else "disabled",
                )
            if redo_button is not None:
                redo_button.configure(
                    text=self._tr(
                        f"恢复改动 ({redo_count}/3)", f"Redo Changes ({redo_count}/3)"
                    ),
                    state="normal" if redo_count > 0 else "disabled",
                )
        except self.tk.TclError:
            pass

    def _save_message_editor_now(self) -> None:
        self._message_editor_save_after = None
        current = self._message_editor_current_document()
        if self._persist_message_editor_state(document=current, visible=True):
            self._message_editor_last_saved_document = copy.deepcopy(current)
        self._refresh_message_editor_selector(current)

    def _commit_message_editor_history(self) -> None:
        self._message_editor_history_after = None
        previous = self._message_editor_pending_history_document
        current = self._message_editor_current_document()
        if previous is not None:
            normalized_previous = _normalize_message_editor_snapshot(previous)
            if self._message_editor_content_changed(normalized_previous, current):
                self._message_editor_history = [
                    item for item in self._message_editor_history
                    if item != normalized_previous
                ]
                self._message_editor_history.append(normalized_previous)
                self._message_editor_history = self._message_editor_history[-MESSAGE_EDITOR_MAX_HISTORY:]
                self._message_editor_redo.clear()
        self._message_editor_pending_history_document = None
        if self._persist_message_editor_state(document=current, visible=True):
            self._message_editor_last_saved_document = copy.deepcopy(current)
        self._refresh_message_editor_selector(current)
        self._update_message_editor_history_buttons()

    def _flush_message_editor_autosave(self, *, commit_history: bool) -> None:
        window = getattr(self, "message_editor_window", None)
        for attribute in ("_message_editor_save_after", "_message_editor_history_after"):
            callback_id = getattr(self, attribute, None)
            if callback_id is not None and window is not None:
                try:
                    window.after_cancel(callback_id)
                except self.tk.TclError:
                    pass
            setattr(self, attribute, None)
        if commit_history:
            self._commit_message_editor_history()
        else:
            self._save_message_editor_now()

    def _on_message_editor_changed(self, *_args: Any) -> None:
        if self._message_editor_applying_document or not self._message_editor_is_open():
            return
        current = self._message_editor_current_document()
        self._schedule_message_editor_text_fit()
        if not self._message_editor_content_changed(
            self._message_editor_last_saved_document, current
        ):
            return
        if self._message_editor_pending_history_document is None:
            self._message_editor_pending_history_document = copy.deepcopy(
                self._message_editor_last_saved_document
            )
        window = self.message_editor_window
        for attribute in ("_message_editor_save_after", "_message_editor_history_after"):
            callback_id = getattr(self, attribute, None)
            if callback_id is not None:
                try:
                    window.after_cancel(callback_id)
                except self.tk.TclError:
                    pass
        try:
            self._message_editor_save_after = window.after(220, self._save_message_editor_now)
            self._message_editor_history_after = window.after(
                1100, self._commit_message_editor_history
            )
        except self.tk.TclError:
            self._message_editor_save_after = None
            self._message_editor_history_after = None

    def _on_message_editor_text_modified(self, event: Any) -> None:
        widget = getattr(event, "widget", None)
        if widget is None:
            return
        try:
            if not bool(widget.edit_modified()):
                return
            widget.edit_modified(False)
        except self.tk.TclError:
            return
        self._on_message_editor_changed()

    def _apply_message_editor_document(self, document: dict[str, Any]) -> None:
        normalized = _normalize_message_editor_snapshot(document)
        self._message_editor_applying_document = True
        try:
            self.message_editor_state["document"] = copy.deepcopy(normalized)
            self._message_editor_selected_id = str(normalized.get("selected_id", "") or "")
            self._render_message_editor_entries(normalized)
            self._refresh_message_editor_selector(normalized)
            self._message_editor_expanded = bool(normalized.get("expanded", True))
            self._apply_message_editor_expanded_state(persist=False)
            self._apply_message_editor_edit_state()
        finally:
            self._message_editor_applying_document = False

    def _replace_message_editor_document(
        self, document: dict[str, Any], *, record_history: bool
    ) -> None:
        previous = _normalize_message_editor_snapshot(
            self._message_editor_last_saved_document
        )
        current = _normalize_message_editor_snapshot(document, fallback=previous)
        if record_history and self._message_editor_content_changed(previous, current):
            self._message_editor_history = [
                item for item in self._message_editor_history if item != previous
            ]
            self._message_editor_history.append(previous)
            self._message_editor_history = self._message_editor_history[-MESSAGE_EDITOR_MAX_HISTORY:]
            self._message_editor_redo.clear()
        self._message_editor_pending_history_document = None
        self._apply_message_editor_document(current)
        if self._persist_message_editor_state(document=current, visible=True):
            self._message_editor_last_saved_document = copy.deepcopy(current)
        self._update_message_editor_history_buttons()

    def _select_message_editor_entry(self, _event: Any = None) -> None:
        if self._message_editor_applying_document:
            return
        selector = getattr(self, "message_editor_selector", None)
        if selector is None:
            return
        try:
            index = int(selector.current())
        except (self.tk.TclError, TypeError, ValueError):
            return
        if not (0 <= index < len(self._message_editor_selector_ids)):
            return
        selected_id = self._message_editor_selector_ids[index]
        if selected_id == self._message_editor_selected_id:
            return
        self._flush_message_editor_autosave(commit_history=True)
        current = _normalize_message_editor_snapshot(
            self._message_editor_last_saved_document
        )
        self._message_editor_editing = False
        self._apply_message_editor_selection(selected_id)

    def _add_message_editor_entry(self) -> None:
        self._flush_message_editor_autosave(commit_history=True)
        current = _normalize_message_editor_snapshot(
            self._message_editor_last_saved_document
        )
        entry_id = f"message-{uuid.uuid4().hex}"
        number = len(current["entries"]) + 1
        current["entries"].append({
            "id": entry_id,
            "title": self._tr(f"{number:02d} - 新消息", f"{number:02d} - New Message"),
            "body": "",
        })
        current["selected_id"] = entry_id
        current["expanded"] = True
        self._message_editor_editing = True
        self._replace_message_editor_document(current, record_history=True)
        try:
            if self.message_editor_title_entry is not None:
                self.message_editor_title_entry.focus_set()
                self.message_editor_title_entry.selection_range(0, "end")
        except self.tk.TclError:
            pass

    def _delete_message_editor_entry(self) -> None:
        self._flush_message_editor_autosave(commit_history=True)
        current = _normalize_message_editor_snapshot(
            self._message_editor_last_saved_document
        )
        selected_id = str(current.get("selected_id", "") or "")
        index = next(
            (i for i, entry in enumerate(current["entries"]) if entry["id"] == selected_id),
            -1,
        )
        if index < 0:
            return
        del current["entries"][index]
        current["selected_id"] = (
            current["entries"][min(index, len(current["entries"]) - 1)]["id"]
            if current["entries"] else ""
        )
        self._message_editor_editing = False
        self._replace_message_editor_document(current, record_history=True)

    def _toggle_message_editor_editing(self) -> None:
        if not self._message_editor_selected_id:
            return
        if self._message_editor_editing:
            self._flush_message_editor_autosave(commit_history=True)
            self._message_editor_editing = False
            self._apply_message_editor_edit_state()
            return
        self._message_editor_editing = True
        self._apply_message_editor_edit_state()
        try:
            if self.message_editor_title_entry is not None:
                self.message_editor_title_entry.focus_set()
        except self.tk.TclError:
            pass

    def _undo_message_editor_history(self) -> None:
        self._flush_message_editor_autosave(commit_history=True)
        if not self._message_editor_history:
            self._update_message_editor_history_buttons()
            return
        current = _normalize_message_editor_snapshot(
            self._message_editor_last_saved_document
        )
        previous = self._message_editor_history.pop()
        self._message_editor_redo.append(current)
        self._message_editor_redo = self._message_editor_redo[-MESSAGE_EDITOR_MAX_HISTORY:]
        self._message_editor_pending_history_document = None
        self._message_editor_editing = False
        self._apply_message_editor_document(previous)
        restored = self._message_editor_current_document()
        if self._persist_message_editor_state(document=restored, visible=True):
            self._message_editor_last_saved_document = copy.deepcopy(restored)
        self._update_message_editor_history_buttons()

    def _redo_message_editor_history(self) -> None:
        self._flush_message_editor_autosave(commit_history=True)
        if not self._message_editor_redo:
            self._update_message_editor_history_buttons()
            return
        current = _normalize_message_editor_snapshot(
            self._message_editor_last_saved_document
        )
        restored = self._message_editor_redo.pop()
        self._message_editor_history.append(current)
        self._message_editor_history = self._message_editor_history[-MESSAGE_EDITOR_MAX_HISTORY:]
        self._message_editor_pending_history_document = None
        self._message_editor_editing = False
        self._apply_message_editor_document(restored)
        redone = self._message_editor_current_document()
        if self._persist_message_editor_state(document=redone, visible=True):
            self._message_editor_last_saved_document = copy.deepcopy(redone)
        self._update_message_editor_history_buttons()

    def _launcher_tile_dock_candidate(
        self,
        window: Any,
    ) -> tuple[str, int] | None:
        try:
            if (
                not bool(window.winfo_exists())
                or str(self.root.state()).casefold() != "normal"
            ):
                return None
            root_x = int(self.root.winfo_rootx())
            root_y = int(self.root.winfo_rooty())
            root_width = max(1, int(self.root.winfo_width()))
            root_height = max(1, int(self.root.winfo_height()))
            win_x = int(window.winfo_x())
            win_y = int(window.winfo_y())
            win_width = max(1, int(window.winfo_width()))
            win_height = max(1, int(window.winfo_height()))
        except self.tk.TclError:
            return None

        vertical_overlap = win_y < root_y + root_height and win_y + win_height > root_y
        horizontal_overlap = win_x < root_x + root_width and win_x + win_width > root_x
        distances: dict[str, int] = {}
        offsets: dict[str, int] = {}
        root_center_x = root_x + (root_width / 2.0)
        root_center_y = root_y + (root_height / 2.0)
        win_center_x = win_x + (win_width / 2.0)
        win_center_y = win_y + (win_height / 2.0)

        for side in ("left", "right", "top", "bottom"):
            offset = win_y - root_y if side in {"left", "right"} else win_x - root_x
            if side == "left":
                if not vertical_overlap or win_center_x > root_center_x:
                    continue
                distance = abs(
                    (win_x + win_width + LAUNCHER_TILE_DOCK_GAP) - root_x
                )
            elif side == "right":
                if not vertical_overlap or win_center_x < root_center_x:
                    continue
                distance = abs(
                    win_x - (root_x + root_width + LAUNCHER_TILE_DOCK_GAP)
                )
            elif side == "top":
                if not horizontal_overlap or win_center_y > root_center_y:
                    continue
                distance = abs(
                    (win_y + win_height + LAUNCHER_TILE_DOCK_GAP) - root_y
                )
            else:
                if not horizontal_overlap or win_center_y < root_center_y:
                    continue
                distance = abs(
                    win_y - (root_y + root_height + LAUNCHER_TILE_DOCK_GAP)
                )
            distances[side] = distance
            offsets[side] = offset
        if not distances:
            return None
        side, distance = min(distances.items(), key=lambda item: item[1])
        if distance > LAUNCHER_TILE_DOCK_CAPTURE_DISTANCE:
            return None
        return side, offsets[side]

    def _message_editor_dock_candidate(self, window: Any) -> tuple[str, int] | None:
        return self._launcher_tile_dock_candidate(window)

    @staticmethod
    def _mark_launcher_tile_programmatic_geometry(
        window: Any, target: tuple[int, int, int, int]
    ) -> None:
        setattr(window, "_pc_rehd_tile_geometry_target", tuple(int(value) for value in target))
        setattr(window, "_pc_rehd_tile_geometry_at", time.monotonic())

    def _launcher_tile_configure_is_programmatic(self, window: Any) -> bool:
        target = getattr(window, "_pc_rehd_tile_geometry_target", None)
        if not isinstance(target, tuple) or len(target) != 4:
            return False
        try:
            current = (
                int(window.winfo_width()),
                int(window.winfo_height()),
                int(window.winfo_x()),
                int(window.winfo_y()),
            )
        except self.tk.TclError:
            return False
        if current == target:
            return True
        elapsed = time.monotonic() - float(
            getattr(window, "_pc_rehd_tile_geometry_at", 0.0) or 0.0
        )
        if (
            _windows_tk_window_in_move_size(window) is not True
            and elapsed <= LAUNCHER_TILE_PROGRAMMATIC_GRACE_SECONDS
        ):
            return True
        setattr(window, "_pc_rehd_tile_geometry_target", None)
        return False

    def _launcher_tile_window_exists(self, window: Any) -> bool:
        if window is None:
            return False
        try:
            return bool(window.winfo_exists())
        except self.tk.TclError:
            return False

    def _schedule_launcher_tile_follow(self) -> None:
        message_window = getattr(self, "message_editor_window", None)
        normals_window = getattr(self, "scene_normals_window", None)
        if not (
            self._launcher_tile_window_exists(message_window)
            or self._launcher_tile_window_exists(normals_window)
            or self._rename_value_history_is_open()
        ):
            return
        if self._launcher_tile_follow_after is not None:
            return
        frame_seconds = 1.0 / 60.0
        elapsed = time.perf_counter() - self._launcher_tile_last_follow_commit
        delay_ms = (
            0
            if elapsed >= frame_seconds
            else max(1, int((frame_seconds - elapsed) * 1000.0) + 1)
        )
        try:
            self._launcher_tile_follow_after = self.root.after(
                delay_ms, self._commit_launcher_tile_follow
            )
        except self.tk.TclError:
            self._launcher_tile_follow_after = None

    def _commit_launcher_tile_follow(self) -> None:
        self._launcher_tile_follow_after = None
        self._launcher_tile_last_follow_commit = time.perf_counter()

        message_window = getattr(self, "message_editor_window", None)
        if self._launcher_tile_window_exists(message_window) and not bool(
            self._message_editor_repositioning
        ):
            if self._message_editor_dock_side in {"top", "bottom", "left", "right"}:
                self._position_message_editor()
            else:
                candidate = self._message_editor_dock_candidate(message_window)
                if candidate is not None:
                    self._message_editor_dock_side, self._message_editor_dock_offset = candidate
                    self._position_message_editor()
                    self._persist_message_editor_state(visible=True)

        normals_window = getattr(self, "scene_normals_window", None)
        if self._launcher_tile_window_exists(normals_window) and not bool(
            self._scene_normals_monitor_repositioning
        ):
            if self._scene_normals_monitor_dock_side in {
                "top",
                "bottom",
                "left",
                "right",
            }:
                self._position_scene_normals_monitor()
            else:
                candidate = self._launcher_tile_dock_candidate(normals_window)
                if candidate is not None:
                    (
                        self._scene_normals_monitor_dock_side,
                        self._scene_normals_monitor_dock_offset,
                    ) = candidate
                    self._position_scene_normals_monitor()

        if self._rename_value_history_is_open():
            self._position_rename_value_history_dropdown()

    def _cancel_launcher_tile_follow_if_idle(self) -> None:
        if self._launcher_tile_window_exists(
            getattr(self, "message_editor_window", None)
        ) or self._launcher_tile_window_exists(
            getattr(self, "scene_normals_window", None)
        ) or self._rename_value_history_is_open():
            return
        callback_id = self._launcher_tile_follow_after
        self._launcher_tile_follow_after = None
        if callback_id is not None:
            try:
                self.root.after_cancel(callback_id)
            except self.tk.TclError:
                pass

    def _message_editor_tile_size(
        self, side: str | None, *, expanded: bool
    ) -> tuple[int, int]:
        window = getattr(self, "message_editor_window", None)
        screen_width = max(640, int(self.root.winfo_screenwidth()))
        screen_height = max(480, int(self.root.winfo_screenheight()))
        root_width = max(1, int(self.root.winfo_width()))
        root_height = max(1, int(self.root.winfo_height()))
        requested_height = 108
        if window is not None:
            try:
                requested_height = max(requested_height, int(window.winfo_reqheight()))
            except self.tk.TclError:
                pass

        if side in {"left", "right"}:
            width = min(screen_width - 40, MESSAGE_EDITOR_VERTICAL_TILE_WIDTH)
            height = (
                min(screen_height - 40, max(260, root_height))
                if expanded else min(screen_height - 40, requested_height)
            )
        elif side in {"top", "bottom"}:
            width = min(screen_width - 40, max(MESSAGE_EDITOR_VERTICAL_TILE_WIDTH, root_width))
            height = (
                min(screen_height - 40, MESSAGE_EDITOR_HORIZONTAL_TILE_HEIGHT)
                if expanded else min(screen_height - 40, requested_height)
            )
        else:
            width = min(screen_width - 40, MESSAGE_EDITOR_VERTICAL_TILE_WIDTH)
            height = (
                min(screen_height - 40, MESSAGE_EDITOR_FLOAT_HEIGHT)
                if expanded else min(screen_height - 40, requested_height)
            )
        return max(260, width), max(108, height)

    def _apply_message_editor_expanded_state(
        self, *, persist: bool = True, preserve_position: bool = False
    ) -> None:
        window = getattr(self, "message_editor_window", None)
        body = getattr(self, "message_editor_card_body", None)
        button = getattr(self, "message_editor_expand_button", None)
        if window is None or body is None or button is None:
            return
        try:
            if self._message_editor_expanded:
                body.grid()
                button.configure(text="▼")
                desired_resizable = (True, True)
            else:
                if int(window.winfo_height()) >= 260:
                    self._message_editor_expanded_height = int(window.winfo_height())
                body.grid_remove()
                button.configure(text="▶")
                desired_resizable = (True, False)
            current_resizable = tuple(bool(int(value)) for value in window.resizable())
            if current_resizable != desired_resizable:
                window.resizable(*desired_resizable)
                if bool(window.winfo_ismapped()):
                    _queue_native_window_theme_refresh(
                        window, dark=bool(self._theme_dark)
                    )
            width, height = self._message_editor_tile_size(
                self._message_editor_dock_side,
                expanded=bool(self._message_editor_expanded),
            )
            x = int(window.winfo_x())
            y = int(window.winfo_y())
            self._message_editor_repositioning = True
            self._mark_launcher_tile_programmatic_geometry(
                window, (width, height, x, y)
            )
            _set_themed_window_geometry(
                window,
                f"{width}x{height}+{x}+{y}",
                dark=bool(self._theme_dark),
            )
            if (
                not preserve_position
                and self._message_editor_dock_side in {"top", "bottom", "left", "right"}
            ):
                self._position_message_editor()
        except self.tk.TclError:
            return
        finally:
            self._message_editor_repositioning = False
        if persist:
            self._persist_message_editor_state(visible=True)

    def _toggle_message_editor_expanded(self) -> None:
        self._message_editor_expanded = not bool(self._message_editor_expanded)
        self._apply_message_editor_expanded_state()

    def _message_editor_dock_position(
        self,
        side: str,
        width: int,
        height: int,
        *,
        offset: int | None = None,
    ) -> tuple[int, int]:
        root_x = int(self.root.winfo_rootx())
        root_y = int(self.root.winfo_rooty())
        root_width = max(1, int(self.root.winfo_width()))
        root_height = max(1, int(self.root.winfo_height()))
        screen_width = max(640, int(self.root.winfo_screenwidth()))
        screen_height = max(480, int(self.root.winfo_screenheight()))
        gap = LAUNCHER_TILE_DOCK_GAP
        if side in {"left", "right"}:
            along = (root_height - height) // 2 if offset is None else int(offset)
            x = root_x - width - gap if side == "left" else root_x + root_width + gap
            y = root_y + along
        else:
            along = (root_width - width) // 2 if offset is None else int(offset)
            x = root_x + along
            y = root_y - height - gap if side == "top" else root_y + root_height + gap
        return (
            min(max(0, x), max(0, screen_width - width)),
            min(max(0, y), max(0, screen_height - height)),
        )

    def _position_message_editor(self) -> None:
        window = getattr(self, "message_editor_window", None)
        side = self._message_editor_dock_side
        if window is None or side not in {"top", "bottom", "left", "right"}:
            return
        try:
            if not bool(window.winfo_exists()) or str(self.root.state()).casefold() != "normal":
                return
            width, height = self._message_editor_tile_size(
                side, expanded=bool(self._message_editor_expanded)
            )
            x, y = self._message_editor_dock_position(
                side, width, height, offset=int(self._message_editor_dock_offset)
            )
            self._message_editor_repositioning = True
            current = (
                int(window.winfo_width()),
                int(window.winfo_height()),
                int(window.winfo_x()),
                int(window.winfo_y()),
            )
            target = (width, height, x, y)
            if current != target:
                self._mark_launcher_tile_programmatic_geometry(window, target)
                _set_themed_window_geometry(
                    window,
                    f"{width}x{height}+{x}+{y}",
                    dark=bool(self._theme_dark),
                )
        except self.tk.TclError:
            return
        finally:
            self._message_editor_repositioning = False

    def _snap_message_editor(self, window: Any) -> None:
        if window is not getattr(self, "message_editor_window", None):
            return
        try:
            if not bool(window.winfo_exists()) or str(self.root.state()).casefold() != "normal":
                return
        except self.tk.TclError:
            return

        if self._launcher_tile_configure_is_programmatic(window):
            return

        previous_side = self._message_editor_dock_side
        if previous_side in {"top", "bottom", "left", "right"}:
            try:
                width, height = self._message_editor_tile_size(
                    previous_side, expanded=bool(self._message_editor_expanded)
                )
                expected_x, expected_y = self._message_editor_dock_position(
                    previous_side,
                    width,
                    height,
                    offset=int(self._message_editor_dock_offset),
                )
                current = (
                    int(window.winfo_width()),
                    int(window.winfo_height()),
                    int(window.winfo_x()),
                    int(window.winfo_y()),
                )
                if current == (width, height, expected_x, expected_y):
                    return
            except self.tk.TclError:
                return

        candidate = self._message_editor_dock_candidate(window)
        if candidate is None:
            self._message_editor_dock_side = None
        else:
            self._message_editor_dock_side, self._message_editor_dock_offset = candidate
            self._position_message_editor()
        self._persist_message_editor_state(visible=True)

    def _close_message_editor(self, *, reopen_next_launch: bool = False) -> None:
        window = getattr(self, "message_editor_window", None)
        if window is None:
            return
        self._flush_message_editor_autosave(commit_history=True)
        if self._message_editor_expanded:
            try:
                self._message_editor_expanded_height = max(260, int(window.winfo_height()))
            except self.tk.TclError:
                pass
        self._persist_message_editor_state(
            visible=bool(reopen_next_launch), embed_document=True
        )
        for owner, attribute in ((window, "_message_editor_text_fit_after"),):
            callback_id = getattr(self, attribute, None)
            if callback_id is not None:
                try:
                    owner.after_cancel(callback_id)
                except self.tk.TclError:
                    pass
            setattr(self, attribute, None)
        _managed_window_scheduler(self.root).dispose(window)
        self.message_editor_window = None
        self.message_editor_selector = None
        self.message_editor_title_var = None
        self.message_editor_title_entry = None
        self.message_editor_text = None
        self.message_editor_card_body = None
        self.message_editor_entries_canvas = None
        self.message_editor_entries_frame = None
        self.message_editor_entries_window_id = None
        self.message_editor_entry_widgets = {}
        self.message_editor_expand_button = None
        self.message_editor_add_button = None
        self.message_editor_delete_button = None
        self.message_editor_edit_button = None
        self.message_editor_redo_button = None
        self.message_editor_undo_button = None
        self._message_editor_selector_ids = []
        self._message_editor_editing = False
        self._message_editor_scrollregion_signature = None
        self._message_editor_entries_width = 0
        self._message_editor_selector_signature = None
        self._cancel_launcher_tile_follow_if_idle()

    def _show_message_editor(self) -> None:
        existing = getattr(self, "message_editor_window", None)
        if existing is not None:
            try:
                if bool(existing.winfo_exists()):
                    _restore_managed_window_foreground(existing, self.root, activate=True)
                    return
            except self.tk.TclError:
                pass

        document = _normalize_message_editor_snapshot(self.message_editor_state.get("document"))
        self._message_editor_expanded = True
        self._message_editor_selected_id = str(document.get("selected_id", "") or "")
        self._message_editor_editing = False
        window = _create_managed_toplevel(self.root)
        self.message_editor_window = window
        setattr(window, "_pc_rehd_stack_layer", MANAGED_WINDOW_PERSISTENT_LAYER)
        _managed_window_scheduler(self.root).observe_geometry(
            window, self._snap_message_editor
        )
        self.message_editor_title_var = None
        self._message_editor_last_saved_document = copy.deepcopy(document)
        window.title(self._tr("消息编辑", "Message Editor"))
        window.configure(background=self.colors["bg"])
        window.protocol("WM_DELETE_WINDOW", self._close_message_editor)
        window.bind("<Escape>", lambda _event: self._close_message_editor())
        window.rowconfigure(0, weight=1)
        window.columnconfigure(0, weight=1)

        body = self.ttk.Frame(window, style="Panel.TFrame", padding=(10, 10, 10, 10))
        body.grid(row=0, column=0, sticky="nsew")
        body.rowconfigure(0, weight=1)
        body.columnconfigure(0, weight=1)
        card = self.ttk.LabelFrame(
            body,
            text=self._tr("持久消息", "Persistent Message"),
            style="V4.TLabelframe",
            padding=(8, 7),
        )
        card.grid(row=0, column=0, sticky="nsew")
        card.rowconfigure(1, weight=1)
        card.columnconfigure(0, weight=1)
        message_actions = self.ttk.Frame(card, style="Panel.TFrame")
        message_actions.grid(row=0, column=0, sticky="ew")
        message_actions.columnconfigure((0, 1, 2), weight=1, uniform="message_actions")
        self.message_editor_add_button = self.ttk.Button(
            message_actions,
            text=self._tr("新增", "Add"),
            command=self._add_message_editor_entry,
        )
        self.message_editor_add_button.grid(row=0, column=0, sticky="ew", padx=(0, 4))
        self.message_editor_delete_button = self.ttk.Button(
            message_actions,
            text=self._tr("删除", "Delete"),
            command=self._delete_message_editor_entry,
        )
        self.message_editor_delete_button.grid(row=0, column=1, sticky="ew", padx=4)
        self.message_editor_edit_button = self.ttk.Button(
            message_actions,
            text=self._tr("编辑", "Edit"),
            command=self._toggle_message_editor_editing,
            style="Accent.TButton",
        )
        self.message_editor_edit_button.grid(row=0, column=2, sticky="ew", padx=(4, 0))

        card_body = self.ttk.Frame(card, style="Panel.TFrame")
        self.message_editor_card_body = card_body
        card_body.grid(row=1, column=0, sticky="nsew", pady=(8, 0))
        card_body.rowconfigure(0, weight=1)
        card_body.columnconfigure(0, weight=1)
        card_body.columnconfigure(1, weight=0)
        entries_canvas = self.tk.Canvas(
            card_body,
            background=self.colors["panel"],
            relief="flat",
            borderwidth=0,
            highlightthickness=0,
        )
        entries_scrollbar = self.ttk.Scrollbar(
            card_body,
            orient="vertical",
            command=_managed_scroll_command(self.root, entries_canvas, "y"),
            style="App.Vertical.TScrollbar",
        )
        entries_canvas.configure(yscrollcommand=entries_scrollbar.set)
        entries_canvas.grid(row=0, column=0, sticky="nsew")
        entries_scrollbar.grid(row=0, column=1, sticky="ns", padx=(5, 0))
        entries_frame = self.ttk.Frame(entries_canvas, style="Panel.TFrame")
        entries_frame.columnconfigure(0, weight=1)
        entries_window_id = entries_canvas.create_window(
            (0, 0), window=entries_frame, anchor="nw"
        )
        self.message_editor_entries_canvas = entries_canvas
        self.message_editor_entries_frame = entries_frame
        self.message_editor_entries_window_id = entries_window_id

        def fit_entries_width(event: Any) -> None:
            try:
                target_width = max(1, int(event.width))
                if target_width == self._message_editor_entries_width:
                    return
                self._message_editor_entries_width = target_width
                entries_canvas.itemconfigure(entries_window_id, width=target_width)
                self._schedule_message_editor_text_fit(all_widgets=True)
            except self.tk.TclError:
                pass

        def refresh_entries_scrollregion(_event: Any = None) -> None:
            self._refresh_message_editor_scrollregion()

        entries_canvas.bind("<Configure>", fit_entries_width, add="+")
        entries_canvas.bind("<MouseWheel>", self._scroll_message_editor_entries, add="+")
        entries_frame.bind("<Configure>", refresh_entries_scrollregion, add="+")
        self.ttk.Label(
            card_body,
            text=self._tr("内容自动保存，保留最近 3 个编辑版本。", "Auto-saved with the latest 3 edit versions."),
            style="Muted.TLabel",
            wraplength=245,
        ).grid(row=1, column=0, columnspan=2, sticky="w", pady=(7, 0))
        history_actions = self.ttk.Frame(card_body, style="Panel.TFrame")
        history_actions.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(5, 0))
        history_actions.columnconfigure(
            (0, 1), weight=1, uniform="message_history_actions"
        )
        self.message_editor_undo_button = self.ttk.Button(
            history_actions,
            text=self._tr("撤销改动 (0/3)", "Undo Changes (0/3)"),
            command=self._undo_message_editor_history,
        )
        self.message_editor_redo_button = self.ttk.Button(
            history_actions,
            text=self._tr("恢复改动 (0/3)", "Redo Changes (0/3)"),
            command=self._redo_message_editor_history,
        )
        self.message_editor_redo_button.grid(
            row=0, column=0, sticky="ew", padx=(0, 3)
        )
        self.message_editor_undo_button.grid(
            row=0, column=1, sticky="ew", padx=(3, 0)
        )
        self._render_message_editor_entries(document)
        self._apply_message_editor_edit_state()
        self._update_message_editor_history_buttons()

        window.update_idletasks()
        screen_width = max(640, int(window.winfo_screenwidth()))
        screen_height = max(480, int(window.winfo_screenheight()))
        side = self._message_editor_dock_side
        width, height = self._message_editor_tile_size(
            side, expanded=bool(self._message_editor_expanded)
        )
        if side in {"top", "bottom", "left", "right"}:
            x, y = self._message_editor_dock_position(
                side, width, height, offset=int(self._message_editor_dock_offset)
            )
        else:
            root_x = int(self.root.winfo_rootx())
            root_y = int(self.root.winfo_rooty())
            root_width = max(1, int(self.root.winfo_width()))
            root_height = max(1, int(self.root.winfo_height()))
            spaces = {
                "right": screen_width
                - (root_x + root_width + LAUNCHER_TILE_DOCK_GAP),
                "left": root_x - LAUNCHER_TILE_DOCK_GAP,
                "bottom": screen_height
                - (root_y + root_height + LAUNCHER_TILE_DOCK_GAP),
                "top": root_y - LAUNCHER_TILE_DOCK_GAP,
            }
            required = {"right": width, "left": width, "bottom": height, "top": height}
            preferred_sides = (
                ("right", "left", "bottom", "top")
                if bool(self.advanced_visible_var.get())
                else ("bottom", "top", "right", "left")
            )
            side = next(
                (
                    candidate
                    for candidate in preferred_sides
                    if spaces[candidate] >= required[candidate]
                ),
                max(spaces, key=lambda candidate: spaces[candidate] / max(1, required[candidate])),
            )
            self._message_editor_dock_side = side
            width, height = self._message_editor_tile_size(
                side, expanded=bool(self._message_editor_expanded)
            )
            self._message_editor_dock_offset = (
                (root_height - height) // 2 if side in {"left", "right"}
                else (root_width - width) // 2
            )
            x, y = self._message_editor_dock_position(
                side, width, height, offset=int(self._message_editor_dock_offset)
            )
        self._message_editor_repositioning = True
        window.minsize(260, 108)
        window.maxsize(screen_width, screen_height)
        self._mark_launcher_tile_programmatic_geometry(
            window, (width, height, x, y)
        )
        _set_themed_window_geometry(
            window,
            f"{width}x{height}+{x}+{y}",
            dark=bool(self._theme_dark),
        )
        window.update_idletasks()
        self._fit_message_editor_text_widgets_now(all_widgets=True)
        self._refresh_message_editor_scrollregion()
        self._message_editor_repositioning = False
        _show_managed_toplevel(window, self.root, activate=True)
        self._persist_message_editor_state(visible=True)

    def _set_scene_normals_monitor_state(
        self,
        state: str,
        *,
        selected_mesh_count: int = 0,
        normal_count: int = 0,
        scene_mesh_count: int = 0,
        scene_mesh_with_normals_count: int = 0,
        scene_normal_count: int = 0,
    ) -> None:
        overall_var = getattr(self, "scene_normals_overall_var", None)
        count_var = getattr(self, "scene_normals_count_var", None)
        all_overall_var = getattr(self, "scene_normals_all_overall_var", None)
        all_count_var = getattr(self, "scene_normals_all_count_var", None)
        if any(value is None for value in (overall_var, count_var, all_overall_var, all_count_var)):
            return
        if state == "no_max":
            overall = self._tr("选中 Mesh：未连接 Max", "Selected Mesh: No Max connected")
            count = self._tr("选中显式法线数量：--", "Selected explicit normal count: --")
            all_overall = self._tr("全部 Mesh：未连接 Max", "All Meshes: No Max connected")
            all_count = self._tr("全部显式法线数量：--", "All explicit normal count: --")
        elif state == "loading":
            overall = self._tr("选中 Mesh：正在读取 Max", "Selected Mesh: Reading Max")
            count = self._tr("选中显式法线数量：读取中…", "Selected explicit normal count: Reading…")
            all_overall = self._tr("全部 Mesh：正在读取 Max", "All Meshes: Reading Max")
            all_count = self._tr("全部显式法线数量：读取中…", "All explicit normal count: Reading…")
        elif state == "unavailable":
            overall = self._tr("选中 Mesh：暂时无法读取", "Selected Mesh: Temporarily unavailable")
            count = self._tr("选中显式法线数量：--", "Selected explicit normal count: --")
            all_overall = self._tr("全部 Mesh：暂时无法读取", "All Meshes: Temporarily unavailable")
            all_count = self._tr("全部显式法线数量：--", "All explicit normal count: --")
        else:
            selected_mesh_count = max(0, int(selected_mesh_count))
            scene_mesh_count = max(0, int(scene_mesh_count))
            scene_mesh_with_normals_count = max(0, int(scene_mesh_with_normals_count))
            if selected_mesh_count <= 0:
                overall = self._tr(
                    "选中 Mesh：未选择",
                    "Selected Mesh: None selected",
                )
            else:
                selected_present = int(normal_count) > 0
                overall = self._tr(
                    f"选中 Mesh：{'有显式法线' if selected_present else '无显式法线'}（{selected_mesh_count}）",
                    f"Selected Mesh: {'Has explicit normals' if selected_present else 'No explicit normals'} ({selected_mesh_count})",
                )
            count = self._tr(
                f"选中显式法线数量：{max(0, int(normal_count)):,}",
                f"Selected explicit normal count: {max(0, int(normal_count)):,}",
            )
            if scene_mesh_count <= 0:
                all_overall = self._tr(
                    "全部 Mesh：场景中没有 Mesh",
                    "All Meshes: No Mesh in scene",
                )
            else:
                all_present = int(scene_normal_count) > 0
                all_overall = self._tr(
                    f"全部 Mesh：{'有显式法线' if all_present else '无显式法线'}（{scene_mesh_with_normals_count}/{scene_mesh_count}）",
                    f"All Meshes: {'Have explicit normals' if all_present else 'No explicit normals'} ({scene_mesh_with_normals_count}/{scene_mesh_count})",
                )
            all_count = self._tr(
                f"全部显式法线数量：{max(0, int(scene_normal_count)):,}",
                f"All explicit normal count: {max(0, int(scene_normal_count)):,}",
            )
        for variable, value in (
            (overall_var, overall),
            (count_var, count),
            (all_overall_var, all_overall),
            (all_count_var, all_count),
        ):
            if str(variable.get()) != value:
                variable.set(value)

    def _scene_normals_dock_position(
        self,
        side: str,
        width: int,
        height: int,
        *,
        offset: int | None = None,
    ) -> tuple[int, int]:
        root_x = int(self.root.winfo_rootx())
        root_y = int(self.root.winfo_rooty())
        root_width = max(1, int(self.root.winfo_width()))
        root_height = max(1, int(self.root.winfo_height()))
        virtual_x, virtual_y, virtual_width, virtual_height = (
            self._toolbox_virtual_desktop_bounds(self.root)
        )
        gap = LAUNCHER_TILE_DOCK_GAP
        if side in {"left", "right"}:
            along = (root_height - height) // 2 if offset is None else int(offset)
            x = root_x - width - gap if side == "left" else root_x + root_width + gap
            y = root_y + along
        else:
            along = (root_width - width) // 2 if offset is None else int(offset)
            x = root_x + along
            y = root_y - height - gap if side == "top" else root_y + root_height + gap
        return (
            min(
                max(virtual_x, x),
                max(virtual_x, virtual_x + virtual_width - width),
            ),
            min(
                max(virtual_y, y),
                max(virtual_y, virtual_y + virtual_height - height),
            ),
        )

    def _scene_normals_monitor_is_open(self) -> bool:
        window = getattr(self, "scene_normals_window", None)
        if window is None:
            return False
        try:
            return bool(window.winfo_exists())
        except self.tk.TclError:
            return False

    def _persist_scene_normals_monitor_visibility(self, visible: bool) -> None:
        desired = bool(visible)
        if bool(self.launcher_state.get("scene_normals_visible", False)) == desired:
            return
        self.launcher_state["scene_normals_visible"] = desired
        self._queue_launcher_state_write()

    def _persist_scene_normals_monitor_placement(
        self,
        geometry: str,
        side: str | None,
        offset: int,
    ) -> None:
        normalized_geometry = str(geometry or "").strip()
        if TK_WINDOW_GEOMETRY_RE.fullmatch(normalized_geometry) is None:
            normalized_geometry = ""
        normalized_side = str(side or "").strip().casefold()
        if normalized_side not in {"top", "bottom", "left", "right"}:
            normalized_side = ""
            offset = 0
        normalized_offset = int(offset)
        changed = False
        for key, value in (
            ("scene_normals_geometry", normalized_geometry),
            ("scene_normals_dock_side", normalized_side),
            ("scene_normals_dock_offset", normalized_offset),
        ):
            if self.launcher_state.get(key) != value:
                self.launcher_state[key] = value
                changed = True
        if changed:
            self._queue_launcher_state_write()

    def _capture_scene_normals_monitor_geometry(
        self,
        window: Any,
        *,
        reconcile_dock: bool = True,
    ) -> str:
        try:
            if not bool(window.winfo_exists()):
                return ""
            window.update_idletasks()
            width = max(1, int(window.winfo_width()))
            height = max(1, int(window.winfo_height()))
            x = int(window.winfo_x())
            y = int(window.winfo_y())
        except (self.tk.TclError, TypeError, ValueError):
            return ""
        if width <= 1 or height <= 1:
            return ""

        side = self._scene_normals_monitor_dock_side
        offset = int(self._scene_normals_monitor_dock_offset)
        if reconcile_dock:
            try:
                root_is_normal = str(self.root.state()).casefold() == "normal"
            except self.tk.TclError:
                root_is_normal = False
            if root_is_normal:
                candidate = self._launcher_tile_dock_candidate(window)
                if candidate is not None:
                    side, offset = candidate
                elif side in {"top", "bottom", "left", "right"}:
                    expected = self._scene_normals_dock_position(
                        side,
                        width,
                        height,
                        offset=offset,
                    )
                    if (x, y) != expected:
                        side, offset = None, 0
                else:
                    side, offset = None, 0
        self._scene_normals_monitor_dock_side = side
        self._scene_normals_monitor_dock_offset = offset
        geometry = f"{width}x{height}{x:+d}{y:+d}"
        self._persist_scene_normals_monitor_placement(geometry, side, offset)
        return geometry

    def _restore_scene_normals_monitor_position(
        self,
        window: Any,
        width: int,
        height: int,
    ) -> tuple[int, int] | None:
        side = self._scene_normals_monitor_dock_side
        if side in {"top", "bottom", "left", "right"}:
            return self._scene_normals_dock_position(
                side,
                width,
                height,
                offset=int(self._scene_normals_monitor_dock_offset),
            )
        saved_geometry = str(
            self.launcher_state.get("scene_normals_geometry", "") or ""
        ).strip()
        match = TK_WINDOW_GEOMETRY_RE.fullmatch(saved_geometry)
        if match is None:
            return None
        virtual_x, virtual_y, virtual_width, virtual_height = (
            self._toolbox_virtual_desktop_bounds(window)
        )
        x = min(
            max(virtual_x, int(match.group("x"))),
            max(virtual_x, virtual_x + virtual_width - width),
        )
        y = min(
            max(virtual_y, int(match.group("y"))),
            max(virtual_y, virtual_y + virtual_height - height),
        )
        return x, y

    def _position_scene_normals_monitor(self) -> None:
        window = getattr(self, "scene_normals_window", None)
        side = getattr(self, "_scene_normals_monitor_dock_side", None)
        if window is None or side not in {"top", "bottom", "left", "right"}:
            return
        try:
            if not bool(window.winfo_exists()) or str(self.root.state()).casefold() != "normal":
                return
            width = max(1, int(window.winfo_width() or window.winfo_reqwidth()))
            height = max(1, int(window.winfo_height() or window.winfo_reqheight()))
            x, y = self._scene_normals_dock_position(
                side,
                width,
                height,
                offset=int(self._scene_normals_monitor_dock_offset),
            )
            self._scene_normals_monitor_repositioning = True
            current = (
                int(window.winfo_width()),
                int(window.winfo_height()),
                int(window.winfo_x()),
                int(window.winfo_y()),
            )
            target = (width, height, x, y)
            if current != target:
                self._mark_launcher_tile_programmatic_geometry(window, target)
                _set_themed_window_geometry(
                    window,
                    f"{width}x{height}+{x}+{y}",
                    dark=bool(self._theme_dark),
                )
        except self.tk.TclError:
            return
        finally:
            self._scene_normals_monitor_repositioning = False

    def _snap_scene_normals_monitor(self, window: Any) -> None:
        if window is not getattr(self, "scene_normals_window", None):
            return
        try:
            if not bool(window.winfo_exists()) or str(self.root.state()).casefold() != "normal":
                return
        except self.tk.TclError:
            return

        if self._launcher_tile_configure_is_programmatic(window):
            return

        previous_side = self._scene_normals_monitor_dock_side
        if previous_side in {"top", "bottom", "left", "right"}:
            try:
                width = max(1, int(window.winfo_width() or window.winfo_reqwidth()))
                height = max(1, int(window.winfo_height() or window.winfo_reqheight()))
                expected_x, expected_y = self._scene_normals_dock_position(
                    previous_side,
                    width,
                    height,
                    offset=int(self._scene_normals_monitor_dock_offset),
                )
                if (int(window.winfo_x()), int(window.winfo_y())) == (
                    expected_x,
                    expected_y,
                ):
                    self._capture_scene_normals_monitor_geometry(
                        window, reconcile_dock=False
                    )
                    return
            except self.tk.TclError:
                return

        candidate = self._launcher_tile_dock_candidate(window)
        if candidate is None:
            self._scene_normals_monitor_dock_side = None
            self._scene_normals_monitor_dock_offset = 0
            self._capture_scene_normals_monitor_geometry(
                window, reconcile_dock=False
            )
            return
        (
            self._scene_normals_monitor_dock_side,
            self._scene_normals_monitor_dock_offset,
        ) = candidate
        self._position_scene_normals_monitor()
        self._capture_scene_normals_monitor_geometry(
            window, reconcile_dock=False
        )

    def _close_scene_normals_monitor(self, *, remember_closed: bool = True) -> None:
        self._scene_normals_monitor_generation += 1
        self._scene_normals_probe_at = 0.0
        window = getattr(self, "scene_normals_window", None)
        if window is not None:
            _managed_window_scheduler(self.root).forget_geometry(window)
            self._capture_scene_normals_monitor_geometry(window)
        if remember_closed:
            self._persist_scene_normals_monitor_visibility(False)
        self.scene_normals_window = None
        self.scene_normals_overall_var = None
        self.scene_normals_count_var = None
        self.scene_normals_all_overall_var = None
        self.scene_normals_all_count_var = None
        self._cancel_launcher_tile_follow_if_idle()
        if window is not None:
            try:
                if bool(window.winfo_exists()):
                    window.destroy()
            except self.tk.TclError:
                pass

    def _show_scene_normals_monitor(self) -> None:
        existing = getattr(self, "scene_normals_window", None)
        if existing is not None:
            try:
                if bool(existing.winfo_exists()):
                    self._scene_normals_probe_at = 0.0
                    self._persist_scene_normals_monitor_visibility(True)
                    _restore_managed_window_foreground(existing, self.root, activate=True)
                    return
            except self.tk.TclError:
                pass

        self._scene_normals_monitor_generation += 1
        window = _create_managed_toplevel(self.root)
        self.scene_normals_window = window
        setattr(window, "_pc_rehd_stack_layer", MANAGED_WINDOW_PERSISTENT_LAYER)
        _managed_window_scheduler(self.root).observe_geometry(
            window, self._snap_scene_normals_monitor
        )
        self.scene_normals_overall_var = self.tk.StringVar(master=window)
        self.scene_normals_count_var = self.tk.StringVar(master=window)
        self.scene_normals_all_overall_var = self.tk.StringVar(master=window)
        self.scene_normals_all_count_var = self.tk.StringVar(master=window)
        window.title(self._tr("显示场景法线", "Show Scene Normals"))
        window.configure(background=self.colors["bg"])
        window.resizable(False, False)
        window.protocol("WM_DELETE_WINDOW", self._close_scene_normals_monitor)
        window.bind("<Escape>", lambda _event: self._close_scene_normals_monitor())
        body = self.ttk.Frame(window, style="Panel.TFrame", padding=(18, 14, 18, 14))
        body.grid(row=0, column=0, sticky="nsew")
        body.columnconfigure(0, weight=1)
        self.ttk.Label(
            body,
            textvariable=self.scene_normals_overall_var,
            style="DialogTitle.TLabel",
        ).grid(row=0, column=0, sticky="w")
        self.ttk.Label(
            body,
            textvariable=self.scene_normals_count_var,
            style="Panel.TLabel",
        ).grid(row=1, column=0, sticky="w", pady=(10, 0))
        self.ttk.Label(
            body,
            textvariable=self.scene_normals_all_overall_var,
            style="DialogTitle.TLabel",
        ).grid(row=2, column=0, sticky="w", pady=(16, 0))
        self.ttk.Label(
            body,
            textvariable=self.scene_normals_all_count_var,
            style="Panel.TLabel",
        ).grid(row=3, column=0, sticky="w", pady=(10, 0))
        self._set_scene_normals_monitor_state(
            "loading" if self._active_session() is not None else "no_max"
        )

        window.update_idletasks()
        screen_width = max(640, int(window.winfo_screenwidth()))
        screen_height = max(480, int(window.winfo_screenheight()))
        width = min(screen_width - 40, max(260, int(window.winfo_reqwidth())))
        height = min(screen_height - 40, max(96, int(window.winfo_reqheight())))
        root_x = int(self.root.winfo_rootx())
        root_y = int(self.root.winfo_rooty())
        root_width = max(1, int(self.root.winfo_width()))
        root_height = max(1, int(self.root.winfo_height()))
        restored_position = self._restore_scene_normals_monitor_position(
            window, width, height
        )
        if restored_position is None:
            virtual_x, virtual_y, virtual_width, virtual_height = (
                self._toolbox_virtual_desktop_bounds(window)
            )
            spaces = {
                "right": virtual_x + virtual_width
                - (root_x + root_width + LAUNCHER_TILE_DOCK_GAP),
                "left": root_x - virtual_x - LAUNCHER_TILE_DOCK_GAP,
                "bottom": virtual_y + virtual_height
                - (root_y + root_height + LAUNCHER_TILE_DOCK_GAP),
                "top": root_y - virtual_y - LAUNCHER_TILE_DOCK_GAP,
            }
            required = {
                "right": width,
                "left": width,
                "bottom": height,
                "top": height,
            }
            preferred_sides = (
                ("right", "left", "bottom", "top")
                if bool(self.advanced_visible_var.get())
                else ("bottom", "top", "right", "left")
            )
            side = next(
                (
                    candidate
                    for candidate in preferred_sides
                    if spaces[candidate] >= required[candidate]
                ),
                max(
                    spaces,
                    key=lambda candidate: spaces[candidate]
                    / max(1, required[candidate]),
                ),
            )
            self._scene_normals_monitor_dock_side = side
            self._scene_normals_monitor_dock_offset = (
                (root_height - height) // 2
                if side in {"left", "right"}
                else (root_width - width) // 2
            )
            x, y = self._scene_normals_dock_position(
                side,
                width,
                height,
                offset=self._scene_normals_monitor_dock_offset,
            )
        else:
            x, y = restored_position
        self._scene_normals_monitor_repositioning = True
        window.minsize(width, height)
        window.maxsize(width, height)
        self._mark_launcher_tile_programmatic_geometry(
            window, (width, height, x, y)
        )
        _set_themed_window_geometry(
            window,
            f"{width}x{height}+{x}+{y}",
            dark=bool(self._theme_dark),
        )
        self._scene_normals_monitor_repositioning = False
        self._persist_scene_normals_monitor_placement(
            f"{width}x{height}{x:+d}{y:+d}",
            self._scene_normals_monitor_dock_side,
            int(self._scene_normals_monitor_dock_offset),
        )
        _show_managed_toplevel(window, self.root, activate=True)
        self._persist_scene_normals_monitor_visibility(True)
        self._scene_normals_probe_at = 0.0

        generation = self._scene_normals_monitor_generation

        def probe_after_map() -> None:
            if (
                generation == self._scene_normals_monitor_generation
                and self.scene_normals_window is window
            ):
                self._poll_scene_normals(time.monotonic())

        try:
            self.root.after(0, probe_after_map)
        except self.tk.TclError:
            pass

