    def _import_auxiliary(self, kind: str) -> None:
        self._dispatch_operation(
            "auxiliary",
            lambda: self._import_auxiliary_active(kind),
        )

    def _import_auxiliary_active(self, kind: str) -> None:
        session = self._active_session()
        if session is None:
            self._show_error(RuntimeError(self._tr("当前没有活动的 Max。", "No active Max session.")))
            return
        normalized = str(kind).lower()
        if normalized not in {"sbc", "adr", "ems"}:
            self._show_error(ValueError(f"Unsupported auxiliary format: {kind}"))
            return
        labels = {
            "sbc": ("REHD 场景碰撞", "REHD Stage Collision", "*.sbc"),
            "adr": ("REHD 门数据", "REHD Door Data", "*.adr"),
            "ems": ("REHD 敌人生成", "REHD Enemy Spawn", "*.ems"),
        }
        cn, en, pattern = labels[normalized]
        selected = _managed_file_dialog(
            self.root, "askopenfilename", title=self._tr(cn, en),
            filetypes=[(f"{normalized.upper()} File", pattern), ("All files", "*.*")],
        )
        if not selected:
            return
        source = Path(selected).resolve()
        pythonized = bool(self.aux_python_vars[normalized].get())
        session.workspace.auxiliary_python[normalized] = pythonized
        action = f"{normalized}_import"
        generation = self._begin_session_operation(session, action)
        request_token = uuid.uuid4().hex
        self._report_bootstrap_health_operation(
            action,
            "started",
            max_process_id=session.pid,
            request_id=request_token,
            extra={"source": str(source), "pythonized": pythonized},
        )
        log_directory = _resolve_log_directory(
            session.workspace.log_dir or self.log_dir_var.get()
        )
        temporary_fbx = (
            log_directory
            / f"aux_{normalized}_import_pid{session.pid}_{request_token}.fbx"
        )

        def operation() -> tuple[str, dict[str, Any], dict[str, Any]]:
            contract = _parse_auxiliary_file(normalized, source)
            source_sha256 = _sha256_file(source)
            try:
                if pythonized:
                    handoff = _build_auxiliary_import_fbx(normalized, contract, temporary_fbx)
                    request_id, result = self._request_max_scene_interface(
                        session,
                        "auxiliary.import_fbx",
                        {
                            "kind": normalized,
                            "fbx_path": str(temporary_fbx),
                            "source_sha256": source_sha256,
                            "nodes": handoff["nodes"],
                        },
                    )
                else:
                    request_id, result = self._request_max_scene_interface(
                        session,
                        "auxiliary.import_legacy",
                        {"contract": contract, "source_sha256": source_sha256},
                    )
                source_record = {
                    "kind": normalized,
                    "path": str(source),
                    "source_sha256": source_sha256,
                    "record_count": int(contract.get("record_count", 0) or 0),
                    "import_pythonized": pythonized,
                }
                return request_id, result, source_record
            finally:
                temporary_fbx.unlink(missing_ok=True)

        def success(value: tuple[str, dict[str, Any], dict[str, Any]]) -> None:
            if not self._owns_session_operation(session, action, generation):
                self._report_bootstrap_health_operation(
                    action,
                    "cancelled",
                    max_process_id=session.pid,
                    request_id=request_token,
                    detail="A newer operation replaced this auxiliary import callback.",
                )
                return
            request_id, result, source_record = value
            created = int(result.get("created", 0) or 0)
            records = int(result.get("records", 0) or 0)
            if created <= 0:
                raise RuntimeError(f"{normalized.upper()} import returned zero created nodes")
            nodes = [copy.deepcopy(row) for row in result.get("nodes", []) if isinstance(row, dict)]
            if len(nodes) != created or any(int(row.get("handle", 0) or 0) <= 0 for row in nodes):
                raise ProtocolError(f"{normalized.upper()} import returned an incomplete node identity receipt")
            source_record["nodes"] = nodes
            source_record["record_count"] = records
            source_record["carrier"] = str(result.get("carrier", "pymxs_legacy") or "pymxs_legacy")
            session.workspace.auxiliary_sources[normalized] = source_record
            self._report_bootstrap_health_operation(
                action,
                "completed",
                max_process_id=session.pid,
                request_id=request_id,
            )
            route_cn = "Python + FBX（未验证）" if pythonized else "传统 pymxs"
            route_en = "Python + FBX (unverified)" if pythonized else "legacy pymxs"
            detail = self._tr(
                f"{normalized.upper()} 导入完成。\n\n路线: {route_cn}\n读取记录: {records}\n已创建 Max 场景节点: {created}\n源文件: {source}",
                f"{normalized.upper()} import completed.\n\nRoute: {route_en}\nRecords read: {records}\nMax scene nodes created: {created}\nSource file: {source}",
            )
            session.workspace.last_status = self._tr(
                f"{normalized.upper()} | 已创建 {created} 个节点 | 请求 {request_id[:12]}",
                f"{normalized.upper()} | {created} nodes | Request {request_id[:12]}",
            )
            if self._session_is_visible(session):
                self._set_status(session.workspace.last_status, progress=100)
                self._activate_pid(session.pid, force_inspect=True)
                ChoiceDialog(
                    self.root, title=self._tr(f"{normalized.upper()} 导入", f"{normalized.upper()} Import"),
                    message=detail, choices=[(self._tr("关闭", "Close"), "close")],
                ).show()

        def failure(exc: Exception) -> None:
            self._report_bootstrap_health_operation(
                action,
                "failed",
                max_process_id=session.pid,
                request_id=request_token,
                detail=f"{type(exc).__name__}: {exc}",
            )
            self._session_error(session, action, generation, exc, report_health=False)

        try:
            self._run_background(
                operation, success, label=self._tr(f"导入 {normalized.upper()}", f"Importing {normalized.upper()}"),
                on_error=failure,
            )
        except Exception as exc:
            failure(exc)

    def _on_aux_python_changed(self, kind: str) -> None:
        normalized = str(kind).lower()
        if normalized not in self.aux_python_vars:
            return
        enabled = bool(self.aux_python_vars[normalized].get())
        workspace = self._active_workspace()
        if workspace is not None:
            workspace.auxiliary_python[normalized] = enabled
        self._sync_auxiliary_export_button_states()
        self._set_status(
            self._tr(
                f"{normalized.upper()}：{'Python + FBX 未验证路线' if enabled else '传统 pymxs 路线'}",
                f"{normalized.upper()}: {'Python + FBX unverified route' if enabled else 'legacy pymxs route'}",
            ),
            progress=0,
        )

    def _sync_auxiliary_export_button_states(
        self,
        *,
        active_view_enabled: bool | None = None,
    ) -> None:
        if active_view_enabled is None:
            active_view_enabled = self._active_session() is not None
        for kind, button in getattr(self, "aux_export_buttons", {}).items():
            pythonized = bool(self.aux_python_vars[kind].get())
            desired_state = "normal" if active_view_enabled and pythonized else "disabled"
            try:
                if str(button.cget("state")) != desired_state:
                    button.configure(state=desired_state)
            except self.tk.TclError:
                continue

    def _export_auxiliary(self, kind: str) -> None:
        self._dispatch_operation(
            "auxiliary",
            lambda: self._export_auxiliary_active(kind),
        )

    def _export_auxiliary_active(self, kind: str) -> None:
        session = self._active_session()
        if session is None:
            self._show_error(RuntimeError(self._tr("当前没有活动的 Max。", "No active Max session.")))
            return
        normalized = str(kind).lower()
        if normalized not in self.aux_python_vars:
            self._show_error(ValueError(f"Unsupported auxiliary format: {kind}"))
            return
        if not bool(self.aux_python_vars[normalized].get()):
            self._show_error(
                RuntimeError(
                    self._tr(
                        f"PC-REHD 1.2.8 没有实现 {normalized.upper()} 导出；请勾选“Python化 - 未验证”后使用新版导出。",
                        f"PC-REHD 1.2.8 did not implement {normalized.upper()} export; enable Pythonized - Unverified to use the new exporter.",
                    )
                )
            )
            return
        source_record = copy.deepcopy(session.workspace.auxiliary_sources.get(normalized, {}))
        source_text = str(source_record.get("path", "") or "")
        source = Path(source_text).resolve() if source_text else Path()
        if not source.is_file():
            self._show_error(
                RuntimeError(
                    self._tr(
                        f"当前 Max PID 尚未导入可追踪的 {normalized.upper()} 源文件。",
                        f"This Max PID has no tracked {normalized.upper()} source import.",
                    )
                )
            )
            return
        nodes = [copy.deepcopy(row) for row in source_record.get("nodes", []) if isinstance(row, dict)]
        if not nodes:
            self._show_error(RuntimeError(f"{normalized.upper()} tracked node receipt is empty"))
            return
        pythonized = bool(self.aux_python_vars[normalized].get())
        session.workspace.auxiliary_python[normalized] = pythonized
        default_name = f"{source.stem}.New{source.suffix.lower()}"
        selected = _managed_file_dialog(
            self.root,
            "asksaveasfilename",
            title=self._tr(f"导出 {normalized.upper()}", f"Export {normalized.upper()}"),
            initialdir=str(source.parent),
            initialfile=default_name,
            defaultextension=f".{normalized}",
            filetypes=[(f"{normalized.upper()} File", f"*.{normalized}"), ("All files", "*.*")],
        )
        if not selected:
            self._set_status(self._tr("导出已取消", "Export cancelled"), progress=0)
            return
        output = Path(selected).resolve()
        if output.suffix.casefold() != f".{normalized}":
            output = output.with_suffix(f".{normalized}")
        action = f"{normalized}_export"
        generation = self._begin_session_operation(session, action)
        request_token = uuid.uuid4().hex
        self._report_bootstrap_health_operation(
            action,
            "started",
            max_process_id=session.pid,
            request_id=request_token,
            extra={"source": str(source), "output": str(output), "pythonized": pythonized},
        )
        log_directory = _resolve_log_directory(
            session.workspace.log_dir or self.log_dir_var.get()
        )
        temporary_fbx = (
            log_directory
            / f"aux_{normalized}_export_pid{session.pid}_{request_token}.fbx"
        )

        def operation() -> tuple[str, dict[str, Any], dict[str, Any]]:
            try:
                request_id, scene_result = self._request_max_scene_interface(
                    session,
                    "auxiliary.export",
                    {
                        "kind": normalized,
                        "source_sha256": str(source_record.get("source_sha256", "") or ""),
                        "pythonized": pythonized,
                        "nodes": nodes,
                        "fbx_path": str(temporary_fbx) if pythonized else "",
                        "correlation_id": request_token,
                    },
                )
                scene_status = str(scene_result.get("status", "") or "")
                if scene_status == "AUX_FAILED":
                    receipt = _normalize_aux_operation_receipt(
                        scene_result.get("failure_receipt"),
                        expected_correlation_id=request_token,
                    )
                    self._record_operation_diagnostic(
                        "auxiliary",
                        receipt=receipt,
                        detail=str(receipt.get("detail", "") or ""),
                    )
                    raise OperationDomainError(
                        f"{receipt.get('status_code', 'AUX_FAILED')}: "
                        f"{receipt.get('detail', 'Auxiliary geometry operation failed')}",
                        receipt,
                    )
                if scene_status != "ok":
                    raise ProtocolError(
                        f"{normalized.upper()} export returned an invalid operation status"
                    )
                if str(scene_result.get("correlation_id", "") or "") != request_token:
                    raise ProtocolError(
                        f"{normalized.upper()} export correlation ID mismatch"
                    )
                auxiliary_receipts = [
                    _normalize_aux_operation_receipt(
                        receipt,
                        expected_correlation_id=request_token,
                    )
                    for receipt in scene_result.get("auxiliary_receipts", [])
                    if isinstance(receipt, dict)
                ]
                expected_auxiliary_receipts = (
                    0
                    if pythonized
                    else sum(
                        1
                        for row in nodes
                        if role_needs_geometry(
                            normalized,
                            str(row.get("role", "") or ""),
                        )
                    )
                )
                if len(auxiliary_receipts) != expected_auxiliary_receipts:
                    raise ProtocolError(
                        f"{normalized.upper()} export returned the wrong AUX receipt count"
                    )
                live_rows = [copy.deepcopy(row) for row in scene_result.get("nodes", []) if isinstance(row, dict)]
                if len(live_rows) != len(nodes):
                    raise ProtocolError(
                        f"{normalized.upper()} export node receipt mismatch: {len(live_rows)} != {len(nodes)}"
                    )
                if pythonized:
                    fbx_receipt = dict(scene_result.get("fbx_receipt", {}))
                    fbx_path = Path(str(fbx_receipt.get("path", "") or temporary_fbx)).resolve()
                    if not fbx_path.is_file():
                        raise RuntimeError(f"{normalized.upper()} Max FBX handoff is missing")
                    geometry_by_name = _read_auxiliary_fbx_geometry(fbx_path)
                    for row in live_rows:
                        if not role_needs_geometry(normalized, str(row.get("role", "") or "")):
                            continue
                        geometry = geometry_by_name.get(str(row.get("name", "") or "").casefold())
                        if geometry is None:
                            raise RuntimeError(
                                f"{normalized.upper()} FBX is missing tracked geometry: {row.get('name', '<unnamed>')}"
                            )
                        row["geometry"] = geometry
                write_result = _atomic_write_auxiliary(
                    normalized,
                    source,
                    output,
                    str(source_record.get("source_sha256", "") or ""),
                    live_rows,
                )
                return request_id, scene_result, write_result
            finally:
                temporary_fbx.unlink(missing_ok=True)

        def success(value: tuple[str, dict[str, Any], dict[str, Any]]) -> None:
            if not self._owns_session_operation(session, action, generation):
                self._report_bootstrap_health_operation(
                    action,
                    "cancelled",
                    max_process_id=session.pid,
                    request_id=request_token,
                    detail="A newer operation replaced this auxiliary export callback.",
                )
                return
            request_id, _scene_result, write_result = value
            changed = int(write_result.get("changed_records", 0) or 0)
            topology_rebuilt = bool(write_result.get("topology_rebuilt", False))
            route_cn = "Python + FBX（未验证）" if pythonized else "传统 pymxs"
            route_en = "Python + FBX (unverified)" if pythonized else "legacy pymxs"
            session.workspace.last_status = self._tr(
                f"{normalized.upper()} 导出完成 | 变更 {changed} | 请求 {request_id[:12]}",
                f"{normalized.upper()} export complete | Changed {changed} | Request {request_id[:12]}",
            )
            self._report_bootstrap_health_operation(
                action,
                "completed",
                max_process_id=session.pid,
                request_id=request_id,
            )
            if not self._session_is_visible(session):
                return
            self._set_status(session.workspace.last_status, progress=100)
            topology_cn = "\nSBC 拓扑已按实验规则重建；请在游戏中验证。" if topology_rebuilt else ""
            topology_en = "\nSBC topology was rebuilt by the experimental rule; validate it in game." if topology_rebuilt else ""
            ChoiceDialog(
                self.root,
                title=self._tr(f"{normalized.upper()} 导出完成", f"{normalized.upper()} Export Complete"),
                message=self._tr(
                    f"{normalized.upper()} 已写出并通过回读验证。\n\n路线: {route_cn}\n变更记录: {changed}\n输出: {write_result['path']}\nSHA-256: {write_result['output_sha256']}{topology_cn}",
                    f"{normalized.upper()} was written and passed readback verification.\n\nRoute: {route_en}\nChanged records: {changed}\nOutput: {write_result['path']}\nSHA-256: {write_result['output_sha256']}{topology_en}",
                ),
                choices=[(self._tr("确定", "OK"), "ok")],
            ).show()

        def failure(exc: Exception) -> None:
            self._report_bootstrap_health_operation(
                action,
                "failed",
                max_process_id=session.pid,
                request_id=request_token,
                detail=f"{type(exc).__name__}: {exc}",
            )
            self._session_error(session, action, generation, exc, report_health=False)

        try:
            self._run_background(
                operation,
                success,
                label=self._tr(f"导出 {normalized.upper()}", f"Exporting {normalized.upper()}"),
                on_error=failure,
            )
        except Exception as exc:
            failure(exc)

    def _backend_sbc_import(self) -> None:
        """Run the live V4 SBC import route against the active Max PID."""
        self._import_auxiliary("sbc")

    def _backend_adr_import(self) -> None:
        """Run the live V4 ADR import route against the active Max PID."""
        self._import_auxiliary("adr")

    def _backend_ems_import(self) -> None:
        """Run the live V4 EMS import route against the active Max PID."""
        self._import_auxiliary("ems")

    def _record_manual_texture_path(self, path: Path | str) -> Path | None:
        normalized = _normalize_manual_texture_path(path)
        if not normalized:
            return None
        resolved = Path(normalized)
        texture_format = resolved.suffix.casefold().lstrip(".")
        last_paths = dict(
            self.launcher_state.get("manual_texture_last_paths", {})
        )
        last_paths[texture_format] = normalized
        history = _normalize_manual_texture_path_history(
            [
                normalized,
                *self.launcher_state.get("manual_texture_path_history", []),
            ]
        )
        self.launcher_state["manual_texture_last_paths"] = last_paths
        self.launcher_state["manual_texture_path_history"] = history
        self._queue_launcher_state_write()
        return resolved

    def _record_mrl_path(self, path: Path | str) -> Path | None:
        normalized = _normalize_mrl_path(path)
        if not normalized:
            return None
        resolved = Path(normalized)
        history = _normalize_mrl_path_history(
            [
                normalized,
                *self.launcher_state.get("mrl_path_history", []),
            ]
        )
        self.launcher_state["mrl_last_path"] = normalized
        self.launcher_state["mrl_path_history"] = history
        self._queue_launcher_state_write()
        return resolved

    def _manual_texture_initial_directory(self, texture_format: str) -> str:
        normalized_format = str(texture_format or "").strip().casefold()
        last_paths = self.launcher_state.get("manual_texture_last_paths", {})
        candidates: list[str] = []
        if isinstance(last_paths, dict):
            candidates.append(str(last_paths.get(normalized_format, "") or ""))
        candidates.extend(
            path
            for path in _normalize_manual_texture_path_history(
                self.launcher_state.get("manual_texture_path_history", [])
            )
            if Path(path).suffix.casefold() == f".{normalized_format}"
        )
        for candidate in candidates:
            normalized = _normalize_manual_texture_path(
                candidate,
                expected_format=normalized_format,
            )
            if not normalized:
                continue
            parent = Path(normalized).parent
            if parent.is_dir():
                return str(parent)

        workspace = self._active_workspace()
        source_text = (
            str(workspace.source_mod or "").strip()
            if workspace is not None
            else ""
        )
        if source_text:
            source_path = Path(source_text).expanduser()
            if source_path.is_file() or source_path.parent.is_dir():
                return str(source_path.parent.resolve(strict=False))
        return ""

    def _close_manual_texture_path_history(self) -> None:
        window = self.manual_texture_history_window
        self.manual_texture_history_window = None
        self.manual_texture_history_tree = None
        self.manual_texture_history_status_var = None
        self._manual_texture_history_rows = []
        if window is None:
            return
        try:
            window.grab_release()
        except self.tk.TclError:
            pass
        try:
            if bool(window.winfo_exists()):
                window.destroy()
        except self.tk.TclError:
            pass

    def _use_selected_manual_texture_history(self, _event: Any = None) -> str:
        tree = self.manual_texture_history_tree
        status = self.manual_texture_history_status_var
        if tree is None:
            return "break"
        try:
            selected = tuple(tree.selection())
        except self.tk.TclError:
            return "break"
        if not selected:
            if status is not None:
                status.set(self._tr("请先选择一个历史路径", "Select a history path first"))
            return "break"
        try:
            index = int(selected[0])
            path_text = self._manual_texture_history_rows[index]
        except (IndexError, TypeError, ValueError):
            return "break"
        path = Path(path_text)
        if not path.is_file():
            if status is not None:
                status.set(
                    self._tr(
                        "该历史文件已不存在，请选择其他路径",
                        "This history file no longer exists; choose another path",
                    )
                )
            return "break"
        texture_format = path.suffix.casefold().lstrip(".")
        if texture_format not in {"dds", "tex"}:
            return "break"

        self._manual_texture_pending_path = path
        self._close_manual_texture_path_history()

        def invoke() -> None:
            try:
                if self.blender_mode_enabled:
                    self._backend_blender_manual_texture(texture_format)
                else:
                    self._backend_manual_texture(texture_format)
            finally:
                if self._manual_texture_pending_path == path:
                    self._manual_texture_pending_path = None

        try:
            self.root.after_idle(invoke)
        except self.tk.TclError:
            self._manual_texture_pending_path = None
        return "break"

    def _show_manual_texture_path_history(self) -> None:
        existing = self.manual_texture_history_window
        if existing is not None:
            try:
                if bool(existing.winfo_exists()):
                    _restore_managed_window_foreground(
                        existing, self.root, activate=True
                    )
                    return
            except self.tk.TclError:
                pass

        rows = _normalize_manual_texture_path_history(
            self.launcher_state.get("manual_texture_path_history", [])
        )
        self._manual_texture_history_rows = rows
        window = _create_managed_toplevel(self.root)
        self.manual_texture_history_window = window
        setattr(window, "_pc_rehd_stack_layer", MANAGED_WINDOW_DIALOG_LAYER)
        window.title(self._tr("贴图历史路径", "Texture Path History"))
        window.configure(background=self.colors["bg"])
        window.resizable(True, True)
        window.protocol("WM_DELETE_WINDOW", self._close_manual_texture_path_history)
        window.bind(
            "<Escape>",
            lambda _event: self._close_manual_texture_path_history(),
            add="+",
        )
        body = self.ttk.Frame(
            window,
            style="Panel.TFrame",
            padding=(14, 12, 14, 12),
        )
        body.grid(row=0, column=0, sticky="nsew")
        window.rowconfigure(0, weight=1)
        window.columnconfigure(0, weight=1)
        body.rowconfigure(1, weight=1)
        body.columnconfigure(0, weight=1)
        self.ttk.Label(
            body,
            text=self._tr("选择历史路径", "Choose Path History"),
            style="DialogTitle.TLabel",
        ).grid(row=0, column=0, columnspan=2, sticky="w", pady=(0, 8))

        tree = self.ttk.Treeview(
            body,
            columns=("format", "path"),
            show="headings",
            selectmode="browse",
            height=max(4, min(12, len(rows))),
        )
        self.manual_texture_history_tree = tree
        tree.heading("format", text=self._tr("格式", "Format"))
        tree.heading("path", text=self._tr("文件路径", "File Path"))
        tree.column("format", width=76, minwidth=64, stretch=False, anchor="center")
        tree.column("path", width=580, minwidth=260, stretch=True, anchor="w")
        vertical = self.ttk.Scrollbar(
            body,
            orient="vertical",
            command=_managed_scroll_command(window, tree, "y"),
        )
        horizontal = self.ttk.Scrollbar(
            body,
            orient="horizontal",
            command=_managed_scroll_command(window, tree, "x"),
        )
        tree.configure(
            yscrollcommand=vertical.set,
            xscrollcommand=horizontal.set,
        )
        tree.grid(row=1, column=0, sticky="nsew")
        vertical.grid(row=1, column=1, sticky="ns", padx=(6, 0))
        horizontal.grid(row=2, column=0, sticky="ew", pady=(6, 0))
        for index, path_text in enumerate(rows):
            path = Path(path_text)
            tags = () if path.is_file() else ("missing",)
            tree.insert(
                "",
                "end",
                iid=str(index),
                values=(path.suffix.upper().lstrip("."), path_text),
                tags=tags,
            )
        tree.tag_configure("missing", foreground=self.colors["muted"])
        tree.bind(
            "<Double-Button-1>",
            self._use_selected_manual_texture_history,
            add="+",
        )
        tree.bind(
            "<Return>",
            self._use_selected_manual_texture_history,
            add="+",
        )

        self.manual_texture_history_status_var = self.tk.StringVar(
            master=window,
            value=(
                self._tr("双击路径即可使用", "Double-click a path to use it")
                if rows
                else self._tr("暂无历史路径", "No path history yet")
            ),
        )
        self.ttk.Label(
            body,
            textvariable=self.manual_texture_history_status_var,
            style="Muted.TLabel",
        ).grid(row=3, column=0, columnspan=2, sticky="w", pady=(8, 0))
        actions = self.ttk.Frame(body, style="Panel.TFrame")
        actions.grid(row=4, column=0, columnspan=2, sticky="e", pady=(10, 0))
        use_button = self.ttk.Button(
            actions,
            text=self._tr("使用选中路径", "Use Selected Path"),
            command=self._use_selected_manual_texture_history,
            style="Accent.TButton",
            state="normal" if rows else "disabled",
        )
        use_button.grid(row=0, column=0, padx=(0, 8))
        self.ttk.Button(
            actions,
            text=self._tr("关闭", "Close"),
            command=self._close_manual_texture_path_history,
        ).grid(row=0, column=1)

        window.update_idletasks()
        screen_width = max(640, int(window.winfo_screenwidth()))
        screen_height = max(480, int(window.winfo_screenheight()))
        width = min(screen_width - 40, max(640, int(window.winfo_reqwidth())))
        height = min(screen_height - 60, max(300, int(window.winfo_reqheight())))
        x, y = _centered_window_position(
            width, height, screen_width, screen_height
        )
        window.minsize(min(width, 520), min(height, 240))
        window.maxsize(screen_width - 20, screen_height - 20)
        _set_themed_window_geometry(
            window,
            f"{width}x{height}+{x}+{y}",
            dark=bool(self._theme_dark),
        )
        shown = _show_managed_toplevel(window, self.root, activate=True)
        if not shown:
            self._close_manual_texture_path_history()
            return

        def commit_history_interaction() -> None:
            try:
                if not bool(window.winfo_viewable()):
                    return
                window.grab_set()
                if rows:
                    tree.selection_set("0")
                    tree.focus("0")
                    tree.focus_set()
                else:
                    use_button.focus_set()
            except self.tk.TclError:
                pass

        _managed_window_scheduler(self.root).run_after_floating_restore(
            window, commit_history_interaction
        )

    def _prompt_manual_texture_path(self, texture_format: str) -> Path | None:
        normalized = str(texture_format or "").strip().casefold()
        if normalized == "dds":
            title = self._tr("选择 DDS 文件", "Choose DDS File")
            filetypes = [("DDS", "*.dds")]
        elif normalized == "tex":
            title = self._tr("选择 TEX 文件", "Choose TEX File")
            filetypes = [("TEX", "*.tex")]
        else:
            return None
        pending = self._manual_texture_pending_path
        self._manual_texture_pending_path = None
        pending_text = _normalize_manual_texture_path(
            pending,
            expected_format=normalized,
        )
        if pending_text and Path(pending_text).is_file():
            return self._record_manual_texture_path(pending_text)
        options: dict[str, Any] = {"title": title, "filetypes": filetypes}
        initial_directory = self._manual_texture_initial_directory(normalized)
        if initial_directory:
            options["initialdir"] = initial_directory
        chosen = _managed_file_dialog(self.root, "askopenfilename", **options)
        if not chosen:
            return None
        chosen_text = _normalize_manual_texture_path(
            chosen,
            expected_format=normalized,
        )
        if not chosen_text or not Path(chosen_text).is_file():
            return None
        return self._record_manual_texture_path(chosen_text)

    def _backend_manual_texture(self, texture_format: str) -> None:
        session = self._active_session()
        workspace = self._active_workspace()
        if session is None or workspace is None:
            self._show_error(RuntimeError(self._tr("当前没有活动的 Max。", "No active Max session.")))
            return
        selected = self._prompt_manual_texture_path(texture_format)
        if selected is None:
            return
        action = "manual_texture"
        generation = self._begin_session_operation(session, action)
        log_directory = _resolve_log_directory(workspace.log_dir)
        workspace.log_dir = str(log_directory)
        self.log_dir_var.set(str(log_directory))
        decoded_from_tex = selected.suffix.casefold() == ".tex"

        def operation() -> tuple[str, dict[str, Any]]:
            decode_directory: Path | None = None
            try:
                if decoded_from_tex:
                    decode_directory = Path(
                        tempfile.mkdtemp(prefix="manual_tex_decode_", dir=str(log_directory))
                    )
                image_path = _prepare_manual_texture_image(
                    selected,
                    decode_directory or log_directory,
                )
                _plan_request_id, scene_data = self._request_max_scene_interface(
                    session,
                    "manual_texture.selection",
                )
                target_rows = [
                    dict(row)
                    for row in scene_data.get("target_meshes", [])
                    if isinstance(row, dict)
                    and int(
                        _parse_scene_name(str(row.get("name", "") or "")).get(
                            "scene_name_mesh_slot", 0
                        )
                        or 0
                    ) > 0
                ]
                request_id, result = self._request_max_scene_interface(
                    session,
                    "manual_texture.apply",
                    {
                        "image_path": str(image_path),
                        "scene_interface_id": "manual_texture.selection",
                        "scene_snapshot_digest": str(scene_data.get("digest", "") or ""),
                        "node_handles": [int(row["handle"]) for row in target_rows],
                        "node_names": {
                            str(int(row["handle"])): str(row.get("name", "") or "")
                            for row in target_rows
                        },
                    },
                )
            finally:
                if decode_directory is not None:
                    shutil.rmtree(decode_directory, ignore_errors=True)
            result = dict(result)
            result["source_texture_path"] = str(selected)
            result["decoded_from_tex"] = decoded_from_tex
            result["temporary_dds_deleted"] = bool(
                not decoded_from_tex or decode_directory is None or not decode_directory.exists()
            )
            return request_id, result

        def success(value: tuple[str, dict[str, Any]]) -> None:
            if not self._owns_session_operation(session, action, generation):
                return
            request_id, result = value
            applied = int(result.get("applied", 0) or 0)
            skipped = int(result.get("skipped", 0) or 0)
            selected_count = int(result.get("selected", 0) or 0)
            zero_reason = str(result.get("zero_reason", "") or "")
            session.workspace.last_status = self._tr(
                f"手动贴图完成：应用 {applied}，跳过 {skipped}",
                f"Manual texture: applied {applied}, skipped {skipped}",
            )
            if self._session_is_visible(session):
                self._set_status(f"{session.workspace.last_status} | {request_id[:12]}", progress=100)
                detail = self._tr(
                    f"RE6 手动贴图完成。\n\n已应用所选网格: {applied}\n跳过所选节点: {skipped}\n选择节点总数: {selected_count}",
                    f"RE6 Manual Tex done.\n\nApplied selected meshes: {applied}\nSkipped selected nodes: {skipped}\nSelected count: {selected_count}",
                )
                if applied == 0:
                    detail += self._tr(f"\n\n未处理原因: {zero_reason}", f"\n\nNothing was processed: {zero_reason}")
                if bool(result.get("decoded_from_tex", False)):
                    detail += self._tr(
                        "\n\n所选 TEX 已通过 RE6 TEX Decoder 临时解析为 DDS；绑定完成后临时 DDS 已删除。",
                        "\n\nThe selected TEX was decoded temporarily to DDS by RE6 TEX Decoder; the temporary DDS was deleted after binding.",
                    )
                ChoiceDialog(
                    self.root,
                    title=self._tr("RE6 手动贴图", "RE6 Manual Texture"),
                    message=detail,
                    choices=[(self._tr("关闭", "Close"), "close")],
                ).show()

        self._run_background(
            operation, success, label=self._tr("正在应用贴图", "Applying texture"),
            on_error=lambda exc: self._session_error(session, action, generation, exc),
        )

    def _backend_mrl_bind(self) -> None:
        if self.blender_mode_enabled:
            self._backend_blender_mrl_bind()
            return
        session = self._active_session()
        workspace = self._active_workspace()
        if session is None or workspace is None:
            self._show_error(RuntimeError(self._tr("当前没有活动的 Max。", "No active Max session.")))
            return
        source_mod_text = str(
            workspace.source_mod or self.source_mod_var.get() or ""
        ).strip()
        source_mod = Path(source_mod_text) if source_mod_text else Path()
        guessed_mrl = _find_mrl_for_source_mod(source_mod_text)
        remembered_mrl = _normalize_mrl_path(
            self.launcher_state.get("mrl_last_path", "")
        )
        initial_mrl = guessed_mrl or (Path(remembered_mrl) if remembered_mrl else None)
        mrl_history = _normalize_mrl_path_history(
            [
                str(guessed_mrl) if guessed_mrl is not None else "",
                remembered_mrl,
                *self.launcher_state.get("mrl_path_history", []),
            ]
        )
        bind_options = MrlTextureBindDialog(
            self.root,
            translate=self._tr,
            initial_mrl_path=str(initial_mrl) if initial_mrl is not None else "",
            history_paths=mrl_history,
            auto_scan_found=bool(initial_mrl is not None and initial_mrl.is_file()),
            initial_save_decoded_textures=bool(
                self.launcher_state.get("mrl_save_decoded_textures", False)
            ),
            initial_open_decoded_texture_directory=bool(
                self.launcher_state.get(
                    "mrl_open_decoded_texture_directory", True
                )
            ),
            on_preferences_changed=self._persist_mrl_texture_preferences,
        ).show()
        if not bind_options:
            return
        mrl_path = self._record_mrl_path(bind_options.get("mrl_path", ""))
        if mrl_path is None:
            return
        texture_directory_text = str(
            bind_options.get("texture_directory", "") or mrl_path.parent
        ).strip().strip('"')
        try:
            texture_directory = Path(texture_directory_text).expanduser().resolve(
                strict=True
            )
        except (OSError, RuntimeError):
            self._show_error(
                RuntimeError(
                    self._tr(
                        "所选贴图文件夹已经不存在。",
                        "The selected texture folder no longer exists.",
                    )
                )
            )
            return
        if not texture_directory.is_dir():
            self._show_error(
                RuntimeError(
                    self._tr(
                        "所选贴图路径不是有效的文件夹。",
                        "The selected texture path is not a valid folder.",
                    )
                )
            )
            return
        texture_mode = _normalize_mrl_texture_source_mode(
            bind_options.get("texture_mode")
        )
        auto_cleanup_decoded_textures = bool(
            bind_options.get(
                "auto_cleanup_decoded_textures",
                not bool(bind_options.get("save_decoded_textures", False)),
            )
        )
        save_decoded_textures = bool(
            texture_mode == "tex" and not auto_cleanup_decoded_textures
        )
        if (
            texture_mode == "tex"
            and self.launcher_state.get("mrl_save_decoded_textures")
            != save_decoded_textures
        ):
            self.launcher_state["mrl_save_decoded_textures"] = save_decoded_textures
            self._queue_launcher_state_write()
        open_decoded_texture_directory = bool(
            bind_options.get(
                "open_decoded_texture_directory",
                self.launcher_state.get(
                    "mrl_open_decoded_texture_directory", True
                ),
            )
        )
        if self.launcher_state.get("mrl_open_decoded_texture_directory") != (
            open_decoded_texture_directory
        ):
            self.launcher_state[
                "mrl_open_decoded_texture_directory"
            ] = open_decoded_texture_directory
            self._queue_launcher_state_write()
        if not source_mod.is_file():
            guessed_mod = next(
                (
                    candidate
                    for candidate in (
                        mrl_path.with_suffix(".mod"),
                        mrl_path.with_suffix(".mod.NewMOD"),
                        mrl_path.with_suffix(".NewMOD"),
                    )
                    if candidate.is_file()
                ),
                Path(),
            )
            mod_text = str(guessed_mod) if guessed_mod.is_file() else _managed_file_dialog(
                self.root, "askopenfilename", title=self._tr("选择 MOD 文件", "Select MOD File"),
                filetypes=[
                    ("RE6 MOD / NewMOD", EXPORT_SOURCE_MOD_FILE_PATTERN),
                    ("All files", "*.*"),
                ],
            )
            if not mod_text:
                return
            source_mod = Path(mod_text).resolve()
        action = "mrl_bind"
        generation = self._begin_session_operation(session, action)
        log_directory = _resolve_log_directory(workspace.log_dir)
        workspace.log_dir = str(log_directory)
        self.log_dir_var.set(str(log_directory))
        plan_state: dict[str, Any] = {}

        def operation() -> tuple[str, dict[str, Any], dict[str, Any]]:
            cleanup_receipt = {"files": 0, "directories": 0}
            if texture_mode == "tex":
                decoded_root = log_directory / MRL_DECODE_CACHE_DIRECTORY_NAME
                decoded_root.mkdir(parents=True, exist_ok=True)
                if not save_decoded_textures:
                    cleanup_receipt = _cleanup_expired_mrl_decoded_textures(decoded_root)
                safe_mrl_stem = re.sub(r"[^A-Za-z0-9._-]+", "_", mrl_path.stem).strip("._") or "mrl"
                decode_directory = Path(
                    tempfile.mkdtemp(
                        prefix=f"{safe_mrl_stem}_{time.strftime('%Y%m%d_%H%M%S')}_",
                        dir=str(decoded_root),
                    )
                )
                try:
                    (decode_directory / ".pc_rehd_mrl_decode_cache").write_text(
                        "Generated by PC-REHD Code X Launcher.\n",
                        encoding="utf-8",
                    )
                except OSError:
                    pass
            else:
                decode_directory = Path(
                    tempfile.mkdtemp(prefix="mrl_decode_", dir=str(log_directory))
                )
            keep_decode_directory = False
            try:
                plan = _parse_mrl_bind_plan(
                    mrl_path,
                    source_mod,
                    decode_directory,
                    texture_directory=texture_directory,
                    texture_mode=texture_mode,
                )
                plan_state.clear()
                plan_state.update(
                    {
                        "mrl_path": str(mrl_path),
                        "mod_path": str(source_mod),
                        "texture_directory": str(texture_directory),
                        "texture_mode": texture_mode,
                        "texture_search_strategy": str(
                            plan.get("texture_search_strategy", "") or ""
                        ),
                        "texture_search_root_count": int(
                            plan.get("texture_search_root_count", 0) or 0
                        ),
                        "texture_search_roots": list(
                            plan.get("texture_search_roots", []) or []
                        ),
                        "texture_resolution": list(
                            plan.get("texture_resolution", []) or []
                        ),
                        "resolved_texture_source_count": int(
                            plan.get("resolved_texture_source_count", 0) or 0
                        ),
                    }
                )
                _plan_request_id, scene_data = self._request_max_scene_interface(
                    session,
                    "mrl_bind.scene",
                )
                target_rows = [
                    dict(row)
                    for row in scene_data.get("target_meshes", [])
                    if isinstance(row, dict)
                    and int(
                        _parse_scene_name(str(row.get("name", "") or "")).get(
                            "scene_name_mesh_slot", 0
                        )
                        or 0
                    ) > 0
                ]
                plan.update(
                    {
                        "scene_interface_id": "mrl_bind.scene",
                        "scene_snapshot_digest": str(scene_data.get("digest", "") or ""),
                        "node_handles": [int(row["handle"]) for row in target_rows],
                        "node_names": {
                            str(int(row["handle"])): str(row.get("name", "") or "")
                            for row in target_rows
                        },
                    }
                )
                request_id, result = self._request_max_scene_interface(
                    session,
                    "mrl_bind.apply",
                    plan,
                )
                decoded_count = int(
                    plan.get("temporary_decoded_texture_count", 0) or 0
                )
                keep_decode_directory = bool(
                    texture_mode == "tex" and decoded_count > 0
                )
                return request_id, result, {
                    "texture_mode": texture_mode,
                    "texture_directory": str(texture_directory),
                    "resolved_texture_source_count": int(
                        plan.get("resolved_texture_source_count", 0) or 0
                    ),
                    "temporary_decoded_texture_count": decoded_count,
                    "expired_decode_files_removed": int(cleanup_receipt.get("files", 0) or 0),
                    "expired_decode_directories_removed": int(cleanup_receipt.get("directories", 0) or 0),
                    "skipped_details": list(
                        result.get("skipped_details", []) or []
                    ),
                    "texture_search_strategy": str(
                        plan.get("texture_search_strategy", "") or ""
                    ),
                    "texture_search_root_count": int(
                        plan.get("texture_search_root_count", 0) or 0
                    ),
                    "texture_search_roots": list(
                        plan.get("texture_search_roots", []) or []
                    ),
                    "texture_resolution": list(
                        plan.get("texture_resolution", []) or []
                    ),
                    "saved_decode_directory": (
                        str(decode_directory) if keep_decode_directory else ""
                    ),
                    "open_decoded_texture_directory": bool(
                        texture_mode == "tex"
                        and open_decoded_texture_directory
                    ),
                }
            finally:
                if not keep_decode_directory:
                    shutil.rmtree(decode_directory, ignore_errors=True)

        def failure(exc: Exception) -> None:
            resolution_rows = [
                dict(row)
                for row in list(plan_state.get("texture_resolution", []) or [])
                if isinstance(row, dict)
            ]
            diagnostic = {
                "schema": "pc-rehd-mrl-bind-diagnostic-v1",
                "status": "ERROR",
                "mrl_path": str(plan_state.get("mrl_path", mrl_path) or mrl_path),
                "mod_path": str(plan_state.get("mod_path", source_mod) or source_mod),
                "texture_directory": str(
                    plan_state.get("texture_directory", texture_directory)
                    or texture_directory
                ),
                "texture_mode": str(
                    plan_state.get("texture_mode", texture_mode) or texture_mode
                ),
                "texture_search_strategy": str(
                    plan_state.get("texture_search_strategy", "") or ""
                ),
                "texture_search_root_count": int(
                    plan_state.get("texture_search_root_count", 0) or 0
                ),
                "texture_search_roots": list(
                    plan_state.get("texture_search_roots", []) or []
                ),
                "texture_resolution": resolution_rows,
                "error_type": type(exc).__name__,
                "detail": str(exc),
            }
            self._record_operation_diagnostic(
                "mrl_bind",
                receipt=diagnostic,
                detail=f"MRL bind failed: {type(exc).__name__}: {exc}",
            )
            self._session_error(session, action, generation, exc)

        def success(
            value: tuple[str, dict[str, Any], dict[str, Any]]
        ) -> None:
            if not self._owns_session_operation(session, action, generation):
                return
            request_id, result, texture_receipt = value
            applied = int(result.get("applied", 0) or 0)
            skipped = int(result.get("skipped", 0) or 0)
            target_count = int(result.get("target_mesh_count", 0) or 0)
            skipped_by_reason = dict(result.get("skipped_by_reason", {}))
            warning_lines: list[str] = []
            reason_labels = {
                "missing_imported_mesh_index": self._tr("缺少导入 mesh 索引", "Missing imported mesh index"),
                "missing_source_mesh_entry": self._tr("源 mesh 材质映射缺失", "Missing source mesh material mapping"),
                "missing_idx_material": self._tr("源 idxMaterial 缺失", "Missing source idxMaterial"),
                "missing_material_hash": self._tr("源材质哈希缺失", "Missing source material hash"),
                "mrl_material_hash_not_matched": self._tr("MRL 材质哈希未匹配", "No matching MRL material hash"),
                "missing_base_color_binding": self._tr("MRL 内没有可绑定的 Base Color/BM", "No Base Color/BM binding was available in MRL"),
                "missing_loadable_images": self._tr("Base Color/BM 贴图资源无法加载", "The Base Color/BM texture could not be loaded"),
                "base_color_bitmap_readback_failed": self._tr("MAX 读取 Base Color/BM 后回读失败", "Max could not verify the Base Color/BM bitmap after assignment"),
            }
            for reason, names_value in skipped_by_reason.items():
                names = [str(name) for name in list(names_value) if str(name)]
                label = reason_labels.get(reason, reason)
                warning_lines.append(f"{label}: {len(names)}")
                if names:
                    warning_lines.append(label + self._tr("的 MESH:", " meshes:") + "\n" + "\n".join(names[:64]))
            for skipped_detail in list(result.get("skipped_details", []) or [])[:32]:
                if not isinstance(skipped_detail, dict):
                    continue
                bitmap_path = str(skipped_detail.get("bitmap_path", "") or "")
                failure_reason = str(
                    skipped_detail.get("failure_reason", "") or ""
                )
                if not bitmap_path or not failure_reason:
                    continue
                warning_lines.append(
                    self._tr(
                        f"MAX 路径检查 | {skipped_detail.get('scene_node', '')}: "
                        f"{failure_reason} | {bitmap_path}",
                        f"Max path check | {skipped_detail.get('scene_node', '')}: "
                        f"{failure_reason} | {bitmap_path}",
                    )
                )

            saved_decode_directory = str(
                texture_receipt.get("saved_decode_directory", "") or ""
            )
            open_decode_directory_requested = bool(
                texture_receipt.get("open_decoded_texture_directory", False)
            )
            opened_decode_directory = False
            if saved_decode_directory and open_decode_directory_requested:
                try:
                    self._open_directory(saved_decode_directory)
                    opened_decode_directory = True
                except Exception as exc:
                    warning_lines.append(
                        self._tr(
                            "TEX 解析结果已经保存，但无法自动打开文件夹：",
                            "The TEX decode result was saved, but its folder could not be opened: ",
                        )
                        + f"{type(exc).__name__}: {exc}"
                    )

            has_warning = skipped > 0 or applied == 0
            summary_head = self._tr("MRL 自动绑定贴图完成。", "MRL auto tex bind done.")
            if has_warning:
                summary_head = self._tr("MRL 自动绑定贴图完成，但存在警告。", "MRL auto tex bind finished with warnings.")
                warning_lines.insert(0, self._tr("自动绑定并不完整，请手动复核结果。", "The auto bind was not fully resolved. Please verify the result manually."))
            detail_sections = [
                summary_head,
                self._tr("已应用网格: ", "Applied meshes: ") + str(applied)
                + "\n" + self._tr("跳过节点: ", "Skipped nodes: ") + str(skipped)
                + "\n" + self._tr("目标 Mesh 数: ", "Target mesh count: ") + str(target_count),
                self._tr("目标贴图模式: ", "Target texture mode: ")
                + str(texture_receipt.get("texture_mode", texture_mode)).upper()
                + "\n"
                + self._tr("已匹配贴图源: ", "Matched texture sources: ")
                + str(int(texture_receipt.get("resolved_texture_source_count", 0) or 0)),
                "MRL: " + str(result.get("mrl_path", mrl_path))
                + "\nMOD: " + str(result.get("mod_path", source_mod))
                + "\n"
                + self._tr("贴图路径: ", "Texture path: ")
                + str(texture_receipt.get("texture_directory", texture_directory)),
            ]
            if texture_mode == "tex":
                decoded_count = int(
                    texture_receipt.get("temporary_decoded_texture_count", 0) or 0
                )
                if saved_decode_directory:
                    if opened_decode_directory:
                        folder_status_cn = "并已打开"
                        folder_status_en = " and opened"
                    elif open_decode_directory_requested:
                        folder_status_cn = "，但未能自动打开文件夹"
                        folder_status_en = ", but the folder could not be opened automatically"
                    else:
                        folder_status_cn = "，未自动打开文件夹"
                        folder_status_en = ", and the folder was not opened automatically"
                    detail_sections.append(
                        self._tr(
                            f"本次 TEX 解析 DDS 结果已保留{folder_status_cn}（MAX 材质使用期间不要删除）：",
                            f"This TEX-to-DDS result was retained{folder_status_en} (do not delete while the Max material uses it): ",
                        )
                        + saved_decode_directory
                    )
                else:
                    detail_sections.append(
                        self._tr(
                        f"本次 TEX 解析 DDS 数量: {decoded_count}。本次结果未产生可保留文件；已删除的 1 天前旧结果: {int(texture_receipt.get('expired_decode_files_removed', 0) or 0)} 个。",
                        f"TEX DDS files decoded this time: {decoded_count}. No retained files were produced; expired results removed: {int(texture_receipt.get('expired_decode_files_removed', 0) or 0)}.",
                    )
                    )
                cleanup_count = int(texture_receipt.get("expired_decode_files_removed", 0) or 0)
                if saved_decode_directory and cleanup_count:
                    detail_sections.append(
                        self._tr(
                            f"已启用自动清理，解析前清理超过 1 天的旧解析 DDS：{cleanup_count} 个。",
                            f"Automatic cleanup was enabled; {cleanup_count} generated DDS files older than one day were cleaned before parsing.",
                        )
                    )
            if warning_lines:
                detail_sections.append(self._tr("警告摘要:", "Warnings:") + "\n" + "\n\n".join(warning_lines))
            resolution_rows = [
                dict(row)
                for row in list(texture_receipt.get("texture_resolution", []) or [])
                if isinstance(row, dict)
            ]
            unresolved_resources = [
                str(row.get("resource", "") or "")
                for row in resolution_rows
                if not bool(row.get("resolved", False))
            ]
            search_summary = self._tr(
                "MRL 资源搜索：以 MRL 为中心的有限相对路径/同级 MODEL 目录搜索，"
                f"候选目录 {int(texture_receipt.get('texture_search_root_count', 0) or 0)} 个，"
                f"Python 命中 {int(texture_receipt.get('resolved_texture_source_count', 0) or 0)} 个。",
                "MRL resource search: bounded relative-path and sibling MODEL search centered on the MRL; "
                f"{int(texture_receipt.get('texture_search_root_count', 0) or 0)} candidate directories, "
                f"{int(texture_receipt.get('resolved_texture_source_count', 0) or 0)} Python matches.",
            )
            if unresolved_resources:
                search_summary += self._tr(
                    "\n未命中资源：" + "、".join(unresolved_resources[:32]),
                    "\nUnresolved resources: " + ", ".join(unresolved_resources[:32]),
                )
            detail_sections.append(search_summary)
            detail_sections.append(self._tr(
                "请用户自己用 RE6 手动贴图 手动判定/修正结果：有些 MESH 只是空间重叠件，有些 MESH 会更大或结构特殊，尤其是 LOD255。",
                "Please verify/fix the result manually with RE6 Manual Tex: some meshes are only spatial overlaps, while some are larger or structurally special, especially LOD255.",
            ))
            detail = "\n\n".join(detail_sections)
            session.workspace.last_status = f"MRL | {request_id[:12]}"
            if self._session_is_visible(session):
                ChoiceDialog(self.root, title=self._tr("MRL 自动绑定贴图", "MRL Auto Tex Bind"), message=detail, choices=[(self._tr("关闭", "Close"), "close")]).show()
                self._set_status(session.workspace.last_status, progress=100)

        self._run_background(
            operation, success, label=self._tr("解析并绑定 MRL", "Parsing and binding MRL"),
            on_error=failure,
        )

    def _normalize_max_scene_materials(self) -> None:
        """Normalize all live Max Mesh materials for texture baking."""
        if self.blender_mode_enabled:
            self._normalize_blender_scene_materials()
            return
        session = self._active_session()
        workspace = self._active_workspace()
        if session is None or workspace is None:
            self._show_error(RuntimeError(self._tr("当前没有活动的 Max。", "No active Max session.")))
            return
        action = "normalize_max_materials"
        generation = self._begin_session_operation(session, action)

        def operation() -> tuple[str, dict[str, Any]]:
            _probe_request_id, scene_data = self._request_max_scene_interface(
                session, "scene_materials.scene"
            )
            rows = [
                dict(row)
                for row in scene_data.get("target_meshes", [])
                if isinstance(row, dict) and int(row.get("handle", 0) or 0) > 0
            ]
            request_id, result = self._request_max_scene_interface(
                session,
                "scene_materials.apply",
                {
                    "scene_interface_id": "scene_materials.scene",
                    "scene_snapshot_digest": str(scene_data.get("digest", "") or ""),
                    "node_handles": [int(row["handle"]) for row in rows],
                    "node_names": {
                        str(int(row["handle"])): str(row.get("name", "") or "")
                        for row in rows
                    },
                },
            )
            return request_id, dict(result)

        def success(value: tuple[str, dict[str, Any]]) -> None:
            if not self._owns_session_operation(session, action, generation):
                return
            request_id, result = value
            changed = int(result.get("changed_count", 0) or 0)
            skipped = int(result.get("skipped_count", 0) or 0)
            preserved = int(result.get("preserved_count", 0) or 0)
            texture_failures = int(
                result.get("texture_extraction_failed_count", 0) or 0
            )
            workspace.last_status = self._tr(
                f"Max 贴图材质修复：处理 {changed}，保留 {preserved}，贴图提取失败 {texture_failures}，跳过 {skipped}",
                f"Max texture material repair: changed {changed}, preserved {preserved}, texture extraction failed {texture_failures}, skipped {skipped}",
            )
            if self._session_is_visible(session):
                self._set_status(f"{workspace.last_status} | {request_id[:12]}", progress=100)

        self._run_background(
            operation,
            success,
            label=self._tr("正在修复 Max 贴图材质", "Repairing Max texture materials"),
            on_error=lambda exc: self._session_error(session, action, generation, exc),
        )

    def _normalize_blender_scene_materials(self) -> None:
        """Normalize every Blender scene Mesh to Image Texture -> Emission."""
        session = self._active_blender_session()
        workspace = self._active_workspace()
        if (
            not self.blender_mode_enabled
            or session is None
            or workspace is None
            or not self._blender_operation_controls_ready()
        ):
            return
        if self._blender_material_bind_inflight:
            return
        action = "normalize_blender_materials"
        generation = self._begin_session_operation(session, action)
        self._blender_material_bind_inflight = True
        self._refresh_blender_material_bind_action_states()

        def operation() -> tuple[str, dict[str, Any]]:
            result = session.request("scene.normalize_texture_materials", {})
            return uuid.uuid4().hex, dict(result)

        def success(value: tuple[str, dict[str, Any]]) -> None:
            self._blender_material_bind_inflight = False
            self._refresh_blender_material_bind_action_states()
            if not self._owns_session_operation(session, action, generation):
                return
            request_id, result = value
            changed = int(result.get("normalized_slot_count", 0) or 0)
            unlit_verified = int(result.get("unlit_verified_count", 0) or 0)
            bsdf_replaced = int(result.get("bsdf_replaced_count", 0) or 0)
            skipped = int(result.get("skipped_count", 0) or 0)
            failure_count = int(result.get("failure_count", 0) or 0)
            if str(result.get("status", "") or "").upper() == "FAILED" or failure_count:
                failure_rows = result.get("failure_rows", [])
                first_failure = (
                    dict(failure_rows[0])
                    if isinstance(failure_rows, list) and failure_rows and isinstance(failure_rows[0], dict)
                    else {}
                )
                detail = str(first_failure.get("error", "") or "")
                workspace.last_status = self._tr(
                    f"Blender 贴图材质修复失败：{failure_count} 个槽未转换，场景未修改。{detail}",
                    f"Blender texture material repair failed: {failure_count} slots were not converted; the scene was not changed. {detail}",
                )
                if self._session_is_visible(session):
                    self._show_error(RuntimeError(workspace.last_status))
                    self._set_status(f"{workspace.last_status} | {request_id[:12]}", progress=0)
                return
            workspace.last_status = self._tr(
                f"Blender 贴图材质修复：处理 {changed}，无光验证 {unlit_verified}，替换 BSDF {bsdf_replaced}，跳过 {skipped}",
                f"Blender texture material repair: changed {changed}, unlit verified {unlit_verified}, BSDF replaced {bsdf_replaced}, skipped {skipped}",
            )
            if self._session_is_visible(session):
                self._set_status(f"{workspace.last_status} | {request_id[:12]}", progress=100)

        def failure(exc: Exception) -> None:
            self._blender_material_bind_inflight = False
            self._refresh_blender_material_bind_action_states()
            self._session_error(session, action, generation, exc)

        self._run_background(
            operation,
            success,
            label=self._tr("正在修复 Blender 贴图材质", "Repairing Blender texture materials"),
            on_error=failure,
        )

    def _backend_blender_manual_texture(self, texture_format: str) -> None:
        """Bind one user-selected image to selected Blender RE6 Meshes only."""
        session = self._active_blender_session()
        workspace = self._active_workspace()
        if (
            not self.blender_mode_enabled
            or session is None
            or workspace is None
            or not self._blender_operation_controls_ready()
        ):
            # The Blender page keeps these labels visually inert until its
            # exact foreground PID has a live Worker. Do not fall back to Max.
            return
        if self._blender_material_bind_inflight:
            return
        selected = self._prompt_manual_texture_path(texture_format)
        if selected is None:
            return
        action = "blender_manual_texture"
        generation = self._begin_session_operation(session, action)
        self._blender_material_bind_inflight = True
        self._refresh_blender_material_bind_action_states()
        log_directory = _resolve_log_directory(workspace.log_dir)
        workspace.log_dir = str(log_directory)
        self.log_dir_var.set(str(log_directory))
        decoded_from_tex = selected.suffix.casefold() == ".tex"

        def operation() -> tuple[str, dict[str, Any]]:
            decode_directory: Path | None = None
            try:
                if decoded_from_tex:
                    decode_directory = Path(
                        tempfile.mkdtemp(
                            prefix="blender_manual_tex_",
                            dir=str(log_directory),
                        )
                    )
                image_path = _prepare_manual_texture_image(
                    selected,
                    decode_directory or log_directory,
                )
                result = session.request(
                    "scene.apply_manual_texture",
                    {
                        "schema": "pc-rehd-blender-manual-texture-v1",
                        "image_path": str(image_path),
                        "source_texture_path": str(selected),
                        "texture_format": str(texture_format).casefold(),
                    },
                )
                result = dict(result)
                result["source_texture_path"] = str(selected)
                result["decoded_from_tex"] = decoded_from_tex
                return uuid.uuid4().hex, result
            finally:
                if decode_directory is not None:
                    # The Worker packs the image before returning, so a TEX
                    # decode never leaves the Blender material dependent on a
                    # temporary launcher directory.
                    shutil.rmtree(decode_directory, ignore_errors=True)

        def success(value: tuple[str, dict[str, Any]]) -> None:
            self._blender_material_bind_inflight = False
            self._refresh_blender_material_bind_action_states()
            if not self._owns_session_operation(session, action, generation):
                return
            request_id, result = value
            applied = int(result.get("applied", 0) or 0)
            skipped = int(result.get("skipped", 0) or 0)
            selected_count = int(result.get("selected", 0) or 0)
            zero_reason = str(result.get("zero_reason", "") or "")
            session.workspace.last_status = self._tr(
                f"Blender 手动贴图：应用 {applied}，跳过 {skipped}",
                f"Blender manual texture: applied {applied}, skipped {skipped}",
            )
            if not self._session_is_visible(session):
                return
            detail = self._tr(
                "Blender RE6 手动绑定贴图完成。\n\n"
                f"选中 Mesh: {selected_count}\n已应用: {applied}\n跳过: {skipped}\n\n"
                f"源贴图: {result.get('source_texture_path', selected)}\n"
                f"Blender 图像: {result.get('image_path', '')}",
                "Blender RE6 Manual Texture Bind completed.\n\n"
                f"Selected Meshes: {selected_count}\nApplied: {applied}\nSkipped: {skipped}\n\n"
                f"Source texture: {result.get('source_texture_path', selected)}\n"
                f"Blender image: {result.get('image_path', '')}",
            )
            if bool(result.get("decoded_from_tex", False)):
                detail += self._tr(
                    "\n\nTEX 已解码并打包进 Blender 图像数据。",
                    "\n\nThe TEX image was decoded and packed into Blender image data.",
                )
            if zero_reason:
                detail += "\n\n" + self._tr(
                    "未应用原因: " + zero_reason,
                    "No material was applied: " + zero_reason,
                )
            skipped_reasons = dict(result.get("skipped_reasons", {}) or {})
            if skipped_reasons:
                detail += "\n\n" + self._tr("跳过原因:\n", "Skip reasons:\n")
                detail += "\n".join(
                    f"{reason}: {count}"
                    for reason, count in list(skipped_reasons.items())[:16]
                )
            ChoiceDialog(
                self.root,
                title=self._tr("RE6 手动贴图", "RE6 Manual Texture"),
                message=detail,
                choices=[(self._tr("关闭", "Close"), "close")],
            ).show()
            self._set_status(
                f"{session.workspace.last_status} | {request_id[:12]}",
                progress=100,
            )

        def failure(exc: Exception) -> None:
            self._blender_material_bind_inflight = False
            self._refresh_blender_material_bind_action_states()
            self._session_error(session, action, generation, exc)

        self._run_background(
            operation,
            success,
            label=self._tr(
                "Blender 正在应用贴图",
                "Applying Blender texture",
            ),
            on_error=failure,
            performance_critical=True,
        )

    def _backend_blender_mrl_bind(self) -> None:
        """Use the exact MRL/MOD slot plan without routing through Max."""
        session = self._active_blender_session()
        workspace = self._active_workspace()
        if (
            not self.blender_mode_enabled
            or session is None
            or workspace is None
            or not self._blender_operation_controls_ready()
        ):
            return
        if self._blender_material_bind_inflight:
            return
        source_mod_text = str(
            workspace.source_mod or self.source_mod_var.get() or ""
        ).strip()
        source_mod = Path(source_mod_text) if source_mod_text else Path()
        guessed_mrl = _find_mrl_for_source_mod(source_mod_text)
        remembered_mrl = _normalize_mrl_path(
            self.launcher_state.get("mrl_last_path", "")
        )
        initial_mrl = guessed_mrl or (
            Path(remembered_mrl) if remembered_mrl else None
        )
        mrl_history = _normalize_mrl_path_history(
            [
                str(guessed_mrl) if guessed_mrl is not None else "",
                remembered_mrl,
                *self.launcher_state.get("mrl_path_history", []),
            ]
        )
        bind_options = MrlTextureBindDialog(
            self.root,
            translate=self._tr,
            initial_mrl_path=str(initial_mrl) if initial_mrl is not None else "",
            history_paths=mrl_history,
            auto_scan_found=bool(initial_mrl is not None and initial_mrl.is_file()),
            initial_save_decoded_textures=bool(
                self.launcher_state.get("mrl_save_decoded_textures", False)
            ),
            initial_open_decoded_texture_directory=bool(
                self.launcher_state.get(
                    "mrl_open_decoded_texture_directory", True
                )
            ),
            on_preferences_changed=self._persist_mrl_texture_preferences,
            target_host="blender",
        ).show()
        if not bind_options:
            return
        mrl_path = self._record_mrl_path(bind_options.get("mrl_path", ""))
        if mrl_path is None:
            return
        texture_directory_text = str(
            bind_options.get("texture_directory", "") or mrl_path.parent
        ).strip().strip('"')
        try:
            texture_directory = Path(texture_directory_text).expanduser().resolve(
                strict=True
            )
        except (OSError, RuntimeError):
            self._show_error(
                RuntimeError(
                    self._tr(
                        "所选贴图文件夹已经不存在。",
                        "The selected texture folder no longer exists.",
                    )
                )
            )
            return
        if not texture_directory.is_dir():
            self._show_error(
                RuntimeError(
                    self._tr(
                        "所选贴图路径不是有效的文件夹。",
                        "The selected texture path is not a valid folder.",
                    )
                )
            )
            return
        texture_mode = _normalize_mrl_texture_source_mode(
            bind_options.get("texture_mode")
        )
        auto_cleanup_decoded_textures = bool(
            bind_options.get(
                "auto_cleanup_decoded_textures",
                not bool(bind_options.get("save_decoded_textures", False)),
            )
        )
        save_decoded_textures = bool(
            texture_mode == "tex" and not auto_cleanup_decoded_textures
        )
        if (
            texture_mode == "tex"
            and self.launcher_state.get("mrl_save_decoded_textures")
            != save_decoded_textures
        ):
            self.launcher_state["mrl_save_decoded_textures"] = (
                save_decoded_textures
            )
            self._queue_launcher_state_write()
        open_decoded_texture_directory = bool(
            bind_options.get(
                "open_decoded_texture_directory",
                self.launcher_state.get(
                    "mrl_open_decoded_texture_directory", True
                ),
            )
        )
        if self.launcher_state.get("mrl_open_decoded_texture_directory") != (
            open_decoded_texture_directory
        ):
            self.launcher_state["mrl_open_decoded_texture_directory"] = (
                open_decoded_texture_directory
            )
            self._queue_launcher_state_write()
        if not source_mod.is_file():
            guessed_mod = next(
                (
                    candidate
                    for candidate in (
                        mrl_path.with_suffix(".mod"),
                        mrl_path.with_suffix(".mod.NewMOD"),
                        mrl_path.with_suffix(".NewMOD"),
                    )
                    if candidate.is_file()
                ),
                Path(),
            )
            mod_text = (
                str(guessed_mod)
                if guessed_mod.is_file()
                else _managed_file_dialog(
                    self.root,
                    "askopenfilename",
                    title=self._tr("选择 MOD 文件", "Select MOD File"),
                    filetypes=[
                        ("RE6 MOD / NewMOD", EXPORT_SOURCE_MOD_FILE_PATTERN),
                        ("All files", "*.*"),
                    ],
                )
            )
            if not mod_text:
                return
            source_mod = Path(mod_text).resolve()
        if not source_mod.is_file():
            self._show_error(
                FileNotFoundError(
                    self._tr("所选 MOD 文件不可读取。", "The selected MOD is not readable.")
                )
            )
            return
        self._set_workspace_source_mod(workspace, source_mod)
        action = "blender_mrl_bind"
        generation = self._begin_session_operation(session, action)
        self._blender_material_bind_inflight = True
        self._refresh_blender_material_bind_action_states()
        log_directory = _resolve_log_directory(workspace.log_dir)
        workspace.log_dir = str(log_directory)
        self.log_dir_var.set(str(log_directory))
        plan_state: dict[str, Any] = {}

        def operation() -> tuple[str, dict[str, Any], dict[str, Any]]:
            cleanup_receipt = {"files": 0, "directories": 0}
            if texture_mode == "tex":
                decoded_root = log_directory / MRL_DECODE_CACHE_DIRECTORY_NAME
                decoded_root.mkdir(parents=True, exist_ok=True)
                if not save_decoded_textures:
                    cleanup_receipt = _cleanup_expired_mrl_decoded_textures(
                        decoded_root
                    )
                safe_mrl_stem = re.sub(
                    r"[^A-Za-z0-9._-]+", "_", mrl_path.stem
                ).strip("._") or "mrl"
                decode_directory = Path(
                    tempfile.mkdtemp(
                        prefix=(
                            f"blender_{safe_mrl_stem}_"
                            f"{time.strftime('%Y%m%d_%H%M%S')}_"
                        ),
                        dir=str(decoded_root),
                    )
                )
            else:
                decode_directory = Path(
                    tempfile.mkdtemp(
                        prefix="blender_mrl_decode_",
                        dir=str(log_directory),
                    )
                )
            keep_decode_directory = False
            try:
                plan = _parse_mrl_bind_plan(
                    mrl_path,
                    source_mod,
                    decode_directory,
                    texture_directory=texture_directory,
                    texture_mode=texture_mode,
                )
                plan_state.clear()
                plan_state.update(
                    {
                        "texture_resolution": list(
                            plan.get("texture_resolution", []) or []
                        ),
                        "resolved_texture_source_count": int(
                            plan.get("resolved_texture_source_count", 0) or 0
                        ),
                    }
                )
                raw_bindings = plan.get("materials_by_mesh_slot", {})
                bindings = {
                    str(slot): dict(binding)
                    for slot, binding in dict(raw_bindings).items()
                    if str(slot).strip()
                    and isinstance(binding, Mapping)
                }
                result = session.request(
                    "scene.apply_mrl_material",
                    {
                        "schema": "pc-rehd-blender-mrl-bind-v1",
                        "mrl_path": str(mrl_path),
                        "mod_path": str(source_mod),
                        "texture_directory": str(texture_directory),
                        "texture_mode": texture_mode,
                        "bindings_by_mesh_slot": bindings,
                    },
                )
                result = dict(result)
                decoded_count = int(
                    plan.get("temporary_decoded_texture_count", 0) or 0
                )
                keep_decode_directory = bool(
                    texture_mode == "tex"
                    and save_decoded_textures
                    and decoded_count > 0
                )
                return uuid.uuid4().hex, result, {
                    "texture_mode": texture_mode,
                    "texture_directory": str(texture_directory),
                    "resolved_texture_source_count": int(
                        plan.get("resolved_texture_source_count", 0) or 0
                    ),
                    "temporary_decoded_texture_count": decoded_count,
                    "texture_resolution": list(
                        plan.get("texture_resolution", []) or []
                    ),
                    "expired_decode_files_removed": int(
                        cleanup_receipt.get("files", 0) or 0
                    ),
                    "saved_decode_directory": (
                        str(decode_directory) if keep_decode_directory else ""
                    ),
                    "open_decoded_texture_directory": bool(
                        texture_mode == "tex"
                        and keep_decode_directory
                        and open_decoded_texture_directory
                    ),
                }
            finally:
                if not keep_decode_directory:
                    shutil.rmtree(decode_directory, ignore_errors=True)

        def success(
            value: tuple[str, dict[str, Any], dict[str, Any]]
        ) -> None:
            self._blender_material_bind_inflight = False
            self._refresh_blender_material_bind_action_states()
            if not self._owns_session_operation(session, action, generation):
                return
            request_id, result, texture_receipt = value
            applied = int(result.get("applied", 0) or 0)
            skipped = int(result.get("skipped", 0) or 0)
            target_count = int(result.get("target_mesh_count", 0) or 0)
            warning_lines: list[str] = []
            reason_labels = {
                "missing_base_color_binding": self._tr(
                    "MRL 内没有可绑定的 Base Color/BM",
                    "No Base Color/BM binding was available in MRL",
                ),
                "missing_loadable_images": self._tr(
                    "Base Color/BM 贴图资源无法加载",
                    "The Base Color/BM texture could not be loaded",
                ),
                "base_color_graph_verification_failed": self._tr(
                    "Blender Base Color 节点验证失败",
                    "Blender Base Color graph verification failed",
                ),
                "material_assignment_failed": self._tr(
                    "Blender 材质写入失败",
                    "Blender material assignment failed",
                ),
            }
            for reason, names_value in dict(
                result.get("skipped_by_reason", {}) or {}
            ).items():
                names = [str(name) for name in list(names_value or []) if str(name)]
                label = reason_labels.get(str(reason), str(reason))
                warning_lines.append(f"{label}: {len(names)}")
                if names:
                    warning_lines.append(
                        label
                        + self._tr(" 的 MESH:\n", " meshes:\n")
                        + "\n".join(names[:32])
                    )
            saved_decode_directory = str(
                texture_receipt.get("saved_decode_directory", "") or ""
            )
            if (
                saved_decode_directory
                and bool(texture_receipt.get("open_decoded_texture_directory", False))
            ):
                try:
                    self._open_directory(saved_decode_directory)
                except Exception as exc:
                    warning_lines.append(
                        "%s: %s" % (type(exc).__name__, exc)
                    )
            detail_sections = [
                self._tr("Blender MRL 自动绑定贴图完成。", "Blender MRL auto texture bind completed."),
                self._tr("已应用 Mesh: ", "Applied Meshes: ")
                + str(applied)
                + "\n"
                + self._tr("跳过 Mesh: ", "Skipped Meshes: ")
                + str(skipped)
                + "\n"
                + self._tr("目标 Mesh: ", "Target Meshes: ")
                + str(target_count),
                "MRL: "
                + str(result.get("mrl_path", mrl_path))
                + "\nMOD: "
                + str(result.get("mod_path", source_mod))
                + "\n"
                + self._tr("贴图路径: ", "Texture path: ")
                + str(texture_receipt.get("texture_directory", texture_directory)),
                self._tr("目标贴图模式: ", "Texture mode: ")
                + str(texture_receipt.get("texture_mode", texture_mode)).upper()
                + "\n"
                + self._tr("已匹配贴图源: ", "Matched texture sources: ")
                + str(
                    int(
                        texture_receipt.get(
                            "resolved_texture_source_count", 0
                        )
                        or 0
                    )
                ),
            ]
            if texture_mode == "tex":
                detail_sections.append(
                    self._tr(
                        "TEX 已解码并打包进 Blender 图像数据。",
                        "TEX images were decoded and packed into Blender image data.",
                    )
                )
                if saved_decode_directory:
                    detail_sections.append(
                        self._tr(
                            "已按当前设置保留本次 TEX 解码目录：",
                            "The current TEX decode directory was retained: ",
                        )
                        + saved_decode_directory
                    )
            zero_reason = str(result.get("zero_reason", "") or "")
            if zero_reason:
                warning_lines.insert(
                    0,
                    self._tr("未应用原因: ", "No material was applied: ")
                    + zero_reason,
                )
            if warning_lines:
                detail_sections.append(
                    self._tr("警告摘要:\n", "Warnings:\n")
                    + "\n\n".join(warning_lines)
                )
            session.workspace.last_status = f"Blender MRL | {request_id[:12]}"
            if self._session_is_visible(session):
                ChoiceDialog(
                    self.root,
                    title=self._tr("MRL 自动绑定贴图", "MRL Auto Tex Bind"),
                    message="\n\n".join(detail_sections),
                    choices=[(self._tr("关闭", "Close"), "close")],
                ).show()
                self._set_status(session.workspace.last_status, progress=100)

        def failure(exc: Exception) -> None:
            self._blender_material_bind_inflight = False
            self._refresh_blender_material_bind_action_states()
            self._session_error(session, action, generation, exc)

        self._run_background(
            operation,
            success,
            label=self._tr(
                "Blender 正在解析并绑定 MRL",
                "Parsing and binding Blender MRL",
            ),
            on_error=failure,
            performance_critical=True,
        )

    def _format_import_texture_receipt(
        self,
        receipt: Mapping[str, Any] | None,
    ) -> tuple[str, str]:
        data = dict(receipt or {})
        status = str(data.get("status", "") or "").strip().upper()
        cleanup_error = str(data.get("error", "") or "").strip()
        removed_fbm_directory_count = max(
            0,
            int(data.get("removed_fbm_directory_count", 0) or 0),
        )
        retained_fbm_directory_count = max(
            0,
            int(data.get("retained_fbm_directory_count", 0) or 0),
        )
        fbm_retention_limit = max(
            1,
            int(
                data.get(
                    "fbm_retention_limit",
                    IMPORT_FBX_MEDIA_DIRECTORY_KEEP_COUNT,
                )
                or IMPORT_FBX_MEDIA_DIRECTORY_KEEP_COUNT
            ),
        )
        retained_import_fbx = str(data.get("retained_import_fbx", "") or "").strip()
        fbm_auto_cleanup_disabled = (
            str(data.get("fbm_auto_cleanup_disabled", False))
            .strip()
            .casefold()
            in {"1", "true", "yes", "on"}
        )
        if cleanup_error:
            cleanup_cn = "\n临时文件清理失败：" + cleanup_error
            cleanup_en = "\nTemporary-file cleanup failed: " + cleanup_error
        elif fbm_auto_cleanup_disabled:
            cleanup_cn = (
                f"\n已关闭自动清理贴图文件夹；当前保留 {retained_fbm_directory_count} 个 FBM 目录。"
            )
            cleanup_en = (
                "\nAutomatic texture-folder cleanup is disabled; "
                f"{retained_fbm_directory_count} FBM folder(s) are retained."
            )
        elif removed_fbm_directory_count:
            cleanup_cn = (
                f"\n已清理 {removed_fbm_directory_count} 个超过最近 {fbm_retention_limit} 次导入的 FBM 目录；"
                f"当前保留 {retained_fbm_directory_count} 个。"
            )
            cleanup_en = (
                f"\nCleaned {removed_fbm_directory_count} FBM folder(s) older than the latest "
                f"{fbm_retention_limit} imports; {retained_fbm_directory_count} remain."
            )
        elif retained_fbm_directory_count or retained_import_fbx:
            cleanup_cn = (
                f"\n已保留最近 {retained_fbm_directory_count} 个 FBM 目录（上限 {fbm_retention_limit} 个）。"
            )
            cleanup_en = (
                f"\nRetained {retained_fbm_directory_count} recent FBM folder(s) "
                f"(limit {fbm_retention_limit})."
            )
        else:
            cleanup_cn = ""
            cleanup_en = ""
        blender_validation = data.get("blender_material_validation")
        if isinstance(blender_validation, Mapping):
            validation = dict(blender_validation)
            validation_status = str(
                validation.get("status", "") or ""
            ).strip().upper()

            def validation_count(key: str) -> int:
                try:
                    return max(0, int(validation.get(key, 0) or 0))
                except (TypeError, ValueError, OverflowError):
                    return 0

            if validation_status in {"VERIFIED", "PARTIAL"}:
                planned = validation_count("planned_binding_count")
                verified = validation_count("verified_binding_count")
                source_unbound = validation_count("source_unbound_mesh_count")
                unresolved = validation_count("unresolved_binding_count")
                actual_untextured = validation_count("actual_untextured_mesh_count")
                deduplicated = validation_count("deduplicated_image_count")
                media_count = max(
                    0,
                    int(data.get("unique_embedded_media_count", 0) or 0),
                )
                return (
                    "Blender 导入贴图：MRL 计划绑定 "
                    f"{planned} 个 Mesh；实际 Base Color 已确认 {verified} 个；"
                    f"源 MRL 本来无绑定 {source_unbound} 个；额外未挂载 {unresolved} 个；"
                    f"实际无 Base Color {actual_untextured} 个（媒体 {media_count}，"
                    f"清理重复图像 {deduplicated} 个）。"
                    + cleanup_cn,
                    "Blender Import Textures: MRL planned "
                    f"{planned} Mesh bindings; {verified} Base Color links were actually verified; "
                    f"{source_unbound} Meshes have no source MRL binding; {unresolved} additional "
                    f"planned bindings are unresolved; {actual_untextured} Meshes actually have no "
                    f"Base Color image (media {media_count}, duplicate images removed {deduplicated})."
                    + cleanup_en,
                )
            if validation_status == "FAILED":
                error = str(validation.get("error", "") or "").strip()
                return (
                    "Blender 导入贴图：原生 FBX 导入已完成，但 Blender Base Color 回填失败；"
                    "几何已照常导入。"
                    + ("\n原因：" + error if error else "")
                    + cleanup_cn,
                    "Blender Import Textures: native FBX import completed, but Blender Base Color "
                    "recovery failed; geometry was imported normally."
                    + ("\nReason: " + error if error else "")
                    + cleanup_en,
                )
        if status == "BOUND":
            binding_count = max(0, int(data.get("binding_count", 0) or 0))
            dds_count = max(0, int(data.get("dds_binding_count", 0) or 0))
            tex_count = max(
                0,
                int(data.get("tex_fallback_binding_count", 0) or 0),
            )
            media_count = max(
                0,
                int(data.get("unique_embedded_media_count", 0) or 0),
            )
            return (
                "导入贴图：已嵌入 "
                f"{binding_count} 个 Mesh 的 Base Color（DDS {dds_count}，"
                f"TEX 回退 {tex_count}，媒体 {media_count}）。"
                + cleanup_cn,
                "Import Textures: embedded Base Color for "
                f"{binding_count} Meshes (DDS {dds_count}, TEX fallback "
                f"{tex_count}, media {media_count})."
                + cleanup_en,
            )
        if status == "DISABLED":
            return ("导入贴图：未启用。", "Import Textures: disabled.")
        reason = str(data.get("reason", "") or "").strip()
        localized_reasons = {
            "mrl_not_selected": "未选择 MRL 文件",
            "mrl_not_found": "未找到 MRL 文件",
            "mrl_invalid_extension": "所选文件不是 MRL",
            "texture_directory_not_selected": "未选择贴图目录",
            "texture_directory_not_found": "贴图目录不存在",
            "no_resolved_base_color_texture": "未找到可用 DDS/TEX Base Color 贴图",
            "importer_texture_planner_unavailable": "贴图规划器不可用",
            "texture_processing_failed": "贴图解析失败",
        }
        english_reasons = {
            "mrl_not_selected": "no MRL file was selected",
            "mrl_not_found": "the MRL file was not found",
            "mrl_invalid_extension": "the selected file is not an MRL",
            "texture_directory_not_selected": "no texture folder was selected",
            "texture_directory_not_found": "the texture folder was not found",
            "no_resolved_base_color_texture": "no usable DDS/TEX Base Color texture was found",
            "importer_texture_planner_unavailable": "the texture planner is unavailable",
            "texture_processing_failed": "texture processing failed",
        }
        return (
            "导入贴图：已跳过（"
            + localized_reasons.get(reason, "贴图输入不可用")
            + "），几何已照常导入。"
            + cleanup_cn,
            "Import Textures: skipped ("
            + english_reasons.get(reason, "texture inputs are unavailable")
            + "); geometry was imported normally."
            + cleanup_en,
        )

    def _format_mrl_unbound_mesh_report(
        self,
        receipt: Mapping[str, Any] | None,
    ) -> tuple[str, str]:
        data = dict(receipt or {})
        blender_validation = data.get("blender_material_validation")
        if isinstance(blender_validation, Mapping):
            validation = dict(blender_validation)
            validation_status = str(
                validation.get("status", "") or ""
            ).strip().upper()
            if validation_status in {"VERIFIED", "PARTIAL"}:
                try:
                    planned = max(
                        0, int(validation.get("planned_binding_count", 0) or 0)
                    )
                    verified = max(
                        0, int(validation.get("verified_binding_count", 0) or 0)
                    )
                    actual_untextured = max(
                        0,
                        int(validation.get("actual_untextured_mesh_count", 0) or 0),
                    )
                except (TypeError, ValueError, OverflowError):
                    planned = verified = actual_untextured = 0
                source_rows = [
                    dict(row)
                    for row in list(
                        validation.get("source_unbound_meshes", []) or []
                    )
                    if isinstance(row, Mapping)
                ]
                unresolved_rows = [
                    dict(row)
                    for row in list(validation.get("unresolved", []) or [])
                    if isinstance(row, Mapping)
                ]
                source_names = [
                    str(row.get("mesh_name", "") or "").strip()
                    or f"MESH_{int(row.get('mesh_slot', 0) or 0):03d}"
                    for row in source_rows
                ]
                unresolved_names = [
                    str(row.get("mesh_name", "") or "").strip()
                    or f"MESH_{int(row.get('mesh_slot', 0) or 0):03d}"
                    for row in unresolved_rows
                ]
                cn_sections = [
                    "Blender 实际 Base Color 验收："
                    f"计划 {planned} 个，已确认 {verified} 个，"
                    f"实际未挂 {actual_untextured} 个。"
                ]
                en_sections = [
                    "Blender actual Base Color verification: "
                    f"planned {planned}, verified {verified}, "
                    f"actually untextured {actual_untextured}."
                ]
                if source_names:
                    cn_sections.append(
                        f"源 MRL 本来无绑定的 Mesh（{len(source_names)} 个）：\n"
                        + "\n".join(source_names)
                    )
                    en_sections.append(
                        f"Meshes with no source MRL binding ({len(source_names)}):\n"
                        + "\n".join(source_names)
                    )
                if unresolved_names:
                    cn_sections.append(
                        f"额外未挂 Base Color 的计划 Mesh（{len(unresolved_names)} 个）：\n"
                        + "\n".join(unresolved_names)
                    )
                    en_sections.append(
                        f"Additional planned Meshes without a Base Color image ({len(unresolved_names)}):\n"
                        + "\n".join(unresolved_names)
                    )
                return "\n\n".join(cn_sections), "\n\n".join(en_sections)
        if not bool(data.get("mrl_binding_plan_available", False)):
            return "", ""
        names = [
            str(value or "").strip()
            for value in list(data.get("mrl_unbound_mesh_names", []) or [])
            if str(value or "").strip()
        ]
        if not names:
            return (
                "MRL 贴图绑定检查：本次导入的所有 Mesh 均已绑定贴图。",
                "MRL texture binding check: every Mesh in this import received a texture binding.",
            )
        count = len(names)
        return (
            f"MRL 贴图未绑定的 Mesh（{count} 个）：\n" + "\n".join(names),
            f"Meshes without an MRL texture binding ({count}):\n" + "\n".join(names),
        )

    def _format_import_skin_compatibility_receipt(
        self,
        receipt: Mapping[str, Any] | None,
    ) -> tuple[str, str]:
        data = dict(receipt or {})
        ignored_count = max(
            0,
            int(data.get("ignored_out_of_range_reference_count", 0) or 0),
        )
        if ignored_count <= 0:
            return "", ""
        positive_count = max(
            0,
            int(
                data.get(
                    "ignored_out_of_range_positive_weight_reference_count",
                    0,
                )
                or 0
            ),
        )
        mesh_count = max(0, int(data.get("affected_mesh_count", 0) or 0))
        vertex_count = max(0, int(data.get("affected_vertex_count", 0) or 0))
        renormalized_vertex_count = max(
            0,
            int(data.get("renormalized_vertex_count", 0) or 0),
        )
        fully_unbound_vertex_count = max(
            0,
            int(data.get("fully_unbound_vertex_count", 0) or 0),
        )
        bone_count = max(0, int(data.get("source_bone_count", 0) or 0))
        source_slots = sorted(
            {
                int(slot)
                for slot in data.get("ignored_source_bone_slots", [])
                if int(slot) > bone_count
            }
        )
        slot_text = ", ".join(str(slot) for slot in source_slots[:12]) or "?"
        if len(source_slots) > 12:
            slot_text += f" ...（共 {len(source_slots)} 种）"
        slot_text_en = ", ".join(str(slot) for slot in source_slots[:12]) or "?"
        if len(source_slots) > 12:
            slot_text_en += f" ... ({len(source_slots)} distinct)"
        return (
            "Skin 兼容警告（非阻断）：源 MOD 在 "
            f"{mesh_count} 个 Mesh、{vertex_count} 个顶点中含 {ignored_count} 个越界骨骼槽位字节"
            f"（骨骼总数 {bone_count}，越界槽位 {slot_text}；其中 {positive_count} 个带正权重）。"
            f"已忽略无效引用；{renormalized_vertex_count} 个顶点保留了合法权重并已重新归一化，"
            f"{fully_unbound_vertex_count} 个顶点没有可恢复的合法正权重。"
            "合法骨骼与可恢复权重照常导入；此类越界引用不会阻断导入。",
            "Skin compatibility warning (non-blocking): the source MOD contains "
            f"{ignored_count} out-of-range bone-slot values across {mesh_count} Meshes and "
            f"{vertex_count} vertices (bone count {bone_count}; out-of-range slots {slot_text_en}; "
            f"{positive_count} carry positive weight). Invalid references were ignored; "
            f"{renormalized_vertex_count} vertices retained legal weights and were renormalized, while "
            f"{fully_unbound_vertex_count} vertices have no recoverable legal positive weight. Legal "
            "bones and recoverable weights were imported normally; these references do not block import.",
        )

    def _format_max_embedded_fbx_texture_preflight(
        self,
        receipt: Mapping[str, Any] | None,
        *,
        embedded_media_count: int,
        embedded_media_bytes: int,
    ) -> tuple[str, str]:
        """Describe disk-backed Max texture validity without trusting the viewport."""
        data = dict(receipt or {})

        def count(key: str) -> int:
            try:
                return max(0, int(data.get(key, 0) or 0))
            except (TypeError, ValueError):
                return 0

        bitmap_texture_count = count("bitmap_texture_count")
        source_available_count = count("source_available_count")
        unavailable_count = count("unavailable_count")
        if bitmap_texture_count <= 0:
            return (
                "MAX场景中无贴图，导出的FBX中不包含贴图。",
                "The 3ds Max scene has no bitmap textures, so the exported FBX contains no textures.",
            )

        unavailable_rows = [
            dict(row)
            for row in list(data.get("unavailable_texture_paths", []) or [])[:8]
            if isinstance(row, Mapping)
        ]
        unavailable_lines: list[str] = []
        for row in unavailable_rows:
            name = str(row.get("name", "") or "").strip()
            path = str(row.get("original_path", "") or "").strip()
            status = str(row.get("status", "") or "").strip().casefold()
            reason_cn = "贴图文件无法读取" if status == "unreadable" else "贴图路径不存在"
            reason_en = "texture file is unreadable" if status == "unreadable" else "texture path is missing"
            label = f"{name}: {path}" if name and path else name or path
            if label:
                unavailable_lines.append(f"{label}（{reason_cn}）")
        if unavailable_count > 0:
            if source_available_count <= 0 and embedded_media_count <= 0 and embedded_media_bytes <= 0:
                message_cn = (
                    "MAX场景中存在贴图但贴图已经被删除或损坏，导出的FBX中将不包含贴图。\n"
                    "视窗里面有贴图是视觉窗口残留的假象，对Mesh进行操作或刷新视窗就能看到贴图已经失效。"
                )
                message_en = (
                    "The 3ds Max scene references textures, but their files are deleted or damaged, so the exported FBX contains no textures.\n"
                    "A texture still visible in the viewport is only delayed viewport residue; editing a Mesh or refreshing the viewport reveals that the texture is already unavailable."
                )
            else:
                message_cn = (
                    f"MAX场景中有 {unavailable_count} 个贴图路径已经被删除或损坏；"
                    "导出的FBX不会包含这些失效贴图。\n"
                    "视窗里面仍显示它们时属于视觉窗口残留的假象，对Mesh进行操作或刷新视窗就能看到贴图已经失效。"
                )
                message_en = (
                    f"The 3ds Max scene has {unavailable_count} deleted or damaged texture paths; "
                    "the exported FBX does not include those unavailable textures.\n"
                    "If they remain visible in the viewport, that is delayed viewport residue; editing a Mesh or refreshing the viewport reveals that the textures are unavailable."
                )
            if unavailable_lines:
                message_cn += "\n\n失效贴图路径（最多显示 8 条）：\n" + "\n".join(unavailable_lines)
                message_en += "\n\nUnavailable texture paths (up to 8 shown):\n" + "\n".join(
                    str(row.get("name", "") or "").strip()
                    + (": " if str(row.get("name", "") or "").strip() and str(row.get("original_path", "") or "").strip() else "")
                    + str(row.get("original_path", "") or "").strip()
                    for row in unavailable_rows
                    if str(row.get("name", "") or "").strip()
                    or str(row.get("original_path", "") or "").strip()
                )
            return message_cn, message_en

        return (
            f"MAX场景贴图路径预检通过：{bitmap_texture_count} 个贴图均存在且可读取，导出的FBX已写入内嵌贴图。",
            f"3ds Max texture path preflight passed: all {bitmap_texture_count} textures exist and are readable, and the exported FBX contains embedded textures.",
        )

